INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded], [Language]) VALUES (280, 31, N'Water-Sector-Cybersecurity-Risk-Managmenet-Guidance-V4.0.pdf', N'AWWA Water Sector Cybersecurity Risk Management Guidance
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded], [Language]) VALUES (3870, 31, N'PCI-DSS-v4_0_1.pdf', N'Payment Card Industry (PCI) Data Security Standard 4.0.1', N'PCI-DSS 4.0.1', NULL, N'PCIDSS 4.0.1', NULL, NULL, N'PCI-DSS 4.0.1', '2024-06-11 00:00:00.000', N'4.0.1', N'The Payment Card Industry Data Security Standard (PCI DSS) was developed to encourage and enhance cardholder data security and facilitate the broad adoption of consistent data security measures globally. PCI DSS provides a baseline of technical and operational requirements designed to protect account data. PCI DSS applies to all entities involved in payment card processing—including merchants, processors, acquirers, issuers, and service providers. PCI DSS also applies to all other entities that store, process or transmit cardholder data (CHD) and/or sensitive authentication data (SAD).', NULL, NULL, 0, NULL)
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded], [Language]) VALUES (3972, 31, N'NIST.SP.800-171r3.pdf', N'NIST SP 800-171 Rev. 3: Protecting Controlled Unclassified Information in Nonfederal Systems and Organizations (May 2024)', N'NIST SP800-171 R3', NULL, N'NONE', NULL, NULL, N'NIST SP 800-171 Rev. 3', '2024-05-01 00:00:00.000', NULL, N'The protection of Controlled Unclassified Information (CUI) resident in nonfederal systems and organizations is of paramount importance to federal agencies and can directly impact the ability of the federal government to successfully conduct its essential missions and functions. This publication provides agencies with recommended security requirements for protecting the confidentiality of CUI when the information is resident in nonfederal systems and organizations; when the nonfederal organization is not collecting or maintaining information on behalf of a federal agency or using or operating a system on behalf of an agency; and where there are no specific safeguarding requirements for protecting the confidentiality of CUI prescribed by the authorizing law, regulation, or governmentwide policy for the CUI category listed in the CUI Registry. The requirements apply to all components of nonfederal systems and organizations that process, store, and/or transmit CUI, or that provide protection for such components. The security requirements are intended for use by federal agencies in contractual vehicles or other agreements established between those agencies and nonfederal organizations.', NULL, NULL, 0, NULL)
INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded], [Language]) VALUES (3990, 31, N'CyberMESA EVCI Eval Procedures Measurements and Metrics.pdf', N'CyberMESA: Evaluation Procedures and Metrics for Charging Infrastructure Cybersecurity', N'CyberMESA', NULL, N'INL/RPT-25-88240', N'', NULL, N'EVCI Eval Procedures Measurements and Metrics', '2025-12-01 00:00:00.000', N'1.0', N'This document aims to aid in the vulnerability assessments of individual EVCI devices, such as Electric Vehicle Supply Equipment (EVSE), to support vendors in adopting and implementing security standards such as UL 2900, NIST SP 800-53 and Common Criteria (CC) (ISO/IEC 15408).', NULL, NULL, 0, NULL)
