INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (362, N'PE-3', N'Physical security and procedures for offices, rooms, and facilities.', N'Staff lock doors that allow access to PCS assets. Security guards inspect doors to make sure they are locked properly.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 7, 4, NULL, NULL)
