INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (365, N'PE-6', N'Physical security and procedures for mail rooms, loading areas, etc., established. These areas must be isolated from OT and enterprise system areas.', N'Server room and PLC cabinets are isolated from areas that delivery personnel and customers may visit.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 10, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (366, N'PE-7', N'Physical security and procedures against equipment environmental threats and hazards or unauthorized access.', N'The utility monitors facilities using security cameras.', N'Physical Security', N'Physical Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 11, 33, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (367, N'PE-8', N'Physical/logical protection against power failure of equipment (UPS).', N'Uninterruptible power supplies (UPS) are available as power backup for critical components.', N'Physical Security', N'Physical Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 12, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (368, N'PE-9', N'Physical/logical protection against access to power and telecommunications cabling established.', N'A utility has a standby power source with separated power cabling for critical sites.', N'Physical Security', N'Physical Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 14, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (369, N'SC-1', N'Policies and procedures governing cryptography and cryptographic protocols including key/certificate-management established to maximize protection of systems and information.', N'When selecting new PLCs for a system upgrade, SCADA techs evaluate the option of using newer PLCs that offer encryption for communication.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 15, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (370, N'SC-11', N'Framework for hardening of mobile code and devices established (including acceptance criteria and approved policies and procedures).', N'A water utility chooses to not allow personal mobile devices to connect to the control network. The utility does provide mobile devices managed by IT that can connect to the network.', N'Server and Workstation Hardening', N'Server and Workstation Hardening', 0, NULL, N'AWWA 4.0', NULL, NULL, 16, 43, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (371, N'SC-12', N'Remote access framework including policies and procedures established to provide secure access to telecommuting staff, established for the management, monitoring, review, and audit of remote access to the organization.', N'Remote access to the SCADA system requires two factor-authentication.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 17, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (372, N'SC-14', N'Network segregation. Firewalls, deep packet inspection and/or application proxy gateways.', N'An actively managed firewall is in place to allow secure data transfer via DMZ.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 18, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (373, N'SC-15', N'Logically separated control network. Minimal or single access points between corporate and control network. Stateful firewall between corporate and control networks filtering on TCP and UDP ports. DMZ networks for data sharing.', N'An actively managed firewall is in place to allow secure data transfer via DMZ to provide operations data to utility asset managers.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 19, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (374, N'SC-16', N'Defense-in-depth. Multiple layers of security with overlapping functionality.', N'A utility employs multiple types of physical and cybersecurity efforts to protect assets and systems. The efforts include such things as locking doors, physical access control, and unique login requirements for each staff member.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 20, 72, NULL, NULL)
