INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (384, N'SC-25', N'Virtual Private Network (VPN) using IPsec, SSL or SSH to encrypt communications from untrusted networks to the control system network.', N'An operator who can access the system remotely must do so through a secured VPN client configuration.', N'Encryption', N'Encryption', 0, NULL, N'AWWA 4.0', NULL, NULL, 31, 13, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (385, N'SC-3', N'Policies and procedures established for network segmentation including implementation of DMZs based on type and sensitivity of equipment, user roles, and types of systems established.', N'All external communication with the PCS is implemented via DMZ.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 32, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (386, N'SI-1', N'Electronic commerce infrastructure in place providing integrity, confidentiality and non-repudiation and including adherence to pertinent laws, regulations, policies, procedures, and approval by management.', N'The company selected to perform billing is compliant with pertinent laws, regulations, policies, procedures that are relevant to the utility.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 33, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (387, N'SI-3', N'Interactive system for managing password implemented to ensure password strength.', N'When configuring a new user''s password, it must meet minimum character length requirements.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 34, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (388, N'AT-1', N'A general security awareness and response program established to ensure staff is aware of the indications of a potential incident, security policies, and incident response/notification procedures.', N'An operator finds a USB media device. Based on their cybersecurity training, they know not to use it on the company network.', N'Education', N'Education', 0, NULL, N'AWWA 4.0', NULL, NULL, 36, 87, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (389, N'AU-1', N'Audit program established to ensure information systems are compliant with policies and standards and to minimize disruption of operations.', N'IT schedules an independent review and examination of records and activities to assess the adequacy of system controls and to ensure compliance with established policies.', N'Application Security', N'Application Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 37, 85, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (390, N'AU-2', N'Framework of information security policies, procedures, and controls including management''s initial and periodic approval established to provide governance, exercise periodic review, dissemination, and coordination of information security activities.', N'The process of implementing policies and procedures is clearly defined and reviewed. Updates to this process are made by a responsible party.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 38, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (391, N'AU-3', N'Governance framework to disseminate/decentralize decision making while maintaining executive authority and strategic control and ensure that managers follow the security policies and enforce the execution of security procedures within their area of responsibility.', N'A utility has a required number of accountable staff that must review or provide input before security policies are put in place. Periodic review that approved security policies are being followed.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 39, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (392, N'AU-4', N'Information security responsibilities defined and assigned.', N'All staff are aware of who they would report to if they notice suspicious behavior in the system.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 40, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (393, N'AU-5', N'Risk based business continuity framework established under the auspices of the executive team to maintain continuity of operations and consistency of policies and plans throughout the organization.  Another purpose of the framework is to ensure consistency across plans in terms of priorities, contact data, testing, and maintenance.', N'The facility has a documented and tested contingency plan to operate the facility without the use of SCADA software, in the case of attack by ransomware.', N'Business Continuity and Disaster Recovery', N'Business Continuity and Disaster Recovery', 0, NULL, N'AWWA 4.0', NULL, NULL, 41, 81, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (394, N'AU-6', N'Policies and procedures established to validate, test, update and audit the business continuity plan throughout the organization.', N'The business continuity plan is revised annually. Revisions are informed by planned exercises, actual events, or documented changes.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 42, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (395, N'AU-7', N'Policies and procedures for system instantiation/deployment established to ensure business continuity.', N'The PCS has a testing/development environment to allow changes to be implemented without immediate effects to the production environment.', N'Business Continuity and Disaster Recovery', N'Business Continuity and Disaster Recovery', 0, NULL, N'AWWA 4.0', NULL, NULL, 43, 81, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (396, N'CM-3', N'Separation of duties implemented for user processes including risk of abuse.', N'Operators are only given clearance to areas they are expected to work in. Supervisors have the ability and training to monitor SCADA tech activities in the PCS.', N'Application Security', N'Application Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 44, 85, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (397, N'CM-4', N'Separation of duties implemented for development, production, and testing work.', N'A SCADA technician must have a second technician review changes made to production equipment before they are implemented.', N'Application Security', N'Application Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 45, 85, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (398, N'CM-5', N'SLAs for all third parties established, including levels of service and change controls.', N'A security policy that outlines what access permissions are distributed to third party employees.', N'Service Level Agreements (SLA)', N'Service Level Agreements (SLA)', 0, NULL, N'AWWA 4.0', NULL, NULL, 47, 90, NULL, NULL)
