INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (400, N'IA-11', N'Workstation and other equipment authentication framework established to secure sensitive access from certain high risk locations.', N'Access to control of critical equipment is only available at a secured terminal.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 49, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (401, N'IA-9', N'Multifactor authentication system established for critical areas.', N'Remote access to the SCADA system requires two factor-authentication.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 50, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (402, N'IR-1', N'Incident response program established with a formal Emergency Response Plan to restore systems and operations based on their criticality and within time constraints and effect recovery in case of a catalogue of disruptive events.  Exercises conducted to test and revise plans and build organizational response capabilities.', N'Emergency Response Plan includes procedures for recovering SCADA system operation from system backup.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 51, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (403, N'PM-3', N'Centralized logging system including policies and procedures to collect, analyze and report to management.', N'A utility has a network intrusion detection system (NIDS) to monitor network traffic.', N'Telecommunications, Network Security, and Architecture', N'Telecommunications, Network Security, and Architecture', 0, NULL, N'AWWA 4.0', NULL, NULL, 52, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (404, N'PM-4', N'SLAs for software and information exchange with internal/external parties in place including interfaces between systems and approved policies and procedures.', N'Third parties must review and sign an information exchange policy before connecting to the system.', N'Service Level Agreements (SLA)', N'Service Level Agreements (SLA)', 0, NULL, N'AWWA 4.0', NULL, NULL, 53, 90, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (405, N'RA-1', N'Risk assessment and approval process before granting access to the organization''s information systems.', N'A third-party system integrator would need to contact IT before connecting to the system''s network.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 54, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (406, N'RA-2', N'Third party agreement process to ensure security on access, processing, communicating, or managing the organization''s information or facilities.', N'System integrators can only access the facility''s equipment remotely from a VPN connection.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 55, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (407, N'SC-10', N'Program for hardening servers, workstations, routers, and other systems using levels of hardening based on criticality established. Program should include policies and procedures for whitelisting (deny-all, allow by exception).', N'Ports are disabled for all network devices when not in use.', N'Server and Workstation Hardening', N'Server and Workstation Hardening', 0, NULL, N'AWWA 4.0', NULL, NULL, 56, 43, NULL, NULL)
