INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (410, N'SC-6', N'Network management and monitoring established including deep packet inspection of traffic, QoS, port-level security, and approved policies and procedures.', N'An actively managed firewall is in place to allow secure data transfer via DMZ to provide operations data to utility asset managers.', N'Telecommunications, Network Security, and Architecture', N'Telecommunications, Network Security, and Architecture', 0, NULL, N'AWWA 4.0', NULL, NULL, 60, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (411, N'SC-7', N'Information exchange protection program in place to protect data in-transit through any communication system including the Internet, email, and text messaging and approved policies and procedures.', N'Web applications for SCADA software use encryption to protect data in transit.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 61, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (412, N'SC-8', N'Routing controls established to provide logical separation of sensitive systems and enforce the organization''s access control policy.', N'Within the SCADA system network, vendor systems are placed on a separate subnet rather than being on a single "flat" network.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 62, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (413, N'SC-9', N'Process isolation established to provide a manual override "air gap" between highly sensitive systems and regular environments.', N'A manual method for disconnecting the ICS network from other networks is implemented and documented.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 63, 89, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (414, N'SI-5', N'Privileged programs controls established to restrict usage of system programs that could reset passwords or override controls as well as enterprise system audit tools that can modify or delete audit data.', N'Utility has implemented tiered access so non-administrator users are unable to make changes to system security settings.', N'Application Security', N'Application Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 64, 85, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (415, N'AT-2', N'Job specific security training including incident response training for employees, contractors and third party users.', N'An operator has received what they believe to be a malicious email. They recognize that it is a phishing attack based on security training awareness programs the company has in place.', N'Education', N'Education', 0, NULL, N'AWWA 4.0', NULL, NULL, 65, 87, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (416, N'AU-8', N'Template for the organization''s confidentiality/non-disclosure agreements defined, reviewed, and approved periodically by management.', N'Reviews of the organization''s confidentiality/non-disclosure agreements are periodically scheduled by a responsible party.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 66, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (417, N'CIE-1', N'A program is in place to engage engineering staff in understanding and mitigating high-consequence and constantly evolving cyber threat throughout the engineering life-cycle including: design, implementation, maintenance, and decommissioning.', N'Engineering staff is fully aware of the potential for a cyber breach. They design electrical and mechanical systems to provide functionality in the case of a SCADA system compromise.', N'Cyber-Informed Engineering', N'Cyber-Informed Engineering', 0, NULL, N'AWWA 4.0', NULL, NULL, 67, 50, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (418, N'CM-1', N'Policies for defining business requirements including data validation and message authenticity established to ensure that new/upgraded systems contain appropriate security requirements and controls.', N'Policies to define minimum security features (i.e. secure protocols, active directory integration, etc.) required for new systems. This could include review and approval by change management and/or security team.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 69, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (419, N'CM-2', N'Procedure modification tracking program in place to manage and log changes to policies and procedures.', N'The Emergency Response Plan is stored in a central repository and clearly displays the version and date of when it was implemented.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 70, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (420, N'IA-8', N'Policies for security of standalone, lost, and misplaced equipment in place.', N'An operator misplaces a managed phone. Based on the missing equipment policy, they contact IT to report the device lost.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 71, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (421, N'IR-3', N'A legal/contractual/regulatory framework established with a formal Emergency Response Plan to track legal/contractual/regulatory requirements and the efforts to meet them with respect to each important system within the organization. Another purpose of the framework is to ensure compliance of policies and procedures with privacy laws, handling cryptographic products, intellectual property rights, and data retention requirements.', N'The Emergency Response Plan is reviewed and updated once a year by responsible staff.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 72, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (422, N'MA-3', N'Off-site equipment maintenance program including risk assessment of outside environmental conditions established.', N'The condition of offsite equipment and risk factors acting on the equipment are periodically reviewed and assessed via an independent party.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 73, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (423, N'MP-2', N'Information exit mechanisms in place to prevent data, software leaving premises without authorization or logging.', N'An approved data leakage prevention (DLP) system is implemented or manual procedures to control data and/or software leaving organization.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 74, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (424, N'PM-1', N'Asset management program including a repository containing all significant assets of the organization with a responsible party for each, periodic inventories, and audits.', N'A database is used to keep track of building conditions in the facility.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 75, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (425, N'PM-2', N'Policies and procedures for acceptable use of assets and information approved and implemented.', N'PLCs that cannot update past a specific security revision are not acceptable for use in the PCS.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 76, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (426, N'PS-1', N'Policies and procedures for hiring/terminating processes on employees, contractors, or support companies to include background checks and contract agreements approved and implemented.', N'A background check on employees is required before they may be given access to the PCS system.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 77, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (427, N'PS-2', N'Defined and approved security roles and responsibilities of all employees, contractors and third party users.', N'A company policy is in place limiting the access of third-party users to assets, systems, and data.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 78, 67, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (428, N'PS-3', N'A clear desk policy in place including clear papers, media, desktop, and computer screens.', N'Confidential documents are stored in locked file cabinets when not in use, as required by policy.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 80, 67, NULL, NULL)
