INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (433, N'SA-4', N'Risk based mobility policies and procedures established to protect against inherent risk of mobile computing and communication systems.', N'Remote access is restricted to only the most necessary applications and only allowed through secure measures.', N'Operations Security', N'Operations Security', 0, NULL, N'AWWA 4.0', NULL, NULL, 85, 89, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (434, N'SA-5', N'Periodic review of backup policies and procedures and testing of recovery processes.', N'System backups are tested on a regular basis by completing a system restoration to the test environment.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 86, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (435, N'SC-13', N'Testing standards including test data selection, protection, and system verification established to ensure system completeness.', N'Organization has a FAT procedure that requires vendors to demonstrate security of systems before they are purchased.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 87, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (436, N'SI-2', N'System acceptance standards including data validation (input/output), message authenticity, and system integrity established to detect information corruption during processing.', N'Acquired assets are inspected, assessed, and documented before implementation with existing systems.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 88, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (437, N'SI-4', N'Organization-wide clock synchronization system in place.', N'All managed network devices synchronize their clocks to a known good source.', N'Telecommunications, Network Security, and Architecture', N'Telecommunications, Network Security, and Architecture', 0, NULL, N'AWWA 4.0', NULL, NULL, 89, 72, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (438, N'CM-6', N'Risk based policies and procedures for change controls, reviews, and audits of SLAs.', N'Inviting all affected parties to discussions to prevent the development of vulnerabilities in the facility.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 91, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (439, N'IA-2', N'Access control for the management, monitoring, review, and audit of accounts established including access control, account roles, privilege accounts, password policies and executive oversight.', N'Upon staff termination or resignation, login credentials are disabled as part of the Human Resources process.', N'Access Control', N'Access Control', 0, NULL, N'AWWA 4.0', NULL, NULL, 92, 4, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (440, N'IR-2', N'A security program established with a formal Emergency Response Plan to respond to security incidents monitor, discover, and handle security alerts and technical vulnerabilities, collect and analyze security data, limit the organization''s risk profile and ensure that management is aware of changing/emerging risks.', N'A SCADA tech believes a machine is infected and responds according to the utility''s emergency response plan for cybersecurity based incidents.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 93, 88, NULL, NULL)
