INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (448, N'SU-2', N'A supply chain risk management program that includes cybersecurity.', N'Preferred vendors for computer hardware, software and peripherals are identified and selected based on evaluation of their supply chain among other criteria.', N'Governance and Risk Management', N'Governance and Risk Management', 0, NULL, N'AWWA 4.0', NULL, NULL, 3, 88, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4200, N'03.01.01', N'<ol type="a"> <li>Define the types of system accounts allowed and prohibited.</li> <li>Create, enable, modify, disable, and remove system accounts in accordance with policy, procedures, prerequisites, and criteria.</li> <li>Specify: <ol type="1"> <li>Authorized users of the system,</li> <li>Group and role membership, and</li> <li>Access authorizations (i.e., privileges) for each account.</li> </ol> </li> <li>Authorize access to the system based on: <ol type="1"> <li>A valid access authorization and</li> <li>Intended system usage.</li> </ol> </li> <li>Monitor the use of system accounts.</li> <li>Disable system accounts when: <ol type="1"> <li>The accounts have expired,</li> <li>The accounts have been inactive for {{Assignment: organization-defined time period}},</li> <li>The accounts are no longer associated with a user or individual,</li> <li>The accounts are in violation of organizational policy, or</li> <li>Significant risks associated with individuals are discovered.</li> </ol> </li> <li>Notify account managers and designated personnel or roles within: <ol type="1"> <li>{{Assignment: organization-defined time period}} when accounts are no longer required.</li> <li>{{Assignment: organization-defined time period}} when users are terminated or transferred.</li> <li>{{Assignment: organization-defined time period}} when system usage or the need-to-know changes for an individual.</li> </ol> </li> <li>Require that users log out of the system after {{Assignment: organization-defined time period}} of expected inactivity or when {{Assignment: organization-defined circumstances}}.</li> </ol>', N'<p><strong>DISCUSSION</strong></p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4201, N'03.01.02', N'Enforce approved authorizations for logical access to CUI and system resources in accordance with applicable access control policies.', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4202, N'03.01.03', N'Enforce approved authorizations for controlling the flow of CUI within the system and between connected systems.', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4203, N'03.01.04', N'<ol type="a">
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4204, N'03.01.05', N'<ol type="a"> <li>Allow only authorized system access for users (or processes acting on behalf of users) that is necessary to accomplish assigned organizational tasks.</li> <li>Authorize access to {{Assignment: organization-defined security functions}} and {{Assignment: organization-defined security-relevant information}}.</li> <li>Review the privileges assigned to roles or classes of users {{Assignment: organization-defined frequency}} to validate the need for such privileges.</li> <li>Reassign or remove privileges, as necessary.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4205, N'03.01.06', N'<ol type="a"> <li>Restrict privileged accounts on the system to {{Assignment: organization-defined personnel or roles}}.</li> <li>Require that users (or roles) with privileged accounts use non-privileged accounts when accessing non-security functions or non-security information.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4206, N'03.01.07', N'<ol type="a">
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4207, N'03.01.08', N'<ol type="a"> <li>Enforce a limit of {{Assignment: organization-defined number}} consecutive invalid logon attempts by a user during a {{Assignment: organization-defined time period}}.</li> <li>Automatically {{Selection (one or more): lock the account or node for an [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt; notify system administrator; take other action}} when the maximum number of unsuccessful attempts is exceeded.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4208, N'03.01.09', N'Display a system use notification message with privacy and security notices consistent with applicable CUI rules before granting access to the system.', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4209, N'03.01.10', N'<ol type="a"> <li>Prevent access to the system by {{Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended}}.</li> <li>Retain the device lock until the user reestablishes access using established identification and authentication procedures.</li> <li>Conceal, via the device lock, information previously visible on the display with a publicly viewable image.</li> </ol>', N'<p>DISCUSSION</p>
