INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4217, N'03.02.02', N'<ol type="a"> <li>Provide role-based security training to organizational personnel: <ol type="1"> <li>Before authorizing access to the system or CUI, before performing assigned duties, and {{Assignment: organization-defined frequency}} thereafter</li> <li>When required by system changes or following {{Assignment: organization-defined events}}.</li> </ol> </li> <li>Update role-based training content {{Assignment: organization-defined frequency}} and following {{Assignment: organization-defined events}}.</li> </ol>', N'<p>DISCUSSION</p>
