INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4222, N'03.03.05', N'<ol type="a"> <li>Review and analyze system audit records {{Assignment: organization-defined frequency}} for indications and the potential impact of inappropriate or unusual activity.</li> <li>Report findings to organizational personnel or roles.</li> <li>Analyze and correlate audit records across different repositories to gain organization-wide situational awareness.</li> </ol>', N'<p>DISCUSSION</p>
