INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4288, N'03.15.01', N'<ol type="a"> <li>Develop, document, and disseminate to organizational personnel or roles the policies and procedures needed to satisfy the security requirements for the protection of CUI.</li> <li>Review and update policies and procedures {{Assignment: organization-defined frequency}}.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4289, N'03.15.02', N'<ol type="a">   <li>Develop a system security plan that:     <ol type="1">       <li>Defines the constituent system components;</li>       <li>Identifies the information types processed, stored, and transmitted by the system;</li>       <li>Describes specific threats to the system that are of concern to the organization;</li>       <li>Describes the operational environment for the system and any dependencies on or connections to other systems or system components;</li>       <li>Provides an overview of the security requirements for the system;</li>       <li>Describes the safeguards in place or planned for meeting the security requirements;</li>       <li>Identifies individuals that fulfill system roles and responsibilities; and</li>       <li>Includes other relevant information necessary for the protection of CUI.</li>     </ol>   </li>   <li>Review and update the system security plan {{Assignment: organization-defined frequency}}.</li>   <li>Protect the system security plan from unauthorized disclosure.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4290, N'03.15.03', N'<ol type="a">   <li>Establish rules that describe the responsibilities and expected behavior for system usage and protecting CUI.</li>   <li>Provide rules to individuals who require access to the system.</li>   <li>Receive a documented acknowledgement from individuals indicating that they have read, understand, and agree to abide by the rules of behavior before authorizing access to CUI and the system.</li>   <li>Review and update the rules of behavior {{Assignment: organization-defined frequency}}.</li> </ol>', N'<p>DISCUSSION</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4291, N'03.16.01', N'Apply the following systems security engineering principles to the development or modification of the system and system components: {{Assignment: organization-defined systems security engineering principles}}.', N'<p>DISCUSSION</p>
