INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (4294, N'03.17.01', N'<ol type="a">   <li>Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations, maintenance, and disposal of the system, system components, or system services.</li>   <li>Review and update the supply chain risk management plan {{Assignment: organization-defined frequency}}.</li>   <li>Protect the supply chain risk management plan from unauthorized disclosure.</li> </ol>', N'<p>DISCUSSION</p>
