INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13233, N'MA-03 (02)', N'Check media containing diagnostic and test programs for malicious code before the media are used in the system.', N'If, upon inspection of media containing maintenance, diagnostic, and test programs, organizations determine that the media contains malicious code, the incident is handled consistent with organizational incident handling policies and procedures.', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 22, NULL, NULL)
