INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13235, N'MA-03 (04)', N'Restrict the use of maintenance tools to authorized personnel only.', N'Restricting the use of maintenance tools to only authorized personnel applies to systems that are used to carry out maintenance functions.', N'Maintenance', N'Maintenance Tools', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 22, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13236, N'MA-03 (05)', N'Monitor the use of maintenance tools that execute with increased privilege.
