INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13685, N'SI-02 (05)', N'Install {{Assignment: organization-defined security-relevant software and firmware updates}} automatically to {{Assignment: organization-defined system components}}.', N'Due to system integrity and availability concerns, organizations consider the methodology used to carry out automatic updates. Organizations balance the need to ensure that the updates are installed as soon as possible with the need to maintain configuration management and control, and with any mission or operational impacts that automatic updates might impose (i.e., implementing a staggered deployment strategy).', N'System and Information Integrity', N'Flaw Remediation', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 73, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13686, N'SI-02 (06)', N'<p>Remove previous versions of {{Assignment: organization-defined software and firmware components}} after updated versions have been installed.</p>', N'Previous versions of software or firmware components that are not removed from the system after updates have been installed may be exploited by adversaries. Some products may automatically remove previous versions of software and firmware from the system.', N'System and Information Integrity', N'Flaw Remediation', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 73, NULL, NULL)
