INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13804, N'SR-11 (01)', N'Train {{Assignment: organization-defined personnel or roles}} to detect counterfeit system components (including hardware, software, and firmware).', NULL, N'Supply Chain Risk Management', N'Component Authenticity', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 82, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13805, N'SR-11 (02)', N'<p>Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: {{Assignment: organization-defined system components}}.</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13806, N'SR-11 (03)', N'Scan for counterfeit system components {{Assignment: organization-defined frequency}}.', N'The type of component determines the type of scanning to be conducted (e.g., web application scanning if the component is a web application).', N'Supply Chain Risk Management', N'Component Authenticity', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 82, NULL, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13807, N'SR-12', N'<p>Dispose of {{Assignment: organization-defined data, documentation, tools, or system components}} using the following techniques and methods: {{Assignment: organization-defined techniques and methods}}.</p>
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach], [Old_Id_For_Copy]) VALUES (13808, N'SA-15 (13)', N'Require the developer of the system, system component, or system service to use {{Assignment: organization-defined secure logging format}} to log {{Assignment: organization-defined event types}} at {{Assignment: organization-defined level of detail}}.', N'<p>In support of better incident response and the ability to more quickly reconstruct security-related actions, identifying specific requirements for secure logging facilitates the ability to connect application-produced audit event logs with operational data.  Event types are consistent with the event types defined in AU-02.</p>', N'System and Services Acquisition', N'Development Process, Standards, and Tools', NULL, NULL, N'C800_53_R520', NULL, NULL, NULL, 48, NULL, NULL)
