UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'The organization does not enforce separation of duties, allowing individuals to perform conflicting roles (e.g., creating and approving their own accounts, making unvalidated security changes). This increases the risk of unauthorized actions and weakens accountability.' WHERE [Mat_Question_Id] = 1411 AND [PropertyName] = 'OBS-DISCOVERY'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'M' WHERE [Mat_Question_Id] = 1411 AND [PropertyName] = 'OBS-IMPACT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Define and document critical duties that require separation and enforce those separations through system access controls. Implement role-based access control(RBAC) prevent conflicting privileges (e.g., access provisioning vs. access auditing) from being assigned to the same user. Conduct regular audits to validate compliance with separation of duties policies, ensuring no single individual has unchecked control over OT and IT-critical systems. If system-based enforcement is not feasible, manual compensating controls, such as dual authorization for critical actions, should be implemented.' WHERE [Mat_Question_Id] = 1411 AND [PropertyName] = 'OBS-RECOMMENDATION'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How are duties segmented among staff to reduce the risk of error or malicious activity, especially around OT-critical and IT-critical processes?(e.g. account creation, firewall configuration)' WHERE [Mat_Question_Id] = 1411 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Without proper separation of duties, a single individual could bypass security controls, approve unauthorized changes, or manipulate OT systems without oversight, increasing the risk of fraud, insider threats, and security breaches.' WHERE [Mat_Question_Id] = 1411 AND [PropertyName] = 'OBS-RISK-STATEMENT'
