UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'AC-14, PL-4, SI-4' WHERE [Mat_Question_Id] = 1419 AND [PropertyName] = 'OBS-VULNERABILITY'
