UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'The organization does not log privileged functions in OT systems. Configuration changes, firmware updates, and critical command executions may occur without traceability. Legacy or standalone devices often lack native support, and compensating controls (e.g., session logs, proxies) are not consistently implemented.' WHERE [Mat_Question_Id] = 1479 AND [PropertyName] = 'OBS-DISCOVERY'
