UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'L' WHERE [Mat_Question_Id] = 1480 AND [PropertyName] = 'OBS-IMPACT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Implement network segmentation and firewall rules to strictly control OT-to-cloud communications. Require approval for all cloud integrations and log outbound traffic to detect unauthorized flows. Use data loss prevention (DLP) or proxy solutions to inspect payloads when feasible, and regularly review cloud communication logs for anomalies or unapproved endpoints.' WHERE [Mat_Question_Id] = 1480 AND [PropertyName] = 'OBS-RECOMMENDATION'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How do you monitor and restrict OT-to-cloud communication to prevent unauthorized data flows or integrations?' WHERE [Mat_Question_Id] = 1480 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Unrestricted communication between OT systems and cloud services opens paths for data exfiltration, command-and-control (C2) activity, or unauthorized third-party integrations. Without visibility and control, these flows can bypass internal defenses, exposing sensitive operational data and threatening compliance.' WHERE [Mat_Question_Id] = 1480 AND [PropertyName] = 'OBS-RISK-STATEMENT'
