UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'L' WHERE [Mat_Question_Id] = 1488 AND [PropertyName] = 'OBS-IMPACT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Review OT audit logs at least monthly. For higher-impact systems or where alerting tools (e.g., SIEMs) are in place, perform reviews weekly or near real-time. Tailor review frequency based on system criticality, past incidents, and organizational capability. Ensure coordination with security teams to flag anomalies and support incident response.' WHERE [Mat_Question_Id] = 1488 AND [PropertyName] = 'OBS-RECOMMENDATION'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How do you review and analyze OT audit records, report findings, and coordinate with other entities for incident detection?' WHERE [Mat_Question_Id] = 1488 AND [PropertyName] = 'OBS-RISK'
