UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Peripheral device usage on ICS/OT systems is not consistently controlled. In some environments, USB ports remain enabled without technical enforcement or physical locks. Logging and monitoring of device connections is minimal or absent. Legacy systems may lack the ability to restrict or detect device usage, and compensating controls are often informal or reactive.' WHERE [Mat_Question_Id] = 1491 AND [PropertyName] = 'OBS-DISCOVERY'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'' WHERE [Mat_Question_Id] = 1491 AND [PropertyName] = 'OBS-IMPACT'
