UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How do you monitor and restrict unauthorized peripheral device (USB, external drive, cellular devices) usage in ICS/OT environments?' WHERE [Mat_Question_Id] = 1491 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Uncontrolled use of peripherals on ICS/OT systems presents a direct path for malware infection, misconfiguration, or data loss. Threat actors have historically leveraged USB devices for lateral movement and initial compromise (e.g., Stuxnet, Russia''s BlackEnergy campaign). Even accidental connection of infected media can bypass perimeter defenses, placing critical infrastructure at risk.' WHERE [Mat_Question_Id] = 1491 AND [PropertyName] = 'OBS-RISK-STATEMENT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'' WHERE [Mat_Question_Id] = 1491 AND [PropertyName] = 'OBS-VULNERABILITY'
