UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'M' WHERE [Mat_Question_Id] = 1492 AND [PropertyName] = 'OBS-IMPACT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Prevent portable media use on OT systems through technical controls where feasible. Where enforcement is limited, apply compensating safeguards such as physical port blockers and pre-use scanning on intermediary systems.' WHERE [Mat_Question_Id] = 1492 AND [PropertyName] = 'OBS-RECOMMENDATION'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'What policies govern portable storage device usage on external systems, and how do you prevent malware introduction to OT or IT systems?' WHERE [Mat_Question_Id] = 1492 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Unregulated portable storage devices can carry malware or unauthorized software, potentially compromising OT or IT systems, leading to data breaches, operational disruption, or spread of malicious code across the organization.' WHERE [Mat_Question_Id] = 1492 AND [PropertyName] = 'OBS-RISK-STATEMENT'
