UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Require formal agreements (e.g., contracts, MOUs) that specify security controls for external systems handling OT data, ensure compliance reviews before granting access, and regularly audit external providers to confirm they meet organizational security standards.' WHERE [Mat_Question_Id] = 1493 AND [PropertyName] = 'OBS-RECOMMENDATION'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'What security measures or agreements must be verified before external systems can process or access organizational data, including OT data?' WHERE [Mat_Question_Id] = 1493 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Without verified security measures or formal agreements, external systems could introduce vulnerabilities or fail to protect OT data, resulting in unauthorized access, data leaks, or compromises to critical processes.' WHERE [Mat_Question_Id] = 1493 AND [PropertyName] = 'OBS-RISK-STATEMENT'
