UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How does your organization ensure that privileged commands executed remotely are logged and reviewed for security and compliance (e.g. firmware updates, shutdowns)?' WHERE [Mat_Question_Id] = 1494 AND [PropertyName] = 'OBS-RISK'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'Without proper authorization and logging of privileged remote access, malicious actors or insider threats could modify OT configurations, disrupt critical processes, or disable safety mechanisms without detection.' WHERE [Mat_Question_Id] = 1494 AND [PropertyName] = 'OBS-RISK-STATEMENT'
UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'AC-6, SC-12, SC-13' WHERE [Mat_Question_Id] = 1494 AND [PropertyName] = 'OBS-VULNERABILITY'
