UPDATE [dbo].[MATURITY_QUESTION_PROPS] SET [PropertyValue]=N'How do you assess vendor OT products for security compliance before procurement, and ensure alignment with operational needs?' WHERE [Mat_Question_Id] = 1529 AND [PropertyName] = 'OBS-RISK'
