UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'<ol type="a"> <li>Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information''s access and use restrictions for {{Assignment: organization-defined information sharing circumstances where user discretion is required}}; and</li> <li>Employ {{Assignment: organization-defined automated mechanisms or manual processes}} to assist users in making information sharing and collaboration decisions.</li> </ol>' WHERE [Requirement_Id] = 3919
