UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-6 (2)', [Requirement_Text]=N'Take the following actions in response to unauthorized changes to {{Assignment: organization-defined configuration settings}}: {{Assignment: organization-defined actions}}.' WHERE [Requirement_Id] = 3970
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'<ol type="a"> <li>Configure the system to provide only {{Assignment: organization-defined mission essential capabilities}}; and</li> <li>Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: {{Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services}}.</li> </ol>' WHERE [Requirement_Id] = 3971
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-7 (1)', [Requirement_Text]=N'<ol type="a"> <li>Review the system {{Assignment: organization-defined frequency}} to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and</li> <li>Disable or remove {{Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure}}.</li> </ol>' WHERE [Requirement_Id] = 3972
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-7 (4)', [Requirement_Text]=N'<ol type="a"> <li>Identify {{Assignment: organization-defined software programs not authorized to execute on the system}};</li> <li>Employ an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the system; and</li> <li>Review and update the list of unauthorized software programs {{Assignment: organization-defined frequency}}.</li> </ol>' WHERE [Requirement_Id] = 3973
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-7 (5)', [Requirement_Text]=N'<ol type="a"> <li>Identify {{Assignment: organization-defined software programs authorized to execute on the system}};</li> <li>Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and</li> <li>Review and update the list of authorized software programs {{Assignment: organization-defined frequency}}.</li> </ol>' WHERE [Requirement_Id] = 3974
