UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-7 (7)', [Requirement_Text]=N'<p>Allow execution of binary or machine-executable code only in confined physical or virtual machine environments and with the explicit approval of {{Assignment: organization-defined personnel or roles}} when such code is:</p> <ol type="a"> <li>Obtained from sources with limited or no warranty; and/or</li> <li>Without the provision of source code.</li> </ol>' WHERE [Requirement_Id] = 3976
