UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-7 (9)', [Requirement_Text]=N'<ol type="a"> <li>Identify {{Assignment: organization-defined hardware components authorized for system use}};</li> <li>Prohibit the use or connection of unauthorized hardware components;</li> <li>Review and update the list of authorized hardware components {{Assignment: organization-defined frequency}}.</li> </ol>' WHERE [Requirement_Id] = 3978
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'<ol type="a"> <li>Develop and document an inventory of system components that: <ol> <li>Accurately reflects the system;</li> <li>Includes all components within the system;</li> <li>Does not include duplicate accounting of components or components assigned to any other system;</li> <li>Is at the level of granularity deemed necessary for tracking and reporting; and</li> <li>Includes the following information to achieve system component accountability: {{Assignment: organization-defined information deemed necessary to achieve effective system component accountability}}; and</li> </ol> </li> <li>Review and update the system component inventory {{Assignment: organization-defined frequency}}.</li> </ol>' WHERE [Requirement_Id] = 3979
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-8 (1)' WHERE [Requirement_Id] = 3980
