UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Title]=N'CM-8 (4)', [Requirement_Text]=N'Include in the system component inventory information, a means for identifying by {{Selection (one or more): name; position; role}}, individuals responsible and accountable for administering those components.' WHERE [Requirement_Id] = 3982
