UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Establishes and administers privileged user accounts in accordance with a role-based access scheme that organizes allowed information system access and privileges into roles; (b) Monitors privileged role assignments; and (c) Takes {{Assignment: organization-defined actions}} when privileged role assignments are no longer appropriate.' WHERE [Requirement_Id] = 9003
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system creates {{Assignment: organization-defined information system accounts}} dynamically.' WHERE [Requirement_Id] = 9004
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies the following types of information system accounts to support organizational missions/business functions: {{Assignment: organization-defined information system account types}}; b. Assigns account managers for information system accounts; c. Establishes conditions for group and role membership; d. Specifies authorized users of the information system, group and role membership, and access authorizations (i.e., privileges) and other attributes (as required) for each account; e. Requires approvals by {{Assignment: organization-defined personnel or roles}} for requests to create information system accounts; f. Creates, enables, modifies, disables, and removes information system accounts; g. Authorizes, and monitors the use of, information system accounts; h. Notifies account managers: 1. When accounts are no longer required; 2. When users are terminated or transferred; and 3. When individual information system usage or need-to-know changes; i. Authorizes access to the information system based on: 1. A valid access authorization; 2. Intended system usage; and 3. Other attributes as required by the organization or associated missions/business functions; j. Reviews accounts for compliance with account management requirements {{Assignment: organization-defined frequency}}; and k. Establishes a process for reissuing shared/group account credentials (if deployed) when individuals are removed from the group.' WHERE [Requirement_Id] = 9013
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of organization-controlled portable storage devices by authorized individuals on external information systems.' WHERE [Requirement_Id] = 9015
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of non-organizationally owned information systems, system components, or devices to process, store, or transmit organizational information.' WHERE [Requirement_Id] = 9016
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the use of {{Assignment: organization-defined network accessible storage devices}} in external information systems.' WHERE [Requirement_Id] = 9017
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements information search and retrieval services that enforce {{Assignment: organization-defined information sharing restrictions}}.' WHERE [Requirement_Id] = 9021
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system transmits {{Assignment: organization-defined access authorization information}} using {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined information systems}} that enforce access control decisions.' WHERE [Requirement_Id] = 9029
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces access control decisions based on {{Assignment: organization-defined security attributes}} that do not include the identity of the user or process acting on behalf of the user.' WHERE [Requirement_Id] = 9030
