UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces dual authorization for {{Assignment: organization-defined privileged commands and/or other organization-defined actions}}.' WHERE [Requirement_Id] = 9033
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined mandatory access control policies}} over all subjects and objects where the policy specifies that: (a) The policy is uniformly enforced across all subjects and objects within the boundary of the information system; (b) A subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes on subjects, objects, the information system, or information system components; (4) Choosing the security attributes to be associated with newly created or modified objects; or (5) Changing the rules governing access control; and (c) {{Assignment: Organized-defined subjects}} may explicitly be granted {{Assignment: organization-defined privileges (i.e., they are trusted subjects)}} such that they are not limited by some or all of the above constraints.' WHERE [Requirement_Id] = 9034
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents access to {{Assignment: organization-defined security-relevant information}} except during secure, non-operable system states.' WHERE [Requirement_Id] = 9038
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses {{Assignment: organization-defined security attributes}} associated with {{Assignment: organization-defined information, source, and destination objects}} to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions.' WHERE [Requirement_Id] = 9040
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for privileged administrators to enable/disable {{Assignment: organization-defined security policy filters}} under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 9041
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for privileged administrators to configure {{Assignment: organization-defined security policy filters}} to support different security policies.' WHERE [Requirement_Id] = 9042
