UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, implements {{Assignment: organization-defined security policy filters}} requiring fully enumerated formats that restrict data structure and content.' WHERE [Requirement_Id] = 9045
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates source and destination points by {{Selection (one or more): organization, system, application, individual}} for information transfer.' WHERE [Requirement_Id] = 9048
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses protected processing domains to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions.' WHERE [Requirement_Id] = 9049
