UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined one-way flows}} using hardware mechanisms.' WHERE [Requirement_Id] = 9054
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces information flow control using {{Assignment: organization-defined security policy filters}} as a basis for flow control decisions for {{Assignment: organization-defined information flows}}.' WHERE [Requirement_Id] = 9055
