UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that users of information system accounts, or roles, with access to {{Assignment: organization-defined security functions or security-relevant information}}, use non-privileged accounts or roles, when accessing non-security functions.' WHERE [Requirement_Id] = 9062
