UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors {{Assignment: organization-defined open source information and/or information sites}} {{Assignment: organization-defined frequency}} for evidence of unauthorized disclosure of organizational information.' WHERE [Requirement_Id] = 9108
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides cross-organizational audit information to {{Assignment: organization-defined organizations}} based on {{Assignment: organization-defined cross-organizational sharing agreements}}.' WHERE [Requirement_Id] = 9114
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined methods}} for coordinating {{Assignment: organization-defined audit information}} among external organizations when audit information is transmitted across organizational boundaries.' WHERE [Requirement_Id] = 9115
