UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides an alert in {{Assignment: organization-defined real-time period}} to {{Assignment: organization-defined personnel, roles, and/or locations}} when the following audit failure events occur: {{Assignment: organization-defined audit failure events requiring real-time alerts}}.' WHERE [Requirement_Id] = 9126
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces configurable network communications traffic volume thresholds reflecting limits on auditing capacity and {{Selection: rejects; delays}} network traffic above those thresholds.' WHERE [Requirement_Id] = 9127
