UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization specifies the permitted actions for each {{Selection (one or more): information system process; role; user}} associated with the review, analysis, and reporting of audit information.' WHERE [Requirement_Id] = 9136
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to process audit records for events of interest based on {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 9139
