UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Uses internal system clocks to generate time stamps for audit records; and b. Generates time in the time stamps that can be mapped to Coordinated Universal Time (UTC) or Greenwich Mean Time (GMT) and meets {{Assignment: organization-defined granularity of time measurement}}.' WHERE [Requirement_Id] = 9143
