UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for {{Selection (one or more): movement; deletion}} of {{Assignment: organization-defined audit information}}.' WHERE [Requirement_Id] = 9147
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes read-only access to audit information to {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 9148
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 9159
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 9160
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 9161
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 9162
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the baseline configuration of the information system: (a) {{Assignment: organization-defined frequency}}; (b) When required due to {{Assignment organization-defined circumstances}}; and (c) As an integral part of information system component installations and upgrades.' WHERE [Requirement_Id] = 9185
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization retains {{Assignment: organization-defined previous versions of baseline configurations of the information system}} to support rollback.' WHERE [Requirement_Id] = 9187
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to: (a) Document proposed changes to the information system; (b) Notify {{Assignment: organized-defined approval authorities}}; (c) Highlight change approvals that have not been received by {{Assignment: organization-defined time period}}; (d) Prohibit changes to the information system until designated approvals are received; and (e) Document completed changes to the information system.' WHERE [Requirement_Id] = 9190
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires an information security representative to be a member of the {{Assignment: organization-defined configuration change control element (e.g., committee, board)}}.' WHERE [Requirement_Id] = 9191
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that cryptographic mechanisms used to provide {{Assignment: organization-defined security safeguards}} are under configuration management.' WHERE [Requirement_Id] = 9192
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines the types of changes to the information system that are configuration-controlled; b. Reviews proposed configuration-controlled changes to the information system and approves or disapproves such changes with explicit consideration for security impact analyses; c. Documents configuration change decisions associated with the information system; d. Implements approved configuration-controlled changes to the information system; e. Retains records of configuration-controlled changes to the information system; f. Reviews activities associated with configuration-controlled changes to the information system; and g. Coordinates and provides oversight for configuration change control activities through {{Assignment: organization-defined configuration change control element (e.g., committee, board)}} that convenes {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined configuration change conditions]}}.' WHERE [Requirement_Id] = 9197
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents the installation of {{Assignment: organization-defined software and firmware components}} without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.' WHERE [Requirement_Id] = 9199
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for implementing changes to {{Assignment: organization-defined information system components and system-level information}}.' WHERE [Requirement_Id] = 9200
