UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and documents configuration settings for information technology products employed within the information system using {{Assignment: organization-defined security configuration checklists}} that reflect the most restrictive mode consistent with operational requirements; b. Implements the configuration settings; c. Identifies, documents, and approves any deviations from established configuration settings for {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined operational requirements}}; and d. Monitors and controls changes to the configuration settings in accordance with organizational policies and procedures' WHERE [Requirement_Id] = 9207
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to respond to unauthorized changes to {{Assignment: organization-defined configuration settings}}.' WHERE [Requirement_Id] = 9209
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews the information system {{Assignment: organization-defined frequency}} to identify unnecessary and/or non-secure functions, ports, protocols, and services; and (b) Disables {{Assignment: organization-defined functions, ports, protocols, and services within the information system deemed to be unnecessary and/or non-secure}}.' WHERE [Requirement_Id] = 9212
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents program execution in accordance with {{Selection (one or more): [Assignment: organization-defined policies regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage}}.' WHERE [Requirement_Id] = 9213
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures compliance with {{Assignment: organization-defined registration requirements for functions, ports, protocols, and services}}.' WHERE [Requirement_Id] = 9216
