UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Employs automated mechanisms {{Assignment: organization-defined frequency}} to detect the presence of unauthorized hardware, software, and firmware components within the information system; and (b) Takes the following actions when unauthorized components are detected: {{Selection (one or more): disables network access by such components; isolates the components; notifies [Assignment: organization-defined personnel or roles]}}.' WHERE [Requirement_Id] = 9222
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes in the information system component inventory information, a means for identifying by {{Selection (one or more): name; position; role}}, individuals responsible/accountable for administering those components.' WHERE [Requirement_Id] = 9223
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Assigns {{Assignment: organization-defined acquired information system components}} to an information system; and (b) Receives an acknowledgement from the information system owner of this assignment.' WHERE [Requirement_Id] = 9225
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the unauthorized installation of software is detected' WHERE [Requirement_Id] = 9238
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans for the resumption of essential missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation.' WHERE [Requirement_Id] = 9249
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans for the resumption of all missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation.' WHERE [Requirement_Id] = 9252
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes an alternate processing site including necessary agreements to permit the transfer and resumption of {{Assignment: organization-defined information system operations}} for essential missions/business functions within {{Assignment: organization-defined time period consistent with recovery time and recovery point objectives}} when the primary processing capabilities are unavailable; b. Ensures that equipment and supplies required to transfer and resume operations are available at the alternate site or contracts are in place to support delivery to the site in time to support the organization-defined time period for transfer/resumption; and c. Ensures that the alternate processing site provides information security safeguards equivalent to that of the primary site.' WHERE [Requirement_Id] = 9269
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes an alternate processing site including necessary agreements to permit the transfer and resumption of {{Assignment: organization-defined information system operations}} for essential missions/business functions within {{Assignment: organization-defined time period consistent with recovery time and recovery point objectives}} when the primary processing capabilities are unavailable; b. Ensures that equipment and supplies required to transfer and resume operations are available at the alternate processing site or contracts are in place to support delivery to the site within the organization-defined time period for transfer/resumption; and c. Ensures that the alternate processing site provides information security safeguards equivalent to that of the primary site.' WHERE [Requirement_Id] = 9270
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes alternate telecommunications services including necessary agreements to permit the resumption of {{Assignment: organization-defined information system operations}} for essential missions and business functions within {{Assignment: organization-defined time period}} when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.' WHERE [Requirement_Id] = 9275
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires primary and alternate telecommunications service providers to have contingency plans; (b) Reviews provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtains evidence of contingency testing/training by providers {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 9278
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization stores backup copies of {{Assignment: organization-defined critical information system software and other security-related information}} in a separate facility or in a fire-rated container that is not collocated with the operational system.' WHERE [Requirement_Id] = 9286
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization transfers information system backup information to the alternate storage site {{Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives}}.' WHERE [Requirement_Id] = 9287
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the deletion or destruction of {{Assignment: organization-defined backup information}}.' WHERE [Requirement_Id] = 9289
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for remote access to privileged and non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 9305
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for network access to privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 9310
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a single sign-on capability for {{Assignment: organization-defined list of information system accounts and services}}.' WHERE [Requirement_Id] = 9311
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system authenticates {{Assignment: organization-defined specific devices and/or types of devices}} before establishing {{Selection (one or more): local; remote; network}} connection using bidirectional authentication that is cryptographically based.' WHERE [Requirement_Id] = 9314
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Standardizes dynamic address allocation lease information and the lease duration assigned to devices in accordance with {{Assignment: organization-defined lease information and lease duration}}; and (b) Audits lease information when assigned to a device.' WHERE [Requirement_Id] = 9315
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that device identification and authentication based on attestation is handled by {{Assignment: organization-defined configuration management process}}.' WHERE [Requirement_Id] = 9316
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages individual identifiers by uniquely identifying each individual as {{Assignment: organization-defined characteristic identifying individual status}}.' WHERE [Requirement_Id] = 9324
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of identifiers.' WHERE [Requirement_Id] = 9326
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, or device receiving the authenticator; b. Establishing initial authenticator content for authenticators defined by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost/compromised or damaged authenticators, and for revoking authenticators; e. Changing default content of authenticators prior to information system installation; f. Establishing minimum and maximum lifetime restrictions and reuse conditions for authenticators; g. Changing/refreshing authenticators {{Assignment: organization-defined time period by authenticator type}}; h. Protecting authenticator content from unauthorized disclosure and modification; i. Requiring individuals to take, and having devices implement, specific security safeguards to protect authenticators; and j. Changing authenticators for group/role accounts when membership to those accounts changes.' WHERE [Requirement_Id] = 9336
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for password-based authentication: (a) Enforces minimum password complexity of {{Assignment: organization-defined requirements for case sensitivity, number of characters, mix of upper-case letters, lower-case letters, numbers, and special characters, including minimum requirements for each type}}; (b) Enforces at least {{Assignment: organization-defined number of changed characters}} when new passwords are created; (c) Stores and transmits only encrypted representations of passwords; (d) Enforces password minimum and maximum lifetime restrictions of {{Assignment: organization-defined numbers for lifetime minimum, lifetime maximum}}; (e) Prohibits password reuse for {{Assignment: organization-defined number}} generations; and (f) Allows the use of a temporary password for system logons with an immediate change to a permanent password.' WHERE [Requirement_Id] = 9341
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for hardware token-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined token quality requirements}}.' WHERE [Requirement_Id] = 9342
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that the registration process to receive {{Assignment: organization-defined types of and/or specific authenticators}} be conducted {{Selection: in person; by a trusted third party}} before {{Assignment: organization-defined registration authority}} with authorization by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 9346
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to determine if password authenticators are sufficiently strong to satisfy {{Assignment: organization-defined requirements}}.' WHERE [Requirement_Id] = 9347
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined security safeguards}} to manage the risk of compromise due to individuals having accounts on multiple information systems.' WHERE [Requirement_Id] = 9351
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of credentials.' WHERE [Requirement_Id] = 9352
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for biometric-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined biometric quality requirements}}.' WHERE [Requirement_Id] = 9354
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prohibits the use of cached authenticators after {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 9355
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs only FICAM-approved information system components in {{Assignment: organization-defined information systems}} to accept third-party credentials.' WHERE [Requirement_Id] = 9362
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that identification and authentication decisions are transmitted between {{Assignment: organization-defined services}} consistent with organizational policies.' WHERE [Requirement_Id] = 9366
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests the incident response capability for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the incident response effectiveness and documents the results.' WHERE [Requirement_Id] = 9374
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes dynamic reconfiguration of {{Assignment: organization-defined information system components}} as part of the incident response capability.' WHERE [Requirement_Id] = 9381
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies {{Assignment: organization-defined classes of incidents}} and {{Assignment: organization-defined actions to take in response to classes of incidents}} to ensure continuation of organizational missions and business functions.' WHERE [Requirement_Id] = 9382
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements a configurable capability to automatically disable the information system if {{Assignment: organization-defined security violations}} are detected.' WHERE [Requirement_Id] = 9383
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates incident handling capability for insider threats across {{Assignment: organization-defined components or elements of the organization}}.' WHERE [Requirement_Id] = 9385
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} to correlate and share {{Assignment: organization-defined incident information}} to achieve a cross-organization perspective on incident awareness and more effective incident responses.' WHERE [Requirement_Id] = 9386
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined dynamic response capabilities}} to effectively respond to security incidents.' WHERE [Requirement_Id] = 9387
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reports information system vulnerabilities associated with reported security incidents to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 9393
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization responds to information spills by: a. Identifying the specific information involved in the information system contamination; b. Alerting {{Assignment: organization-defined personnel or roles}} of the information spill using a method of communication not associated with the spill; c. Isolating the contaminated information system or system component; d. Eradicating the information from the contaminated information system or component; e. Identifying other information systems or system components that may have been subsequently contaminated; and f. Performing other {{Assignment: organization-defined actions}}.' WHERE [Requirement_Id] = 9402
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization assigns {{Assignment: organization-defined personnel or roles}} with responsibility for responding to information spills.' WHERE [Requirement_Id] = 9403
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides information spillage response training {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 9404
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined procedures}} to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions.' WHERE [Requirement_Id] = 9405
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} for personnel exposed to information not within assigned access authorizations.' WHERE [Requirement_Id] = 9406
