UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires the approval of each nonlocal maintenance session by {{Assignment: organization-defined personnel or roles}}; and (b) Notifies {{Assignment: organization-defined personnel or roles}} of the date and time of planned nonlocal maintenance.' WHERE [Requirement_Id] = 9430
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs predictive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 9444
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Marks information system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempts {{Assignment: organization-defined types of information system media}} from marking as long as the exempted items remain within {{Assignment: organization-defined controlled areas}}.' WHERE [Requirement_Id] = 9450
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests sanitization equipment and procedures {{Assignment: organization-defined frequency}} to verify that the intended sanitization is being achieved.' WHERE [Requirement_Id] = 9461
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization applies nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the information system under the following circumstances: {{Assignment: organization-defined circumstances requiring sanitization of portable storage devices}}.' WHERE [Requirement_Id] = 9462
