UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to purge/wipe information from {{Assignment: organization-defined information systems, system components, or devices}} either remotely or under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 9465
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined information system media downgrading process}} that includes employing downgrading mechanisms with {{Assignment: organization-defined strength and integrity}}; b. Ensures that the information system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information; c. Identifies {{Assignment: organization-defined information system media requiring downgrading}}; and d. Downgrades the identified information system media using the established process.' WHERE [Requirement_Id] = 9468
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tests}} of downgrading equipment and procedures to verify correct performance {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 9470
