UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts unescorted access to the facility where the information system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 9479
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Enforces physical access authorizations at designated entry/exit points to the facility where the information system resides; b. Employs physical access control systems at {{Assignment: organization-defined entry/exit points}}; c. Verifies individual access authorizations before granting access to the facility; d. Controls ingress/egress to the facility using {{Selection (one or more): [Assignment: organization-defined physical access devices]; guards}}; e. Maintains physical access audit logs for {{Assignment: organization-defined entry/exit points}}; f. Provides {{Assignment: organization-defined security safeguards}} to control access to areas within the facility officially designated as publicly accessible; g. Escorts visitors and monitors visitor activity {{Assignment: organization-defined circumstances requiring visitor escorts and monitoring}}; h. Secures keys, combinations, and other physical access devices; i. Inventories {{Assignment: organization-defined physical access devices}} every {{Assignment: organization-defined frequency}}; and j. Changes combinations and keys {{Assignment: organization-defined frequency}} and/or when keys are lost, combinations are compromised, or individuals are transferred or terminated.' WHERE [Requirement_Id] = 9486
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization uses lockable physical casings to protect {{Assignment: organization-defined information system components}} from unauthorized physical access.' WHERE [Requirement_Id] = 9490
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization-defined hardware components}} within the information system.' WHERE [Requirement_Id] = 9491
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Ensures that only authorized individuals receive output from the device.' WHERE [Requirement_Id] = 9494
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Links individual identity to receipt of the output from the device.' WHERE [Requirement_Id] = 9495
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization marks {{Assignment: organization-defined information system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 9496
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to recognize {{Assignment: organization-defined classes/types of intrusions}} and initiate {{Assignment: organization-defined response actions}}.' WHERE [Requirement_Id] = 9502
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs video surveillance of {{Assignment: organization-defined operational areas}} and retains video recordings for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 9503
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains visitor access records to the facility where the information system resides; and b. Reviews visitor access records {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 9504
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire detection devices/systems for the information system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire.' WHERE [Requirement_Id] = 9516
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire suppression devices/systems for the information system that provide automatic notification of any activation to {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}}.' WHERE [Requirement_Id] = 9517
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and makes readily available to individuals requiring access to the information system, the rules that describe their responsibilities and expected behavior with regard to information and information system usage; b. Receives a signed acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the information system; and c. Reviews and updates the rules of behavior {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 9540
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization designs its security architecture using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security safeguards operate in a coordinated and mutually reinforcing manner.' WHERE [Requirement_Id] = 9545
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that {{Assignment: organization-defined security safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 9546
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization, upon termination of individual employment: a. Disables information system access within {{Assignment: organization-defined time period}}; b. Terminates/revokes any authenticators/credentials associated with the individual; c. Includes discussion of {{Assignment: organization-defined information security topics}} in exit interviews; d. Retrieves all security-related organizational information system-related property; and e. Retains access to organizational information and information systems formerly controlled by terminated individual.' WHERE [Requirement_Id] = 9580
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews logical and physical access authorizations to information systems/facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiates {{Assignment: organization-defined transfer or reassignment actions}} within {{Assignment: organization-defined time period following the formal transfer action}}; c. Confirms ongoing operational need for current access authorizations; and d. Modifies access authorization as needed to correspond with any changes in operational need due to reassignment or transfer.' WHERE [Requirement_Id] = 9583
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs a formal sanctions process for individuals failing to comply with established information security policies and procedures; and b. Notifies {{Assignment: organization-defined personnel or roles}} when a formal employee sanctions process is implemented, identifying the individual sanctioned and the reason for the sanction.' WHERE [Requirement_Id] = 9593
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization updates the information system vulnerabilities scanned {{Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported}}.' WHERE [Requirement_Id] = 9607
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements privileged access authorization to {{Assignment: organization-identified information system components}} for selected {{Assignment: organization-defined vulnerability scanning activities}}.' WHERE [Requirement_Id] = 9608
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{Assignment: organization-defined state-of-the-practice system/security engineering methods, software development methods, testing/evaluation/validation techniques, and quality control processes}}.' WHERE [Requirement_Id] = 9626
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to produce a plan for the continuous monitoring of security control effectiveness that contains {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 9629
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Conducts an organizational assessment of risk prior to the acquisition or outsourcing of dedicated information security services; and (b) Ensures that the acquisition or outsourcing of dedicated information security services is approved by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 9638
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts the location of {{Selection (one or more): information processing; information/data; information system services}} to {{Assignment: organization-defined locations}} based on {{Assignment: organization-defined requirements or conditions}}.' WHERE [Requirement_Id] = 9639
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Perform configuration management during system, component, or service {{Selection (one or more): design; development; implementation; operation}}; b. Document, manage, and control the integrity of changes to {{Assignment: organization-defined configuration items under configuration management}}; c. Implement only organization-approved changes to the information system; d. Document approved changes to the system, component, or service and the potential security impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service.' WHERE [Requirement_Id] = 9642
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Create and implement a security assessment plan that provides for security testing and evaluation: 1. At the depth of {{Selection (one or more): security-related functional properties; security-related externally visible interfaces; high-level design; low-level design; implementation representation (source code/hardware schematics)}}; and 2. At the rigor of {{Selection: showing; demonstrating; rigorously demonstrating}}; b. Perform {{Selection (one or more): unit; integration; system; regression}} testing/evaluation at {{Assignment: organization-defined breadth/depth}}; c. Produce evidence of the execution of the security assessment plan and the results of the security testing/evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during security testing/evaluation.' WHERE [Requirement_Id] = 9648
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to employ {{Selection (one or more): static; dynamic}} code analysis tools to identify common flaws and document the results of the analysis.' WHERE [Requirement_Id] = 9649
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security assessment plan and the evidence produced during security testing/evaluation.' WHERE [Requirement_Id] = 9651
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tailored acquisition strategies, contract tools, and procurement methods}} for the purchase of the information system, system component, or information system service from suppliers.' WHERE [Requirement_Id] = 9653
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to limit harm from potential adversaries identifying and targeting the organizational supply chain.' WHERE [Requirement_Id] = 9655
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} in accordance with classification guides to protect supply chain-related information for the information system, system component, or information system service.' WHERE [Requirement_Id] = 9657
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection (one or more): organizational analysis, independent third-party analysis, organizational penetration testing, independent third-party penetration testing}} of {{Assignment: organization-defined supply chain elements, processes, and actors}} associated with the information system, system component, or information system service.' WHERE [Requirement_Id] = 9658
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and retains unique identification of {{Assignment: organization-defined supply chain elements, processes, and actors}} for the information system, system component, or information system service.' WHERE [Requirement_Id] = 9659
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization inspects {{Assignment: organization-defined information systems, system components, or devices}} {{Selection (one or more): at random; at [Assignment: organization-defined frequency], upon [Assignment: organization-defined indications of need for inspection]}} to detect tampering.' WHERE [Requirement_Id] = 9670
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and implements anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the information system; and b. Reports counterfeit information system components to {{Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]}}.' WHERE [Requirement_Id] = 9671
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization trains {{Assignment: organization-defined personnel or roles}} to detect counterfeit information system components (including hardware, software, and firmware).' WHERE [Requirement_Id] = 9672
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization maintains configuration control over {{Assignment: organization-defined information system components}} awaiting service/repair and serviced/repaired components awaiting return to service.' WHERE [Requirement_Id] = 9673
