UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the following indications of compromise or potential compromise occur: {{Assignment: organization-defined compromise indicators}}.' WHERE [Requirement_Id] = 9804
