UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization takes information system components out of service by transferring component responsibilities to substitute components no later than {{Assignment: organization-defined fraction or percentage}} of mean time to failure.' WHERE [Requirement_Id] = 9848
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manually initiates transfers between active and standby information system components {{Assignment: organization-defined frequency}} if the mean time to failure exceeds {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 9849
