UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Selection: real-time; near real-time}} {{Assignment: organization-defined failover capability}} for the information system.' WHERE [Requirement_Id] = 9851
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements non-persistent {{Assignment: organization-defined information system components and services}} that are initiated in a known state and terminated {{Selection (one or more): upon end of session of use; periodically at [Assignment: organization-defined frequency]}}.' WHERE [Requirement_Id] = 9852
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that software and data employed during information system component and service refreshes are obtained from {{Assignment: organization-defined trusted sources}}.' WHERE [Requirement_Id] = 9853
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces a role-based access control policy over defined subjects and objects and controls access based upon {{Assignment: organization-defined roles and users authorized to assume such roles}}.' WHERE [Requirement_Id] = 9864
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on {{Assignment: organization-defined rules governing the timing of revocations of access authorizations}}.' WHERE [Requirement_Id] = 9865
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs an audited override of automated access control mechanisms under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 9867
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined out-of-band authentication}} under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 9869
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automatic voltage controls for {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 9870
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]}} for unsupported information system components.' WHERE [Requirement_Id] = 9873
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined discretionary access control policies}} over all subjects and objects where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects; (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the information system, or the information system’s components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control.' WHERE [Requirement_Id] = 10316
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews {{Assignment: organization-defined frequency}} the privileges assigned to {{Assignment: organization-defined roles or classes of users}} to validate the need for such privileges; and (b) Reassigns or removes privileges, if necessary, to correctly reflect organizational mission/business needs.' WHERE [Requirement_Id] = 10318
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An access control policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the access control policy and associated access controls; and b. Reviews and updates the current: 1. Access control policy {{Assignment: organization-defined frequency}}; and 2. Access control procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10753
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies and selects the following types of information system accounts to support organizational missions/business functions: {{Assignment: organization-defined information system account types}}; b. Assigns account managers for information system accounts; c. Establishes conditions for group and role membership; d. Specifies authorized users of the information system, group and role membership, and access authorizations (i.e., privileges) and other attributes (as required) for each account; e. Requires approvals by {{Assignment: organization-defined personnel or roles}} for requests to create information system accounts; f. Creates, enables, modifies, disables, and removes information system accounts in accordance with {{Assignment: organization-defined procedures or conditions}}; g. Monitors the use of, information system accounts; h. Notifies account managers: 1. When accounts are no longer required; 2. When users are terminated or transferred; and 3. When individual information system usage or need-to-know changes; i. Authorizes access to the information system based on: 1. A valid access authorization; 2. Intended system usage; and 3. Other attributes as required by the organization or associated missions/business functions; j. Reviews accounts for compliance with account management requirements {{Assignment: organization-defined frequency}}; and k. Establishes a process for reissuing shared/group account credentials (if deployed) when individuals are removed from the group.' WHERE [Requirement_Id] = 10754
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Control Enhancements (1) The organization employs automated mechanisms to support the management of information system accounts. (2) The information system automatically {{Selection: removes; disables}} temporary and emergency accounts after {{Assignment: organization-defined time period for each type of account}}. (3) The information system automatically disables inactive accounts after {{Assignment: organization-defined time period}}. (4) The information system automatically audits account creation, modification, enabling, disabling, and removal actions, and notifies {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 10755
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Control Enhancements (5) The organization requires that users log out when {{Assignment: organization-defined time-period of expected inactivity or description of when to log out}}. (12) The organization: (a) Monitors information system accounts for {{Assignment: organization-defined atypical use}}; and (b) Reports atypical usage of information system accounts to {{Assignment: organization-defined personnel or roles}}. (13) The organization disables accounts of users posing a significant risk within {{Assignment: organization-defined time period}} of discovery of the risk.' WHERE [Requirement_Id] = 10756
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements the following dynamic privilege management capabilities: {{Assignment: organization-defined list of dynamic privilege management capabilities}}. The organization: (a) Establishes and administers privileged user accounts in accordance with a role-based access scheme that organizes allowed information system access and privileges into roles; (b) Monitors privileged role assignments; and (c) Takes {{Assignment: organization-defined actions}} when privileged role assignments are no longer appropriate. The information system creates {{Assignment: organization-defined information system accounts}} dynamically. The organization only permits the use of shared/group accounts that meet {{Assignment: organization-defined conditions for establishing shared/group accounts}}. The information system terminates shared/group account credentials when members leave the group. The information system enforces {{Assignment: organization-defined circumstances and/or usage conditions}} for {{Assignment: organization-defined information system accounts}}.' WHERE [Requirement_Id] = 10757
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces dual authorization for {{Assignment: organization-defined privileged commands and/or other organization-defined actions}}. The information system enforces {{Assignment: organization-defined mandatory access control policies}} over all subjects and objects where the policy specifies that: (a) The policy is uniformly enforced across all subjects and objects within the boundary of the information system; (b) A subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes on subjects, objects, the information system, or information system components; (4) Choosing the security attributes and attribute values to be associated with newly created or modified objects; or (5) Changing the rules governing access control; and (c) {{Assignment: Organized-defined subjects}} may explicitly be granted {{Assignment: organization-defined privileges (i.e., they are trusted subjects)}} such that they are not limited by some or all of the above constraints. The information system enforces {{Assignment: organization-defined discretionary access control policies}} over defined subjects and objects where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects; (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the information system, or the information system’s components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control. The information system prevents access to {{Assignment: organization-defined security-relevant information}} except during secure, non-operable system states. The information system enforces a role-based access control policy over {{Assignment: organization-defined users and information resources}} and controls access based upon {{Assignment: organization-defined roles and users authorized to assume such roles}}. The information system enforces the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on {{Assignment: organization-defined rules governing the timing of revocations of access authorizations}}. The information system does not release information outside of the established system boundary unless: (a) The receiving {{Assignment: organization-defined information system or system component}} provides {{Assignment: organization-defined security safeguards}}; and (b) {{Assignment: organization-defined security safeguards}} are used to validate the appropriateness of the information designated for release. The organization employs an audited override of automated access control mechanisms under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 10759
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces approved authorizations for controlling the flow of information within the system and between interconnected systems based on {{Assignment: organization-defined information flow control policies}}.' WHERE [Requirement_Id] = 10760
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses {{Assignment: organization-defined security attributes}} associated with {{Assignment: organization-defined information, source, and destination objects}} to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions. The information system uses protected processing domains to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions. The information system enforces dynamic information flow control based on {{Assignment: organization-defined policies}}. The information system prevents encrypted information from bypassing content-checking mechanisms by {{Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]}}. The information system enforces {{Assignment: organization-defined limitations}} on embedding data types within other data types. The information system enforces information flow control based on {{Assignment: organization-defined metadata}}. The information system enforces {{Assignment: organization-defined one-way flows}} using hardware mechanisms. The information system enforces information flow control using {{Assignment: organization-defined security policy filters}} as a basis for flow control decisions for {{Assignment: organization-defined information flows}}. The information system enforces the use of human reviews for {{Assignment: organization-defined information flows}} under the following conditions: {{Assignment: organization-defined conditions}}. The information system provides the capability for privileged administrators to enable/disable {{Assignment: organization-defined security policy filters}} under the following conditions: {{Assignment: organization-defined conditions}}. The information system provides the capability for privileged administrators to configure {{Assignment: organization-defined security policy filters}} to support different security policies. The information system, when transferring information between different security domains, uses {{Assignment: organization-defined data type identifiers}} to validate data essential for information flow decisions. The information system, when transferring information between different security domains, decomposes information into {{Assignment: organization-defined policy-relevant subcomponents}} for submission to policy enforcement mechanisms. The information system, when transferring information between different security domains, implements {{Assignment: organization-defined security policy filters}} requiring fully enumerated formats that restrict data structure and content. The information system, when transferring information between different security domains, examines the information for the presence of {{Assignment: organized-defined unsanctioned information}} and prohibits the transfer of such information in accordance with the {{Assignment: organization-defined security policy}}. The information system uniquely identifies and authenticates source and destination points by {{Selection (one or more): organization, system, application, individual}} for information transfer. The information system binds security attributes to information using {{Assignment: organization-defined binding techniques}} to facilitate information flow policy enforcement. The information system, when transferring information between different security domains, applies the same security policy filtering to metadata as it applies to data payloads. The organization employs {{Assignment: organization-defined solutions in approved configurations}} to control the flow of {{Assignment: organization-defined information}} across security domains. The information system separates information flows logically or physically using {{Assignment: organization-defined mechanisms and/or techniques}} to accomplish {{Assignment: organization-defined required separations by types of information}}. The information system provides access from a single device to computing platforms, applications, or data residing on multiple different security domains, while preventing any information flow between the different security domains.' WHERE [Requirement_Id] = 10761
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Separates {{Assignment: organization-defined duties of individuals}}; b. Documents separation of duties of individuals; and c. Defines information system access authorizations to support separation of duties.' WHERE [Requirement_Id] = 10762
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) which are necessary to accomplish assigned tasks in accordance with organizational missions and business functions. The organization explicitly authorizes access to {{Assignment: organization-defined security functions (deployed in hardware, software, and firmware) and security-relevant information}}. The organization requires that users of information system accounts, or roles, with access to {{Assignment: organization-defined security functions or security-relevant information}}, use non-privileged accounts or roles, when accessing non-security functions. The organization restricts privileged accounts on the information system to {{Assignment: organization-defined personnel or roles}}. The information system audits the execution of privileged functions. The information system prevents non-privileged users from executing privileged functions to include disabling, circumventing, or altering implemented security safeguards/countermeasures.' WHERE [Requirement_Id] = 10763
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes network access to {{Assignment: organization-defined privileged commands}} only for {{Assignment: organization-defined compelling operational needs}} and documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 10764
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides separate processing domains to enable finer-grained allocation of user privileges. The organization prohibits privileged access to the information system by non-organizational users. The organization: (a) Reviews {{Assignment: organization-defined frequency}} the privileges assigned to {{Assignment: organization-defined roles or classes of users}} to validate the need for such privileges; and (b) Reassigns or removes privileges, if necessary, to correctly reflect organizational mission/business needs. The information system prevents {{Assignment: organization-defined software}} from executing at higher privilege levels than users executing the software.' WHERE [Requirement_Id] = 10765
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Enforces a limit of {{Assignment: organization-defined number}} consecutive invalid logon attempts by a user during a {{Assignment: organization-defined time period}}; and b. Automatically {{Selection: locks the account/node for an [Assignment: organization-defined time period]; locks the account/node until released by an administrator; delays next logon prompt according to [Assignment: organization-defined delay algorithm]}} when the maximum number of unsuccessful attempts is exceeded.' WHERE [Requirement_Id] = 10766
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system purges/wipes information from {{Assignment: organization-defined mobile devices}} based on {{Assignment: organization-defined purging/wiping requirements/techniques}} after {{Assignment: organization-defined number}} consecutive, unsuccessful device logon attempts.' WHERE [Requirement_Id] = 10767
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Displays to users {{Assignment: organization-defined system use notification message or banner}} before granting access to the system that provides privacy and security notices consistent with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance and states that: 1. Users are accessing a U.S. Government information system; 2. Information system usage may be monitored, recorded, and subject to audit; 3. Unauthorized use of the information system is prohibited and subject to criminal and civil penalties; and 4. Use of the information system indicates consent to monitoring and recording; b. Retains the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the information system; and c. For publicly accessible systems: 1. Displays system use information {{Assignment: organization-defined conditions}}, before granting further access; 2. Displays references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and 3. Includes a description of the authorized uses of the system.' WHERE [Requirement_Id] = 10768
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system notifies the user, upon successful logon (access) to the system, of the date and time of the last logon (access). The information system notifies the user, upon successful logon/access, of the number of unsuccessful logon/access attempts since the last successful logon/access. The information system notifies the user of the number of {{Selection: successful logons/accesses; unsuccessful logon/access attempts; both}} during {{Assignment: organization-defined time period}}. The information system notifies the user of changes to {{Assignment: organization-defined security-related characteristics/parameters of the user''s account}} during {{Assignment: organization-defined time period}}. The information system notifies the user, upon successful logon (access), of the following additional information: {{Assignment: organization-defined information to be included in addition to the date and time of the last logon (access)}}.' WHERE [Requirement_Id] = 10769
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system limits the number of concurrent sessions for each system account to {{Assignment: organization-defined number}}.' WHERE [Requirement_Id] = 10770
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prevents further access to the system by initiating a session lock after {{Assignment: organization-defined time period}} of inactivity or upon receiving a request from a user; and b. Retains the session lock until the user reestablishes access using established identification and authentication procedures. The information system conceals, via the session lock, information previously visible on the display with a publicly viewable image.' WHERE [Requirement_Id] = 10771
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system automatically terminates a user session after {{Assignment: organization-defined conditions or trigger events requiring session disconnect}}.' WHERE [Requirement_Id] = 10772
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Provides a logout capability for user-initiated communications sessions whenever authentication is used to gain access to {{Assignment: organization-defined information resources}}; and (b) Displays an explicit logout message to users indicating the reliable termination of authenticated communications sessions.' WHERE [Requirement_Id] = 10773
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies {{Assignment: organization-defined user actions}} that can be performed on the information system without identification or authentication consistent with organizational missions/business functions; and b. Documents and provides supporting rationale in the security plan for the information system, user actions not requiring identification or authentication.' WHERE [Requirement_Id] = 10774
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Provides the means to associate {{Assignment: organization-defined types of security attributes}} having {{Assignment: organization-defined security attribute values}} with information in storage, in process, and/or in transmission; b. Ensures that the security attribute associations are made and retained with the information; c. Establishes the permitted {{Assignment: organization-defined security attributes}} for {{Assignment: organization-defined information systems}}; and d. Determines the permitted {{Assignment: organization-defined values or ranges}} for each of the established security attributes. The information system dynamically associates security attributes with {{Assignment: organization-defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}} as information is created and combined. The information system provides authorized individuals (or processes acting on behalf of individuals) the capability to define or change the value of associated security attributes. The information system maintains the association and integrity of {{Assignment: organization-defined security attributes}} to {{Assignment: organization-defined subjects and objects}}. The information system supports the association of {{Assignment: organization-defined security attributes}} with {{Assignment: organization-defined subjects and objects}} by authorized individuals. The information system displays security attributes in human-readable form on each object that the system transmits to output devices to identify {{Assignment: organization-identified special dissemination, handling, or distribution instructions}} using {{Assignment: organization-identified human-readable, standard naming conventions}}. The organization allows personnel to associate, and maintain the association of {{Assignment: organization-defined security attributes}} with {{Assignment: organization-defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}}. The organization provides a consistent interpretation of security attributes transmitted between distributed information system components. The information system implements {{Assignment: organization-defined techniques or technologies}} with {{Assignment: organization-defined level of assurance}} in associating security attributes to information. The organization ensures that security attributes associated with information are reassigned only via re-grading mechanisms validated using {{Assignment: organization-defined techniques or procedures}}. The information system provides authorized individuals the capability to define or change the type and value of security attributes available for association with subjects and objects.' WHERE [Requirement_Id] = 10775
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system monitors and controls remote access methods. The information system implements cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions. The information system routes all remote accesses through {{Assignment: organization-defined number}} managed network access control points. The organization: (a) Authorizes the execution of privileged commands and access to security-relevant information via remote access only for {{Assignment: organization-defined needs}}; and (b) Documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 10777
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that users protect information about remote access mechanisms from unauthorized use and disclosure. The organization provides the capability to expeditiously disconnect or disable remote access to the information system within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 10778
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects wireless access to the system using authentication of {{Selection (one or more): users; devices}} and encryption.' WHERE [Requirement_Id] = 10780
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: full-device encryption; container encryption}} to protect the confidentiality and integrity of information on {{Assignment: organization-defined mobile devices}}.' WHERE [Requirement_Id] = 10784
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Prohibits the use of unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and (b) Enforces the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information: (1) Connection of unclassified mobile devices to classified information systems is prohibited; (2) Connection of unclassified mobile devices to unclassified information systems requires approval from the authorizing official; (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by {{Assignment: organization-defined security officials}}, and if classified information is found, the incident handling policy is followed. (c) Restricts the connection of classified mobile devices to classified information systems in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 10785
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization permits authorized individuals to use an external information system to access the information system or to process, store, or transmit organization-controlled information only when the organization: (a) Verifies the implementation of required security controls on the external system as specified in the organization’s information security policy and security plan; or (b) Retains approved information system connection or processing agreements with the organizational entity hosting the external information system. The organization {{Selection: restricts; prohibits}} the use of organization-controlled portable storage devices by authorized individuals on external information systems.' WHERE [Requirement_Id] = 10787
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of non-organizationally owned information systems, system components, or devices to process, store, or transmit organizational information. The organization prohibits the use of {{Assignment: organization-defined network accessible storage devices}} in external information systems.' WHERE [Requirement_Id] = 10788
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Facilitates information sharing by enabling authorized users to determine whether access authorizations assigned to the sharing partner match the access restrictions on the information for {{Assignment: organization-defined information sharing circumstances where user discretion is required}}; and b. Employs {{Assignment: organization-defined automated mechanisms or manual processes}} to assist users in making information sharing/collaboration decisions.' WHERE [Requirement_Id] = 10789
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared. The information system implements information search and retrieval services that enforce {{Assignment: organization-defined information sharing restrictions}}.' WHERE [Requirement_Id] = 10790
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Designates individuals authorized to post information onto a publicly accessible information system; b. Trains authorized individuals to ensure that publicly accessible information does not contain nonpublic information; c. Reviews the proposed content of information prior to posting onto the publicly accessible information system to ensure that nonpublic information is not included; and d. Reviews the content on the publicly accessible information system for nonpublic information {{Assignment: organization-defined frequency}} and removes such information, if discovered.' WHERE [Requirement_Id] = 10791
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined data mining prevention and detection techniques}} for {{Assignment: organization-defined data storage objects}} to adequately detect and protect against data mining.' WHERE [Requirement_Id] = 10792
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes procedures to ensure {{Assignment: organization-defined access control decisions}} are applied to each access request prior to access enforcement. The information system transmits {{Assignment: organization-defined access authorization information}} using {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined information systems}} that enforce access control decisions. The information system enforces access control decisions based on {{Assignment: organization-defined security attributes}} that do not include the identity of the user or process acting on behalf of the user.' WHERE [Requirement_Id] = 10793
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements a reference monitor for {{Assignment: organization-defined access control policies}} that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.' WHERE [Requirement_Id] = 10794
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security awareness and training policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security awareness and training policy and associated security awareness and training controls; and b. Reviews and updates the current: 1. Security awareness and training policy {{Assignment: organization-defined frequency}}; and 2. Security awareness and training procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10795
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides basic security awareness training to information system users (including managers, senior executives, and contractors): a. As part of initial training for new users; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 10796
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides role-based security training to personnel with assigned security roles and responsibilities: a. Before authorizing access to the information system or performing assigned duties; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 10799
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Assignment: organization-defined personnel or roles}} with initial and {{Assignment: organization-defined frequency}} training in the employment and operation of environmental controls. The organization provides {{Assignment: organization-defined personnel or roles}} with initial and {{Assignment: organization-defined frequency}} training in the employment and operation of physical security controls. The organization includes practical exercises in security training that reinforce training objectives. The organization provides training to its personnel on {{Assignment: organization-defined indicators of malicious code}} to recognize suspicious communications and anomalous behavior in organizational information systems.' WHERE [Requirement_Id] = 10800
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Documents and monitors individual information system security training activities including basic security awareness training and specific information system security training; and b. Retains individual training records for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 10801
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An audit and accountability policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the audit and accountability policy and associated audit and accountability controls; and b. Reviews and updates the current: 1. Audit and accountability policy {{Assignment: organization-defined frequency}}; and 2. Audit and accountability procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10802
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines that the information system is capable of auditing the following events: {{Assignment: organization-defined auditable events}}; b. Coordinates the security audit function with other organizational entities requiring audit-related information to enhance mutual support and to help guide the selection of auditable events; c. Provides a rationale for why the auditable events are deemed to be adequate to support after-the-fact investigations of security incidents; and d. Determines that the following events are to be audited within the information system: {{Assignment: organization-defined audited events (the subset of the auditable events defined in AU-2 a.) along with the frequency of (or situation requiring) auditing for each identified event}}.' WHERE [Requirement_Id] = 10803
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the audited events {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10804
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system generates audit records containing the following additional information: {{Assignment: organization-defined additional, more detailed information}}.' WHERE [Requirement_Id] = 10806
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides centralized management and configuration of the content to be captured in audit records generated by {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 10807
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization allocates audit record storage capacity in accordance with {{Assignment: organization-defined audit record storage requirements}}.' WHERE [Requirement_Id] = 10808
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system off-loads audit records {{Assignment: organization-defined frequency}} onto a different system or media than the system being audited.' WHERE [Requirement_Id] = 10809
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Alerts {{Assignment: organization-defined personnel or roles}} in the event of an audit processing failure; and b. Takes the following additional actions: {{Assignment: organization-defined actions to be taken (e.g., shut down information system, overwrite oldest audit records, stop generating audit records)}}.' WHERE [Requirement_Id] = 10810
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a warning to {{Assignment: organization-defined personnel, roles, and/or locations}} within {{Assignment: organization-defined time period}} when allocated audit record storage volume reaches {{Assignment: organization-defined percentage}} of repository maximum audit record storage capacity. The information system provides an alert in {{Assignment: organization-defined real-time period}} to {{Assignment: organization-defined personnel, roles, and/or locations}} when the following audit failure events occur: {{Assignment: organization-defined audit failure events requiring real-time alerts}}.' WHERE [Requirement_Id] = 10811
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces configurable network communications traffic volume thresholds reflecting limits on auditing capacity and {{Selection: rejects; delays}} network traffic above those thresholds. The information system invokes a {{Selection: full system shutdown; partial system shutdown; degraded operational mode with limited mission/business functionality available}} in the event of {{Assignment: organization-defined audit failures}}, unless an alternate audit capability exists.' WHERE [Requirement_Id] = 10812
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and analyzes information system audit records {{Assignment: organization-defined frequency}} for indications of {{Assignment: organization-defined inappropriate or unusual activity}}; and b. Reports findings to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 10813
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization integrates analysis of audit records with analysis of {{Selection (one or more): vulnerability scanning information; performance data; information system monitoring information; [Assignment: organization-defined data/information collected from other sources]}} to further enhance the ability to identify inappropriate or unusual activity. The organization correlates information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity.' WHERE [Requirement_Id] = 10815
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to centrally review and analyze audit records from multiple components within the system. The organization specifies the permitted actions for each {{Selection (one or more): information system process; role; user}} associated with the review, analysis, and reporting of audit information. The organization performs a full text analysis of audited privileged commands in a physically distinct component or subsystem of the information system, or other information system that is dedicated to that analysis. The organization correlates information from nontechnical sources with audit information to enhance organization-wide situational awareness. The organization adjusts the level of audit review, analysis, and reporting within the information system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.' WHERE [Requirement_Id] = 10816
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides an audit reduction and report generation capability that: a. Supports on-demand audit review, analysis, and reporting requirements and after-the-fact investigations of security incidents; and b. Does not alter the original content or time ordering of audit records. The information system provides the capability to process audit records for events of interest based on {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 10817
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to sort and search audit records for events of interest based on the content of {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 10818
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Uses internal system clocks to generate time stamps for audit records; and b. Records time stamps for audit records that can be mapped to Coordinated Universal Time (UTC) or Greenwich Mean Time (GMT) and meets {{Assignment: organization-defined granularity of time measurement}}.' WHERE [Requirement_Id] = 10819
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Compares the internal information system clocks {{Assignment: organization-defined frequency}} with {{Assignment: organization-defined authoritative time source}}; and (b) Synchronizes the internal system clocks to the authoritative time source when the time difference is greater than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 10820
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes access to management of audit functionality to only {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 10823
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system backs up audit records {{Assignment: organization-defined frequency}} onto a physically different system or system component than the system or component being audited. The information system implements cryptographic mechanisms to protect the integrity of audit information and audit tools.' WHERE [Requirement_Id] = 10824
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system writes audit trails to hardware-enforced, write-once media. The organization requires and enforces dual authorization for {{Selection (one or more): changes to; deletion of}} {{Assignment: organization-defined audit information}}. The organization authorizes read-only access to audit information to {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 10825
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against an individual (or process acting on behalf of an individual) falsely denying having performed {{Assignment: organization-defined actions to be covered by non-repudiation}}.' WHERE [Requirement_Id] = 10826
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Binds the identity of the information producer with the information to {{Assignment: organization-defined strength of binding}}; and (b) Provides the means for authorized individuals to determine the identity of the producer of the information. The information system: (a) Validates the binding of the information producer identity to the information at {{Assignment: organization-defined frequency}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error. The information system maintains reviewer/releaser identity and credentials within the established chain of custody for all information reviewed or released. The information system: (a) Validates the binding of the information reviewer identity to the information at the transfer or release points prior to release/transfer between {{Assignment: organization-defined security domains}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 10827
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization retains audit records for {{Assignment: organization-defined time period consistent with records retention policy}} to provide support for after-the-fact investigations of security incidents and to meet regulatory and organizational information retention requirements.' WHERE [Requirement_Id] = 10828
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined measures}} to ensure that long-term audit records generated by the information system can be retrieved.' WHERE [Requirement_Id] = 10829
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Provides audit record generation capability for the auditable events defined in AU-2 at {{Assignment: organization-defined information system components}}; b. Allows {{Assignment: organization-defined personnel or roles}} to select which auditable events are to be audited by specific components of the information system; and c. Generates audit records for the events defined in AU-2 d with the content defined in AU-3.' WHERE [Requirement_Id] = 10830
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system compiles audit records from {{Assignment: organization-defined information system components}} into a system-wide (logical or physical) audit trail that is time-correlated to within {{Assignment: organization-defined level of tolerance for relationship between time stamps of individual records in the audit trail}}. The information system provides the capability for {{Assignment: organization-defined individuals or roles}} to change the auditing to be performed on {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined selectable event criteria}} within {{Assignment: organization-defined time thresholds}}.' WHERE [Requirement_Id] = 10831
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors {{Assignment: organization-defined open source information and/or information sites}} {{Assignment: organization-defined frequency}} for evidence of unauthorized disclosure of organizational information. The organization employs automated mechanisms to determine if organizational information has been disclosed in an unauthorized manner. The organization reviews the open source information sites being monitored {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10833
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides an alternate audit capability in the event of a failure in primary audit capability that provides {{Assignment: organization-defined alternate audit functionality}}.' WHERE [Requirement_Id] = 10835
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined methods}} for coordinating {{Assignment: organization-defined audit information}} among external organizations when audit information is transmitted across organizational boundaries. The organization requires that the identity of individuals be preserved in cross-organizational audit trails. The organization provides cross-organizational audit information to {{Assignment: organization-defined organizations}} based on {{Assignment: organization-defined cross-organizational sharing agreements}}.' WHERE [Requirement_Id] = 10836
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security assessment and authorization policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security assessment and authorization policy and associated security assessment and authorization controls; and b. Reviews and updates the current: 1. Security assessment and authorization policy {{Assignment: organization-defined frequency}}; and 2. Security assessment and authorization procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10837
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security assessment plan that describes the scope of the assessment including: 1. Security controls and control enhancements under assessment; 2. Assessment procedures to be used to determine security control effectiveness; and 3. Assessment environment, assessment team, and assessment roles and responsibilities; b. Assesses the security controls in the information system and its environment of operation {{Assignment: organization-defined frequency}} to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements; c. Produces a security assessment report that documents the results of the assessment; and d. Provides the results of the security control assessment to {{Assignment: organization-defined individuals or roles}}.' WHERE [Requirement_Id] = 10838
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to conduct security control assessments.' WHERE [Requirement_Id] = 10839
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes as part of security control assessments, {{Assignment: organization-defined frequency}}, {{Selection: announced; unannounced}}, {{Selection (one or more): in-depth monitoring; vulnerability scanning; malicious user testing; insider threat assessment; performance/load testing; [Assignment: organization-defined other forms of security assessment]}}.' WHERE [Requirement_Id] = 10840
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization accepts the results of an assessment of {{Assignment: organization-defined information system}} performed by {{Assignment: organization-defined external organization}} when the assessment meets {{Assignment: organization-defined requirements}}.' WHERE [Requirement_Id] = 10841
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes connections from the information system to other information systems through the use of Interconnection Security Agreements; b. Documents, for each interconnection, the interface characteristics, security requirements, and the nature of the information communicated; and c. Reviews and updates Interconnection Security Agreements {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10842
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: allow-all, deny-by-exception; deny-all, permit-by-exception}} policy for allowing {{Assignment: organization-defined information systems}} to connect to external information systems.' WHERE [Requirement_Id] = 10843
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a plan of action and milestones for the information system to document the organization’s planned remedial actions to correct weaknesses or deficiencies noted during the assessment of the security controls and to reduce or eliminate known vulnerabilities in the system; and b. Updates existing plan of action and milestones {{Assignment: organization-defined frequency}} based on the findings from security controls assessments, security impact analyses, and continuous monitoring activities.' WHERE [Requirement_Id] = 10844
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a senior-level executive or manager as the authorizing official for the information system; b. Ensures that the authorizing official authorizes the information system for processing before commencing operations; and c. Updates the security authorization {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10846
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization develops a continuous monitoring strategy and implements a continuous monitoring program that includes: a. Establishment of {{Assignment: organization-defined metrics}} to be monitored; b. Establishment of {{Assignment: organization-defined frequencies}} for monitoring and {{Assignment: organization-defined frequencies}} for assessments supporting such monitoring; c. Ongoing security control assessments in accordance with the organizational continuous monitoring strategy; d. Ongoing security status monitoring of organization-defined metrics in accordance with the organizational continuous monitoring strategy; e. Correlation and analysis of security-related information generated by assessments and monitoring; f. Response actions to address results of the analysis of security-related information; and g. Reporting the security status of organization and the information system to {{Assignment: organization-defined personnel or roles}} {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10847
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to monitor the security controls in the information system on an ongoing basis.' WHERE [Requirement_Id] = 10848
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization conducts penetration testing {{Assignment: organization-defined frequency}} on {{Assignment: organization-defined information systems or system components}}.' WHERE [Requirement_Id] = 10850
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes internal connections of {{Assignment: organization-defined information system components or classes of components}} to the information system; and b. Documents, for each internal connection, the interface characteristics, security requirements, and the nature of the information communicated.' WHERE [Requirement_Id] = 10852
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A configuration management policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the configuration management policy and associated configuration management controls; and b. Reviews and updates the current: 1. Configuration management policy {{Assignment: organization-defined frequency}}; and 2. Configuration management procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10854
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the baseline configuration of the information system: (a) {{Assignment: organization-defined frequency}}; (b) When required due to {{Assignment organization-defined circumstances}}; and (c) As an integral part of information system component installations and upgrades. The organization retains {{Assignment: organization-defined previous versions of baseline configurations of the information system}} to support rollback. The organization: (a) Issues {{Assignment: organization-defined information systems, system components, or devices}} with {{Assignment: organization-defined configurations}} to individuals traveling to locations that the organization deems to be of significant risk; and (b) Applies {{Assignment: organization-defined security safeguards}} to the devices when the individuals return.' WHERE [Requirement_Id] = 10856
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines the types of changes to the information system that are configuration-controlled; b. Reviews proposed configuration-controlled changes to the information system and approves or disapproves such changes with explicit consideration for security impact analyses; c. Documents configuration change decisions associated with the information system; d. Implements approved configuration-controlled changes to the information system; e. Retains records of configuration-controlled changes to the information system for {{Assignment: organization-defined time period}}; f. Audits and reviews activities associated with configuration-controlled changes to the information system; and g. Coordinates and provides oversight for configuration change control activities through {{Assignment: organization-defined configuration change control element (e.g., committee, board)}} that convenes {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined configuration change conditions]}}. The organization tests, validates, and documents changes to the information system before implementing the changes on the operational system.' WHERE [Requirement_Id] = 10859
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to: (a) Document proposed changes to the information system; (b) Notify {{Assignment: organized-defined approval authorities}} of proposed changes to the information system and request change approval; (c) Highlight proposed changes to the information system that have not been approved or disapproved by {{Assignment: organization-defined time period}}; (d) Prohibit changes to the information system until designated approvals are received; (e) Document all changes to the information system; and (f) Notify {{Assignment: organization-defined personnel}} when approved changes to the information system are completed.' WHERE [Requirement_Id] = 10860
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to implement changes to the current information system baseline and deploys the updated baseline across the installed base. The organization requires an information security representative to be a member of the {{Assignment: organization-defined configuration change control element (e.g., committee, board)}}. The information system implements {{Assignment: organization-defined security responses}} automatically if baseline configurations are changed in an unauthorized manner. The organization ensures that cryptographic mechanisms used to provide {{Assignment: organization-defined security safeguards}} are under configuration management.' WHERE [Requirement_Id] = 10861
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces access restrictions and supports auditing of the enforcement actions. The organization reviews information system changes {{Assignment: organization-defined frequency}} and {{Assignment: organization-defined circumstances}} to determine whether unauthorized changes have occurred. The information system prevents the installation of {{Assignment: organization-defined software and firmware components}} without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.' WHERE [Requirement_Id] = 10866
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for implementing changes to {{Assignment: organization-defined information system components and system-level information}}. The organization: (a) Limits privileges to change information system components and system-related information within a production or operational environment; and (b) Reviews and reevaluates privileges {{Assignment: organization-defined frequency}}. The organization limits privileges to change software resident within software libraries.' WHERE [Requirement_Id] = 10867
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and documents configuration settings for information technology products employed within the information system using {{Assignment: organization-defined security configuration checklists}} that reflect the most restrictive mode consistent with operational requirements; b. Implements the configuration settings; c. Identifies, documents, and approves any deviations from established configuration settings for {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined operational requirements}}; and d. Monitors and controls changes to the configuration settings in accordance with organizational policies and procedures.' WHERE [Requirement_Id] = 10868
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to centrally manage, apply, and verify configuration settings for {{Assignment: organization-defined information system components}}. The organization employs {{Assignment: organization-defined security safeguards}} to respond to unauthorized changes to {{Assignment: organization-defined configuration settings}}.' WHERE [Requirement_Id] = 10869
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Configures the information system to provide only essential capabilities; and b. Prohibits or restricts the use of the following functions, ports, protocols, and/or services: {{Assignment: organization-defined prohibited or restricted functions, ports, protocols, and/or services}}.' WHERE [Requirement_Id] = 10870
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews the information system {{Assignment: organization-defined frequency}} to identify unnecessary and/or non-secure functions, ports, protocols, and services; and (b) Disables {{Assignment: organization-defined functions, ports, protocols, and services within the information system deemed to be unnecessary and/or non-secure}}. The information system prevents program execution in accordance with {{Selection (one or more): [Assignment: organization-defined policies regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage}}.' WHERE [Requirement_Id] = 10871
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs not authorized to execute on the information system}}; (b) Employs an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the information system; and (c) Reviews and updates the list of unauthorized software programs {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10872
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs authorized to execute on the information system}}; (b) Employs a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the information system; and (c) Reviews and updates the list of authorized software programs {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10873
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents an inventory of information system components that: 1. Accurately reflects the current information system; 2. Includes all components within the authorization boundary of the information system; 3. Is at the level of granularity deemed necessary for tracking and reporting; and 4. Includes {{Assignment: organization-defined information deemed necessary to achieve effective information system component accountability}}; and b. Reviews and updates the information system component inventory {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10874
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization updates the inventory of information system components as an integral part of component installations, removals, and information system updates. The organization: (a) Employs automated mechanisms {{Assignment: organization-defined frequency}} to detect the presence of unauthorized hardware, software, and firmware components within the information system; and (b) Takes the following actions when unauthorized components are detected: {{Selection (one or more): disables network access by such components; isolates the components; notifies [Assignment: organization-defined personnel or roles]}}. The organization verifies that all components within the authorization boundary of the information system are not duplicated in other information system inventories.' WHERE [Requirement_Id] = 10875
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to help maintain an up-to-date, complete, accurate, and readily available inventory of information system components. The organization includes in the information system component inventory information, a means for identifying by {{Selection (one or more): name; position; role}}, individuals responsible/accountable for administering those components.' WHERE [Requirement_Id] = 10876
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes assessed component configurations and any approved deviations to current deployed configurations in the information system component inventory. The organization provides a centralized repository for the inventory of information system components. The organization employs automated mechanisms to support tracking of information system components by geographic location. The organization: (a) Assigns {{Assignment: organization-defined acquired information system components}} to an information system; and (b) Receives an acknowledgement from the information system owner of this assignment.' WHERE [Requirement_Id] = 10877
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes the following restrictions on the use of open source software: {{Assignment: organization-defined restrictions}}.' WHERE [Requirement_Id] = 10881
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined policies}} governing the installation of software by users; b. Enforces software installation policies through {{Assignment: organization-defined methods}}; and c. Monitors policy compliance at {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10882
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the unauthorized installation of software is detected. The information system prohibits user installation of software without explicit privileged status.' WHERE [Requirement_Id] = 10883
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A contingency planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls; and b. Reviews and updates the current: 1. Contingency planning policy {{Assignment: organization-defined frequency}}; and 2. Contingency planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10884
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a contingency plan for the information system that: 1. Identifies essential missions and business functions and associated contingency requirements; 2. Provides recovery objectives, restoration priorities, and metrics; 3. Addresses contingency roles, responsibilities, assigned individuals with contact information; 4. Addresses maintaining essential missions and business functions despite an information system disruption, compromise, or failure; 5. Addresses eventual, full information system restoration without deterioration of the security safeguards originally planned and implemented; and 6. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the contingency plan to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; c. Coordinates contingency planning activities with incident handling activities; d. Reviews the contingency plan for the information system {{Assignment: organization-defined frequency}}; e. Updates the contingency plan to address changes to the organization, information system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing; f. Communicates contingency plan changes to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; and g. Protects the contingency plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 10885
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates contingency plan development with organizational elements responsible for related plans. The organization plans for the resumption of essential missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation. The organization identifies critical information system assets supporting essential missions and business functions.' WHERE [Requirement_Id] = 10886
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization conducts capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations. The organization plans for the resumption of all missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation. The organization plans for the continuance of essential missions and business functions with little or no loss of operational continuity and sustains that continuity until full information system restoration at primary processing and/or storage sites.' WHERE [Requirement_Id] = 10887
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides contingency training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming a contingency role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 10889
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Tests the contingency plan for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the effectiveness of the plan and the organizational readiness to execute the plan; b. Reviews the contingency plan test results; and c. Initiates corrective actions, if needed.' WHERE [Requirement_Id] = 10892
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes an alternate processing site including necessary agreements to permit the transfer and resumption of {{Assignment: organization-defined information system operations}} for essential missions/business functions within {{Assignment: organization-defined time period consistent with recovery time and recovery point objectives}} when the primary processing capabilities are unavailable; b. Ensures that equipment and supplies required to transfer and resume operations are available at the alternate processing site or contracts are in place to support delivery to the site within the organization-defined time period for transfer/resumption; and c. Ensures that the alternate processing site provides information security safeguards equivalent to that of the primary site. The organization identifies an alternate processing site that is separated from the primary processing site to reduce susceptibility to the same threats. The organization identifies potential accessibility problems to the alternate processing site in the event of an area-wide disruption or disaster and outlines explicit mitigation actions. The organization develops alternate processing site agreements that contain priority-of-service provisions in accordance with organizational availability requirements (including recovery time objectives).' WHERE [Requirement_Id] = 10898
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes alternate telecommunications services including necessary agreements to permit the resumption of {{Assignment: organization-defined information system operations}} for essential missions and business functions within {{Assignment: organization-defined time period}} when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites. The organization: (a) Develops primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with organizational availability requirements (including recovery time objectives); and (b) Requests Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness in the event that the primary and/or alternate telecommunications services are provided by a common carrier. The organization obtains alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.' WHERE [Requirement_Id] = 10901
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization obtains alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats. The organization: (a) Requires primary and alternate telecommunications service providers to have contingency plans; (b) Reviews provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtains evidence of contingency testing/training by providers {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10902
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests alternate telecommunication services {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10903
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts backups of user-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; b. Conducts backups of system-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; c. Conducts backups of information system documentation including security-related documentation {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; and d. Protects the confidentiality, integrity, and availability of backup information at storage locations.' WHERE [Requirement_Id] = 10904
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests backup information {{Assignment: organization-defined frequency}} to verify media reliability and information integrity.' WHERE [Requirement_Id] = 10905
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization uses a sample of backup information in the restoration of selected information system functions as part of contingency plan testing. The organization stores backup copies of {{Assignment: organization-defined critical information system software and other security-related information}} in a separate facility or in a fire-rated container that is not collocated with the operational system. The organization transfers information system backup information to the alternate storage site {{Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives}}.' WHERE [Requirement_Id] = 10906
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization accomplishes information system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations. The organization enforces dual authorization for the deletion or destruction of {{Assignment: organization-defined backup information}}.' WHERE [Requirement_Id] = 10907
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to restore information system components within {{Assignment: organization-defined restoration time-periods}} from configuration-controlled and integrity-protected information representing a known, operational state for the components.' WHERE [Requirement_Id] = 10910
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to employ {{Assignment: organization-defined alternative communications protocols}} in support of maintaining continuity of operations.' WHERE [Requirement_Id] = 10912
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when {{Assignment: organization-defined conditions}} are detected, enters a safe mode of operation with {{Assignment: organization-defined restrictions of safe mode of operation}}.' WHERE [Requirement_Id] = 10913
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined alternative or supplemental security mechanisms}} for satisfying {{Assignment: organization-defined security functions}} when the primary means of implementing the security function is unavailable or compromised.' WHERE [Requirement_Id] = 10914
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An identification and authentication policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the identification and authentication policy and associated identification and authentication controls; and b. Reviews and updates the current: 1. Identification and authentication policy {{Assignment: organization-defined frequency}}; and 2. Identification and authentication procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10915
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for network access to non-privileged accounts. The information system implements multifactor authentication for local access to privileged accounts. The information system implements replay-resistant authentication mechanisms for network access to privileged accounts. The information system implements multifactor authentication for remote access to privileged and non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 10917
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires individuals to be authenticated with an individual authenticator when a group authenticator is employed. The information system implements multifactor authentication for network access to privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}. The information system implements multifactor authentication for network access to non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}. The information system provides a single sign-on capability for {{Assignment: organization-defined list of information system accounts and services}}. The information system implements {{Assignment: organization-defined out-of-band authentication}} under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 10919
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates {{Assignment: organization-defined specific and/or types of devices}} before establishing a {{Selection (one or more): local; remote; network}} connection.' WHERE [Requirement_Id] = 10920
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system authenticates {{Assignment: organization-defined specific devices and/or types of devices}} before establishing {{Selection (one or more): local; remote; network}} connection using bidirectional authentication that is cryptographically based. The organization: (a) Standardizes dynamic address allocation lease information and the lease duration assigned to devices in accordance with {{Assignment: organization-defined lease information and lease duration}}; and (b) Audits lease information when assigned to a device. The organization ensures that device identification and authentication based on attestation is handled by {{Assignment: organization-defined configuration management process}}.' WHERE [Requirement_Id] = 10921
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system identifiers by: a. Receiving authorization from {{Assignment: organization-defined personnel or roles}} to assign an individual, group, role, or device identifier; b. Selecting an identifier that identifies an individual, group, role, or device; c. Assigning the identifier to the intended individual, group, role, or device; d. Preventing reuse of identifiers for {{Assignment: organization-defined time period}}; and e. Disabling the identifier after {{Assignment: organization-defined time period of inactivity}}.' WHERE [Requirement_Id] = 10922
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the use of information system account identifiers that are the same as public identifiers for individual electronic mail accounts. The organization requires that the registration process to receive an individual identifier includes supervisor authorization. The organization requires multiple forms of certification of individual identification such as documentary evidence or a combination of documents and biometrics be presented to the registration authority. The organization manages individual identifiers by uniquely identifying each individual as {{Assignment: organization-defined characteristic identifying individual status}}. The information system dynamically manages identifiers. The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of identifiers. The organization requires that the registration process to receive an individual identifier be conducted in person before a designated registration authority.' WHERE [Requirement_Id] = 10923
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, or device receiving the authenticator; b. Establishing initial authenticator content for authenticators defined by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost/compromised or damaged authenticators, and for revoking authenticators; e. Changing default content of authenticators prior to information system installation; f. Establishing minimum and maximum lifetime restrictions and reuse conditions for authenticators; g. Changing/refreshing authenticators {{Assignment: organization-defined time period by authenticator type}}; h. Protecting authenticator content from unauthorized disclosure and modification; i. Requiring individuals to take, and having devices implement, specific security safeguards to protect authenticators; and j. Changing authenticators for group/role accounts when membership to those accounts changes. The information system, for password-based authentication: (a) Enforces minimum password complexity of {{Assignment: organization-defined requirements for case sensitivity, number of characters, mix of upper-case letters, lower-case letters, numbers, and special characters, including minimum requirements for each type}}; (b) Enforces at least the following number of changed characters when new passwords are created: {{Assignment: organization-defined number}}; (c) Stores and transmits only encrypted representations of passwords; (d) Enforces password minimum and maximum lifetime restrictions of {{Assignment: organization-defined numbers for lifetime minimum, lifetime maximum}}; (e) Prohibits password reuse for {{Assignment: organization-defined number}} generations; and (f) Allows the use of a temporary password for system logons with an immediate change to a permanent password. The information system, for hardware token-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined token quality requirements}}.' WHERE [Requirement_Id] = 10924
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for PKI-based authentication: (a) Validates certifications by constructing and verifying a certification path to an accepted trust anchor including checking certificate status information; (b) Enforces authorized access to the corresponding private key; (c) Maps the authenticated identity to the account of the individual or group; and (d) Implements a local cache of revocation data to support path discovery and validation in case of inability to access revocation information via the network. The organization requires that the registration process to receive {{Assignment: organization-defined types of and/or specific authenticators}} be conducted {{Selection: in person; by a trusted third party}} before {{Assignment: organization-defined registration authority}} with authorization by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 10925
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to determine if password authenticators are sufficiently strong to satisfy {{Assignment: organization-defined requirements}}. The organization requires developers/installers of information system components to provide unique authenticators or change default authenticators prior to delivery/installation. The organization protects authenticators commensurate with the security category of the information to which use of the authenticator permits access. The organization ensures that unencrypted static authenticators are not embedded in applications or access scripts or stored on function keys. The organization implements {{Assignment: organization-defined security safeguards}} to manage the risk of compromise due to individuals having accounts on multiple information systems. The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of credentials. The information system dynamically provisions identities. The information system, for biometric-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined biometric quality requirements}}. The information system prohibits the use of cached authenticators after {{Assignment: organization-defined time period}}. The organization, for PKI-based authentication, employs a deliberate organization-wide methodology for managing the content of PKI trust stores installed across all platforms including networks, operating systems, browsers, and applications. The organization uses only FICAM-approved path discovery and validation products and services.' WHERE [Requirement_Id] = 10926
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates non-organizational users (or processes acting on behalf of non-organizational users). The information system accepts and electronically verifies Personal Identity Verification (PIV) credentials from other federal agencies. The information system accepts only FICAM-approved third-party credentials. The organization employs only FICAM-approved information system components in {{Assignment: organization-defined information systems}} to accept third-party credentials. The information system conforms to FICAM-issued profiles.' WHERE [Requirement_Id] = 10929
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies and authenticates {{Assignment: organization-defined information system services}} using {{Assignment: organization-defined security safeguards}}. The organization ensures that service providers receive, validate, and transmit identification and authentication information. The organization ensures that identification and authentication decisions are transmitted between {{Assignment: organization-defined services}} consistent with organizational policies.' WHERE [Requirement_Id] = 10931
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that individuals accessing the information system employ {{Assignment: organization-defined supplemental authentication techniques or mechanisms}} under specific {{Assignment: organization-defined circumstances or situations}}.' WHERE [Requirement_Id] = 10932
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires users and devices to re-authenticate when {{Assignment: organization-defined circumstances or situations requiring re-authentication}}.' WHERE [Requirement_Id] = 10933
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An incident response policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the incident response policy and associated incident response controls; and b. Reviews and updates the current: 1. Incident response policy {{Assignment: organization-defined frequency}}; and 2. Incident response procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10934
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides incident response training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming an incident response role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 10935
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests the incident response capability for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the incident response effectiveness and documents the results. The organization coordinates incident response testing with organizational elements responsible for related plans.' WHERE [Requirement_Id] = 10937
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes dynamic reconfiguration of {{Assignment: organization-defined information system components}} as part of the incident response capability. The organization identifies {{Assignment: organization-defined classes of incidents}} and {{Assignment: organization-defined actions to take in response to classes of incidents}} to ensure continuation of organizational missions and business functions. The organization implements a configurable capability to automatically disable the information system if {{Assignment: organization-defined security violations}} are detected. The organization implements incident handling capability for insider threats. The organization coordinates incident handling capability for insider threats across {{Assignment: organization-defined components or elements of the organization}}. The organization coordinates with {{Assignment: organization-defined external organizations}} to correlate and share {{Assignment: organization-defined incident information}} to achieve a cross-organization perspective on incident awareness and more effective incident responses. The organization employs {{Assignment: organization-defined dynamic response capabilities}} to effectively respond to security incidents. The organization coordinates incident handling activities involving supply chain events with other organizations involved in the supply chain.' WHERE [Requirement_Id] = 10942
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires personnel to report suspected security incidents to the organizational incident response capability within {{Assignment: organization-defined time period}}; and b. Reports security incident information to {{Assignment: organization-defined authorities}}.' WHERE [Requirement_Id] = 10945
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reports information system vulnerabilities associated with reported security incidents to {{Assignment: organization-defined personnel or roles}}. The organization provides security incident information to other organizations involved in the supply chain for information systems or information system components related to the incident.' WHERE [Requirement_Id] = 10947
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an incident response plan that: 1. Provides the organization with a roadmap for implementing its incident response capability; 2. Describes the structure and organization of the incident response capability; 3. Provides a high-level approach for how the incident response capability fits into the overall organization; 4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions; 5. Defines reportable incidents; 6. Provides metrics for measuring the incident response capability within the organization; 7. Defines the resources and management support needed to effectively maintain and mature an incident response capability; and 8. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the incident response plan to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; c. Reviews the incident response plan {{Assignment: organization-defined frequency}}; d. Updates the incident response plan to address system/organizational changes or problems encountered during plan implementation, execution, or testing; e. Communicates incident response plan changes to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; and f. Protects the incident response plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 10951
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization responds to information spills by: a. Identifying the specific information involved in the information system contamination; b. Alerting {{Assignment: organization-defined personnel or roles}} of the information spill using a method of communication not associated with the spill; c. Isolating the contaminated information system or system component; d. Eradicating the information from the contaminated information system or component; e. Identifying other information systems or system components that may have been subsequently contaminated; and f. Performing other {{Assignment: organization-defined actions}}. The organization assigns {{Assignment: organization-defined personnel or roles}} with responsibility for responding to information spills. The organization provides information spillage response training {{Assignment: organization-defined frequency}}. The organization implements {{Assignment: organization-defined procedures}} to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions. The organization employs {{Assignment: organization-defined security safeguards}} for personnel exposed to information not within assigned access authorizations.' WHERE [Requirement_Id] = 10952
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system maintenance policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system maintenance policy and associated system maintenance controls; and b. Reviews and updates the current: 1. System maintenance policy {{Assignment: organization-defined frequency}}; and 2. System maintenance procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10954
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Schedules, performs, documents, and reviews records of maintenance and repairs on information system components in accordance with manufacturer or vendor specifications and/or organizational requirements; b. Approves and monitors all maintenance activities, whether performed on site or remotely and whether the equipment is serviced on site or removed to another location; c. Requires that {{Assignment: organization-defined personnel or roles}} explicitly approve the removal of the information system or system components from organizational facilities for off-site maintenance or repairs; d. Sanitizes equipment to remove all information from associated media prior to removal from organizational facilities for off-site maintenance or repairs; e. Checks all potentially impacted security controls to verify that the controls are still functioning properly following maintenance or repair actions; and f. Includes {{Assignment: organization-defined maintenance-related information}} in organizational maintenance records.' WHERE [Requirement_Id] = 10955
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prevents the unauthorized removal of maintenance equipment containing organizational information by: (a) Verifying that there is no organizational information contained on the equipment; (b) Sanitizing or destroying the equipment; (c) Retaining the equipment within the facility; or (d) Obtaining an exemption from {{Assignment: organization-defined personnel or roles}} explicitly authorizing removal of the equipment from the facility.' WHERE [Requirement_Id] = 10958
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Audits nonlocal maintenance and diagnostic sessions {{Assignment: organization-defined audit events}}; and (b) Reviews the records of the maintenance and diagnostic sessions. The organization protects nonlocal maintenance sessions by: (a) Employing {{Assignment: organization-defined authenticators that are replay resistant}}; and (b) Separating the maintenance sessions from other network sessions with the information system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths based upon encryption. The organization: (a) Requires the approval of each nonlocal maintenance session by {{Assignment: organization-defined personnel or roles}}; and (b) Notifies {{Assignment: organization-defined personnel or roles}} of the date and time of planned nonlocal maintenance. The information system implements cryptographic mechanisms to protect the integrity and confidentiality of nonlocal maintenance and diagnostic communications. The information system implements remote disconnect verification at the termination of nonlocal maintenance and diagnostic sessions.' WHERE [Requirement_Id] = 10963
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization obtains maintenance support and/or spare parts for {{Assignment: organization-defined information system components}} within {{Assignment: organization-defined time period}} of failure.' WHERE [Requirement_Id] = 10967
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs preventive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}. The organization performs predictive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}. The organization employs automated mechanisms to transfer predictive maintenance data to a computerized maintenance management system.' WHERE [Requirement_Id] = 10968
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A media protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the media protection policy and associated media protection controls; and b. Reviews and updates the current: 1. Media protection policy {{Assignment: organization-defined frequency}}; and 2. Media protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10969
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts access to {{Assignment: organization-defined types of digital and/or non-digital media}} to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 10970
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Marks information system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempts {{Assignment: organization-defined types of information system media}} from marking as long as the media remain within {{Assignment: organization-defined controlled areas}}.' WHERE [Requirement_Id] = 10971
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Physically controls and securely stores {{Assignment: organization-defined types of digital and/or non-digital media}} within {{Assignment: organization-defined controlled areas}}; and b. Protects information system media until the media are destroyed or sanitized using approved equipment, techniques, and procedures.' WHERE [Requirement_Id] = 10972
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Protects and controls {{Assignment: organization-defined types of information system media}} during transport outside of controlled areas using {{Assignment: organization-defined security safeguards}}; b. Maintains accountability for information system media during transport outside of controlled areas; c. Documents activities associated with the transport of information system media; and d. Restricts the activities associated with the transport of information system media to authorized personnel. The information system implements cryptographic mechanisms to protect the confidentiality and integrity of information stored on digital media during transport outside of controlled areas.' WHERE [Requirement_Id] = 10974
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Sanitizes {{Assignment: organization-defined information system media}} prior to disposal, release out of organizational control, or release for reuse using {{Assignment: organization-defined sanitization techniques and procedures}} in accordance with applicable federal and organizational standards and policies; and b. Employs sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.' WHERE [Requirement_Id] = 10977
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews, approves, tracks, documents, and verifies media sanitization and disposal actions. The organization tests sanitization equipment and procedures {{Assignment: organization-defined frequency}} to verify that the intended sanitization is being achieved. The organization applies nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the information system under the following circumstances: {{Assignment: organization-defined circumstances requiring sanitization of portable storage devices}}.' WHERE [Requirement_Id] = 10978
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the sanitization of {{Assignment: organization-defined information system media}}. The organization provides the capability to purge/wipe information from {{Assignment: organization-defined information systems, system components, or devices}} either remotely or under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 10979
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of {{Assignment: organization-defined types of information system media}} on {{Assignment: organization-defined information systems or system components}} using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 10980
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined information system media downgrading process}} that includes employing downgrading mechanisms with {{Assignment: organization-defined strength and integrity}}; b. Ensures that the information system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information; c. Identifies {{Assignment: organization-defined information system media requiring downgrading}}; and d. Downgrades the identified information system media using the established process. The organization documents information system media downgrading actions. The organization employs {{Assignment: organization-defined tests}} of downgrading equipment and procedures to verify correct performance {{Assignment: organization-defined frequency}}. The organization downgrades information system media containing {{Assignment: organization-defined Controlled Unclassified Information (CUI)}} prior to public release in accordance with applicable federal and organizational standards and policies. The organization downgrades information system media containing classified information prior to release to individuals without required access authorizations in accordance with NSA standards and policies.' WHERE [Requirement_Id] = 10983
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A physical and environmental protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the physical and environmental protection policy and associated physical and environmental protection controls; and b. Reviews and updates the current: 1. Physical and environmental protection policy {{Assignment: organization-defined frequency}}; and 2. Physical and environmental protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10984
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, approves, and maintains a list of individuals with authorized access to the facility where the information system resides; b. Issues authorization credentials for facility access; c. Reviews the access list detailing authorized facility access by individuals {{Assignment: organization-defined frequency}}; and d. Removes individuals from the facility access list when access is no longer required.' WHERE [Requirement_Id] = 10985
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes physical access to the facility where the information system resides based on position or role. The organization requires two forms of identification from {{Assignment: organization-defined list of acceptable forms of identification}} for visitor access to the facility where the information system resides. The organization restricts unescorted access to the facility where the information system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 10986
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Enforces physical access authorizations at {{Assignment: organization-defined entry/exit points to the facility where the information system resides}} by; 1. Verifying individual access authorizations before granting access to the facility; and 2. Controlling ingress/egress to the facility using {{Selection (one or more): [Assignment: organization-defined physical access control systems/devices]; guards}}; b. Maintains physical access audit logs for {{Assignment: organization-defined entry/exit points}}; c. Provides {{Assignment: organization-defined security safeguards}} to control access to areas within the facility officially designated as publicly accessible; d. Escorts visitors and monitors visitor activity {{Assignment: organization-defined circumstances requiring visitor escorts and monitoring}}; e. Secures keys, combinations, and other physical access devices; f. Inventories {{Assignment: organization-defined physical access devices}} every {{Assignment: organization-defined frequency}}; and g. Changes combinations and keys {{Assignment: organization-defined frequency}} and/or when keys are lost, combinations are compromised, or individuals are transferred or terminated.' WHERE [Requirement_Id] = 10987
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces physical access authorizations to the information system in addition to the physical access controls for the facility at {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 10988
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs security checks {{Assignment: organization-defined frequency}} at the physical boundary of the facility or information system for unauthorized exfiltration of information or removal of information system components. The organization employs guards and/or alarms to monitor every physical access point to the facility where the information system resides 24 hours per day, 7 days per week. The organization uses lockable physical casings to protect {{Assignment: organization-defined information system components}} from unauthorized physical access. The organization employs {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization-defined hardware components}} within the information system. The organization employs a penetration testing process that includes {{Assignment: organization-defined frequency}}, unannounced attempts to bypass or circumvent security controls associated with physical access points to the facility.' WHERE [Requirement_Id] = 10989
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization controls physical access to {{Assignment: organization-defined information system distribution and transmission lines}} within organizational facilities using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 10990
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Ensures that only authorized individuals receive output from the device. The information system: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Links individual identity to receipt of the output from the device. The organization marks {{Assignment: organization-defined information system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 10992
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors physical access to the facility where the information system resides to detect and respond to physical security incidents; b. Reviews physical access logs {{Assignment: organization-defined frequency}} and upon occurrence of {{Assignment: organization-defined events or potential indications of events}}; and c. Coordinates results of reviews and investigations with the organizational incident response capability.' WHERE [Requirement_Id] = 10993
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors physical access to the information system in addition to the physical access monitoring of the facility as {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 10995
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to recognize {{Assignment: organization-defined classes/types of intrusions}} and initiate {{Assignment: organization-defined response actions}}. The organization employs video surveillance of {{Assignment: organization-defined operational areas}} and retains video recordings for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 10996
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains visitor access records to the facility where the information system resides for {{Assignment: organization-defined time period}}; and b. Reviews visitor access records {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 10997
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs redundant power cabling paths that are physically separated by {{Assignment: organization-defined distance}}. The organization employs automatic voltage controls for {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 11000
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Provides the capability of shutting off power to the information system or individual system components in emergency situations; b. Places emergency shutoff switches or devices in {{Assignment: organization-defined location by information system or system component}} to facilitate safe and easy access for personnel; and c. Protects emergency power shutoff capability from unauthorized activation.' WHERE [Requirement_Id] = 11001
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a short-term uninterruptible power supply to facilitate {{Selection (one or more): an orderly shutdown of the information system; transition of the information system to long-term alternate power}} in the event of a primary power source loss.' WHERE [Requirement_Id] = 11002
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a long-term alternate power supply for the information system that is: (a) Self-contained; (b) Not reliant on external power generation; and (c) Capable of maintaining {{Selection: minimally required operational capability; full operational capability}} in the event of an extended loss of the primary power source.' WHERE [Requirement_Id] = 11004
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire detection devices/systems for the information system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire. The organization employs fire suppression devices/systems for the information system that provide automatic notification of any activation to {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}}.' WHERE [Requirement_Id] = 11009
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that the facility undergoes {{Assignment: organization-defined frequency}} inspections by authorized and qualified inspectors and resolves identified deficiencies within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11010
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains temperature and humidity levels within the facility where the information system resides at {{Assignment: organization-defined acceptable levels}}; and b. Monitors temperature and humidity levels {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11011
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to detect the presence of water in the vicinity of the information system and alerts {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 11014
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes, monitors, and controls {{Assignment: organization-defined types of information system components}} entering and exiting the facility and maintains records of those items.' WHERE [Requirement_Id] = 11015
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs {{Assignment: organization-defined security controls}} at alternate work sites; b. Assesses as feasible, the effectiveness of security controls at alternate work sites; and c. Provides a means for employees to communicate with information security personnel in case of security incidents or problems.' WHERE [Requirement_Id] = 11016
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization positions information system components within the facility to minimize potential damage from {{Assignment: organization-defined physical and environmental hazards}} and to minimize the opportunity for unauthorized access.' WHERE [Requirement_Id] = 11017
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs {{Assignment: organization-defined asset location technologies}} to track and monitor the location and movement of {{Assignment: organization-defined assets}} within {{Assignment: organization-defined controlled areas}}; and b. Ensures that asset location technologies are employed in accordance with applicable federal laws, Executive Orders, directives, regulations, policies, standards, and guidance.' WHERE [Requirement_Id] = 11020
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security planning policy and associated security planning controls; and b. Reviews and updates the current: 1. Security planning policy {{Assignment: organization-defined frequency}}; and 2. Security planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11021
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security plan for the information system that: 1. Is consistent with the organization’s enterprise architecture; 2. Explicitly defines the authorization boundary for the system; 3. Describes the operational context of the information system in terms of missions and business processes; 4. Provides the security categorization of the information system including supporting rationale; 5. Describes the operational environment for the information system and relationships with or connections to other information systems; 6. Provides an overview of the security requirements for the system; 7. Identifies any relevant overlays, if applicable; 8. Describes the security controls in place or planned for meeting those requirements including a rationale for the tailoring and supplementation decisions; and 9. Is reviewed and approved by the authorizing official or designated representative prior to plan implementation; b. Distributes copies of the security plan and communicates subsequent changes to the plan to {{Assignment: organization-defined personnel or roles}}; c. Reviews the security plan for the information system {{Assignment: organization-defined frequency}}; d. Updates the plan to address changes to the information system/environment of operation or problems identified during plan implementation or security control assessments; and e. Protects the security plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 11022
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans and coordinates security-related activities affecting the information system with {{Assignment: organization-defined individuals or groups}} before conducting such activities in order to reduce the impact on other organizational entities.' WHERE [Requirement_Id] = 11023
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and makes readily available to individuals requiring access to the information system, the rules that describe their responsibilities and expected behavior with regard to information and information system usage; b. Receives a signed acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the information system; c. Reviews and updates the rules of behavior {{Assignment: organization-defined frequency}}; and d. Requires individuals who have signed a previous version of the rules of behavior to read and resign when the rules of behavior are revised/updated.' WHERE [Requirement_Id] = 11024
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security Concept of Operations (CONOPS) for the information system containing at a minimum, how the organization intends to operate the system from the perspective of information security; and b. Reviews and updates the CONOPS {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11026
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an information security architecture for the information system that: 1. Describes the overall philosophy, requirements, and approach to be taken with regard to protecting the confidentiality, integrity, and availability of organizational information; 2. Describes how the information security architecture is integrated into and supports the enterprise architecture; and 3. Describes any information security assumptions about, and dependencies on, external services; b. Reviews and updates the information security architecture {{Assignment: organization-defined frequency}} to reflect updates in the enterprise architecture; and c. Ensures that planned information security architecture changes are reflected in the security plan, the security Concept of Operations (CONOPS), and organizational procurements/acquisitions.' WHERE [Requirement_Id] = 11027
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization designs its security architecture using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security safeguards operate in a coordinated and mutually reinforcing manner. The organization requires that {{Assignment: organization-defined security safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 11028
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization centrally manages {{Assignment: organization-defined security controls and related processes}}.' WHERE [Requirement_Id] = 11029
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and disseminates an organization-wide information security program plan that: 1. Provides an overview of the requirements for the security program and a description of the security program management controls and common controls in place or planned for meeting those requirements; 2. Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 3. Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; b. Reviews the organization-wide information security program plan {{Assignment: organization-defined frequency}}; c. Updates the plan to address organizational changes and problems identified during plan implementation or security control assessments; and d. Protects the information security program plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 11030
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A personnel security policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the personnel security policy and associated personnel security controls; and b. Reviews and updates the current: 1. Personnel security policy {{Assignment: organization-defined frequency}}; and 2. Personnel security procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11046
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a risk designation to all organizational positions; b. Establishes screening criteria for individuals filling those positions; and c. Reviews and updates position risk designations {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11047
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Screens individuals prior to authorizing access to the information system; and b. Rescreens individuals according to {{Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of such rescreening}}.' WHERE [Requirement_Id] = 11048
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that individuals accessing an information system processing, storing, or transmitting classified information are cleared and indoctrinated to the highest classification level of the information to which they have access on the system. The organization ensures that individuals accessing an information system processing, storing, or transmitting types of classified information which require formal indoctrination, are formally indoctrinated for all of the relevant types of information to which they have access on the system. The organization ensures that individuals accessing an information system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 11049
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization, upon termination of individual employment: a. Disables information system access within {{Assignment: organization-defined time period}}; b. Terminates/revokes any authenticators/credentials associated with the individual; c. Conducts exit interviews that include a discussion of {{Assignment: organization-defined information security topics}}; d. Retrieves all security-related organizational information system-related property; e. Retains access to organizational information and information systems formerly controlled by terminated individual; and f. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11050
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to notify {{Assignment: organization-defined personnel or roles}} upon termination of an individual.' WHERE [Requirement_Id] = 11051
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and confirms ongoing operational need for current logical and physical access authorizations to information systems/facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiates {{Assignment: organization-defined transfer or reassignment actions}} within {{Assignment: organization-defined time period following the formal transfer action}}; c. Modifies access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11053
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents access agreements for organizational information systems; b. Reviews and updates the access agreements {{Assignment: organization-defined frequency}}; and c. Ensures that individuals requiring access to organizational information and information systems: 1. Sign appropriate access agreements prior to being granted access; and 2. Re-sign access agreements to maintain access to organizational information systems when access agreements have been updated or {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11054
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes personnel security requirements including security roles and responsibilities for third-party providers; b. Requires third-party providers to comply with personnel security policies and procedures established by the organization; c. Documents personnel security requirements; d. Requires third-party providers to notify {{Assignment: organization-defined personnel or roles}} of any personnel transfers or terminations of third-party personnel who possess organizational credentials and/or badges, or who have information system privileges within {{Assignment: organization-defined time period}}; and e. Monitors provider compliance.' WHERE [Requirement_Id] = 11056
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs a formal sanctions process for individuals failing to comply with established information security policies and procedures; and b. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}} when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.' WHERE [Requirement_Id] = 11057
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A risk assessment policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the risk assessment policy and associated risk assessment controls; and b. Reviews and updates the current: 1. Risk assessment policy {{Assignment: organization-defined frequency}}; and 2. Risk assessment procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11058
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts an assessment of risk, including the likelihood and magnitude of harm, from the unauthorized access, use, disclosure, disruption, modification, or destruction of the information system and the information it processes, stores, or transmits; b. Documents risk assessment results in {{Selection: security plan; risk assessment report; [Assignment: organization-defined document]}}; c. Reviews risk assessment results {{Assignment: organization-defined frequency}}; d. Disseminates risk assessment results to {{Assignment: organization-defined personnel or roles}}; and e. Updates the risk assessment {{Assignment: organization-defined frequency}} or whenever there are significant changes to the information system or environment of operation (including the identification of new threats and vulnerabilities), or other conditions that may impact the security state of the system.' WHERE [Requirement_Id] = 11060
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Scans for vulnerabilities in the information system and hosted applications {{Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process}} and when new vulnerabilities potentially affecting the system/applications are identified and reported; b. Employs vulnerability scanning tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for: 1. Enumerating platforms, software flaws, and improper configurations; 2. Formatting checklists and test procedures; and 3. Measuring vulnerability impact; c. Analyzes vulnerability scan reports and results from security control assessments; d. Remediates legitimate vulnerabilities {{Assignment: organization-defined response times}} in accordance with an organizational assessment of risk; and e. Shares information obtained from the vulnerability scanning process and security control assessments with {{Assignment: organization-defined personnel or roles}} to help eliminate similar vulnerabilities in other information systems (i.e., systemic weaknesses or deficiencies).' WHERE [Requirement_Id] = 11061
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs vulnerability scanning tools that include the capability to readily update the information system vulnerabilities to be scanned. The organization updates the information system vulnerabilities scanned {{Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported}}. The information system implements privileged access authorization to {{Assignment: organization-identified information system components}} for selected {{Assignment: organization-defined vulnerability scanning activities}}.' WHERE [Requirement_Id] = 11062
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization determines what information about the information system is discoverable by adversaries and subsequently takes {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 11063
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a technical surveillance countermeasures survey at {{Assignment: organization-defined locations}} {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined events or indicators occur]}}.' WHERE [Requirement_Id] = 11065
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and services acquisition policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and services acquisition policy and associated system and services acquisition controls; and b. Reviews and updates the current: 1. System and services acquisition policy {{Assignment: organization-defined frequency}}; and 2. System and services acquisition procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11066
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Manages the information system using {{Assignment: organization-defined system development life cycle}} that incorporates information security considerations; b. Defines and documents information security roles and responsibilities throughout the system development life cycle; c. Identifies individuals having information security roles and responsibilities; and d. Integrates the organizational information security risk management process into system development life cycle activities.' WHERE [Requirement_Id] = 11068
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide a description of the functional properties of the security controls to be employed. The organization requires the developer of the information system, system component, or information system service to provide design and implementation information for the security controls to be employed that includes: {{Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design/implementation information]}} at {{Assignment: organization-defined level of detail}}. The organization requires the developer of the information system, system component, or information system service to identify early in the system development life cycle, the functions, ports, protocols, and services intended for organizational use.' WHERE [Requirement_Id] = 11070
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{Assignment: organization-defined state-of-the-practice system/security engineering methods, software development methods, testing/evaluation/validation techniques, and quality control processes}}. The organization requires the developer of the information system, system component, or information system service to: (a) Deliver the system, component, or service with {{Assignment; organization-defined security configurations}} implemented; and (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade. The organization: (a) Employs only government off-the-shelf (GOTS) or commercial off-the-shelf (COTS) information assurance (IA) and IA-enabled information technology products that compose an NSA-approved solution to protect classified information when the networks used to transmit the information are at a lower classification level than the information being transmitted; and (b) Ensures that these products have been evaluated and/or validated by NSA or in accordance with NSA-approved procedures. The organization: (a) Limits the use of commercially provided information assurance (IA) and IA-enabled information technology products to those products that have been successfully evaluated against a National Information Assurance partnership (NIAP)-approved Protection Profile for a specific technology type, if such a profile exists; and (b) Requires, if no NIAP-approved Protection Profile exists for a specific technology type but a commercially provided information technology product relies on cryptographic functionality to enforce its security policy, that the cryptographic module is FIPS-validated. The organization requires the developer of the information system, system component, or information system service to produce a plan for the continuous monitoring of security control effectiveness that contains {{Assignment: organization-defined level of detail}}. The organization employs only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational information systems.' WHERE [Requirement_Id] = 11071
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Obtains administrator documentation for the information system, system component, or information system service that describes: 1. Secure configuration, installation, and operation of the system, component, or service; 2. Effective use and maintenance of security functions/mechanisms; and 3. Known vulnerabilities regarding configuration and use of administrative (i.e., privileged) functions; b. Obtains user documentation for the information system, system component, or information system service that describes: 1. User-accessible security functions/mechanisms and how to effectively use those security functions/mechanisms; 2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner; and 3. User responsibilities in maintaining the security of the system, component, or service; c. Documents attempts to obtain information system, system component, or information system service documentation when such documentation is either unavailable or nonexistent and {{Assignment: organization-defined actions}} in response; d. Protects documentation as required, in accordance with the risk management strategy; and e. Distributes documentation to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 11073
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires that providers of external information system services comply with organizational information security requirements and employ {{Assignment: organization-defined security controls}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance; b. Defines and documents government oversight and user roles and responsibilities with regard to external information system services; and c. Employs {{Assignment: organization-defined processes, methods, and techniques}} to monitor security control compliance by external service providers on an ongoing basis.' WHERE [Requirement_Id] = 11075
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires providers of {{Assignment: organization-defined external information system services}} to identify the functions, ports, protocols, and other services required for the use of such services.' WHERE [Requirement_Id] = 11076
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Conducts an organizational assessment of risk prior to the acquisition or outsourcing of dedicated information security services; and (b) Ensures that the acquisition or outsourcing of dedicated information security services is approved by {{Assignment: organization-defined personnel or roles}}. The organization establishes, documents, and maintains trust relationships with external service providers based on {{Assignment: organization-defined security requirements, properties, factors, or conditions defining acceptable trust relationships}}. The organization employs {{Assignment: organization-defined security safeguards}} to ensure that the interests of {{Assignment: organization-defined external service providers}} are consistent with and reflect organizational interests. The organization restricts the location of {{Selection (one or more): information processing; information/data; information system services}} to {{Assignment: organization-defined locations}} based on {{Assignment: organization-defined requirements or conditions}}.' WHERE [Requirement_Id] = 11077
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Perform configuration management during system, component, or service {{Selection (one or more): design; development; implementation; operation}}; b. Document, manage, and control the integrity of changes to {{Assignment: organization-defined configuration items under configuration management}}; c. Implement only organization-approved changes to the system, component, or service; d. Document approved changes to the system, component, or service and the potential security impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service and report findings to {{Assignment: organization-defined personnel}}.' WHERE [Requirement_Id] = 11078
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Create and implement a security assessment plan; b. Perform {{Selection (one or more): unit; integration; system; regression}} testing/evaluation at {{Assignment: organization-defined depth and coverage}}; c. Produce evidence of the execution of the security assessment plan and the results of the security testing/evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during security testing/evaluation.' WHERE [Requirement_Id] = 11080
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to employ static code analysis tools to identify common flaws and document the results of the analysis. The organization requires the developer of the information system, system component, or information system service to perform threat and vulnerability analyses and subsequent testing/evaluation of the as-built system, component, or service. The organization: (a) Requires an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security assessment plan and the evidence produced during security testing/evaluation; and (b) Ensures that the independent agent either is provided with sufficient information to complete the verification process or has been granted the authority to obtain such information. The organization requires the developer of the information system, system component, or information system service to perform a manual code review of {{Assignment: organization-defined specific code}} using {{Assignment: organization-defined processes, procedures, and/or techniques}}. The organization requires the developer of the information system, system component, or information system service to perform penetration testing at {{Assignment: organization-defined breadth/depth}} and with {{Assignment: organization-defined constraints}}. The organization requires the developer of the information system, system component, or information system service to perform attack surface reviews. The organization requires the developer of the information system, system component, or information system service to verify that the scope of security testing/evaluation provides complete coverage of required security controls at {{Assignment: organization-defined depth of testing/evaluation}}. The organization requires the developer of the information system, system component, or information system service to employ dynamic code analysis tools to identify common flaws and document the results of the analysis.' WHERE [Requirement_Id] = 11081
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects against supply chain threats to the information system, system component, or information system service by employing {{Assignment: organization-defined security safeguards}} as part of a comprehensive, defense-in-breadth information security strategy.' WHERE [Requirement_Id] = 11082
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tailored acquisition strategies, contract tools, and procurement methods}} for the purchase of the information system, system component, or information system service from suppliers. The organization conducts a supplier review prior to entering into a contractual agreement to acquire the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to limit harm from potential adversaries identifying and targeting the organizational supply chain. The organization conducts an assessment of the information system, system component, or information system service prior to selection, acceptance, or update. The organization uses all-source intelligence analysis of suppliers and potential suppliers of the information system, system component, or information system service. The organization employs {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} in accordance with classification guides to protect supply chain-related information for the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to validate that the information system or system component received is genuine and has not been altered. The organization employs {{Selection (one or more): organizational analysis, independent third-party analysis, organizational penetration testing, independent third-party penetration testing}} of {{Assignment: organization-defined supply chain elements, processes, and actors}} associated with the information system, system component, or information system service. The organization establishes inter-organizational agreements and procedures with entities involved in the supply chain for the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to ensure an adequate supply of {{Assignment: organization-defined critical information system components}}. The organization establishes and retains unique identification of {{Assignment: organization-defined supply chain elements, processes, and actors}} for the information system, system component, or information system service. The organization establishes a process to address weaknesses or deficiencies in supply chain elements identified during independent or organizational assessments of such elements.' WHERE [Requirement_Id] = 11083
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Describes the trustworthiness required in the {{Assignment: organization-defined information system, information system component, or information system service}} supporting its critical missions/business functions; and b. Implements {{Assignment: organization-defined assurance overlay}} to achieve such trustworthiness.' WHERE [Requirement_Id] = 11084
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies critical information system components and functions by performing a criticality analysis for {{Assignment: organization-defined information systems, information system components, or information system services}} at {{Assignment: organization-defined decision points in the system development life cycle}}.' WHERE [Requirement_Id] = 11085
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires the developer of the information system, system component, or information system service to follow a documented development process that: 1. Explicitly addresses security requirements; 2. Identifies the standards and tools used in the development process; 3. Documents the specific tool options and tool configurations used in the development process; and 4. Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; and b. Reviews the development process, standards, tools, and tool options/configurations {{Assignment: organization-defined frequency}} to determine if the process, standards, tools, and tool options/configurations selected and employed can satisfy {{Assignment: organization-defined security requirements}}.' WHERE [Requirement_Id] = 11086
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery}}. The organization requires the developer of the information system, system component, or information system service to select and employ a security tracking tool for use during the development process. The organization requires the developer of the information system, system component, or information system service to perform a criticality analysis at {{Assignment: organization-defined breadth/depth}} and at {{Assignment: organization-defined decision points in the system development life cycle}}. The organization requires that developers perform threat modeling and a vulnerability analysis for the information system at {{Assignment: organization-defined breadth/depth}} that: (a) Uses {{Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels}}; (b) Employs {{Assignment: organization-defined tools and methods}}; and (c) Produces evidence that meets {{Assignment: organization-defined acceptance criteria}}. The organization requires the developer of the information system, system component, or information system service to reduce attack surfaces to {{Assignment: organization-defined thresholds}}. The organization requires the developer of the information system, system component, or information system service to implement an explicit process to continuously improve the development process. The organization requires the developer of the information system, system component, or information system service to: (a) Perform an automated vulnerability analysis using {{Assignment: organization-defined tools}}; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to {{Assignment: organization-defined personnel or roles}}. The organization requires the developer of the information system, system component, or information system service to use threat modeling and vulnerability analyses from similar systems, components, or services to inform the current development process. The organization approves, documents, and controls the use of live data in development and test environments for the information system, system component, or information system service. The organization requires the developer of the information system, system component, or information system service to provide an incident response plan. The organization requires the developer of the information system or system component to archive the system or component to be released or delivered together with the corresponding evidence supporting the final security review.' WHERE [Requirement_Id] = 11087
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide {{Assignment: organization-defined training}} on the correct use and operation of the implemented security functions, controls, and/or mechanisms.' WHERE [Requirement_Id] = 11088
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, a formal policy model describing the {{Assignment: organization-defined elements of organizational security policy}} to be enforced; and (b) Prove that the formal policy model is internally consistent and sufficient to enforce the defined elements of the organizational security policy when implemented. The organization requires the developer of the information system, system component, or information system service to: (a) Define security-relevant hardware, software, and firmware; and (b) Provide a rationale that the definition for security-relevant hardware, software, and firmware is complete. The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, a formal top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via proof to the extent feasible with additional informal demonstration as necessary, that the formal top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the formal top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the formal top-level specification is an accurate description of the implemented security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the formal top-level specification but strictly internal to the security-relevant hardware, software, and firmware. The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, an informal descriptive top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via {{Selection: informal demonstration, convincing argument with formal methods as feasible}} that the descriptive top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the descriptive top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the descriptive top-level specification is an accurate description of the interfaces to security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the descriptive top-level specification but strictly internal to the security-relevant hardware, software, and firmware. The organization requires the developer of the information system, system component, or information system service to: (a) Design and structure the security-relevant hardware, software, and firmware to use a complete, conceptually simple protection mechanism with precisely defined semantics; and (b) Internally structure the security-relevant hardware, software, and firmware with specific regard for this mechanism. The organization requires the developer of the information system, system component, or information system service to structure security-relevant hardware, software, and firmware to facilitate testing. The organization requires the developer of the information system, system component, or information system service to structure security-relevant hardware, software, and firmware to facilitate controlling access with least privilege.' WHERE [Requirement_Id] = 11090
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements a tamper protection program for the information system, system component, or information system service. The organization employs anti-tamper technologies and techniques during multiple phases in the system development life cycle including design, development, integration, operations, and maintenance. The organization inspects {{Assignment: organization-defined information systems, system components, or devices}} {{Selection (one or more): at random; at [Assignment: organization-defined frequency], upon [Assignment: organization-defined indications of need for inspection]}} to detect tampering.' WHERE [Requirement_Id] = 11091
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and implements anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the information system; and b. Reports counterfeit information system components to {{Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]}}. The organization trains {{Assignment: organization-defined personnel or roles}} to detect counterfeit information system components (including hardware, software, and firmware). The organization maintains configuration control over {{Assignment: organization-defined information system components}} awaiting service/repair and serviced/repaired components awaiting return to service. The organization disposes of information system components using {{Assignment: organization-defined techniques and methods}}. The organization scans for counterfeit information system components {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11092
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization re-implements or custom develops {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 11093
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that the developer of {{Assignment: organization-defined information system, system component, or information system service}}: a. Have appropriate access authorizations as determined by assigned {{Assignment: organization-defined official government duties}}; and b. Satisfy {{Assignment: organization-defined additional personnel screening criteria}}. The organization requires the developer of the information system, system component, or information system service take {{Assignment: organization-defined actions}} to ensure that the required access authorizations and screening criteria are satisfied.' WHERE [Requirement_Id] = 11094
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Replaces information system components when support for the components is no longer available from the developer, vendor, or manufacturer; and b. Provides justification and documents approval for the continued use of unsupported system components required to satisfy mission/business needs. The organization provides {{Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]}} for unsupported information system components.' WHERE [Requirement_Id] = 11095
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and communications protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and communications protection policy and associated system and communications protection controls; and b. Reviews and updates the current: 1. System and communications protection policy {{Assignment: organization-defined frequency}}; and 2. System and communications protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11096
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents unauthorized information transfer via shared resources in accordance with {{Assignment: organization-defined procedures}} when system processing explicitly switches between different information classification levels or security categories.' WHERE [Requirement_Id] = 11102
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against or limits the effects of the following types of denial of service attacks: {{Assignment: organization-defined types of denial of service attacks or reference to source for such information}} by employing {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 11103
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system restricts the ability of individuals to launch {{Assignment: organization-defined denial of service attacks}} against other information systems. The information system manages excess capacity, bandwidth, or other redundancy to limit the effects of information flooding denial of service attacks. The organization: (a) Employs {{Assignment: organization-defined monitoring tools}} to detect indicators of denial of service attacks against the information system; and (b) Monitors {{Assignment: organization-defined information system resources}} to determine if sufficient resources exist to prevent effective denial of service attacks.' WHERE [Requirement_Id] = 11104
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the availability of resources by allocating {{Assignment: organization-defined resources}} by {{Selection (one or more); priority; quota; [Assignment: organization-defined security safeguards]}}.' WHERE [Requirement_Id] = 11105
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Monitors and controls communications at the external boundary of the system and at key internal boundaries within the system; b. Implements subnetworks for publicly accessible system components that are {{Selection: physically; logically}} separated from internal organizational networks; and c. Connects to external networks or information systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security architecture.' WHERE [Requirement_Id] = 11106
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization limits the number of external network connections to the information system. The organization: (a) Implements a managed interface for each external telecommunication service; (b) Establishes a traffic flow policy for each managed interface; (c) Protects the confidentiality and integrity of the information being transmitted across each interface; (d) Documents each exception to the traffic flow policy with a supporting mission/business need and duration of that need; and (e) Reviews exceptions to the traffic flow policy {{Assignment: organization-defined frequency}} and removes exceptions that are no longer supported by an explicit mission/business need. The information system at managed interfaces denies network communications traffic by default and allows network communications traffic by exception (i.e., deny all, permit by exception). The information system, in conjunction with a remote device, prevents the device from simultaneously establishing non-remote connections with the system and communicating via some other connection to resources in external networks.' WHERE [Requirement_Id] = 11107
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system routes {{Assignment: organization-defined internal communications traffic}} to {{Assignment: organization-defined external networks}} through authenticated proxy servers at managed interfaces. The information system fails securely in the event of an operational failure of a boundary protection device. The organization employs boundary protection mechanisms to separate {{Assignment: organization-defined information system components}} supporting {{Assignment: organization-defined missions and/or business functions}}.' WHERE [Requirement_Id] = 11108
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Detects and denies outgoing communications traffic posing a threat to external information systems; and (b) Audits the identity of internal users associated with denied communications. The organization prevents the unauthorized exfiltration of information across managed interfaces. The information system only allows incoming communications from {{Assignment: organization-defined authorized sources}} routed to {{Assignment: organization-defined authorized destinations}}. The organization implements {{Assignment: organization-defined host-based boundary protection mechanisms}} at {{Assignment: organization-defined information system components}}. The organization isolates {{Assignment: organization-defined information security tools, mechanisms, and support components}} from other internal information system components by implementing physically separate subnetworks with managed interfaces to other components of the system. The organization protects against unauthorized physical connections at {{Assignment: organization-defined managed interfaces}}. The information system routes all networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing. The information system prevents discovery of specific system components composing a managed interface. The information system enforces adherence to protocol formats. The information system blocks both inbound and outbound communications traffic between {{Assignment: organization-defined communication clients}} that are independently configured by end users and external service providers. The information system provides the capability to dynamically isolate/segregate {{Assignment: organization-defined information system components}} from other components of the system. The information system implements separate network addresses (i.e., different subnets) to connect to systems in different security domains. The information system disables feedback to senders on protocol format validation failure.' WHERE [Requirement_Id] = 11109
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of transmitted information. The information system implements cryptographic mechanisms to {{Selection (one or more): prevent unauthorized disclosure of information; detect changes to information}} during transmission unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 11110
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system maintains the {{Selection (one or more): confidentiality; integrity}} of information during preparation for transmission and during reception. The information system implements cryptographic mechanisms to protect message externals unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}. The information system implements cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 11111
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system terminates the network connection associated with a communications session at the end of the session or after {{Assignment: organization-defined time period}} of inactivity.' WHERE [Requirement_Id] = 11112
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system establishes a trusted communications path between the user and the following security functions of the system: {{Assignment: organization-defined security functions to include at a minimum, information system authentication and re-authentication}}. The information system provides a trusted communications path that is logically isolated and distinguishable from other paths.' WHERE [Requirement_Id] = 11113
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and manages cryptographic keys for required cryptography employed within the information system in accordance with {{Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction}}.' WHERE [Requirement_Id] = 11114
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization produces, controls, and distributes symmetric cryptographic keys using {{Selection: NIST FIPS-compliant; NSA-approved}} key management technology and processes. The organization produces, controls, and distributes asymmetric cryptographic keys using {{Selection: NSA-approved key management technology and processes; approved PKI Class 3 certificates or prepositioned keying material; approved PKI Class 3 or Class 4 certificates and hardware security tokens that protect the user''s private key}}.' WHERE [Requirement_Id] = 11116
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined cryptographic uses and type of cryptography required for each use}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, and standards.' WHERE [Requirement_Id] = 11117
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prohibits remote activation of collaborative computing devices with the following exceptions: {{Assignment: organization-defined exceptions where remote activation is to be allowed}}; and b. Provides an explicit indication of use to users physically present at the devices.' WHERE [Requirement_Id] = 11119
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides physical disconnect of collaborative computing devices in a manner that supports ease of use. The organization disables or removes collaborative computing devices from {{Assignment: organization-defined information systems or information system components}} in {{Assignment: organization-defined secure work areas}}. The information system provides an explicit indication of current participants in {{Assignment: organization-defined online meetings and teleconferences}}.' WHERE [Requirement_Id] = 11120
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system associates {{Assignment: organization-defined security attributes}} with information exchanged between information systems and between system components. The information system validates the integrity of transmitted security attributes.' WHERE [Requirement_Id] = 11121
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization issues public key certificates under an {{Assignment: organization-defined certificate policy}} or obtains public key certificates from an approved service provider.' WHERE [Requirement_Id] = 11122
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system identifies {{Assignment: organization-defined unacceptable mobile code}} and takes {{Assignment: organization-defined corrective actions}}. The organization ensures that the acquisition, development, and use of mobile code to be deployed in the information system meets {{Assignment: organization-defined mobile code requirements}}. The information system prevents the download and execution of {{Assignment: organization-defined unacceptable mobile code}}. The information system prevents the automatic execution of mobile code in {{Assignment: organization-defined software applications}} and enforces {{Assignment: organization-defined actions}} prior to executing the code. The organization allows execution of permitted mobile code only in confined virtual machine environments.' WHERE [Requirement_Id] = 11124
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system invalidates session identifiers upon user logout or other session termination. The information system generates a unique session identifier for each session with {{Assignment: organization-defined randomness requirements}} and recognizes only session identifiers that are system-generated. The information system only allows the use of {{Assignment: organization-defined certificate authorities}} for verification of the establishment of protected sessions.' WHERE [Requirement_Id] = 11131
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system fails to a {{Assignment: organization-defined known-state}} for {{Assignment: organization-defined types of failures}} preserving {{Assignment: organization-defined system state information}} in failure.' WHERE [Requirement_Id] = 11132
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined information system components}} with minimal functionality and information storage.' WHERE [Requirement_Id] = 11133
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system includes: {{Assignment: organization-defined platform-independent applications}}.' WHERE [Requirement_Id] = 11135
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of {{Assignment: organization-defined information at rest}}.' WHERE [Requirement_Id] = 11136
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to prevent unauthorized disclosure and modification of {{Assignment: organization-defined information}} on {{Assignment: organization-defined information system components}}. The organization removes from online storage and stores off-line in a secure location {{Assignment: organization-defined information}}.' WHERE [Requirement_Id] = 11137
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Increasing the diversity of information technologies within organizational information systems reduces the impact of potential exploitations of specific technologies and also defends against common mode failures, including those failures induced by supply chain attacks. Diversity in information technologies also reduces the likelihood that the means adversaries use to compromise one information system component will be equally effective against other system components, thus further increasing the adversary work factor to successfully complete planned cyber attacks. An increase in diversity may add complexity and management overhead which could ultimately lead to mistakes and unauthorized configurations. Related controls: SA-12, SA-14, SC-27. The organization employs virtualization techniques to support the deployment of a diversity of operating systems and applications that are changed {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11138
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined concealment and misdirection techniques}} for {{Assignment: organization-defined information systems}} at {{Assignment: organization-defined time period}} to confuse and mislead adversaries. The organization employs {{Assignment: organization-defined techniques}} to introduce randomness into organizational operations and assets. The organization changes the location of {{Assignment: organization-defined processing and/or storage}} {{Selection: [Assignment: organization-defined time frequency]; at random time intervals}}. The organization employs realistic, but misleading information in {{Assignment: organization-defined information system components}} with regard to its security state or posture. The organization employs {{Assignment: organization-defined techniques}} to hide or conceal {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 11139
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined techniques}} to introduce randomness into organizational operations and assets. The organization changes the location of {{Assignment: organization-defined processing and/or storage}} {{Selection: [Assignment: organization-defined time frequency]; at random time intervals}}. The organization employs realistic, but misleading information in {{Assignment: organization-defined information system components}} with regard to its security state or posture. The organization employs {{Assignment: organization-defined techniques}} to hide or conceal {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 11140
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Performs a covert channel analysis to identify those aspects of communications within the information system that are potential avenues for covert {{Selection (one or more): storage; timing}} channels; and b. Estimates the maximum bandwidth of those channels. The organization tests a subset of the identified covert channels to determine which channels are exploitable. The organization reduces the maximum bandwidth for identified covert {{Selection (one or more); storage; timing}} channels to {{Assignment: organization-defined values}}. The organization measures the bandwidth of {{Assignment: organization-defined subset of identified covert channels}} in the operational environment of the information system.' WHERE [Requirement_Id] = 11141
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization partitions the information system into {{Assignment: organization-defined information system components}} residing in separate physical domains or environments based on {{Assignment: organization-defined circumstances for physical separation of components}}.' WHERE [Requirement_Id] = 11142
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system at {{Assignment: organization-defined information system components}}: a. Loads and executes the operating environment from hardware-enforced, read-only media; and b. Loads and executes {{Assignment: organization-defined applications}} from hardware-enforced, read-only media. The organization employs {{Assignment: organization-defined information system components}} with no writeable storage that is persistent across component restart or power on/off. The organization protects the integrity of information prior to storage on read-only media and controls the media after such information has been recorded onto the media. The organization: (a) Employs hardware-based, write-protect for {{Assignment: organization-defined information system firmware components}}; and (b) Implements specific procedures for {{Assignment: organization-defined authorized individuals}} to manually disable hardware write-protect for firmware modifications and re-enable the write-protect prior to returning to operational mode.' WHERE [Requirement_Id] = 11144
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization distributes {{Assignment: organization-defined processing and storage}} across multiple physical locations. The organization employs polling techniques to identify potential faults, errors, or compromises to {{Assignment: organization-defined distributed processing and storage components}}.' WHERE [Requirement_Id] = 11146
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined out-of-band channels}} for the physical delivery or electronic transmission of {{Assignment: organization-defined information, information system components, or devices}} to {{Assignment: organization-defined individuals or information systems}}. The organization employs {{Assignment: organization-defined security safeguards}} to ensure that only {{Assignment: organization-defined individuals or information systems}} receive the {{Assignment: organization-defined information, information system components, or devices}}.' WHERE [Requirement_Id] = 11147
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined operations security safeguards}} to protect key organizational information throughout the system development life cycle.' WHERE [Requirement_Id] = 11148
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements underlying hardware separation mechanisms to facilitate process separation. The information system maintains a separate execution domain for each thread in {{Assignment: organization-defined multi-threaded processing}}.' WHERE [Requirement_Id] = 11150
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects external and internal {{Assignment: organization-defined wireless links}} from {{Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks}}. The information system implements cryptographic mechanisms that achieve {{Assignment: organization-defined level of protection}} against the effects of intentional electromagnetic interference. The information system implements cryptographic mechanisms to reduce the detection potential of wireless links to {{Assignment: organization-defined level of reduction}}. The information system implements cryptographic mechanisms to identify and reject wireless transmissions that are deliberate attempts to achieve imitative or manipulative communications deception based on signal parameters. The information system implements cryptographic mechanisms to prevent the identification of {{Assignment: organization-defined wireless transmitters}} by using the transmitter signal parameters.' WHERE [Requirement_Id] = 11151
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization physically disables or removes {{Assignment: organization-defined connection ports or input/output devices}} on {{Assignment: organization-defined information systems or information system components}}.' WHERE [Requirement_Id] = 11152
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prohibits the remote activation of environmental sensing capabilities with the following exceptions: {{Assignment: organization-defined exceptions where remote activation of sensors is allowed}}; and b. Provides an explicit indication of sensor use to {{Assignment: organization-defined class of users}}. The organization ensures that the information system is configured so that data or information collected by the {{Assignment: organization-defined sensors}} is only reported to authorized individuals or roles. The organization employs the following measures: {{Assignment: organization-defined measures}}, so that data or information collected by {{Assignment: organization-defined sensors}} is only used for authorized purposes. The organization prohibits the use of devices possessing {{Assignment: organization-defined environmental sensing capabilities}} in {{Assignment: organization-defined facilities, areas, or systems}}.' WHERE [Requirement_Id] = 11153
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes usage restrictions and implementation guidance for {{Assignment: organization-defined information system components}} based on the potential to cause damage to the information system if used maliciously; and b. Authorizes, monitors, and controls the use of such components within the information system.' WHERE [Requirement_Id] = 11154
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a detonation chamber capability within {{Assignment: organization-defined information system, system component, or location}}.' WHERE [Requirement_Id] = 11155
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and information integrity policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and information integrity policy and associated system and information integrity controls; and b. Reviews and updates the current: 1. System and information integrity policy {{Assignment: organization-defined frequency}}; and 2. System and information integrity procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11156
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies, reports, and corrects information system flaws; b. Tests software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation; c. Installs security-relevant software and firmware updates within {{Assignment: organization-defined time period}} of the release of the updates; and d. Incorporates flaw remediation into the organizational configuration management process.' WHERE [Requirement_Id] = 11157
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms {{Assignment: organization-defined frequency}} to determine the state of information system components with regard to flaw remediation.' WHERE [Requirement_Id] = 11158
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Measures the time between flaw identification and flaw remediation; and (b) Establishes {{Assignment: organization-defined benchmarks}} for taking corrective actions. The organization installs {{Assignment: organization-defined security-relevant software and firmware updates}} automatically to {{Assignment: organization-defined information system components}}. The organization removes {{Assignment: organization-defined software and firmware components}} after updated versions have been installed.' WHERE [Requirement_Id] = 11160
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs malicious code protection mechanisms at information system entry and exit points to detect and eradicate malicious code; b. Updates malicious code protection mechanisms whenever new releases are available in accordance with organizational configuration management policy and procedures; c. Configures malicious code protection mechanisms to: 1. Perform periodic scans of the information system {{Assignment: organization-defined frequency}} and real-time scans of files from external sources at {{Selection (one or more); endpoint; network entry/exit points}} as the files are downloaded, opened, or executed in accordance with organizational security policy; and 2. {{Selection (one or more): block malicious code; quarantine malicious code; send alert to administrator; [Assignment: organization-defined action]}} in response to malicious code detection; and d. Addresses the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the information system.' WHERE [Requirement_Id] = 11161
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system updates malicious code protection mechanisms only when directed by a privileged user. The organization: (a) Tests malicious code protection mechanisms {{Assignment: organization-defined frequency}} by introducing a known benign, non-spreading test case into the information system; and (b) Verifies that both detection of the test case and associated incident reporting occur. The information system implements nonsignature-based malicious code detection mechanisms. The information system detects {{Assignment: organization-defined unauthorized operating system commands}} through the kernel application programming interface at {{Assignment: organization-defined information system hardware components}} and {{Selection (one or more): issues a warning; audits the command execution; prevents the execution of the command}}. The information system implements {{Assignment: organization-defined security safeguards}} to authenticate {{Assignment: organization-defined remote commands}}. The organization: (a) Employs {{Assignment: organization-defined tools and techniques}} to analyze the characteristics and behavior of malicious code; and (b) Incorporates the results from malicious code analysis into organizational incident response and flaw remediation processes.' WHERE [Requirement_Id] = 11163
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors the information system to detect: 1. Attacks and indicators of potential attacks in accordance with {{Assignment: organization-defined monitoring objectives}}; and 2. Unauthorized local, network, and remote connections; b. Identifies unauthorized use of the information system through {{Assignment: organization-defined techniques and methods}}; c. Deploys monitoring devices: (i) strategically within the information system to collect organization-determined essential information; and (ii) at ad hoc locations within the system to track specific types of transactions of interest to the organization; d. Protects information obtained from intrusion-monitoring tools from unauthorized access, modification, and deletion; e. Heightens the level of information system monitoring activity whenever there is an indication of increased risk to organizational operations and assets, individuals, other organizations, or the Nation based on law enforcement information, intelligence information, or other credible sources of information; f. Obtains legal opinion with regard to information system monitoring activities in accordance with applicable federal laws, Executive Orders, directives, policies, or regulations; and g. Provides {{Assignment: organization-defined information system monitoring information}} to {{Assignment: organization-defined personnel or roles}} {{Selection (one or more): as needed; [Assignment: organization-defined frequency]}}.' WHERE [Requirement_Id] = 11164
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to support near real-time analysis of events. The information system monitors inbound and outbound communications traffic {{Assignment: organization-defined frequency}} for unusual or unauthorized activities or conditions. The information system alerts {{Assignment: organization-defined personnel or roles}} when the following indications of compromise or potential compromise occur: {{Assignment: organization-defined compromise indicators}}.' WHERE [Requirement_Id] = 11165
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization connects and configures individual intrusion detection tools into an information system-wide intrusion detection system. The organization employs automated tools to integrate intrusion detection tools into access control and flow control mechanisms for rapid response to attacks by enabling reconfiguration of these mechanisms in support of attack isolation and elimination. The information system notifies {{Assignment: organization-defined incident response personnel (identified by name and/or by role)}} of detected suspicious events and takes {{Assignment: organization-defined least-disruptive actions to terminate suspicious events}}. The organization tests intrusion-monitoring tools {{Assignment: organization-defined frequency}}. The organization makes provisions so that {{Assignment: organization-defined encrypted communications traffic}} is visible to {{Assignment: organization-defined information system monitoring tools}}. The organization analyzes outbound communications traffic at the external boundary of the information system and selected {{Assignment: organization-defined interior points within the system (e.g., subnetworks, subsystems)}} to discover anomalies. The organization employs automated mechanisms to alert security personnel of the following inappropriate or unusual activities with security implications: {{Assignment: organization-defined activities that trigger alerts}}. The organization: (a) Analyzes communications traffic/event patterns for the information system; (b) Develops profiles representing common traffic patterns and/or events; and (c) Uses the traffic/event profiles in tuning system-monitoring devices to reduce the number of false positives and the number of false negatives. The organization employs a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises/breaches to the information system. The organization employs an intrusion detection system to monitor wireless communications traffic as the traffic passes from wireless to wireline networks. The organization correlates information from monitoring tools employed throughout the information system. The organization correlates information from monitoring physical, cyber, and supply chain activities to achieve integrated, organization-wide situational awareness. The organization analyzes outbound communications traffic at the external boundary of the information system (i.e., system perimeter) and at {{Assignment: organization-defined interior points within the system (e.g., subsystems, subnetworks)}} to detect covert exfiltration of information. The organization implements {{Assignment: organization-defined additional monitoring}} of individuals who have been identified by {{Assignment: organization-defined sources}} as posing an increased level of risk. The organization implements {{Assignment: organization-defined additional monitoring}} of privileged users. The organization implements {{Assignment: organization-defined additional monitoring}} of individuals during {{Assignment: organization-defined probationary period}}. The information system detects network services that have not been authorized or approved by {{Assignment: organization-defined authorization or approval processes}} and {{Selection (one or more): audits; alerts [Assignment: organization-defined personnel or roles]}}. The organization implements {{Assignment: organization-defined host-based monitoring mechanisms}} at {{Assignment: organization-defined information system components}}. The information system discovers, collects, distributes, and uses indicators of compromise.' WHERE [Requirement_Id] = 11166
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Receives information system security alerts, advisories, and directives from {{Assignment: organization-defined external organizations}} on an ongoing basis; b. Generates internal security alerts, advisories, and directives as deemed necessary; c. Disseminates security alerts, advisories, and directives to: {{Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements within the organization]; [Assignment: organization-defined external organizations]}}; and d. Implements security directives in accordance with established time frames, or notifies the issuing organization of the degree of noncompliance.' WHERE [Requirement_Id] = 11167
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Verifies the correct operation of {{Assignment: organization-defined security functions}}; b. Performs this verification {{Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]}}; c. Notifies {{Assignment: organization-defined personnel or roles}} of failed security verification tests; and d. {{Selection (one or more): shuts the information system down; restarts the information system; [Assignment: organization-defined alternative action(s)]}} when anomalies are discovered.' WHERE [Requirement_Id] = 11169
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements automated mechanisms to support for the management of distributed security testing. The organization reports the results of security function verification to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 11170
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs integrity verification tools to detect unauthorized changes to {{Assignment: organization-defined software, firmware, and information}}. The information system performs an integrity check of {{Assignment: organization-defined software, firmware, and information}} {{Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]}}. The organization incorporates the detection of unauthorized {{Assignment: organization-defined security-relevant changes to the information system}} into the organizational incident response capability.' WHERE [Requirement_Id] = 11171
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools that provide notification to {{Assignment: organization-defined personnel or roles}} upon discovering discrepancies during integrity verification. The information system automatically {{Selection (one or more): shuts the information system down; restarts the information system; implements [Assignment: organization-defined security safeguards]}} when integrity violations are discovered. The organization: (a) Prohibits the use of binary or machine-executable code from sources with limited or no warranty and without the provision of source code; and (b) Provides exceptions to the source code requirement only for compelling mission/operational requirements and with the approval of the authorizing official.' WHERE [Requirement_Id] = 11172
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs centrally managed integrity verification tools. The information system implements cryptographic mechanisms to detect unauthorized changes to software, firmware, and information. The information system, upon detection of a potential integrity violation, provides the capability to audit the event and initiates the following actions: {{Selection (one or more): generates an audit record; alerts current user; alerts [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined other actions]}}. The information system verifies the integrity of the boot process of {{Assignment: organization-defined devices}}. The information system implements {{Assignment: organization-defined security safeguards}} to protect the integrity of boot firmware in {{Assignment: organization-defined devices}}. The organization requires that {{Assignment: organization-defined user-installed software}} execute in a confined physical or virtual machine environment with limited privileges. The organization requires that the integrity of {{Assignment: organization-defined user-installed software}} be verified prior to execution. The organization allows execution of binary or machine-executable code obtained from sources with limited or no warranty and without the provision of source code only in confined physical or virtual machine environments and with the explicit approval of {{Assignment: organization-defined personnel or roles}}. The information system implements cryptographic mechanisms to authenticate {{Assignment: organization-defined software or firmware components}} prior to installation. The organization does not allow processes to execute without supervision for more than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11173
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system checks the validity of {{Assignment: organization-defined information inputs}}.' WHERE [Requirement_Id] = 11176
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Provides a manual override capability for input validation of {{Assignment: organization-defined inputs}}; (b) Restricts the use of the manual override capability to only {{Assignment: organization-defined authorized individuals}}; and (c) Audits the use of the manual override capability. The organization ensures that input validation errors are reviewed and resolved within {{Assignment: organization-defined time period}}. The information system behaves in a predictable and documented manner that reflects organizational and system objectives when invalid inputs are received. The organization accounts for timing interactions among information system components in determining appropriate responses for invalid inputs. The organization restricts the use of information inputs to {{Assignment: organization-defined trusted sources}} and/or {{Assignment: organization-defined formats}}.' WHERE [Requirement_Id] = 11177
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Generates error messages that provide information necessary for corrective actions without revealing information that could be exploited by adversaries; and b. Reveals error messages only to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 11178
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines mean time to failure (MTTF) for {{Assignment: organization-defined information system components}} in specific environments of operation; and b. Provides substitute information system components and a means to exchange active and standby components at {{Assignment: organization-defined MTTF substitution criteria}}. The organization takes information system components out of service by transferring component responsibilities to substitute components no later than {{Assignment: organization-defined fraction or percentage}} of mean time to failure. The organization manually initiates transfers between active and standby information system components {{Assignment: organization-defined frequency}} if the mean time to failure exceeds {{Assignment: organization-defined time period}}. The organization, if information system component failures are detected: (a) Ensures that the standby components are successfully and transparently installed within {{Assignment: organization-defined time period}}; and (b) {{Selection (one or more): activates [Assignment: organization-defined alarm]; automatically shuts down the information system}}. The organization provides {{Selection: real-time; near real-time}} {{Assignment: organization-defined failover capability}} for the information system.' WHERE [Requirement_Id] = 11180
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements non-persistent {{Assignment: organization-defined information system components and services}} that are initiated in a known state and terminated {{Selection (one or more): upon end of session of use; periodically at [Assignment: organization-defined frequency]}}. The organization ensures that software and data employed during information system component and service refreshes are obtained from {{Assignment: organization-defined trusted sources}}.' WHERE [Requirement_Id] = 11181
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system validates information output from {{Assignment: organization-defined software programs and/or applications}} to ensure that the information is consistent with the expected content.' WHERE [Requirement_Id] = 11182
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined security safeguards}} to protect its memory from unauthorized code execution.' WHERE [Requirement_Id] = 11183
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined fail-safe procedures}} when {{Assignment: organization-defined failure conditions occur}}.' WHERE [Requirement_Id] = 11184
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization does not allow processes to execute without supervision for more than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11274
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Appoints a Senior Agency Official for Privacy (SAOP)/Chief Privacy Officer (CPO) accountable for developing, implementing, and maintaining an organization-wide governance and privacy program to ensure compliance with all applicable laws and regulations regarding the collection, use, maintenance, sharing, and disposal of personally identifiable information (PII) by programs and information systems; b. Monitors federal privacy laws and policy for changes that affect the privacy program; c. Allocates {{Assignment: organization-defined allocation of budget and staffing}} sufficient resources to implement and operate the organization-wide privacy program; d. Develops a strategic organizational privacy plan for implementing applicable privacy controls, policies, and procedures; e. Develops, disseminates, and implements operational privacy policies and procedures that govern the appropriate privacy and security controls for programs, information systems, or technologies involving PII; and f. Updates privacy plan, policies, and procedures {{Assignment: organization-defined frequency, at least biennially}}.' WHERE [Requirement_Id] = 11755
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization monitors and audits privacy controls and internal privacy policy {{Assignment: organization-defined frequency}} to ensure effective implementation.' WHERE [Requirement_Id] = 11758
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Develops, implements, and updates a comprehensive training and awareness strategy aimed at ensuring that personnel understand privacy responsibilities and procedures; b. Administers basic privacy training {{Assignment: organization-defined frequency, at least annually}} and targeted, role-based privacy training for personnel having responsibility for personally identifiable information (PII) or for activities that involve PII {{Assignment: organization-defined frequency, at least annually}}; and c. Ensures that personnel certify (manually or electronically) acceptance of responsibilities for privacy requirements {{Assignment: organization-defined frequency, at least annually}}.' WHERE [Requirement_Id] = 11759
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Confirms to the greatest extent practicable upon collection or creation of personally identifiable information (PII), the accuracy, relevance, timeliness, and completeness of that information; b. Collects PII directly from the individual to the greatest extent practicable; c. Checks for, and corrects as necessary, any inaccurate or outdated PII used by its programs or systems {{Assignment: organization-defined frequency}}; and d. Issues guidelines ensuring and maximizing the quality, utility, objectivity, and integrity of disseminated information.' WHERE [Requirement_Id] = 11763
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization requests that the individual or individual''s authorized representative revalidate that PII collected is still accurate {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 11765
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Identifies the minimum personally identifiable information (PII) elements that are relevant and necessary to accomplish the legally authorized purpose of collection; b. Limits the collection and retention of PII to the minimum elements identified for the purposes described in the notice and for which the individual has provided consent; and c. Conducts an initial evaluation of PII holdings and establishes and follows a schedule for regularly reviewing those holdings {{Assignment: organization-defined frequency, at least annually}} to ensure that only PII identified in the notice is collected and retained, and that the PII continues to be necessary to accomplish the legally authorized purpose.' WHERE [Requirement_Id] = 11768
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Retains each collection of personally identifiable information (PII) for {{Assignment: organization-defined time period}} to fulfill the purpose(s) identified in the notice or as required by law; b. Disposes of, destroys, erases, and/or anonymizes the PII, regardless of the method of storage, in accordance with a NARA-approved record retention schedule and in a manner that prevents loss, theft, misuse, or unauthorized access; and c. Uses {{Assignment: organization-defined techniques or methods}} to ensure secure deletion or destruction of PII (including originals, copies, and archived records).' WHERE [Requirement_Id] = 11770
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization responds to complaints, concerns, or questions from individuals within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 11779
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N' The organization: a. Establishes, maintains, and updates {{Assignment: organization-defined frequency}} an inventory that contains a listing of all programs and information systems identified as collecting, using, maintaining, or sharing personally identifiable information (PII); and b. Provides each update of the PII inventory to the CIO or information security official {{Assignment: organization-defined frequency}} to support the establishment of information security requirements for all new or modified information systems containing PII.' WHERE [Requirement_Id] = 11780
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Organizations should analyze the detailed risk assessment, identify the cost of mitigation for each risk, compare the cost with the risk of occurrence, and select those mitigation controls where cost is less than the potential risk. Because it is usually impractical or impossible to eliminate all risks, organizations should focus on mitigating risk with the greatest potential impact to the ICS and the process. The controls to mitigate a specific risk may vary among types of systems. For example, user authentication controls might be different for ICS than for corporate payroll systems and e-commerce systems. Organizations should document and communicate the selected controls, along with the procedures for using the controls. As the team identifies mitigation strategies, risks may be identified that can be mitigated by “quick fix” solutions—low-cost, high-value practices that can significantly reduce risk. Examples of these solutions are restricting Internet access and eliminating e-mail access on operator control stations or consoles. Organizations should identify, evaluate, and implement suitable quick fix solutions as soon as possible to reduce security risks and achieve rapid benefits. The Department of Energy (DOE) has a “21 Steps to Improve Cyber Security of SCADA Networks” [31] document that could be used as a starting point to outline specific actions to increase the security of SCADA systems and other ICS.' WHERE [Requirement_Id] = 12221
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Packet Filtering Firewalls - The most basic type of firewall is called a packet filter. Packet filter firewalls are essentially routing devices that include access control functionality for system addresses and communication sessions. The access control is governed by a set of directives collectively referred to as a rule set. In their most basic form, packet filters operate at layer 3 (network) of the Open Systems Interconnection (OSI) model. This type of firewall checks basic information in each packet, such as IP addresses, against a set of criteria before forwarding the packet. Depending on the packet and the criteria, the firewall can drop the packet, forward it, or send a message to the originator. The advantages of packet filtering firewalls include low cost and low impact on network performance, usually because only one or a few header fields in the packet are examined. Stateful Inspection Firewalls - Stateful inspection firewalls are packet filters that incorporate added awareness of the OSI model data at layer 4. Stateful inspection firewalls filter packets at the network layer, determine whether session packets are legitimate, and evaluate the contents of packets at the transport layer (e.g., TCP, UDP) as well. Stateful inspection keeps track of active sessions and uses that information to determine if packets should be forwarded or blocked. It offers a high level of security and good performance, but it may be more expensive and complex to administer. Additional rule sets for ICS applications may be required. Application-Proxy Gateway Firewalls - This class of firewalls examines packets at the application layer and filters traffic based on specific application rules, such as specified applications (e.g., browsers) or protocols (e.g., FTP). It offers a high level of security, but could have overhead and delay impacts on network performance, which can be unacceptable in an ICS environment. In an ICS environment, firewalls are most often deployed between the ICS network and the corporate network [32]. Properly configured, they can greatly restrict undesired access to and from control system host computers and controllers, thereby improving security. They can also potentially improve a control network’s responsiveness by removing non-essential traffic from the network. When properly designed, configured, and maintained, dedicated hardware firewalls can contribute significantly to increasing the security of today’s ICS environments.' WHERE [Requirement_Id] = 12222
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'By introducing a simple two-port firewall between the corporate and control networks, as shown in Figure 5-1, a significant security improvement can be achieved. Properly configured, a firewall significantly reduces the chance of a successful external attack on the control network. Unfortunately, two issues still remain with this design. First, if the data historian resides on the corporate network, the firewall must allow the data historian to communicate with the control devices on the control network. A packet originating from a malicious or incorrectly configured host on the corporate network (appearing to be the data historian) would be forwarded to individual PLCs/DCS. If the data historian resides on the control network, a firewall rule must exist that allows all hosts from the enterprise to communicate with the historian. Typically, this communication occurs at the application layer as Structured Query Language (SQL) or Hypertext Transfer Protocol (HTTP) requests. Flaws in the historian’s application layer code could result in a compromised historian. Once the historian is compromised, the remaining nodes on the control network are vulnerable to a worm propagating or an interactive attack. Another issue with having a simple firewall between the networks is that spoofed packets can be constructed that can affect the control network, potentially permitting covert data to be tunneled in allowed protocols. For example, if HTTP packets are allowed through the firewall, then Trojan horse software accidentally introduced on an HMI or control network laptop could be controlled by a remote entity and send data (such as captured passwords) to that entity, disguised as legitimate traffic. In summary, while this architecture is a significant improvement over a non-segregated network, it requires the use of firewall rules that allow direct communications between the corporate network and control network devices. This can result in possible security breaches if not very carefully designed and monitored [33].' WHERE [Requirement_Id] = 12224
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The security controls that fall within the NIST SP 800-53 System and Services Acquisition (SA) family provide the basis for developing policies and procedures for acquisition of resources required to adequately protect an information system. These acquisitions are based on security requirements and security specifications. As part of the acquisition procedures, an information system is managed using a system development life cycle methodology that includes information security considerations. As part of acquisition, adequate documentation must be maintained on the information system and constituent components. The SA family also addresses outsourced systems and the inclusion of adequate security controls by vendors as specified by the supported organization. Vendors are also responsible for configuration management and security testing for these outsourced information systems. The security requirements of an organization outsourcing the management and control of all or some of its information systems, networks, and desktop environments should be addressed in a contract agreed between the parties. External suppliers that have an impact on the security of the organization must be held to the same security policies and procedures to maintain the overall level of ICS security. Security policies and procedures of second and third-tier suppliers should also be in compliance with corporate cyber security policies and procedures in the case that they impact ICS security. The SCADA and Control System Procurement Project [46] has developed a procurement language for specifying security requirements when procuring new systems or maintaining existing systems.' WHERE [Requirement_Id] = 12231
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Antivirus products evaluate files on a computer’s storage devices against an inventory of known malware signature files. If one of the files on a computer matches the profile of a known virus, the virus is removed through a disinfection process (e.g., quarantine, deletion) so it cannot infect other local files or communicate across a network to infect other files. Antivirus software can be deployed on workstations, servers, firewalls and handheld devices. Antivirus tools only function effectively when installed, configured, running full-time, and maintained properly against the state of known attack methods and payloads. While antivirus tools are common security practice in IT computer systems, their use with ICS may require adopting special practices including compatibility checks, change management issues, and performance impact metrics. These special practices should be utilized whenever new signatures or new versions of antivirus software are installed. Major ICS vendors recommend and even support the use of particular antivirus tools. In some cases, control system vendors may have performed regression testing across their product line for supported versions of a particular antivirus tool and also provide associated installation and configuration documentation. There is also an effort to develop a general set of guidelines and test procedures focused on ICS performance impacts to fill the gaps where ICS and antivirus vendor guidance is not available [54]. Generally: a. Windows, Unix, Linux systems, etc. used as consoles, engineering workstations, data historians, HMIs and general purpose SCADA and backup servers can be secured just like commercial IT equipment: install push- or auto-updated antivirus and patch management software with updates distributed via an antivirus server and patch management server located inside the process control network and auto-updated from the IT network b. Follow vendor recommendations on all other servers and computers (DCS, PLC, instruments) that have time-dependent code, modified or extended the operating system or any other change that makes it different from any standard PC that one could buy at an office supply or computer store. Expect the vendor to make periodic maintenance releases that include security patches.' WHERE [Requirement_Id] = 12250
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Intrusion detection systems (IDS) monitor events on a network, such as traffic patterns, or a system, such as log entries or file accesses, so that they can identify an intruder breaking into or attempting to break into a system [55]. IDS ensure that unusual activity such as new open ports, unusual traffic patterns, or changes to critical operating system files is brought to the attention of the appropriate security personnel. The two most commonly used types of IDS are: a. Network-Based IDS. These systems monitor network traffic and generate alarms when they identify traffic that they deem to be an attack. b. Host-Based IDS. This software monitors one or more types of characteristics of a system, such as application log file entries, system configuration changes, and access to sensitive data on a system and responds with an alarm or countermeasure when a user attempts to breach security. An effective IDS deployment typically involves both host-based and network-based IDS. In the current ICS environment, network-based IDS are most often deployed between the control network and the corporate network in conjunction with a firewall; host-based IDS are most often deployed on the computers that use general-purpose OSs or applications such as HMIs, SCADA servers, and engineering workstations. Properly configured, an IDS can greatly enhance the security management team’s ability to detect attacks entering or leaving the system, thereby improving security. They can also potentially improve a control network’s efficiency by detecting non-essential traffic on the network. However, even when IDS are implemented, security staff can primarily recognize individual attacks, as opposed to organized patterns of attacks over time. Additionally, care should be given to not confuse unusual ICS activity, such as during transient conditions, as an attack. Current IDS and IPS products are effective in detecting and preventing well-known Internet attacks, but until recently they have not addressed ICS protocol attacks. IDS and IPS vendors are beginning to develop and incorporate attack signatures for various ICS protocols such as Modbus, DNP, and ICCP. [56] Appendix D provides some additional information on emerging IDS capabilities.' WHERE [Requirement_Id] = 12251
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Authentication describes the process of positively identifying potential network users, hosts, applications, services, and resources using a combination of identification factors or credentials. The result of this authentication process then becomes the basis for permitting or denying further actions (e.g., when an automatic teller machine asks for a PIN). Based on the authentication determination, the system may or may not allow the potential user access to its resources. Authorization is the process of determining who and what should be allowed to have access to a particular resource; access control is the mechanism for enforcing authorization. Access control is described in Section 6.16. There are several possible factors for determining the authenticity of a person, device, or system, including something you know, something you have or something you are. For example, authentication could be based on something known (e.g., PIN number or password), something possessed (e.g., key, dongle, smart card), something you are such as a biological characteristic (e.g., fingerprint, retinal signature), a location (e.g., Global Positioning System [GPS] location access), the time a request is made, or a combination of these attributes. In general, the more factors that are used in the authentication process, the more robust the process will be. When two or more factors are used, the process is known generically as multi-factor authentication. The security controls that fall within the NIST SP 800-53 Identification and Authentication (IA) family provide policy and guidance for the identification and authentication of users of and devices within the information system. These include controls to manage identifiers and authenticators within each technology used (e.g., tokens, certificates, biometrics, passwords, key cards). Computer systems in ICS environments typically rely on traditional passwords for authentication. Control system suppliers often supply systems with default passwords. These passwords are factory set and are often easy to guess or are changed infrequently, which creates additional security risks. Also, protocols currently used in ICS environments generally have inadequate or no network service authentication. There are now several forms of authentication available in addition to traditional password techniques being used with ICS. Some of these, including password authentication, are presented in the following sections with discussions regarding their use with ICS.' WHERE [Requirement_Id] = 12257
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Biometric authentication technologies determine authenticity by determining presumably unique biological characteristics of the human requesting access. Usable biometric features include finger minutiae, facial geometry, retinal and iris signatures, voice patterns, typing patterns, and hand geometry. Like physical tokens and smart cards, biometric authentication enhances software-only solutions, such as password authentication, by offering an additional authentication factor and removing the human element in memorizing complex secrets. In addition, because biometric characteristics are unique to a given individual, biometric authentication addresses the issues of lost or stolen physical tokens and smart cards. Noted issues with biometric authentication include: a. Distinguishing a real object from a fake (e.g., how to distinguish a real human finger from a silicon-rubber cast of one or a real human voice from a recorded one). b. Generating type-I and type-II errors (the probability of rejecting a valid biometric image, and the probability of accepting an invalid biometric image, respectively). Biometric authentication devices should be configured to the lowest crossover between these two probabilities, also known as the crossover error rate. c. Handling environmental factors such as temperature and humidity to which some biometric devices are sensitive. d. Addressing industrial applications where employees may have on safety glasses and/or gloves and industrial chemicals may impact biometric scanners. e. Retraining biometric scanners that occasionally “drift” over time. Human biometric traits may also shift over time, necessitating periodic scanner retraining. f. Requiring face-to-face technical support and verification for device training, unlike a password that can be given over a phone or an access card that can be handed out by a receptionist. g. Denying needed access to the control system because of a temporary inability of the sensing device to acknowledge a legitimate user. h. Being socially acceptable. Users consider some biometric authentication devices more acceptable than others. For example, retinal scans may be considered very low on the scale of acceptability, while thumb print scanners may be considered high on the scale of acceptability. Users of biometric authentication devices will need to take social acceptability for their target group into consideration when selecting among various biometric authentication technologies. Biometric devices make a useful secondary check versus other forms of authentication that can become lost or borrowed. Using biometric authentication in combination with token-based access control or badge-operated employee time clocks increases the security level. A possible application is in a control room that is environmentally controlled and physically secured [32].' WHERE [Requirement_Id] = 12262
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'VLANs divide physical networks into smaller logical networks to increase performance, improve manageability, and simplify network design. VLANs are achieved through configuration of Ethernet switches. Each VLAN consists of a single broadcast domain that isolates traffic from other VLANs. Just as replacing hubs with switches reduces collisions, using VLANs limits the broadcast traffic, as well as allowing logical subnets to span multiple physical locations. There are two categories of VLANs: a. Static, often referred to as port-based, where switch ports are assigned to a VLAN so that it is transparent to the end user b. Dynamic, where an end device negotiates VLAN characteristics with the switch or determines the VLAN based on the IP or hardware addresses. Although more than one IP subnet may coexist on the same VLAN, the general recommendation is to use a one-to-one relationship between subnets and VLANs. This practice requires the use of a router or multi-layer switch to join multiple VLANs. Many routers and firewalls support tagged frames so that a single physical interface can be used to route between multiple logical networks. VLANs are not typically deployed to address host or network vulnerabilities in the way that firewalls or IDS are deployed. However, when properly configured, VLANs do allow switches to enforce security policies and segregate traffic at the Ethernet layer. Properly segmented networks can also mitigate the risks of broadcast storms that may result from port scanning or worm activity. Switches have been susceptible to attacks such as MAC spoofing, table overflows, and attacks against the spanning tree protocols, depending on the device and its configuration. VLAN hopping, the ability for an attack to inject frames to unauthorized ports, has been demonstrated using switch spoofing or double-encapsulated frames. These attacks cannot be conducted remotely and require local physical access to the switch. A variety of features such as MAC address filtering, port-based authentication using IEEE 802.1x, and specific vendor recommended practices can be used to mitigate these attacks, depending on the device and implementation. VLANs have been effectively deployed in ICS networks, with each automation cell assigned to a single VLAN to limit unnecessary traffic flooding and allow network devices on the same VLAN to span multiple switches [32].' WHERE [Requirement_Id] = 12266
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The use of wireless within an ICS is a risk-based decision that has to be determined by the organization. Generally, wireless LANs should only be deployed where health, safety, environmental, and financial implications are low. NIST SP 800-48 and SP 800-97 provide guidance on wireless network security. Wireless LANs a. Prior to installation, a wireless survey should be performed to determine antenna location and strength to minimize exposure of the wireless network. The survey should take into account the fact that attackers can use powerful directional antennas, which extend the effective range of a wireless LAN beyond the expected standard range. Faraday cages and other methods are also available to minimize exposure of the wireless network outside of the designated areas. b. Wireless users’ access should utilize IEEE 802.1x authentication using a secure authentication protocol (e.g., Extensible Authentication Protocol [EAP] with TLS [EAP-TLS]) that authenticates users via a user certificates or a Remote Authentication Dial In User Service (RADIUS) server. c. The wireless access points and data servers for wireless worker devices should be located on an isolated network with documented and minimal (single if possible) connections to the ICS network. d. Wireless access points should be configured to have a unique service set identifier (SSID), disable SSID broadcast, and enable MAC filtering at a minimum. e. Wireless devices, if being utilized in a Microsoft Windows ICS network, should be configured into a separate organizational unit of the Windows domain. f. Wireless device communications should be encrypted and integrity-protected. The encryption must not degrade the operational performance of the end device. Encryption at OSI Layer 2 should be considered, rather than at Layer 3 to reduce encryption latency. The use of hardware accelerators to perform cryptographic functions should also be considered.' WHERE [Requirement_Id] = 12268
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Encryption is the cryptographic transformation of data (called plaintext) into a form (called ciphertext) that conceals the data’s original meaning to prevent it from being known or used. If the transformation is reversible, the corresponding reversal process is called decryption, which is a transformation that restores encrypted data to its original state [73]. Before deploying encryption, first determine if encryption is an appropriate solution for the specific ICS application, because authentication and integrity are generally the key security issues for ICS applications. Other cryptographic solutions such as cryptographic hashes should also be considered. The use of encryption within an ICS environment could introduce communications latency due to the additional time and computing resources required to encrypt, decrypt, and authenticate each message. For ICS, any latency induced from the use of encryption, or any other security technique, must not degrade the operational performance of the end device or system. Encryption at OSI Layer 2 should be considered, rather than at Layer 3 to reduce encryption latency. In addition, encrypted messages are often larger than unencrypted messages due to one or more of the following: a. Additional checksums to reduce errors b. Protocols to control the cryptography c. Padding (for block ciphers) d. Authentication procedures e. Other required cryptographic processes. Cryptography also introduces key management issues. Sound security policies require periodic key changes. This process becomes more difficult as the geographic size of the ICS increases, with extensive SCADA systems being the most severe example. Because site visits to change keys can be costly and slow, it is useful to be able to change keys remotely. If cryptography is selected, the most effective safeguard is to use a complete cryptographic system approved by the NIST/ Communications Security Establishment (CSE) Cryptographic Module Validation Program (CMVP) (http://csrc.nist.gov/cryptval/cmvp.htm). Within this program standards are maintained to ensure that cryptographic systems were studied carefully for weaknesses by a wide range of experts, rather than being developed by a few engineers in a single organization. At a minimum, certification makes it probable that: a. Some method (such as counter mode) will be used to ensure that the same message does not generate the same value each time b. ICS messages are protected against replay and forging c. Key management is secure throughout the life cycle of the key d. The system is using an effective random number generator e. The entire system has been implemented securely. Even then, the technology is only effective if it is an integral part of an effectively enforced information security policy. American Gas Association (AGA) report 12-1 [5] contains an example of such a security policy. While it is directed toward a natural gas SCADA system, many of its policy recommendations could apply to any ICS. The encryption hardware should be protected from physical tampering and uncontrolled electronic connections. Assuming cryptography is the appropriate solution, organizations should select cryptographic protection with remote key management if the units being protected are so numerous or geographically dispersed that changing keys is difficult or expensive. [32]' WHERE [Requirement_Id] = 12277
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'One method of encrypting communication data is through a VPN, which is a private network that operates as an overlay on a public infrastructure, so that the private network can function across a public network. VPNs are most often used in the ICS environment to provide secure access from an untrusted network to the ICS control network. Untrusted networks can range from the Internet to the corporate LAN. Properly configured, VPNs can greatly restrict access to and from control system host computers and controllers, thereby improving security. They can also potentially improve control network responsiveness by removing unauthorized non-essential traffic from the intermediary network. VPN devices used to protect control systems should be thoroughly tested to verify that the VPN technology is compatible with the application and implementation of the VPN devices does not unacceptably affect network traffic characteristics [32].' WHERE [Requirement_Id] = 12280
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An access control policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the access control policy and associated access controls; and b. Reviews and updates the current: 1. Access control policy {{Assignment: organization-defined frequency}}; and 2. Access control procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12390
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies and selects the following types of information system accounts to support organizational missions/business functions: {{Assignment: organization-defined information system account types}}; b. Assigns account managers for information system accounts; c. Establishes conditions for group and role membership; d. Specifies authorized users of the information system, group and role membership, and access authorizations (i.e., privileges) and other attributes (as required) for each account; e. Requires approvals by {{Assignment: organization-defined personnel or roles}} for requests to create information system accounts; f. Creates, enables, modifies, disables, and removes information system accounts in accordance with {{Assignment: organization-defined procedures or conditions}}; g. Monitors the use of, information system accounts; h. Notifies account managers: 1. When accounts are no longer required; 2. When users are terminated or transferred; and 3. When individual information system usage or need-to-know changes; i. Authorizes access to the information system based on: 1. A valid access authorization; 2. Intended system usage; and 3. Other attributes as required by the organization or associated missions/business functions; j. Reviews accounts for compliance with account management requirements {{Assignment: organization-defined frequency}}; and k. Establishes a process for reissuing shared/group account credentials (if deployed) when individuals are removed from the group.' WHERE [Requirement_Id] = 12391
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to support the management of information system accounts. The information system automatically {{Selection: removes; disables}} temporary and emergency accounts after {{Assignment: organization-defined time period for each type of account}}. The information system automatically disables inactive accounts after {{Assignment: organization-defined time period}}. The information system automatically audits account creation, modification, enabling, disabling, and removal actions, and notifies {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12392
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that users log out when {{Assignment: organization-defined time-period of expected inactivity or description of when to log out}}. (a) Monitors information system accounts for {{Assignment: organization-defined atypical use}}; and (b) Reports atypical usage of information system accounts to {{Assignment: organization-defined personnel or roles}}. The organization disables accounts of users posing a significant risk within {{Assignment: organization-defined time period}} of discovery of the risk.' WHERE [Requirement_Id] = 12393
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements the following dynamic privilege management capabilities: {{Assignment: organization-defined list of dynamic privilege management capabilities}}. The organization: (a) Establishes and administers privileged user accounts in accordance with a role-based access scheme that organizes allowed information system access and privileges into roles; (b) Monitors privileged role assignments; and (c) Takes {{Assignment: organization-defined actions}} when privileged role assignments are no longer appropriate. The information system creates {{Assignment: organization-defined information system accounts}} dynamically. The organization only permits the use of shared/group accounts that meet {{Assignment: organization-defined conditions for establishing shared/group accounts}}. The information system terminates shared/group account credentials when members leave the group. The information system enforces {{Assignment: organization-defined circumstances and/or usage conditions}} for {{Assignment: organization-defined information system accounts}}.' WHERE [Requirement_Id] = 12394
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces dual authorization for {{Assignment: organization-defined privileged commands and/or other organization-defined actions}}. The information system enforces {{Assignment: organization-defined mandatory access control policies}} over all subjects and objects where the policy specifies that: (a) The policy is uniformly enforced across all subjects and objects within the boundary of the information system; (b) A subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes on subjects, objects, the information system, or information system components; (4) Choosing the security attributes and attribute values to be associated with newly created or modified objects; or (5) Changing the rules governing access control; and (c) {{Assignment: Organized-defined subjects}} may explicitly be granted {{Assignment: organization-defined privileges (i.e., they are trusted subjects)}} such that they are not limited by some or all of the above constraints. The information system enforces {{Assignment: organization-defined discretionary access control policies}} over defined subjects and objects where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects; (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the information system, or the information systems components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control. The information system prevents access to {{Assignment: organization-defined security-relevant information}} except during secure, non-operable system states. The information system enforces a role-based access control policy over {{Assignment: organization-defined users and information resources}} and controls access based upon {{Assignment: organization-defined roles and users authorized to assume such roles}}. The information system enforces the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on {{Assignment: organization-defined rules governing the timing of revocations of access authorizations}}. The information system does not release information outside of the established system boundary unless: (a) The receiving {{Assignment: organization-defined information system or system component}} provides {{Assignment: organization-defined security safeguards}}; and (b) {{Assignment: organization-defined security safeguards}} are used to validate the appropriateness of the information designated for release. The organization employs an audited override of automated access control mechanisms under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 12396
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces approved authorizations for controlling the flow of information within the system and between interconnected systems based on {{Assignment: organization-defined information flow control policies}}.' WHERE [Requirement_Id] = 12397
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses {{Assignment: organization-defined security attributes}} associated with {{Assignment: organization-defined information, source, and destination objects}} to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions. The information system uses protected processing domains to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions. The information system enforces dynamic information flow control based on {{Assignment: organization-defined policies}}. The information system prevents encrypted information from bypassing content-checking mechanisms by {{Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]}}. The information system enforces {{Assignment: organization-defined limitations}} on embedding data types within other data types. The information system enforces information flow control based on {{Assignment: organization-defined metadata}}. The information system enforces {{Assignment: organization-defined one-way flows}} using hardware mechanisms. The information system enforces information flow control using {{Assignment: organization-defined security policy filters}} as a basis for flow control decisions for {{Assignment: organization-defined information flows}}. The information system enforces the use of human reviews for {{Assignment: organization-defined information flows}} under the following conditions: {{Assignment: organization-defined conditions}}. The information system provides the capability for privileged administrators to enable/disable {{Assignment: organization-defined security policy filters}} under the following conditions: {{Assignment: organization-defined conditions}}. The information system provides the capability for privileged administrators to configure {{Assignment: organization-defined security policy filters}} to support different security policies. The information system, when transferring information between different security domains, uses {{Assignment: organization-defined data type identifiers}} to validate data essential for information flow decisions. The information system, when transferring information between different security domains, decomposes information into {{Assignment: organization-defined policy-relevant subcomponents}} for submission to policy enforcement mechanisms. The information system, when transferring information between different security domains, implements {{Assignment: organization-defined security policy filters}} requiring fully enumerated formats that restrict data structure and content. The information system, when transferring information between different security domains, examines the information for the presence of {{Assignment: organized-defined unsanctioned information}} and prohibits the transfer of such information in accordance with the {{Assignment: organization-defined security policy}}. The information system uniquely identifies and authenticates source and destination points by {{Selection (one or more): organization, system, application, individual}} for information transfer. The information system binds security attributes to information using {{Assignment: organization-defined binding techniques}} to facilitate information flow policy enforcement. The information system, when transferring information between different security domains, applies the same security policy filtering to metadata as it applies to data payloads. The organization employs {{Assignment: organization-defined solutions in approved configurations}} to control the flow of {{Assignment: organization-defined information}} across security domains. The information system separates information flows logically or physically using {{Assignment: organization-defined mechanisms and/or techniques}} to accomplish {{Assignment: organization-defined required separations by types of information}}. The information system provides access from a single device to computing platforms, applications, or data residing on multiple different security domains, while preventing any information flow between the different security domains.' WHERE [Requirement_Id] = 12398
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Separates {{Assignment: organization-defined duties of individuals}}; b. Documents separation of duties of individuals; and c. Defines information system access authorizations to support separation of duties.' WHERE [Requirement_Id] = 12399
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) which are necessary to accomplish assigned tasks in accordance with organizational missions and business functions. The organization explicitly authorizes access to {{Assignment: organization-defined security functions (deployed in hardware, software, and firmware) and security-relevant information}}. The organization requires that users of information system accounts, or roles, with access to {{Assignment: organization-defined security functions or security-relevant information}}, use non-privileged accounts or roles, when accessing non-security functions. The organization restricts privileged accounts on the information system to {{Assignment: organization-defined personnel or roles}}. The information system audits the execution of privileged functions. The information system prevents non-privileged users from executing privileged functions to include disabling, circumventing, or altering implemented security safeguards/countermeasures.' WHERE [Requirement_Id] = 12400
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes network access to {{Assignment: organization-defined privileged commands}} only for {{Assignment: organization-defined compelling operational needs}} and documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 12401
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides separate processing domains to enable finer-grained allocation of user privileges. The organization prohibits privileged access to the information system by non-organizational users. The organization: (a) Reviews {{Assignment: organization-defined frequency}} the privileges assigned to {{Assignment: organization-defined roles or classes of users}} to validate the need for such privileges; and (b) Reassigns or removes privileges, if necessary, to correctly reflect organizational mission/business needs. The information system prevents {{Assignment: organization-defined software}} from executing at higher privilege levels than users executing the software.' WHERE [Requirement_Id] = 12402
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Enforces a limit of {{Assignment: organization-defined number}} consecutive invalid logon attempts by a user during a {{Assignment: organization-defined time period}}; and b. Automatically {{Selection: locks the account/node for an [Assignment: organization-defined time period]; locks the account/node until released by an administrator; delays next logon prompt according to [Assignment: organization-defined delay algorithm]}} when the maximum number of unsuccessful attempts is exceeded.' WHERE [Requirement_Id] = 12403
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system purges/wipes information from {{Assignment: organization-defined mobile devices}} based on {{Assignment: organization-defined purging/wiping requirements/techniques}} after {{Assignment: organization-defined number}} consecutive, unsuccessful device logon attempts.' WHERE [Requirement_Id] = 12404
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Displays to users {{Assignment: organization-defined system use notification message or banner}} before granting access to the system that provides privacy and security notices consistent with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance and states that: 1. Users are accessing a U.S. Government information system; 2. Information system usage may be monitored, recorded, and subject to audit; 3. Unauthorized use of the information system is prohibited and subject to criminal and civil penalties; and 4. Use of the information system indicates consent to monitoring and recording; b. Retains the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the information system; and c. For publicly accessible systems: 1. Displays system use information {{Assignment: organization-defined conditions}}, before granting further access; 2. Displays references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and 3. Includes a description of the authorized uses of the system.' WHERE [Requirement_Id] = 12405
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system notifies the user, upon successful logon (access) to the system, of the date and time of the last logon (access). The information system notifies the user, upon successful logon/access, of the number of unsuccessful logon/access attempts since the last successful logon/access. The information system notifies the user of the number of {{Selection: successful logons/accesses; unsuccessful logon/access attempts; both}} during {{Assignment: organization-defined time period}}. The information system notifies the user of changes to {{Assignment: organization-defined security-related characteristics/parameters of the user''s account}} during {{Assignment: organization-defined time period}}. The information system notifies the user, upon successful logon (access), of the following additional information: {{Assignment: organization-defined information to be included in addition to the date and time of the last logon (access)}}.' WHERE [Requirement_Id] = 12406
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system limits the number of concurrent sessions for each {{Assignment: organization-defined account and/or account type}} to {{Assignment: organization-defined number}}.' WHERE [Requirement_Id] = 12407
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prevents further access to the system by initiating a session lock after {{Assignment: organization-defined time period}} of inactivity or upon receiving a request from a user; and b. Retains the session lock until the user reestablishes access using established identification and authentication procedures. The information system conceals, via the session lock, information previously visible on the display with a publicly viewable image.' WHERE [Requirement_Id] = 12408
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system automatically terminates a user session after {{Assignment: organization-defined conditions or trigger events requiring session disconnect}}.' WHERE [Requirement_Id] = 12409
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Provides a logout capability for user-initiated communications sessions whenever authentication is used to gain access to {{Assignment: organization-defined information resources}}; and (b) Displays an explicit logout message to users indicating the reliable termination of authenticated communications sessions.' WHERE [Requirement_Id] = 12410
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies {{Assignment: organization-defined user actions}} that can be performed on the information system without identification or authentication consistent with organizational missions/business functions; and b. Documents and provides supporting rationale in the security plan for the information system, user actions not requiring identification or authentication.' WHERE [Requirement_Id] = 12411
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system monitors and controls remote access methods. The information system implements cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions. The information system routes all remote accesses through {{Assignment: organization-defined number}} managed network access control points. The organization: (a) Authorizes the execution of privileged commands and access to security-relevant information via remote access only for {{Assignment: organization-defined needs}}; and (b) Documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 12413
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that users protect information about remote access mechanisms from unauthorized use and disclosure. The organization provides the capability to expeditiously disconnect or disable remote access to the information system within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12414
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects wireless access to the system using authentication of {{Selection (one or more): users; devices}} and encryption.' WHERE [Requirement_Id] = 12416
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: full-device encryption; container encryption}} to protect the confidentiality and integrity of information on {{Assignment: organization-defined mobile devices}}.' WHERE [Requirement_Id] = 12420
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Prohibits the use of unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and (b) Enforces the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information: (1) Connection of unclassified mobile devices to classified information systems is prohibited; (2) Connection of unclassified mobile devices to unclassified information systems requires approval from the authorizing official; (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by {{Assignment: organization-defined security officials}}, and if classified information is found, the incident handling policy is followed. (c) Restricts the connection of classified mobile devices to classified information systems in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 12421
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization permits authorized individuals to use an external information system to access the information system or to process, store, or transmit organization-controlled information only when the organization: (a) Verifies the implementation of required security controls on the external system as specified in the organizations information security policy and security plan; or (b) Retains approved information system connection or processing agreements with the organizational entity hosting the external information system. The organization {{Selection: restricts; prohibits}} the use of organization-controlled portable storage devices by authorized individuals on external information systems.' WHERE [Requirement_Id] = 12423
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of non-organizationally owned information systems, system components, or devices to process, store, or transmit organizational information. The organization prohibits the use of {{Assignment: organization-defined network accessible storage devices}} in external information systems.' WHERE [Requirement_Id] = 12424
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Facilitates information sharing by enabling authorized users to determine whether access authorizations assigned to the sharing partner match the access restrictions on the information for {{Assignment: organization-defined information sharing circumstances where user discretion is required}}; and b. Employs {{Assignment: organization-defined automated mechanisms or manual processes}} to assist users in making information sharing/collaboration decisions.' WHERE [Requirement_Id] = 12425
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces information-sharing decisions by authorized users based on access authorizations of sharing partners and access restrictions on information to be shared. The information system implements information search and retrieval services that enforce {{Assignment: organization-defined information sharing restrictions}}.' WHERE [Requirement_Id] = 12426
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Designates individuals authorized to post information onto a publicly accessible information system; b. Trains authorized individuals to ensure that publicly accessible information does not contain nonpublic information; c. Reviews the proposed content of information prior to posting onto the publicly accessible information system to ensure that nonpublic information is not included; and d. Reviews the content on the publicly accessible information system for nonpublic information {{Assignment: organization-defined frequency}} and removes such information, if discovered.' WHERE [Requirement_Id] = 12427
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security awareness and training policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security awareness and training policy and associated security awareness and training controls; and b. Reviews and updates the current: 1. Security awareness and training policy {{Assignment: organization-defined frequency}}; and 2. Security awareness and training procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12428
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides basic security awareness training to information system users (including managers, senior executives, and contractors): a. As part of initial training for new users; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 12429
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides role-based security training to personnel with assigned security roles and responsibilities: a. Before authorizing access to the information system or performing assigned duties; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 12432
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Assignment: organization-defined personnel or roles}} with initial and {{Assignment: organization-defined frequency}} training in the employment and operation of environmental controls. The organization provides {{Assignment: organization-defined personnel or roles}} with initial and {{Assignment: organization-defined frequency}} training in the employment and operation of physical security controls. The organization includes practical exercises in security training that reinforce training objectives. The organization provides training to its personnel on {{Assignment: organization-defined indicators of malicious code}} to recognize suspicious communications and anomalous behavior in organizational information systems.' WHERE [Requirement_Id] = 12433
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Documents and monitors individual information system security training activities including basic security awareness training and specific information system security training; and b. Retains individual training records for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12434
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An audit and accountability policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the audit and accountability policy and associated audit and accountability controls; and b. Reviews and updates the current: 1. Audit and accountability policy {{Assignment: organization-defined frequency}}; and 2. Audit and accountability procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12435
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines that the information system is capable of auditing the following events: {{Assignment: organization-defined auditable events}}; b. Coordinates the security audit function with other organizational entities requiring audit-related information to enhance mutual support and to help guide the selection of auditable events; c. Provides a rationale for why the auditable events are deemed to be adequate to support after-the-fact investigations of security incidents; and d. Determines that the following events are to be audited within the information system: {{Assignment: organization-defined audited events (the subset of the auditable events defined in AU-2 a.) along with the frequency of (or situation requiring) auditing for each identified event}}.' WHERE [Requirement_Id] = 12436
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the audited events {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12437
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system generates audit records containing the following additional information: {{Assignment: organization-defined additional, more detailed information}}.' WHERE [Requirement_Id] = 12439
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides centralized management and configuration of the content to be captured in audit records generated by {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 12440
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization allocates audit record storage capacity in accordance with {{Assignment: organization-defined audit record storage requirements}}. The information system off-loads audit records {{Assignment: organization-defined frequency}} onto a different system or media than the system being audited.' WHERE [Requirement_Id] = 12441
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Alerts {{Assignment: organization-defined personnel or roles}} in the event of an audit processing failure; and b. Takes the following additional actions: {{Assignment: organization-defined actions to be taken (e.g., shut down information system, overwrite oldest audit records, stop generating audit records)}}.' WHERE [Requirement_Id] = 12442
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a warning to {{Assignment: organization-defined personnel, roles, and/or locations}} within {{Assignment: organization-defined time period}} when allocated audit record storage volume reaches {{Assignment: organization-defined percentage}} of repository maximum audit record storage capacity. The information system provides an alert in {{Assignment: organization-defined real-time period}} to {{Assignment: organization-defined personnel, roles, and/or locations}} when the following audit failure events occur: {{Assignment: organization-defined audit failure events requiring real-time alerts}}.' WHERE [Requirement_Id] = 12443
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces configurable network communications traffic volume thresholds reflecting limits on auditing capacity and {{Selection: rejects; delays}} network traffic above those thresholds. The information system invokes a {{Selection: full system shutdown; partial system shutdown; degraded operational mode with limited mission/business functionality available}} in the event of {{Assignment: organization-defined audit failures}}, unless an alternate audit capability exists.' WHERE [Requirement_Id] = 12444
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and analyzes information system audit records {{Assignment: organization-defined frequency}} for indications of {{Assignment: organization-defined inappropriate or unusual activity}}; and b. Reports findings to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12445
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization integrates analysis of audit records with analysis of {{Selection (one or more): vulnerability scanning information; performance data; information system monitoring information; [Assignment: organization-defined data/information collected from other sources]}} to further enhance the ability to identify inappropriate or unusual activity. The organization correlates information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity.' WHERE [Requirement_Id] = 12447
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to centrally review and analyze audit records from multiple components within the system. The organization specifies the permitted actions for each {{Selection (one or more): information system process; role; user}} associated with the review, analysis, and reporting of audit information. The organization performs a full text analysis of audited privileged commands in a physically distinct component or subsystem of the information system, or other information system that is dedicated to that analysis. The organization correlates information from nontechnical sources with audit information to enhance organization-wide situational awareness. The organization adjusts the level of audit review, analysis, and reporting within the information system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information.' WHERE [Requirement_Id] = 12448
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to process audit records for events of interest based on {{Assignment: organization-defined audit fields within audit records}}. The information system provides the capability to sort and search audit records for events of interest based on the content of {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 12450
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Uses internal system clocks to generate time stamps for audit records; and b. Records time stamps for audit records that can be mapped to Coordinated Universal Time (UTC) or Greenwich Mean Time (GMT) and meets {{Assignment: organization-defined granularity of time measurement}}.' WHERE [Requirement_Id] = 12451
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Compares the internal information system clocks {{Assignment: organization-defined frequency}} with {{Assignment: organization-defined authoritative time source}}; and (b) Synchronizes the internal system clocks to the authoritative time source when the time difference is greater than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12452
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes access to management of audit functionality to only {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 12455
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system backs up audit records {{Assignment: organization-defined frequency}} onto a physically different system or system component than the system or component being audited. The information system implements cryptographic mechanisms to protect the integrity of audit information and audit tools.' WHERE [Requirement_Id] = 12456
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system writes audit trails to hardware-enforced, write-once media. The organization requires and enforces dual authorization for {{Selection (one or more): changes to; deletion of}} {{Assignment: organization-defined audit information}}. The organization authorizes read-only access to audit information to {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 12457
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against an individual (or process acting on behalf of an individual) falsely denying having performed {{Assignment: organization-defined actions to be covered by non-repudiation}}.' WHERE [Requirement_Id] = 12458
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Binds the identity of the information producer with the information to {{Assignment: organization-defined strength of binding}}; and (b) Provides the means for authorized individuals to determine the identity of the producer of the information. The information system: (a) Validates the binding of the information producer identity to the information at {{Assignment: organization-defined frequency}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error. The information system maintains reviewer/releaser identity and credentials within the established chain of custody for all information reviewed or released. The information system: (a) Validates the binding of the information reviewer identity to the information at the transfer or release points prior to release/transfer between {{Assignment: organization-defined security domains}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 12459
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization retains audit records for {{Assignment: organization-defined time period consistent with records retention policy}} to provide support for after-the-fact investigations of security incidents and to meet regulatory and organizational information retention requirements.' WHERE [Requirement_Id] = 12460
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined measures}} to ensure that long-term audit records generated by the information system can be retrieved.' WHERE [Requirement_Id] = 12461
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Provides audit record generation capability for the auditable events defined in AU-2 at {{Assignment: organization-defined information system components}}; b. Allows {{Assignment: organization-defined personnel or roles}} to select which auditable events are to be audited by specific components of the information system; and c. Generates audit records for the events defined in AU-2 (d) with the content defined in AU-3.' WHERE [Requirement_Id] = 12462
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system compiles audit records from {{Assignment: organization-defined information system components}} into a system-wide (logical or physical) audit trail that is time-correlated to within {{Assignment: organization-defined level of tolerance for relationship between time stamps of individual records in the audit trail}}. The information system provides the capability for {{Assignment: organization-defined individuals or roles}} to change the auditing to be performed on {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined selectable event criteria}} within {{Assignment: organization-defined time thresholds}}.' WHERE [Requirement_Id] = 12463
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security assessment and authorization policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security assessment and authorization policy and associated security assessment and authorization controls; and b. Reviews and updates the current: 1. Security assessment and authorization policy {{Assignment: organization-defined frequency}}; and 2. Security assessment and authorization procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12465
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security assessment plan that describes the scope of the assessment including: 1. Security controls and control enhancements under assessment; 2. Assessment procedures to be used to determine security control effectiveness; and 3. Assessment environment, assessment team, and assessment roles and responsibilities; b. Assesses the security controls in the information system and its environment of operation {{Assignment: organization-defined frequency}} to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements; c. Produces a security assessment report that documents the results of the assessment; and d. Provides the results of the security control assessment to {{Assignment: organization-defined individuals or roles}}.' WHERE [Requirement_Id] = 12466
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to conduct security control assessments.' WHERE [Requirement_Id] = 12467
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes as part of security control assessments, {{Assignment: organization-defined frequency}}, {{Selection: announced; unannounced}}, {{Selection (one or more): in-depth monitoring; vulnerability scanning; malicious user testing; insider threat assessment; performance/load testing; [Assignment: organization-defined other forms of security assessment]}}.' WHERE [Requirement_Id] = 12468
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization accepts the results of an assessment of {{Assignment: organization-defined information system}} performed by {{Assignment: organization-defined external organization}} when the assessment meets {{Assignment: organization-defined requirements}}.' WHERE [Requirement_Id] = 12469
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes connections from the information system to other information systems through the use of Interconnection Security Agreements; b. Documents, for each interconnection, the interface characteristics, security requirements, and the nature of the information communicated; and c. Reviews and updates Interconnection Security Agreements {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12470
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: allow-all, deny-by-exception; deny-all, permit-by-exception}} policy for allowing {{Assignment: organization-defined information systems}} to connect to external information systems.' WHERE [Requirement_Id] = 12471
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 12472
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a plan of action and milestones for the information system to document the organizations planned remedial actions to correct weaknesses or deficiencies noted during the assessment of the security controls and to reduce or eliminate known vulnerabilities in the system; and b. Updates existing plan of action and milestones {{Assignment: organization-defined frequency}} based on the findings from security controls assessments, security impact analyses, and continuous monitoring activities.' WHERE [Requirement_Id] = 12473
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a senior-level executive or manager as the authorizing official for the information system; b. Ensures that the authorizing official authorizes the information system for processing before commencing operations; and c. Updates the security authorization {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12475
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization develops a continuous monitoring strategy and implements a continuous monitoring program that includes: a. Establishment of {{Assignment: organization-defined metrics}} to be monitored; b. Establishment of {{Assignment: organization-defined frequencies}} for monitoring and {{Assignment: organization-defined frequencies}} for assessments supporting such monitoring; c. Ongoing security control assessments in accordance with the organizational continuous monitoring strategy; d. Ongoing security status monitoring of organization-defined metrics in accordance with the organizational continuous monitoring strategy; e. Correlation and analysis of security-related information generated by assessments and monitoring; f. Response actions to address results of the analysis of security-related information; and g. Reporting the security status of organization and the information system to {{Assignment: organization-defined personnel or roles}} {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12476
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to monitor the security controls in the information system on an ongoing basis.' WHERE [Requirement_Id] = 12477
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization conducts penetration testing {{Assignment: organization-defined frequency}} on {{Assignment: organization-defined information systems or system components}}.' WHERE [Requirement_Id] = 12479
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes internal connections of {{Assignment: organization-defined information system components or classes of components}} to the information system; and b. Documents, for each internal connection, the interface characteristics, security requirements, and the nature of the information communicated.' WHERE [Requirement_Id] = 12481
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A configuration management policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the configuration management policy and associated configuration management controls; and b. Reviews and updates the current: 1. Configuration management policy {{Assignment: organization-defined frequency}}; and 2. Configuration management procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12483
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the baseline configuration of the information system: (a) {{Assignment: organization-defined frequency}}; (b) When required due to {{Assignment organization-defined circumstances}}; and (c) As an integral part of information system component installations and upgrades. The organization retains {{Assignment: organization-defined previous versions of baseline configurations of the information system}} to support rollback. The organization: (a) Issues {{Assignment: organization-defined information systems, system components, or devices}} with {{Assignment: organization-defined configurations}} to individuals traveling to locations that the organization deems to be of significant risk; and (b) Applies {{Assignment: organization-defined security safeguards}} to the devices when the individuals return.' WHERE [Requirement_Id] = 12485
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines the types of changes to the information system that are configuration-controlled; b. Reviews proposed configuration-controlled changes to the information system and approves or disapproves such changes with explicit consideration for security impact analyses; c. Documents configuration change decisions associated with the information system; d. Implements approved configuration-controlled changes to the information system; e. Retains records of configuration-controlled changes to the information system for {{Assignment: organization-defined time period}}; f. Audits and reviews activities associated with configuration-controlled changes to the information system; and g. Coordinates and provides oversight for configuration change control activities through {{Assignment: organization-defined configuration change control element (e.g., committee, board)}} that convenes {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined configuration change conditions]}}. The organization tests, validates, and documents changes to the information system before implementing the changes on the operational system.' WHERE [Requirement_Id] = 12488
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to: (a) Document proposed changes to the information system; (b) Notify {{Assignment: organized-defined approval authorities}} of proposed changes to the information system and request change approval; (c) Highlight proposed changes to the information system that have not been approved or disapproved by {{Assignment: organization-defined time period}}; (d) Prohibit changes to the information system until designated approvals are received; (e) Document all changes to the information system; and (f) Notify {{Assignment: organization-defined personnel}} when approved changes to the information system are completed.' WHERE [Requirement_Id] = 12489
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to implement changes to the current information system baseline and deploys the updated baseline across the installed base. The organization requires an information security representative to be a member of the {{Assignment: organization-defined configuration change control element (e.g., committee, board)}}. The information system implements {{Assignment: organization-defined security responses}} automatically if baseline configurations are changed in an unauthorized manner. The organization ensures that cryptographic mechanisms used to provide {{Assignment: organization-defined security safeguards}} are under configuration management.' WHERE [Requirement_Id] = 12490
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces access restrictions and supports auditing of the enforcement actions. The organization reviews information system changes {{Assignment: organization-defined frequency}} and {{Assignment: organization-defined circumstances}} to determine whether unauthorized changes have occurred. The information system prevents the installation of {{Assignment: organization-defined software and firmware components}} without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.' WHERE [Requirement_Id] = 12495
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for implementing changes to {{Assignment: organization-defined information system components and system-level information}}. The organization: (a) Limits privileges to change information system components and system-related information within a production or operational environment; and (b) Reviews and reevaluates privileges {{Assignment: organization-defined frequency}}. The organization limits privileges to change software resident within software libraries.' WHERE [Requirement_Id] = 12496
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and documents configuration settings for information technology products employed within the information system using {{Assignment: organization-defined security configuration checklists}} that reflect the most restrictive mode consistent with operational requirements; b. Implements the configuration settings; c. Identifies, documents, and approves any deviations from established configuration settings for {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined operational requirements}}; and d. Monitors and controls changes to the configuration settings in accordance with organizational policies and procedures.' WHERE [Requirement_Id] = 12497
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to centrally manage, apply, and verify configuration settings for {{Assignment: organization-defined information system components}}. The organization employs {{Assignment: organization-defined security safeguards}} to respond to unauthorized changes to {{Assignment: organization-defined configuration settings}}.' WHERE [Requirement_Id] = 12498
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Configures the information system to provide only essential capabilities; and b. Prohibits or restricts the use of the following functions, ports, protocols, and/or services: {{Assignment: organization-defined prohibited or restricted functions, ports, protocols, and/or services}}. The organization: a. Reviews the information system {{Assignment: organization-defined frequency}} to identify unnecessary and/or non-secure functions, ports, protocols, and services; and b. Disables {{Assignment: organization-defined functions, ports, protocols, and services within the information system deemed to be unnecessary and/or non-secure}}.' WHERE [Requirement_Id] = 12499
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents program execution in accordance with {{Selection (one or more): [Assignment: organization-defined policies regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage}}. The organization: (a) Identifies {{Assignment: organization-defined software programs authorized to execute on the information system}}; (b) Employs a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the information system; and (c) Reviews and updates the list of authorized software programs {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12500
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs not authorized to execute on the information system}}; (b) Employs an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the information system; and (c) Reviews and updates the list of unauthorized software programs {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12501
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents an inventory of information system components that: 1. Accurately reflects the current information system; 2. Includes all components within the authorization boundary of the information system; 3. Is at the level of granularity deemed necessary for tracking and reporting; and 4. Includes {{Assignment: organization-defined information deemed necessary to achieve effective information system component accountability}}; and b. Reviews and updates the information system component inventory {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12502
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization updates the inventory of information system components as an integral part of component installations, removals, and information system updates. The organization: (a) Employs automated mechanisms {{Assignment: organization-defined frequency}} to detect the presence of unauthorized hardware, software, and firmware components within the information system; and (b) Takes the following actions when unauthorized components are detected: {{Selection (one or more): disables network access by such components; isolates the components; notifies [Assignment: organization-defined personnel or roles]}}. The organization verifies that all components within the authorization boundary of the information system are not duplicated in other information system inventories.' WHERE [Requirement_Id] = 12503
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to help maintain an up-to-date, complete, accurate, and readily available inventory of information system components. The organization includes in the information system component inventory information, a means for identifying by {{Selection (one or more): name; position; role}}, individuals responsible/accountable for administering those components.' WHERE [Requirement_Id] = 12504
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes assessed component configurations and any approved deviations to current deployed configurations in the information system component inventory. The organization provides a centralized repository for the inventory of information system components. The organization employs automated mechanisms to support tracking of information system components by geographic location. The organization: (a) Assigns {{Assignment: organization-defined acquired information system components}} to an information system; and (b) Receives an acknowledgement from the information system owner of this assignment.' WHERE [Requirement_Id] = 12505
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes the following restrictions on the use of open source software: {{Assignment: organization-defined restrictions}}.' WHERE [Requirement_Id] = 12509
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined policies}} governing the installation of software by users; b. Enforces software installation policies through {{Assignment: organization-defined methods}}; and c. Monitors policy compliance at {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12510
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the unauthorized installation of software is detected. The information system prohibits user installation of software without explicit privileged status.' WHERE [Requirement_Id] = 12511
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A contingency planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls; and b. Reviews and updates the current: 1. Contingency planning policy {{Assignment: organization-defined frequency}}; and 2. Contingency planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12512
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a contingency plan for the information system that: 1. Identifies essential missions and business functions and associated contingency requirements; 2. Provides recovery objectives, restoration priorities, and metrics; 3. Addresses contingency roles, responsibilities, assigned individuals with contact information; 4. Addresses maintaining essential missions and business functions despite an information system disruption, compromise, or failure; 5. Addresses eventual, full information system restoration without deterioration of the security safeguards originally planned and implemented; and 6. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the contingency plan to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; c. Coordinates contingency planning activities with incident handling activities; d. Reviews the contingency plan for the information system {{Assignment: organization-defined frequency}}; e. Updates the contingency plan to address changes to the organization, information system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing; f. Communicates contingency plan changes to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; and g. Protects the contingency plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 12513
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates contingency plan development with organizational elements responsible for related plans. The organization plans for the resumption of essential missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation. The organization plans for the continuance of essential missions and business functions with little or no loss of operational continuity and sustains that continuity until full information system restoration at primary processing and/or storage sites.' WHERE [Requirement_Id] = 12514
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization conducts capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations. The organization plans for the resumption of all missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation.' WHERE [Requirement_Id] = 12515
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides contingency training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming a contingency role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 12517
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Tests the contingency plan for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the effectiveness of the plan and the organizational readiness to execute the plan; b. Reviews the contingency plan test results; and c. Initiates corrective actions, if needed.' WHERE [Requirement_Id] = 12520
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes an alternate processing site including necessary agreements to permit the transfer and resumption of {{Assignment: organization-defined information system operations}} for essential missions/business functions within {{Assignment: organization-defined time period consistent with recovery time and recovery point objectives}} when the primary processing capabilities are unavailable; b. Ensures that equipment and supplies required to transfer and resume operations are available at the alternate processing site or contracts are in place to support delivery to the site within the organization-defined time period for transfer/resumption; and c. Ensures that the alternate processing site provides information security safeguards equivalent to that of the primary site. The organization identifies an alternate processing site that is separated from the primary processing site to reduce susceptibility to the same threats. The organization identifies potential accessibility problems to the alternate processing site in the event of an area-wide disruption or disaster and outlines explicit mitigation actions. The organization develops alternate processing site agreements that contain priority-of-service provisions in accordance with organizational availability requirements (including recovery time objectives).' WHERE [Requirement_Id] = 12526
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes alternate telecommunications services including necessary agreements to permit the resumption of {{Assignment: organization-defined information system operations}} for essential missions and business functions within {{Assignment: organization-defined time period}} when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites. The organization: (a) Develops primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with organizational availability requirements (including recovery time objectives); and (b) Requests Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness in the event that the primary and/or alternate telecommunications services are provided by a common carrier. The organization obtains alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.' WHERE [Requirement_Id] = 12529
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization obtains alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats. The organization: (a) Requires primary and alternate telecommunications service providers to have contingency plans; (b) Reviews provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtains evidence of contingency testing/training by providers {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12530
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests alternate telecommunication services {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12531
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts backups of user-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; b. Conducts backups of system-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; c. Conducts backups of information system documentation including security-related documentation {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; and d. Protects the confidentiality, integrity, and availability of backup information at storage locations.' WHERE [Requirement_Id] = 12532
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests backup information {{Assignment: organization-defined frequency}} to verify media reliability and information integrity.' WHERE [Requirement_Id] = 12533
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization uses a sample of backup information in the restoration of selected information system functions as part of contingency plan testing. The organization stores backup copies of {{Assignment: organization-defined critical information system software and other security-related information}} in a separate facility or in a fire-rated container that is not collocated with the operational system. The organization transfers information system backup information to the alternate storage site {{Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives}}.' WHERE [Requirement_Id] = 12534
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization accomplishes information system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations. The organization enforces dual authorization for the deletion or destruction of {{Assignment: organization-defined backup information}}.' WHERE [Requirement_Id] = 12535
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to restore information system components within {{Assignment: organization-defined restoration time-periods}} from configuration-controlled and integrity-protected information representing a known, operational state for the components.' WHERE [Requirement_Id] = 12538
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when {{Assignment: organization-defined conditions}} are detected, enters a safe mode of operation with {{Assignment: organization-defined restrictions of safe mode of operation}}.' WHERE [Requirement_Id] = 12540
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An identification and authentication policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the identification and authentication policy and associated identification and authentication controls; and b. Reviews and updates the current: 1. Identification and authentication policy {{Assignment: organization-defined frequency}}; and 2. Identification and authentication procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12541
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for network access to non-privileged accounts. The information system implements multifactor authentication for local access to privileged accounts. The information system implements replay-resistant authentication mechanisms for network access to privileged accounts. The information system implements multifactor authentication for remote access to privileged and non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}. The information system implements multifactor authentication for remote access to non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 12543
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires individuals to be authenticated with an individual authenticator when a group authenticator is employed. The information system implements multifactor authentication for network access to privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}. The information system implements multifactor authentication for network access to non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}. The information system provides a single sign-on capability for {{Assignment: organization-defined list of information system accounts and services}}. The information system implements {{Assignment: organization-defined out-of-band authentication}} under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 12545
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates {{Assignment: organization-defined specific and/or types of devices}} before establishing a {{Selection (one or more): local; remote; network}} connection.' WHERE [Requirement_Id] = 12546
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system authenticates {{Assignment: organization-defined specific devices and/or types of devices}} before establishing {{Selection (one or more): local; remote; network}} connection using bidirectional authentication that is cryptographically based. The organization ensures that device identification and authentication based on attestation is handled by {{Assignment: organization-defined configuration management process}}.' WHERE [Requirement_Id] = 12547
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Standardizes dynamic address allocation lease information and the lease duration assigned to devices in accordance with {{Assignment: organization-defined lease information and lease duration}}; and (b) Audits lease information when assigned to a device.' WHERE [Requirement_Id] = 12548
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system identifiers by: a. Receiving authorization from {{Assignment: organization-defined personnel or roles}} to assign an individual, group, role, or device identifier; b. Selecting an identifier that identifies an individual, group, role, or device; c. Assigning the identifier to the intended individual, group, role, or device; d. Preventing reuse of identifiers for {{Assignment: organization-defined time period}}; and e. Disabling the identifier after {{Assignment: organization-defined time period of inactivity}}.' WHERE [Requirement_Id] = 12549
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the use of information system account identifiers that are the same as public identifiers for individual electronic mail accounts. The organization requires that the registration process to receive an individual identifier includes supervisor authorization. The organization requires multiple forms of certification of individual identification such as documentary evidence or a combination of documents and biometrics be presented to the registration authority. The organization manages individual identifiers by uniquely identifying each individual as {{Assignment: organization-defined characteristic identifying individual status}}. The information system dynamically manages identifiers. The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of identifiers. The organization requires that the registration process to receive an individual identifier be conducted in person before a designated registration authority.' WHERE [Requirement_Id] = 12550
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, or device receiving the authenticator; b. Establishing initial authenticator content for authenticators defined by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost/compromised or damaged authenticators, and for revoking authenticators; e. Changing default content of authenticators prior to information system installation; f. Establishing minimum and maximum lifetime restrictions and reuse conditions for authenticators; g. Changing/refreshing authenticators {{Assignment: organization-defined time period by authenticator type}}; h. Protecting authenticator content from unauthorized disclosure and modification; i. Requiring individuals to take, and having devices implement, specific security safeguards to protect authenticators; and j. Changing authenticators for group/role accounts when membership to those accounts changes. The information system, for password-based authentication: (a) Enforces minimum password complexity of {{Assignment: organization-defined requirements for case sensitivity, number of characters, mix of upper-case letters, lower-case letters, numbers, and special characters, including minimum requirements for each type}}; (b) Enforces at least the following number of changed characters when new passwords are created: {{Assignment: organization-defined number}}; (c) Stores and transmits only encrypted representations of passwords; (d) Enforces password minimum and maximum lifetime restrictions of {{Assignment: organization-defined numbers for lifetime minimum, lifetime maximum}}; (e) Prohibits password reuse for {{Assignment: organization-defined number}} generations; and (f) Allows the use of a temporary password for system logons with an immediate change to a permanent password. The information system, for hardware token-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined token quality requirements}}.' WHERE [Requirement_Id] = 12551
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for PKI-based authentication: (a) Validates certifications by constructing and verifying a certification path to an accepted trust anchor including checking certificate status information; (b) Enforces authorized access to the corresponding private key; (c) Maps the authenticated identity to the account of the individual or group; and (d) Implements a local cache of revocation data to support path discovery and validation in case of inability to access revocation information via the network. The organization requires that the registration process to receive {{Assignment: organization-defined types of and/or specific authenticators}} be conducted {{Selection: in person; by a trusted third party}} before {{Assignment: organization-defined registration authority}} with authorization by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12552
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to determine if password authenticators are sufficiently strong to satisfy {{Assignment: organization-defined requirements}}. The organization requires developers/installers of information system components to provide unique authenticators or change default authenticators prior to delivery/installation. The organization protects authenticators commensurate with the security category of the information to which use of the authenticator permits access. The organization ensures that unencrypted static authenticators are not embedded in applications or access scripts or stored on function keys. The organization implements {{Assignment: organization-defined security safeguards}} to manage the risk of compromise due to individuals having accounts on multiple information systems. The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of credentials. The information system dynamically provisions identities. The information system, for biometric-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined biometric quality requirements}}. The information system prohibits the use of cached authenticators after {{Assignment: organization-defined time period}}. The organization, for PKI-based authentication, employs a deliberate organization-wide methodology for managing the content of PKI trust stores installed across all platforms including networks, operating systems, browsers, and applications. The organization uses only FICAM-approved path discovery and validation products and services.' WHERE [Requirement_Id] = 12553
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates non-organizational users (or processes acting on behalf of non-organizational users). The information system accepts and electronically verifies Personal Identity Verification (PIV) credentials from other federal agencies. The information system accepts only FICAM-approved third-party credentials. The organization employs only FICAM-approved information system components in {{Assignment: organization-defined information systems}} to accept third-party credentials. The information system conforms to FICAM-issued profiles.' WHERE [Requirement_Id] = 12556
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An incident response policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the incident response policy and associated incident response controls; and b. Reviews and updates the current: 1. Incident response policy {{Assignment: organization-defined frequency}}; and 2. Incident response procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12558
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides incident response training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming an incident response role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 12559
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests the incident response capability for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the incident response effectiveness and documents the results. The organization coordinates incident response testing with organizational elements responsible for related plans.' WHERE [Requirement_Id] = 12561
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes dynamic reconfiguration of {{Assignment: organization-defined information system components}} as part of the incident response capability. The organization identifies {{Assignment: organization-defined classes of incidents}} and {{Assignment: organization-defined actions to take in response to classes of incidents}} to ensure continuation of organizational missions and business functions. The organization implements a configurable capability to automatically disable the information system if {{Assignment: organization-defined security violations}} are detected. The organization implements incident handling capability for insider threats. The organization coordinates incident handling capability for insider threats across {{Assignment: organization-defined components or elements of the organization}}. The organization coordinates with {{Assignment: organization-defined external organizations}} to correlate and share {{Assignment: organization-defined incident information}} to achieve a cross-organization perspective on incident awareness and more effective incident responses. The organization employs {{Assignment: organization-defined dynamic response capabilities}} to effectively respond to security incidents. The organization coordinates incident handling activities involving supply chain events with other organizations involved in the supply chain.' WHERE [Requirement_Id] = 12566
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires personnel to report suspected security incidents to the organizational incident response capability within {{Assignment: organization-defined time period}}; and b. Reports security incident information to {{Assignment: organization-defined authorities}}.' WHERE [Requirement_Id] = 12569
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reports information system vulnerabilities associated with reported security incidents to {{Assignment: organization-defined personnel or roles}}. The organization provides security incident information to other organizations involved in the supply chain for information systems or information system components related to the incident.' WHERE [Requirement_Id] = 12571
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an incident response plan that: 1. Provides the organization with a roadmap for implementing its incident response capability; 2. Describes the structure and organization of the incident response capability; 3. Provides a high-level approach for how the incident response capability fits into the overall organization; 4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions; 5. Defines reportable incidents; 6. Provides metrics for measuring the incident response capability within the organization; 7. Defines the resources and management support needed to effectively maintain and mature an incident response capability; and 8. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the incident response plan to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; c. Reviews the incident response plan {{Assignment: organization-defined frequency}}; d. Updates the incident response plan to address system/organizational changes or problems encountered during plan implementation, execution, or testing; e. Communicates incident response plan changes to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; and f. Protects the incident response plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 12575
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system maintenance policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system maintenance policy and associated system maintenance controls; and b. Reviews and updates the current: 1. System maintenance policy {{Assignment: organization-defined frequency}}; and 2. System maintenance procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12576
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Schedules, performs, documents, and reviews records of maintenance and repairs on information system components in accordance with manufacturer or vendor specifications and/or organizational requirements; b. Approves and monitors all maintenance activities, whether performed on site or remotely and whether the equipment is serviced on site or removed to another location; c. Requires that {{Assignment: organization-defined personnel or roles}} explicitly approve the removal of the information system or system components from organizational facilities for off-site maintenance or repairs; d. Sanitizes equipment to remove all information from associated media prior to removal from organizational facilities for off-site maintenance or repairs; e. Checks all potentially impacted security controls to verify that the controls are still functioning properly following maintenance or repair actions; and f. Includes {{Assignment: organization-defined maintenance-related information}} in organizational maintenance records.' WHERE [Requirement_Id] = 12577
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prevents the unauthorized removal of maintenance equipment containing organizational information by: (a) Verifying that there is no organizational information contained on the equipment; (b) Sanitizing or destroying the equipment; (c) Retaining the equipment within the facility; or (d) Obtaining an exemption from {{Assignment: organization-defined personnel or roles}} explicitly authorizing removal of the equipment from the facility.' WHERE [Requirement_Id] = 12580
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Audits non-local maintenance and diagnostic sessions {{Assignment: organization-defined audit events}}; and (b) Reviews the records of the maintenance and diagnostic sessions. The organization protects non-local maintenance sessions by: (a) Employing {{Assignment: organization-defined authenticators that are replay resistant}}; and (b) Separating the maintenance sessions from other network sessions with the information system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths based upon encryption. The organization: (a) Requires the approval of each non-local maintenance session by {{Assignment: organization-defined personnel or roles}}; and (b) Notifies {{Assignment: organization-defined personnel or roles}} of the date and time of planned non-local maintenance. The information system implements cryptographic mechanisms to protect the integrity and confidentiality of non-local maintenance and diagnostic communications. The information system implements remote disconnect verification at the termination of non-local maintenance and diagnostic sessions.' WHERE [Requirement_Id] = 12585
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization obtains maintenance support and/or spare parts for {{Assignment: organization-defined information system components}} within {{Assignment: organization-defined time period}} of failure.' WHERE [Requirement_Id] = 12589
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs preventive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}. The organization performs predictive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}. The organization employs automated mechanisms to transfer predictive maintenance data to a computerized maintenance management system.' WHERE [Requirement_Id] = 12590
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A media protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the media protection policy and associated media protection controls; and b. Reviews and updates the current: 1. Media protection policy {{Assignment: organization-defined frequency}}; and 2. Media protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12591
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts access to {{Assignment: organization-defined types of digital and/or non-digital media}} to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12592
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Marks information system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempts {{Assignment: organization-defined types of information system media}} from marking as long as the media remain within {{Assignment: organization-defined controlled areas}}.' WHERE [Requirement_Id] = 12593
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Physically controls and securely stores {{Assignment: organization-defined types of digital and/or non-digital media}} within {{Assignment: organization-defined controlled areas}}; and b. Protects information system media until the media are destroyed or sanitized using approved equipment, techniques, and procedures.' WHERE [Requirement_Id] = 12594
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Protects and controls {{Assignment: organization-defined types of information system media}} during transport outside of controlled areas using {{Assignment: organization-defined security safeguards}}; b. Maintains accountability for information system media during transport outside of controlled areas; c. Documents activities associated with the transport of information system media; and d. Restricts the activities associated with the transport of information system media to authorized personnel.' WHERE [Requirement_Id] = 12596
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Sanitizes {{Assignment: organization-defined information system media}} prior to disposal, release out of organizational control, or release for reuse using {{Assignment: organization-defined sanitization techniques and procedures}} in accordance with applicable federal and organizational standards and policies; and b. Employs sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.' WHERE [Requirement_Id] = 12599
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews, approves, tracks, documents, and verifies media sanitization and disposal actions. The organization tests sanitization equipment and procedures {{Assignment: organization-defined frequency}} to verify that the intended sanitization is being achieved. The organization applies non-destructive sanitization techniques to portable storage devices prior to connecting such devices to the information system under the following circumstances: {{Assignment: organization-defined circumstances requiring sanitization of portable storage devices}}.' WHERE [Requirement_Id] = 12600
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the sanitization of {{Assignment: organization-defined information system media}}. The organization provides the capability to purge/wipe information from {{Assignment: organization-defined information systems, system components, or devices}} either remotely or under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 12601
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of {{Assignment: organization-defined types of information system media}} on {{Assignment: organization-defined information systems or system components}} using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 12602
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A physical and environmental protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the physical and environmental protection policy and associated physical and environmental protection controls; and b. Reviews and updates the current: 1. Physical and environmental protection policy {{Assignment: organization-defined frequency}}; and 2. Physical and environmental protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12605
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, approves, and maintains a list of individuals with authorized access to the facility where the information system resides; b. Issues authorization credentials for facility access; c. Reviews the access list detailing authorized facility access by individuals {{Assignment: organization-defined frequency}}; and d. Removes individuals from the facility access list when access is no longer required.' WHERE [Requirement_Id] = 12606
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes physical access to the facility where the information system resides based on position or role. The organization requires two forms of identification from {{Assignment: organization-defined list of acceptable forms of identification}} for visitor access to the facility where the information system resides. The organization restricts unescorted access to the facility where the information system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 12607
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Enforces physical access authorizations at {{Assignment: organization-defined entry/exit points to the facility where the information system resides}} by; 1. Verifying individual access authorizations before granting access to the facility; and 2. Controlling ingress/egress to the facility using {{Selection (one or more): [Assignment: organization-defined physical access control systems/devices]; guards}}; b. Maintains physical access audit logs for {{Assignment: organization-defined entry/exit points}}; c. Provides {{Assignment: organization-defined security safeguards}} to control access to areas within the facility officially designated as publicly accessible; d. Escorts visitors and monitors visitor activity {{Assignment: organization-defined circumstances requiring visitor escorts and monitoring}}; e. Secures keys, combinations, and other physical access devices; f. Inventories {{Assignment: organization-defined physical access devices}} every {{Assignment: organization-defined frequency}}; and g. Changes combinations and keys {{Assignment: organization-defined frequency}} and/or when keys are lost, combinations are compromised, or individuals are transferred or terminated.' WHERE [Requirement_Id] = 12608
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces physical access authorizations to the information system in addition to the physical access controls for the facility at {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 12609
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs security checks {{Assignment: organization-defined frequency}} at the physical boundary of the facility or information system for unauthorized exfiltration of information or removal of information system components. The organization employs guards and/or alarms to monitor every physical access point to the facility where the information system resides 24 hours per day, 7 days per week. The organization uses lockable physical casings to protect {{Assignment: organization-defined information system components}} from unauthorized physical access. The organization employs {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization-defined hardware components}} within the information system. The organization employs a penetration testing process that includes {{Assignment: organization-defined frequency}}, unannounced attempts to bypass or circumvent security controls associated with physical access points to the facility.' WHERE [Requirement_Id] = 12610
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization controls physical access to {{Assignment: organization-defined information system distribution and transmission lines}} within organizational facilities using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 12611
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Ensures that only authorized individuals receive output from the device. The information system: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Links individual identity to receipt of the output from the device. The organization marks {{Assignment: organization-defined information system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 12613
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors physical access to the facility where the information system resides to detect and respond to physical security incidents; b. Reviews physical access logs {{Assignment: organization-defined frequency}} and upon occurrence of {{Assignment: organization-defined events or potential indications of events}}; and c. Coordinates results of reviews and investigations with the organizational incident response capability.' WHERE [Requirement_Id] = 12614
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors physical intrusion alarms and surveillance equipment. The organization monitors physical access to the information system in addition to the physical access monitoring of the facility as {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 12615
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to recognize {{Assignment: organization-defined classes/types of intrusions}} and initiate {{Assignment: organization-defined response actions}}. The organization employs video surveillance of {{Assignment: organization-defined operational areas}} and retains video recordings for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12616
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains visitor access records to the facility where the information system resides for {{Assignment: organization-defined time period}}; and b. Reviews visitor access records {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12617
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects power equipment and power cabling for the information system from damage and destruction. The organization employs redundant power cabling paths that are physically separated by {{Assignment: organization-defined distance}}.' WHERE [Requirement_Id] = 12619
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automatic voltage controls for {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 12620
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Provides the capability of shutting off power to the information system or individual system components in emergency situations; b. Places emergency shutoff switches or devices in {{Assignment: organization-defined location by information system or system component}} to facilitate safe and easy access for personnel; and c. Protects emergency power shutoff capability from unauthorized activation.' WHERE [Requirement_Id] = 12621
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a short-term uninterruptible power supply to facilitate {{Selection (one or more): an orderly shutdown of the information system; transition of the information system to long-term alternate power}} in the event of a primary power source loss. The organization provides a long-term alternate power supply for the information system that is capable of maintaining minimally required operational capability in the event of an extended loss of the primary power source.' WHERE [Requirement_Id] = 12622
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a long-term alternate power supply for the information system that is: (a) Self-contained; (b) Not reliant on external power generation; and (c) Capable of maintaining {{Selection: minimally required operational capability; full operational capability}} in the event of an extended loss of the primary power source.' WHERE [Requirement_Id] = 12623
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire detection devices/systems for the information system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire. The organization employs fire suppression devices/systems for the information system that provide automatic notification of any activation to {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}}.' WHERE [Requirement_Id] = 12628
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that the facility undergoes {{Assignment: organization-defined frequency}} inspections by authorized and qualified inspectors and resolves identified deficiencies within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12629
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains temperature and humidity levels within the facility where the information system resides at {{Assignment: organization-defined acceptable levels}}; and b. Monitors temperature and humidity levels {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12630
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to detect the presence of water in the vicinity of the information system and alerts {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12633
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes, monitors, and controls {{Assignment: organization-defined types of information system components}} entering and exiting the facility and maintains records of those items.' WHERE [Requirement_Id] = 12634
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs {{Assignment: organization-defined security controls}} at alternate work sites; b. Assesses as feasible, the effectiveness of security controls at alternate work sites; and c. Provides a means for employees to communicate with information security personnel in case of security incidents or problems.' WHERE [Requirement_Id] = 12635
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization positions information system components within the facility to minimize potential damage from {{Assignment: organization-defined physical and environmental hazards}} and to minimize the opportunity for unauthorized access.' WHERE [Requirement_Id] = 12636
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security planning policy and associated security planning controls; and b. Reviews and updates the current: 1. Security planning policy {{Assignment: organization-defined frequency}}; and 2. Security planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12638
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security plan for the information system that: 1. Is consistent with the organizations enterprise architecture; 2. Explicitly defines the authorization boundary for the system; 3. Describes the operational context of the information system in terms of missions and business processes; 4. Provides the security categorization of the information system including supporting rationale; 5. Describes the operational environment for the information system and relationships with or connections to other information systems; 6. Provides an overview of the security requirements for the system; 7. Identifies any relevant overlays, if applicable; 8. Describes the security controls in place or planned for meeting those requirements including a rationale for the tailoring and supplementation decisions; and 9. Is reviewed and approved by the authorizing official or designated representative prior to plan implementation; b. Distributes copies of the security plan and communicates subsequent changes to the plan to {{Assignment: organization-defined personnel or roles}}; c. Reviews the security plan for the information system {{Assignment: organization-defined frequency}}; d. Updates the plan to address changes to the information system/environment of operation or problems identified during plan implementation or security control assessments; and e. Protects the security plan from unauthorized disclosure and modification. The organization plans and coordinates security-related activities affecting the information system with {{Assignment: organization-defined individuals or groups}} before conducting such activities in order to reduce the impact on other organizational entities.' WHERE [Requirement_Id] = 12639
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and makes readily available to individuals requiring access to the information system, the rules that describe their responsibilities and expected behavior with regard to information and information system usage; b. Receives a signed acknowledgement from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the information system; c. Reviews and updates the rules of behavior {{Assignment: organization-defined frequency}}; and d. Requires individuals who have signed a previous version of the rules of behavior to read and resign when the rules of behavior are revised/updated.' WHERE [Requirement_Id] = 12640
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security Concept of Operations (CONOPS) for the information system containing at a minimum, how the organization intends to operate the system from the perspective of information security; and b. Reviews and updates the CONOPS {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12642
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an information security architecture for the information system that: 1. Describes the overall philosophy, requirements, and approach to be taken with regard to protecting the confidentiality, integrity, and availability of organizational information; 2. Describes how the information security architecture is integrated into and supports the enterprise architecture; and 3. Describes any information security assumptions about, and dependencies on, external services; b. Reviews and updates the information security architecture {{Assignment: organization-defined frequency}} to reflect updates in the enterprise architecture; and c. Ensures that planned information security architecture changes are reflected in the security plan, the security Concept of Operations (CONOPS), and organizational procurements/acquisitions.' WHERE [Requirement_Id] = 12643
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization designs its security architecture using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security safeguards operate in a coordinated and mutually reinforcing manner. The organization requires that {{Assignment: organization-defined security safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 12644
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and disseminates an organization-wide information security program plan that: 1. Provides an overview of the requirements for the security program and a description of the security program management controls and common controls in place or planned for meeting those requirements; 2. Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 3. Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; b. Reviews the organization-wide information security program plan {{Assignment: organization-defined frequency}}; c. Updates the plan to address organizational changes and problems identified during plan implementation or security control assessments; and d. Protects the information security program plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 12645
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A personnel security policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the personnel security policy and associated personnel security controls; and b. Reviews and updates the current: 1. Personnel security policy {{Assignment: organization-defined frequency}}; and 2. Personnel security procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12661
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a risk designation to all organizational positions; b. Establishes screening criteria for individuals filling those positions; and c. Reviews and updates position risk designations {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12662
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Screens individuals prior to authorizing access to the information system; and b. Rescreens individuals according to {{Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of such rescreening}}.' WHERE [Requirement_Id] = 12663
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that individuals accessing an information system processing, storing, or transmitting classified information are cleared and indoctrinated to the highest classification level of the information to which they have access on the system. The organization ensures that individuals accessing an information system processing, storing, or transmitting types of classified information which require formal indoctrination, are formally indoctrinated for all of the relevant types of information to which they have access on the system. The organization ensures that individuals accessing an information system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 12664
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization, upon termination of individual employment: a. Disables information system access within {{Assignment: organization-defined time period}}; b. Terminates/revokes any authenticators/credentials associated with the individual; c. Conducts exit interviews that include a discussion of {{Assignment: organization-defined information security topics}}; d. Retrieves all security-related organizational information system-related property; e. Retains access to organizational information and information systems formerly controlled by terminated individual; and f. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12665
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to notify {{Assignment: organization-defined personnel or roles}} upon termination of an individual.' WHERE [Requirement_Id] = 12666
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and confirms ongoing operational need for current logical and physical access authorizations to information systems/facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiates {{Assignment: organization-defined transfer or reassignment actions}} within {{Assignment: organization-defined time period following the formal transfer action}}; c. Modifies access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12668
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents access agreements for organizational information systems; b. Reviews and updates the access agreements {{Assignment: organization-defined frequency}}; and c. Ensures that individuals requiring access to organizational information and information systems: 1. Sign appropriate access agreements prior to being granted access; and 2. Re-sign access agreements to maintain access to organizational information systems when access agreements have been updated or {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12669
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes personnel security requirements including security roles and responsibilities for third-party providers; b. Requires third-party providers to comply with personnel security policies and procedures established by the organization; c. Documents personnel security requirements; d. Requires third-party providers to notify {{Assignment: organization-defined personnel or roles}} of any personnel transfers or terminations of third-party personnel who possess organizational credentials and/or badges, or who have information system privileges within {{Assignment: organization-defined time period}}; and e. Monitors provider compliance.' WHERE [Requirement_Id] = 12671
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs a formal sanctions process for individuals failing to comply with established information security policies and procedures; and b. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}} when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.' WHERE [Requirement_Id] = 12672
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A risk assessment policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the risk assessment policy and associated risk assessment controls; and b. Reviews and updates the current: 1. Risk assessment policy {{Assignment: organization-defined frequency}}; and 2. Risk assessment procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12673
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts an assessment of risk, including the likelihood and magnitude of harm, from the unauthorized access, use, disclosure, disruption, modification, or destruction of the information system and the information it processes, stores, or transmits; b. Documents risk assessment results in {{Selection: security plan; risk assessment report; [Assignment: organization-defined document]}}; c. Reviews risk assessment results {{Assignment: organization-defined frequency}}; d. Disseminates risk assessment results to {{Assignment: organization-defined personnel or roles}}; and e. Updates the risk assessment {{Assignment: organization-defined frequency}} or whenever there are significant changes to the information system or environment of operation (including the identification of new threats and vulnerabilities), or other conditions that may impact the security state of the system.' WHERE [Requirement_Id] = 12675
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Scans for vulnerabilities in the information system and hosted applications {{Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process}} and when new vulnerabilities potentially affecting the system/applications are identified and reported; b. Employs vulnerability scanning tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for: 1. Enumerating platforms, software flaws, and improper configurations; 2. Formatting checklists and test procedures; and 3. Measuring vulnerability impact; c. Analyzes vulnerability scan reports and results from security control assessments; d. Remediates legitimate vulnerabilities {{Assignment: organization-defined response times}} in accordance with an organizational assessment of risk; and e. Shares information obtained from the vulnerability scanning process and security control assessments with {{Assignment: organization-defined personnel or roles}} to help eliminate similar vulnerabilities in other information systems (i.e., systemic weaknesses or deficiencies).' WHERE [Requirement_Id] = 12676
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs vulnerability scanning tools that include the capability to readily update the information system vulnerabilities to be scanned. The organization updates the information system vulnerabilities scanned {{Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported}}. The information system implements privileged access authorization to {{Assignment: organization-identified information system components}} for selected {{Assignment: organization-defined vulnerability scanning activities}}.' WHERE [Requirement_Id] = 12677
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization determines what information about the information system is discoverable by adversaries and subsequently takes {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 12678
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and services acquisition policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and services acquisition policy and associated system and services acquisition controls; and b. Reviews and updates the current: 1. System and services acquisition policy {{Assignment: organization-defined frequency}}; and 2. System and services acquisition procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12680
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Manages the information system using {{Assignment: organization-defined system development life cycle}} that incorporates information security considerations; b. Defines and documents information security roles and responsibilities throughout the system development life cycle; c. Identifies individuals having information security roles and responsibilities; and d. Integrates the organizational information security risk management process into system development life cycle activities.' WHERE [Requirement_Id] = 12682
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide a description of the functional properties of the security controls to be employed. The organization requires the developer of the information system, system component, or information system service to provide design and implementation information for the security controls to be employed that includes: {{Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design/implementation information]}} at {{Assignment: organization-defined level of detail}}. The organization requires the developer of the information system, system component, or information system service to identify early in the system development life cycle, the functions, ports, protocols, and services intended for organizational use.' WHERE [Requirement_Id] = 12684
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{Assignment: organization-defined state-of-the-practice system/security engineering methods, software development methods, testing/evaluation/validation techniques, and quality control processes}}. The organization requires the developer of the information system, system component, or information system service to: (a) Deliver the system, component, or service with {{Assignment; organization-defined security configurations}} implemented; and (b) Use the configurations as the default for any subsequent system, component, or service re-installation or upgrade. The organization: (a) Employs only government off-the-shelf (GOTS) or commercial off-the-shelf (COTS) information assurance (IA) and IA-enabled information technology products that compose an NSA-approved solution to protect classified information when the networks used to transmit the information are at a lower classification level than the information being transmitted; and (b) Ensures that these products have been evaluated and/or validated by NSA or in accordance with NSA-approved procedures. The organization: (a) Limits the use of commercially provided information assurance (IA) and IA-enabled information technology products to those products that have been successfully evaluated against a National Information Assurance partnership (NIAP)-approved Protection Profile for a specific technology type, if such a profile exists; and (b) Requires, if no NIAP-approved Protection Profile exists for a specific technology type but a commercially provided information technology product relies on cryptographic functionality to enforce its security policy, that the cryptographic module is FIPS-validated. The organization requires the developer of the information system, system component, or information system service to produce a plan for the continuous monitoring of security control effectiveness that contains {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 12685
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Obtains administrator documentation for the information system, system component, or information system service that describes: 1. Secure configuration, installation, and operation of the system, component, or service; 2. Effective use and maintenance of security functions/mechanisms; and 3. Known vulnerabilities regarding configuration and use of administrative (i.e., privileged) functions; b. Obtains user documentation for the information system, system component, or information system service that describes: 1. User-accessible security functions/mechanisms and how to effectively use those security functions/mechanisms; 2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner; and 3. User responsibilities in maintaining the security of the system, component, or service; c. Documents attempts to obtain information system, system component, or information system service documentation when such documentation is either unavailable or nonexistent and {{Assignment: organization-defined actions}} in response; d. Protects documentation as required, in accordance with the risk management strategy; and e. Distributes documentation to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12686
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires that providers of external information system services comply with organizational information security requirements and employ {{Assignment: organization-defined security controls}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance; b. Defines and documents government oversight and user roles and responsibilities with regard to external information system services; and c. Employs {{Assignment: organization-defined processes, methods, and techniques}} to monitor security control compliance by external service providers on an ongoing basis.' WHERE [Requirement_Id] = 12688
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires providers of {{Assignment: organization-defined external information system services}} to identify the functions, ports, protocols, and other services required for the use of such services.' WHERE [Requirement_Id] = 12689
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Conducts an organizational assessment of risk prior to the acquisition or outsourcing of dedicated information security services; and (b) Ensures that the acquisition or outsourcing of dedicated information security services is approved by {{Assignment: organization-defined personnel or roles}}. The organization establishes, documents, and maintains trust relationships with external service providers based on {{Assignment: organization-defined security requirements, properties, factors, or conditions defining acceptable trust relationships}}. The organization employs {{Assignment: organization-defined security safeguards}} to ensure that the interests of {{Assignment: organization-defined external service providers}} are consistent with and reflect organizational interests. The organization restricts the location of {{Selection (one or more): information processing; information/data; information system services}} to {{Assignment: organization-defined locations}} based on {{Assignment: organization-defined requirements or conditions}}.' WHERE [Requirement_Id] = 12690
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Perform configuration management during system, component, or service {{Selection (one or more): design; development; implementation; operation}}; b. Document, manage, and control the integrity of changes to {{Assignment: organization-defined configuration items under configuration management}}; c. Implement only organization-approved changes to the system, component, or service; d. Document approved changes to the system, component, or service and the potential security impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service and report findings to {{Assignment: organization-defined personnel}}.' WHERE [Requirement_Id] = 12691
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Create and implement a security assessment plan; b. Perform {{Selection (one or more): unit; integration; system; regression}} testing/evaluation at {{Assignment: organization-defined depth and coverage}}; c. Produce evidence of the execution of the security assessment plan and the results of the security testing/evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during security testing/evaluation.' WHERE [Requirement_Id] = 12693
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to employ static code analysis tools to identify common flaws and document the results of the analysis. The organization requires the developer of the information system, system component, or information system service to perform threat and vulnerability analyses and subsequent testing/evaluation of the as-built system, component, or service. The organization: (a) Requires an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security assessment plan and the evidence produced during security testing/evaluation; and (b) Ensures that the independent agent either is provided with sufficient information to complete the verification process or has been granted the authority to obtain such information. The organization requires the developer of the information system, system component, or information system service to perform a manual code review of {{Assignment: organization-defined specific code}} using {{Assignment: organization-defined processes, procedures, and/or techniques}}. The organization requires the developer of the information system, system component, or information system service to perform penetration testing at {{Assignment: organization-defined breadth/depth}} and with {{Assignment: organization-defined constraints}}. The organization requires the developer of the information system, system component, or information system service to perform attack surface reviews. The organization requires the developer of the information system, system component, or information system service to verify that the scope of security testing/evaluation provides complete coverage of required security controls at {{Assignment: organization-defined depth of testing/evaluation}}. The organization requires the developer of the information system, system component, or information system service to employ dynamic code analysis tools to identify common flaws and document the results of the analysis.' WHERE [Requirement_Id] = 12694
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects against supply chain threats to the information system, system component, or information system service by employing {{Assignment: organization-defined security safeguards}} as part of a comprehensive, defense-in-breadth information security strategy.' WHERE [Requirement_Id] = 12695
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tailored acquisition strategies, contract tools, and procurement methods}} for the purchase of the information system, system component, or information system service from suppliers. The organization conducts a supplier review prior to entering into a contractual agreement to acquire the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to limit harm from potential adversaries identifying and targeting the organizational supply chain. The organization conducts an assessment of the information system, system component, or information system service prior to selection, acceptance, or update. The organization uses all-source intelligence analysis of suppliers and potential suppliers of the information system, system component, or information system service. The organization employs {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} in accordance with classification guides to protect supply chain-related information for the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to validate that the information system or system component received is genuine and has not been altered. The organization employs {{Selection (one or more): organizational analysis, independent third-party analysis, organizational penetration testing, independent third-party penetration testing}} of {{Assignment: organization-defined supply chain elements, processes, and actors}} associated with the information system, system component, or information system service. The organization establishes inter-organizational agreements and procedures with entities involved in the supply chain for the information system, system component, or information system service. The organization employs {{Assignment: organization-defined security safeguards}} to ensure an adequate supply of {{Assignment: organization-defined critical information system components}}. The organization establishes and retains unique identification of {{Assignment: organization-defined supply chain elements, processes, and actors}} for the information system, system component, or information system service. The organization establishes a process to address weaknesses or deficiencies in supply chain elements identified during independent or organizational assessments of such elements.' WHERE [Requirement_Id] = 12696
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires the developer of the information system, system component, or information system service to follow a documented development process that: 1. Explicitly addresses security requirements; 2. Identifies the standards and tools used in the development process; 3. Documents the specific tool options and tool configurations used in the development process; and 4. Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; and b. Reviews the development process, standards, tools, and tool options/configurations {{Assignment: organization-defined frequency}} to determine if the process, standards, tools, and tool options/configurations selected and employed can satisfy {{Assignment: organization-defined security requirements}}.' WHERE [Requirement_Id] = 12697
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery}}. The organization requires the developer of the information system, system component, or information system service to select and employ a security tracking tool for use during the development process. The organization requires the developer of the information system, system component, or information system service to perform a criticality analysis at {{Assignment: organization-defined breadth/depth}} and at {{Assignment: organization-defined decision points in the system development life cycle}}. The organization requires that developers perform threat modeling and a vulnerability analysis for the information system at {{Assignment: organization-defined breadth/depth}} that: (a) Uses {{Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels}}; (b) Employs {{Assignment: organization-defined tools and methods}}; and (c) Produces evidence that meets {{Assignment: organization-defined acceptance criteria}}. The organization requires the developer of the information system, system component, or information system service to reduce attack surfaces to {{Assignment: organization-defined thresholds}}. The organization requires the developer of the information system, system component, or information system service to implement an explicit process to continuously improve the development process. The organization requires the developer of the information system, system component, or information system service to: (a) Perform an automated vulnerability analysis using {{Assignment: organization-defined tools}}; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to {{Assignment: organization-defined personnel or roles}}. The organization requires the developer of the information system, system component, or information system service to use threat modeling and vulnerability analyses from similar systems, components, or services to inform the current development process. The organization approves, documents, and controls the use of live data in development and test environments for the information system, system component, or information system service. The organization requires the developer of the information system, system component, or information system service to provide an incident response plan. The organization requires the developer of the information system or system component to archive the system or component to be released or delivered together with the corresponding evidence supporting the final security review.' WHERE [Requirement_Id] = 12698
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide {{Assignment: organization-defined training}} on the correct use and operation of the implemented security functions, controls, and/or mechanisms.' WHERE [Requirement_Id] = 12699
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, a formal policy model describing the {{Assignment: organization-defined elements of organizational security policy}} to be enforced; and (b) Prove that the formal policy model is internally consistent and sufficient to enforce the defined elements of the organizational security policy when implemented. The organization requires the developer of the information system, system component, or information system service to: (a) Define security-relevant hardware, software, and firmware; and (b) Provide a rationale that the definition for security-relevant hardware, software, and firmware is complete. The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, a formal top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via proof to the extent feasible with additional informal demonstration as necessary, that the formal top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the formal top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the formal top-level specification is an accurate description of the implemented security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the formal top-level specification but strictly internal to the security-relevant hardware, software, and firmware. The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, an informal descriptive top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via {{Selection: informal demonstration, convincing argument with formal methods as feasible}} that the descriptive top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the descriptive top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the descriptive top-level specification is an accurate description of the interfaces to security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the descriptive top-level specification but strictly internal to the security-relevant hardware, software, and firmware. The organization requires the developer of the information system, system component, or information system service to: (a) Design and structure the security-relevant hardware, software, and firmware to use a complete, conceptually simple protection mechanism with precisely defined semantics; and (b) Internally structure the security-relevant hardware, software, and firmware with specific regard for this mechanism. The organization requires the developer of the information system, system component, or information system service to structure security-relevant hardware, software, and firmware to facilitate testing. The organization requires the developer of the information system, system component, or information system service to structure security-relevant hardware, software, and firmware to facilitate controlling access with least privilege.' WHERE [Requirement_Id] = 12701
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and communications protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and communications protection policy and associated system and communications protection controls; and b. Reviews and updates the current: 1. System and communications protection policy {{Assignment: organization-defined frequency}}; and 2. System and communications protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12702
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents unauthorized information transfer via shared resources in accordance with {{Assignment: organization-defined procedures}} when system processing explicitly switches between different information classification levels or security categories.' WHERE [Requirement_Id] = 12708
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against or limits the effects of the following types of denial of service attacks: {{Assignment: organization-defined types of denial of service attacks or reference to source for such information}} by employing {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 12709
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system restricts the ability of individuals to launch {{Assignment: organization-defined denial of service attacks}} against other information systems. The information system manages excess capacity, bandwidth, or other redundancy to limit the effects of information flooding denial of service attacks. The organization: (a) Employs {{Assignment: organization-defined monitoring tools}} to detect indicators of denial of service attacks against the information system; and (b) Monitors {{Assignment: organization-defined information system resources}} to determine if sufficient resources exist to prevent effective denial of service attacks.' WHERE [Requirement_Id] = 12710
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Monitors and controls communications at the external boundary of the system and at key internal boundaries within the system; b. Implements subnetworks for publicly accessible system components that are {{Selection: physically; logically}} separated from internal organizational networks; and c. Connects to external networks or information systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security architecture.' WHERE [Requirement_Id] = 12711
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization physically allocates publicly accessible information system components to separate subnetworks with separate physical network interfaces. The organization limits the number of external network connections to the information system. The organization: (a) Implements a managed interface for each external telecommunication service; (b) Establishes a traffic flow policy for each managed interface; (c) Protects the confidentiality and integrity of the information being transmitted across each interface; (d) Documents each exception to the traffic flow policy with a supporting mission/business need and duration of that need; and (e) Reviews exceptions to the traffic flow policy {{Assignment: organization-defined frequency}} and removes exceptions that are no longer supported by an explicit mission/business need. The information system at managed interfaces denies network communications traffic by default and allows network communications traffic by exception (i.e., deny all, permit by exception).The information system, in conjunction with a remote device, prevents the device from simultaneously establishing non-remote connections with the system and communicating via some other connection to resources in external networks. The information system fails securely in the event of an operational failure of a boundary protection device.' WHERE [Requirement_Id] = 12712
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system routes {{Assignment: organization-defined internal communications traffic}} to {{Assignment: organization-defined external networks}} through authenticated proxy servers at managed interfaces. The organization employs boundary protection mechanisms to separate {{Assignment: organization-defined information system components}} supporting {{Assignment: organization-defined missions and/or business functions}}.' WHERE [Requirement_Id] = 12713
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Detects and denies outgoing communications traffic posing a threat to external information systems; and (b) Audits the identity of internal users associated with denied communications. The organization prevents the unauthorized exfiltration of information across managed interfaces. The information system only allows incoming communications from {{Assignment: organization-defined authorized sources}} routed to {{Assignment: organization-defined authorized destinations}}. The organization implements {{Assignment: organization-defined host-based boundary protection mechanisms}} at {{Assignment: organization-defined information system components}}. The organization isolates {{Assignment: organization-defined information security tools, mechanisms, and support components}} from other internal information system components by implementing physically separate subnetworks with managed interfaces to other components of the system. The organization protects against unauthorized physical connections at {{Assignment: organization-defined managed interfaces}}. The information system routes all networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing. The information system prevents discovery of specific system components composing a managed interface. The information system enforces adherence to protocol formats. The information system blocks both inbound and outbound communications traffic between {{Assignment: organization-defined communication clients}} that are independently configured by end users and external service providers. The information system provides the capability to dynamically isolate/segregate {{Assignment: organization-defined information system components}} from other components of the system. The information system implements separate network addresses (i.e., different subnets) to connect to systems in different security domains. The information system disables feedback to senders on protocol format validation failure.' WHERE [Requirement_Id] = 12714
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of transmitted information. The information system implements cryptographic mechanisms to {{Selection (one or more): prevent unauthorized disclosure of information; detect changes to information}} during transmission unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 12715
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system maintains the {{Selection (one or more): confidentiality; integrity}} of information during preparation for transmission and during reception. The information system implements cryptographic mechanisms to protect message externals unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}. The information system implements cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 12716
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system terminates the network connection associated with a communications session at the end of the session or after {{Assignment: organization-defined time period}} of inactivity.' WHERE [Requirement_Id] = 12717
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and manages cryptographic keys for required cryptography employed within the information system in accordance with {{Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction}}.' WHERE [Requirement_Id] = 12718
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization produces, controls, and distributes symmetric cryptographic keys using {{Selection: NIST FIPS-compliant; NSA-approved}} key management technology and processes. The organization produces, controls, and distributes asymmetric cryptographic keys using {{Selection: NSA-approved key management technology and processes; approved PKI Class 3 certificates or prepositioned keying material; approved PKI Class 3 or Class 4 certificates and hardware security tokens that protect the user''s private key}}.' WHERE [Requirement_Id] = 12720
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined cryptographic uses and type of cryptography required for each use}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, and standards.' WHERE [Requirement_Id] = 12721
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prohibits remote activation of collaborative computing devices with the following exceptions: {{Assignment: organization-defined exceptions where remote activation is to be allowed}}; and b. Provides an explicit indication of use to users physically present at the devices.' WHERE [Requirement_Id] = 12722
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides physical disconnect of collaborative computing devices in a manner that supports ease of use. The organization disables or removes collaborative computing devices from {{Assignment: organization-defined information systems or information system components}} in {{Assignment: organization-defined secure work areas}}. The information system provides an explicit indication of current participants in {{Assignment: organization-defined online meetings and teleconferences}}.' WHERE [Requirement_Id] = 12723
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization issues public key certificates under an {{Assignment: organization-defined certificate policy}} or obtains public key certificates from an approved service provider.' WHERE [Requirement_Id] = 12724
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system identifies {{Assignment: organization-defined unacceptable mobile code}} and takes {{Assignment: organization-defined corrective actions}}. The organization ensures that the acquisition, development, and use of mobile code to be deployed in the information system meets {{Assignment: organization-defined mobile code requirements}}. The information system prevents the download and execution of {{Assignment: organization-defined unacceptable mobile code}}. The information system prevents the automatic execution of mobile code in {{Assignment: organization-defined software applications}} and enforces {{Assignment: organization-defined actions}} prior to executing the code. The organization allows execution of permitted mobile code only in confined virtual machine environments.' WHERE [Requirement_Id] = 12726
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system invalidates session identifiers upon user logout or other session termination. The information system generates a unique session identifier for each session with {{Assignment: organization-defined randomness requirements}} and recognizes only session identifiers that are system-generated. The information system only allows the use of {{Assignment: organization-defined certificate authorities}} for verification of the establishment of protected sessions.' WHERE [Requirement_Id] = 12733
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system fails to a {{Assignment: organization-defined known-state}} for {{Assignment: organization-defined types of failures}} preserving {{Assignment: organization-defined system state information}} in failure.' WHERE [Requirement_Id] = 12734
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of {{Assignment: organization-defined information at rest}}.' WHERE [Requirement_Id] = 12735
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to prevent unauthorized disclosure and modification of {{Assignment: organization-defined information}} on {{Assignment: organization-defined information system components}}. The organization removes from online storage and stores off-line in a secure location {{Assignment: organization-defined information}}.' WHERE [Requirement_Id] = 12736
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements underlying hardware separation mechanisms to facilitate process separation. The information system maintains a separate execution domain for each thread in {{Assignment: organization-defined multi-threaded processing}}.' WHERE [Requirement_Id] = 12738
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization physically disables or removes {{Assignment: organization-defined connection ports or input/output devices}} on {{Assignment: organization-defined information systems or information system components}}.' WHERE [Requirement_Id] = 12739
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and information integrity policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and information integrity policy and associated system and information integrity controls; and b. Reviews and updates the current: 1. System and information integrity policy {{Assignment: organization-defined frequency}}; and 2. System and information integrity procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 12740
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies, reports, and corrects information system flaws; b. Tests software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation; c. Installs security-relevant software and firmware updates within {{Assignment: organization-defined time period}} of the release of the updates; and d. Incorporates flaw remediation into the organizational configuration management process.' WHERE [Requirement_Id] = 12741
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms {{Assignment: organization-defined frequency}} to determine the state of information system components with regard to flaw remediation.' WHERE [Requirement_Id] = 12742
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Measures the time between flaw identification and flaw remediation; and (b) Establishes {{Assignment: organization-defined benchmarks}} for taking corrective actions. The organization installs {{Assignment: organization-defined security-relevant software and firmware updates}} automatically to {{Assignment: organization-defined information system components}}. The organization removes {{Assignment: organization-defined software and firmware components}} after updated versions have been installed.' WHERE [Requirement_Id] = 12744
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs malicious code protection mechanisms at information system entry and exit points to detect and eradicate malicious code; b. Updates malicious code protection mechanisms whenever new releases are available in accordance with organizational configuration management policy and procedures; c. Configures malicious code protection mechanisms to: 1. Perform periodic scans of the information system {{Assignment: organization-defined frequency}} and real-time scans of files from external sources at {{Selection (one or more); endpoint; network entry/exit points}} as the files are downloaded, opened, or executed in accordance with organizational security policy; and 2. {{Selection (one or more): block malicious code; quarantine malicious code; send alert to administrator; [Assignment: organization-defined action]}} in response to malicious code detection; and d. Addresses the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the information system.' WHERE [Requirement_Id] = 12745
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system updates malicious code protection mechanisms only when directed by a privileged user. The organization: (a) Tests malicious code protection mechanisms {{Assignment: organization-defined frequency}} by introducing a known benign, non-spreading test case into the information system; and (b) Verifies that both detection of the test case and associated incident reporting occur. The information system implements nonsignature-based malicious code detection mechanisms. The information system detects {{Assignment: organization-defined unauthorized operating system commands}} through the kernel application programming interface at {{Assignment: organization-defined information system hardware components}} and {{Selection (one or more): issues a warning; audits the command execution; prevents the execution of the command}}. The information system implements {{Assignment: organization-defined security safeguards}} to authenticate {{Assignment: organization-defined remote commands}}. The organization: (a) Employs {{Assignment: organization-defined tools and techniques}} to analyze the characteristics and behavior of malicious code; and (b) Incorporates the results from malicious code analysis into organizational incident response and flaw remediation processes.' WHERE [Requirement_Id] = 12747
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors the information system to detect: 1. Attacks and indicators of potential attacks in accordance with {{Assignment: organization-defined monitoring objectives}}; and 2. Unauthorized local, network, and remote connections; b. Identifies unauthorized use of the information system through {{Assignment: organization-defined techniques and methods}}; c. Deploys monitoring devices: (i) strategically within the information system to collect organization-determined essential information; and (ii) at ad hoc locations within the system to track specific types of transactions of interest to the organization; d. Protects information obtained from intrusion-monitoring tools from unauthorized access, modification, and deletion; e. Heightens the level of information system monitoring activity whenever there is an indication of increased risk to organizational operations and assets, individuals, other organizations, or the Nation based on law enforcement information, intelligence information, or other credible sources of information; f. Obtains legal opinion with regard to information system monitoring activities in accordance with applicable federal laws, Executive Orders, directives, policies, or regulations; and g. Provides {{Assignment: organization-defined information system monitoring information}} to {{Assignment: organization-defined personnel or roles}} {{Selection (one or more): as needed; [Assignment: organization-defined frequency]}}.' WHERE [Requirement_Id] = 12748
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to support near real-time analysis of events. The information system monitors inbound and outbound communications traffic {{Assignment: organization-defined frequency}} for unusual or unauthorized activities or conditions. The information system alerts {{Assignment: organization-defined personnel or roles}} when the following indications of compromise or potential compromise occur: {{Assignment: organization-defined compromise indicators}}.' WHERE [Requirement_Id] = 12749
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization connects and configures individual intrusion detection tools into an information system-wide intrusion detection system. The organization employs automated tools to integrate intrusion detection tools into access control and flow control mechanisms for rapid response to attacks by enabling reconfiguration of these mechanisms in support of attack isolation and elimination. The information system notifies {{Assignment: organization-defined incident response personnel (identified by name and/or by role)}} of detected suspicious events and takes {{Assignment: organization-defined least-disruptive actions to terminate suspicious events}}. The organization tests intrusion-monitoring tools {{Assignment: organization-defined frequency}}. The organization makes provisions so that {{Assignment: organization-defined encrypted communications traffic}} is visible to {{Assignment: organization-defined information system monitoring tools}}. The organization analyzes outbound communications traffic at the external boundary of the information system and selected {{Assignment: organization-defined interior points within the system (e.g., subnetworks, subsystems)}} to discover anomalies. The organization employs automated mechanisms to alert security personnel of the following inappropriate or unusual activities with security implications: {{Assignment: organization-defined activities that trigger alerts}}. The organization: (a) Analyzes communications traffic/event patterns for the information system; (b) Develops profiles representing common traffic patterns and/or events; and (c) Uses the traffic/event profiles in tuning system-monitoring devices to reduce the number of false positives and the number of false negatives. The organization employs a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises/breaches to the information system. The organization employs an intrusion detection system to monitor wireless communications traffic as the traffic passes from wireless to wireline networks. The organization correlates information from monitoring tools employed throughout the information system. The organization correlates information from monitoring physical, cyber, and supply chain activities to achieve integrated, organization-wide situational awareness. The organization analyzes outbound communications traffic at the external boundary of the information system (i.e., system perimeter) and at {{Assignment: organization-defined interior points within the system (e.g., subsystems, subnetworks)}} to detect covert exfiltration of information. The organization implements {{Assignment: organization-defined additional monitoring}} of individuals who have been identified by {{Assignment: organization-defined sources}} as posing an increased level of risk. The organization implements {{Assignment: organization-defined additional monitoring}} of privileged users. The organization implements {{Assignment: organization-defined additional monitoring}} of individuals during {{Assignment: organization-defined probationary period}}. The information system detects network services that have not been authorized or approved by {{Assignment: organization-defined authorization or approval processes}} and {{Selection (one or more): audits; alerts [Assignment: organization-defined personnel or roles]}}. The organization implements {{Assignment: organization-defined host-based monitoring mechanisms}} at {{Assignment: organization-defined information system components}}. The information system discovers, collects, distributes, and uses indicators of compromise.' WHERE [Requirement_Id] = 12750
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Receives information system security alerts, advisories, and directives from {{Assignment: organization-defined external organizations}} on an ongoing basis; b. Generates internal security alerts, advisories, and directives as deemed necessary; c. Disseminates security alerts, advisories, and directives to: {{Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements within the organization]; [Assignment: organization-defined external organizations]}}; and d. Implements security directives in accordance with established time frames, or notifies the issuing organization of the degree of noncompliance.' WHERE [Requirement_Id] = 12751
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Verifies the correct operation of {{Assignment: organization-defined security functions}}; b. Performs this verification {{Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]}}; c. Notifies {{Assignment: organization-defined personnel or roles}} of failed security verification tests; and d. {{Selection (one or more): shuts the information system down; restarts the information system; [Assignment: organization-defined alternative action(s)]}} when anomalies are discovered.' WHERE [Requirement_Id] = 12753
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements automated mechanisms to support for the management of distributed security testing. The organization reports the results of security function verification to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12754
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs integrity verification tools to detect unauthorized changes to {{Assignment: organization-defined software, firmware, and information}}. The information system performs an integrity check of {{Assignment: organization-defined software, firmware, and information}} {{Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]}}. The organization incorporates the detection of unauthorized {{Assignment: organization-defined security-relevant changes to the information system}} into the organizational incident response capability.' WHERE [Requirement_Id] = 12755
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools that provide notification to {{Assignment: organization-defined personnel or roles}} upon discovering discrepancies during integrity verification. The information system automatically {{Selection (one or more): shuts the information system down; restarts the information system; implements [Assignment: organization-defined security safeguards]}} when integrity violations are discovered. The organization: (a) Prohibits the use of binary or machine-executable code from sources with limited or no warranty and without the provision of source code; and (b) Provides exceptions to the source code requirement only for compelling mission/operational requirements and with the approval of the authorizing official.' WHERE [Requirement_Id] = 12756
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs centrally managed integrity verification tools. The information system implements cryptographic mechanisms to detect unauthorized changes to software, firmware, and information. The information system, upon detection of a potential integrity violation, provides the capability to audit the event and initiates the following actions: {{Selection (one or more): generates an audit record; alerts current user; alerts [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined other actions]}}. The information system verifies the integrity of the boot process of {{Assignment: organization-defined devices}}. The information system implements {{Assignment: organization-defined security safeguards}} to protect the integrity of boot firmware in {{Assignment: organization-defined devices}}. The organization requires that {{Assignment: organization-defined user-installed software}} execute in a confined physical or virtual machine environment with limited privileges. The organization requires that the integrity of {{Assignment: organization-defined user-installed software}} be verified prior to execution. The organization allows execution of binary or machine-executable code obtained from sources with limited or no warranty and without the provision of source code only in confined physical or virtual machine environments and with the explicit approval of {{Assignment: organization-defined personnel or roles}}. The information system implements cryptographic mechanisms to authenticate {{Assignment: organization-defined software or firmware components}} prior to installation. The organization does not allow processes to execute without supervision for more than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 12757
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system checks the validity of {{Assignment: organization-defined information inputs}}.' WHERE [Requirement_Id] = 12760
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Provides a manual override capability for input validation of {{Assignment: organization-defined inputs}}; (b) Restricts the use of the manual override capability to only {{Assignment: organization-defined authorized individuals}}; and (c) Audits the use of the manual override capability. The organization ensures that input validation errors are reviewed and resolved within {{Assignment: organization-defined time period}}. The information system behaves in a predictable and documented manner that reflects organizational and system objectives when invalid inputs are received. The organization accounts for timing interactions among information system components in determining appropriate responses for invalid inputs. The organization restricts the use of information inputs to {{Assignment: organization-defined trusted sources}} and/or {{Assignment: organization-defined formats}}.' WHERE [Requirement_Id] = 12761
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Generates error messages that provide information necessary for corrective actions without revealing information that could be exploited by adversaries; and b. Reveals error messages only to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 12762
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines mean time to failure (MTTF) for {{Assignment: organization-defined information system components}} in specific environments of operation; and b. Provides substitute information system components and a means to exchange active and standby components at {{Assignment: organization-defined MTTF substitution criteria}}. The organization takes information system components out of service by transferring component responsibilities to substitute components no later than {{Assignment: organization-defined fraction or percentage}} of mean time to failure. The organization manually initiates transfers between active and standby information system components {{Assignment: organization-defined frequency}} if the mean time to failure exceeds {{Assignment: organization-defined time period}}. The organization, if information system component failures are detected: (a) Ensures that the standby components are successfully and transparently installed within {{Assignment: organization-defined time period}}; and (b) {{Selection (one or more): activates [Assignment: organization-defined alarm]; automatically shuts down the information system}}. The organization provides {{Selection: real-time; near real-time}} {{Assignment: organization-defined failover capability}} for the information system.' WHERE [Requirement_Id] = 12764
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined security safeguards}} to protect its memory from unauthorized code execution.' WHERE [Requirement_Id] = 12765
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined fail-safe procedures}} when {{Assignment: organization-defined failure conditions occur}}.' WHERE [Requirement_Id] = 12766
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 12770
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 12771
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 12772
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}. The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 12773
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An access control policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the access control policy and associated access controls; and b. Reviews and updates the current: 1. Access control policy at least annually if not otherwise defined in formal organizational policy; and 2. Access control procedures at least annually if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14192
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies and selects the following types of information system accounts to support organizational missions/business functions: {{Assignment: organization-defined information system account types}}; b. Assigns account managers for information system accounts; c. Establishes conditions for group and role membership; d. Specifies authorized users of the information system, group and role membership, and access authorizations (i.e., privileges) and other attributes (as required) for each account; e. Requires approvals by {{Assignment: organization-defined personnel or roles}} for requests to create information system accounts; f. Creates, enables, modifies, disables, and removes information system accounts in accordance with {{Assignment: organization-defined procedures or conditions}}; g. Monitors the use of, information system accounts; h. Notifies account managers: 1. When accounts are no longer required; 2. When users are terminated or transferred; and 3. When individual information system usage or need-to-know changes; i. Authorizes access to the information system based on: 1. A valid access authorization; 2. Intended system usage; and 3. Other attributes as required by the organization or associated missions/business functions; j. Reviews accounts for compliance with account management requirements at least annually if not otherwise defined in formal organizational policy; and k. Establishes a process for reissuing shared/group account credentials (if deployed) when individuals are removed from the group.' WHERE [Requirement_Id] = 14193
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system automatically audits account creation, modification, enabling, disabling, and removal actions, and notifies {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14197
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements the following dynamic privilege management capabilities: {{Assignment: organization-defined list of dynamic privilege management capabilities}}.' WHERE [Requirement_Id] = 14199
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system creates {{Assignment: organization-defined information system accounts}} dynamically.' WHERE [Requirement_Id] = 14201
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization only permits the use of shared/group accounts that meet {{Assignment: organization-defined conditions for establishing shared/group accounts}}.' WHERE [Requirement_Id] = 14202
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined circumstances and/or usage conditions}} for {{Assignment: organization-defined information system accounts}}.' WHERE [Requirement_Id] = 14204
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Monitors information system accounts for {{Assignment: organization-defined atypical use}}; and (b) Reports atypical usage of information system accounts to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14205
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces dual authorization for {{Assignment: organization-defined privileged commands and/or other organization-defined actions}}.' WHERE [Requirement_Id] = 14207
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined mandatory access control policies}} over all subjects and objects where the policy specifies that: (a) The policy is uniformly enforced across all subjects and objects within the boundary of the information system; (b) A subject that has been granted access to information is constrained from doing any of the following; (1) Passing the information to unauthorized subjects or objects; (2) Granting its privileges to other subjects; (3) Changing one or more security attributes on subjects, objects, the information system, or information system components; (4) Choosing the security attributes and attribute values to be associated with newly created or modified objects; or (5) Changing the rules governing access control; and (c) {{Assignment: Organized-defined subjects}} may explicitly be granted {{Assignment: organization-defined privileges (i.e., they are trusted subjects)}} such that they are not limited by some or all of the above constraints.' WHERE [Requirement_Id] = 14208
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined discretionary access control policies}} over defined subjects and objects where the policy specifies that a subject that has been granted access to information can do one or more of the following: (a) Pass the information to any other subjects or objects; (b) Grant its privileges to other subjects; (c) Change security attributes on subjects, objects, the information system, or the information systems components; (d) Choose the security attributes to be associated with newly created or revised objects; or (e) Change the rules governing access control.' WHERE [Requirement_Id] = 14209
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents access to {{Assignment: organization-defined security-relevant information}} except during secure, non-operable system states.' WHERE [Requirement_Id] = 14210
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces a role-based access control policy over {{Assignment: organization-defined users and information resources}} and controls access based upon {{Assignment: organization-defined roles and users authorized to assume such roles}}.' WHERE [Requirement_Id] = 14211
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces the revocation of access authorizations resulting from changes to the security attributes of subjects and objects based on {{Assignment: organization-defined rules governing the timing of revocations of access authorizations}}.' WHERE [Requirement_Id] = 14212
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system does not release information outside of the established system boundary unless: (a) The receiving {{Assignment: organization-defined information system or system component}} provides {{Assignment: organization-defined security safeguards}}; and (b) {{Assignment: organization-defined security safeguards}} are used to validate the appropriateness of the information designated for release.' WHERE [Requirement_Id] = 14213
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs an audited override of automated access control mechanisms under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 14214
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses {{Assignment: organization-defined security attributes}} associated with {{Assignment: organization-defined information, source, and destination objects}} to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions.' WHERE [Requirement_Id] = 14215
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uses protected processing domains to enforce {{Assignment: organization-defined information flow control policies}} as a basis for flow control decisions.' WHERE [Requirement_Id] = 14216
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces dynamic information flow control based on {{Assignment: organization-defined policies}}.' WHERE [Requirement_Id] = 14217
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents encrypted information from bypassing content-checking mechanisms by {{Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]}}.' WHERE [Requirement_Id] = 14218
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined limitations}} on embedding data types within other data types.' WHERE [Requirement_Id] = 14219
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces information flow control based on {{Assignment: organization-defined metadata}}.' WHERE [Requirement_Id] = 14220
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces {{Assignment: organization-defined one-way flows}} using hardware mechanisms.' WHERE [Requirement_Id] = 14221
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces information flow control using {{Assignment: organization-defined security policy filters}} as a basis for flow control decisions for {{Assignment: organization-defined information flows}}.' WHERE [Requirement_Id] = 14222
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces the use of human reviews for {{Assignment: organization-defined information flows}} under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 14223
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for privileged administrators to enable/disable {{Assignment: organization-defined security policy filters}} under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 14224
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for privileged administrators to configure {{Assignment: organization-defined security policy filters}} to support different security policies.' WHERE [Requirement_Id] = 14225
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, uses {{Assignment: organization-defined data type identifiers}} to validate data essential for information flow decisions.' WHERE [Requirement_Id] = 14226
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, decomposes information into {{Assignment: organization-defined policy-relevant subcomponents}} for submission to policy enforcement mechanisms.' WHERE [Requirement_Id] = 14227
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, implements {{Assignment: organization-defined security policy filters}} requiring fully enumerated formats that restrict data structure and content.' WHERE [Requirement_Id] = 14228
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, examines the information for the presence of {{Assignment: organized-defined unsanctioned information}} and prohibits the transfer of such information in accordance with the {{Assignment: organization-defined security policy}}.' WHERE [Requirement_Id] = 14229
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates source and destination points by {{Selection (one or more): organization, system, application, individual}} for information transfer.' WHERE [Requirement_Id] = 14230
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system binds security attributes to information using {{Assignment: organization-defined binding techniques}} to facilitate information flow policy enforcement.' WHERE [Requirement_Id] = 14231
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined solutions in approved configurations}} to control the flow of {{Assignment: organization-defined information}} across security domains.' WHERE [Requirement_Id] = 14233
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system separates information flows logically or physically using {{Assignment: organization-defined mechanisms and/or techniques}} to accomplish {{Assignment: organization-defined required separations by types of information}}.' WHERE [Requirement_Id] = 14234
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization explicitly authorizes access to {{Assignment: organization-defined security functions (deployed in hardware, software, and firmware) and security-relevant information}}.' WHERE [Requirement_Id] = 14237
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes network access to {{Assignment: organization-defined privileged commands}} only for {{Assignment: organization-defined compelling operational needs}} and documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 14239
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts privileged accounts on the information system to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14241
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews {{Assignment: organization-defined frequency}} the privileges assigned to {{Assignment: organization-defined roles or classes of users}} to validate the need for such privileges; and (b) Reassigns or removes privileges, if necessary, to correctly reflect organizational mission/business needs.' WHERE [Requirement_Id] = 14243
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Enforces a limit of 3 consecutive invalid logon attempts by a user during a 15 minute interval; and b. Automatically locks the account/node for at least 15 minutes, or until unlocked by an administrator; locks the account/node until released by an administrator; delays next logon prompt according to {{Assignment: organization-defined delay algorithm}} when the maximum number of unsuccessful attempts is exceeded.' WHERE [Requirement_Id] = 14247
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system purges/wipes information from {{Assignment: organization-defined mobile devices}} based on {{Assignment: organization-defined purging/wiping requirements/techniques}} after 10 consecutive, unsuccessful device logon attempts.' WHERE [Requirement_Id] = 14248
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system notifies the user of the number of {{Selection: successful logons/accesses; unsuccessful logon/access attempts; both}} during {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 14251
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system notifies the user of changes to {{Assignment: organization-defined security-related characteristics/parameters of the user''s account}} since the last successful logon.' WHERE [Requirement_Id] = 14252
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system notifies the user, upon successful logon (access), of the following additional information: {{Assignment: organization-defined information to be included in addition to the date and time of the last logon (access)}}.' WHERE [Requirement_Id] = 14253
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Provides the means to associate {{Assignment: organization-defined types of security attributes}} having {{Assignment: organization-defined security attribute values}} with information in storage, in process, and/or in transmission; b. Ensures that the security attribute associations are made and retained with the information; c. Establishes the permitted {{Assignment: organization-defined security attributes}} for {{Assignment: organization-defined information systems}}; and d. Determines the permitted {{Assignment: organization-defined values or ranges}} for each of the established security attributes.' WHERE [Requirement_Id] = 14259
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system dynamically associates security attributes with {{Assignment: organization-defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}} as information is created and combined.' WHERE [Requirement_Id] = 14260
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system maintains the association and integrity of {{Assignment: organization-defined security attributes}} to {{Assignment: organization-defined subjects and objects}}.' WHERE [Requirement_Id] = 14262
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system supports the association of {{Assignment: organization-defined security attributes}} with {{Assignment: organization-defined subjects and objects}} by authorized individuals (or processes acting on behalf of individuals).' WHERE [Requirement_Id] = 14263
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system displays security attributes in human-readable form on each object that the system transmits to output devices to identify {{Assignment: organization-identified special dissemination, handling, or distribution instructions}} using {{Assignment: organization-identified human-readable, standard naming conventions}}.' WHERE [Requirement_Id] = 14264
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization allows personnel to associate, and maintain the association of {{Assignment: organization-defined security attributes}} with {{Assignment: organization-defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 14265
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined techniques or technologies}} with {{Assignment: organization-defined level of assurance}} in associating security attributes to information.' WHERE [Requirement_Id] = 14267
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that security attributes associated with information are reassigned only via re-grading mechanisms validated using {{Assignment: organization-defined techniques or procedures}}.' WHERE [Requirement_Id] = 14268
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system routes all remote accesses through {{Assignment: organization-defined number}} managed network access control points.' WHERE [Requirement_Id] = 14272
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Authorizes the execution of privileged commands and access to security-relevant information via remote access only for {{Assignment: organization-defined needs}}; and (b) Documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 14273
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Prohibits the use of unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and (b) Enforces the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information: (1) Connection of unclassified mobile devices to classified information systems is prohibited; (2) Connection of unclassified mobile devices to unclassified information systems requires approval from the authorizing official; (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by {{Assignment: organization-defined security officials}}, and if classified information is found, the incident handling policy is followed. (c) Restricts the connection of classified mobile devices to classified information systems in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 14282
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: full-device encryption; container encryption}} to protect the confidentiality and integrity of information on all mobile devices authorized to connect to the organization''s ISs.' WHERE [Requirement_Id] = 14283
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of organization-controlled portable storage devices by authorized individuals on external information systems.' WHERE [Requirement_Id] = 14285
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the use of {{Assignment: organization-defined network accessible storage devices}} in external information systems.' WHERE [Requirement_Id] = 14287
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements information search and retrieval services that enforce {{Assignment: organization-defined information sharing restrictions}}.' WHERE [Requirement_Id] = 14289
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes procedures to ensure {{Assignment: organization-defined access control decisions}} are applied to each access request prior to access enforcement.' WHERE [Requirement_Id] = 14291
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system transmits {{Assignment: organization-defined access authorization information}} using {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined information systems}} that enforce access control decisions.' WHERE [Requirement_Id] = 14292
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces access control decisions based on {{Assignment: organization-defined security attributes}} that do not include the identity of the user or process acting on behalf of the user.' WHERE [Requirement_Id] = 14293
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Assignment: organization-defined personnel or roles}} with initial and at least annually if not otherwise defined in formal organization policy or when sufficient changes are made to physical security systems training in the employment and operation of environmental controls.' WHERE [Requirement_Id] = 14297
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Assignment: organization-defined personnel or roles}} with initial and at least annually if not otherwise defined in formal organization policy or when sufficient changes are made to physical security systems. training in the employment and operation of physical security controls.' WHERE [Requirement_Id] = 14298
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines that the information system is capable of auditing the following events: 1. Authentication events: (1) Logons (Success/Failure) (2) Logoffs (Success) 2. File and Objects events: (1) Create (Success/Failure) (2) Access (Success/Failure) (3) Delete (Success/Failure) (4) Modify (Success/Failure) (5) Permission Modification (Success/Failure) (6) Ownership Modification (Success/Failure) 3. Writes/downloads to external devices/media (e.g., A-Drive, CD/DVD devices/printers) (Success/Failure) 4. Uploads from external devices (e.g., CD/DVD drives) (Success/Failure) 5. User and Group Management events: (1) User add, delete, modify, suspend, lock (Success/Failure) (2) Group/Role add, delete, modify (Success/Failure) 6. Use of Privileged/Special Rights events: (1) Security or audit policy changes (Success/Failure) (2) Configuration changes (Success/Failure) 7. Admin or root-level access (Success/Failure) 8. Privilege/Role escalation (Success/Failure) 9. Audit and log data accesses (Success/Failure) 10. System reboot, restart and shutdown (Success/Failure) 11. Print to a device (Success/Failure) 12. Print to a file (e.g., pdf format) (Success/Failure) 13. Application (e.g., Firefox, Internet Explorer, MS Office Suite, etc.) initialization (Success/Failure) 14. Export of information (Success/Failure) include (e.g., to CDRW, thumb drives, or remote systems) 15. Import of information (Success/Failure) include (e.g., from CDRW, thumb drives, or remote systems); b. Coordinates the security audit function with other organizational entities requiring audit-related information to enhance mutual support and to help guide the selection of auditable events; c. Provides a rationale for why the auditable events are deemed to be adequate to support after-the-fact investigations of security incidents; and d. Determines that the following events are to be audited within the information system: {{Assignment: organization-defined audited events (the subset of the auditable events defined in AU-2 a.) along with the frequency of (or situation requiring) auditing for each identified event}}.' WHERE [Requirement_Id] = 14302
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a warning to {{Assignment: organization-defined personnel, roles, and/or locations}} within {{Assignment: organization-defined time period}} when allocated audit record storage volume reaches 75% of repository maximum audit record storage capacity.' WHERE [Requirement_Id] = 14304
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides an alert in {{Assignment: organization-defined real-time period}} to {{Assignment: organization-defined personnel, roles, and/or locations}} when the following audit failure events occur: minimally but not limited to: auditing software/hardware errors; failures in the audit capturing mechanisms; and audit storage capacity being reached or exceeded.' WHERE [Requirement_Id] = 14305
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces configurable network communications traffic volume thresholds reflecting limits on auditing capacity and {{Selection: rejects; delays}} network traffic above those thresholds.' WHERE [Requirement_Id] = 14306
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system invokes a {{Selection: full system shutdown; partial system shutdown; degraded operational mode with limited mission/business functionality available}} in the event of {{Assignment: organization-defined audit failures}}, unless an alternate audit capability exists.' WHERE [Requirement_Id] = 14307
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and analyzes information system audit records at least weekly (seven days) for indications of {{Assignment: organization-defined inappropriate or unusual activity}}; and b. Reports findings to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14308
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization integrates analysis of audit records with analysis of {{Selection (one or more): vulnerability scanning information; performance data; information system monitoring information; [Assignment: organization-defined data/information collected from other sources]}} to further enhance the ability to identify inappropriate or unusual activity.' WHERE [Requirement_Id] = 14312
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization specifies the permitted actions for each {{Selection (one or more): information system process; role; user}} associated with the review, analysis, and reporting of audit information.' WHERE [Requirement_Id] = 14314
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to process audit records for events of interest based on {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 14319
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to sort and search audit records for events of interest based on the content of {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 14320
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Compares the internal information system clocks at least every 24 hours with {{Assignment: organization-defined authoritative time source}}; and (b) Synchronizes the internal system clocks to the authoritative time source when the time difference is greater than the organizationally defined granularity in AU-8.' WHERE [Requirement_Id] = 14321
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for {{Selection (one or more): movement; deletion}} of any security related audit information.' WHERE [Requirement_Id] = 14325
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes read-only access to audit information to {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 14326
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Binds the identity of the information producer with the information to {{Assignment: organization-defined strength of binding}}; and (b) Provides the means for authorized individuals to determine the identity of the producer of the information.' WHERE [Requirement_Id] = 14327
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Validates the binding of the information producer identity to the information at {{Assignment: organization-defined frequency}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 14328
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Validates the binding of the information reviewer identity to the information at the transfer or release points prior to release/transfer between {{Assignment: organization-defined security domains}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 14330
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Provides audit record generation capability for the auditable events defined in AU-2 a. at all information systems and network components; b. Allows {{Assignment: organization-defined personnel or roles}} to select which auditable events are to be audited by specific components of the information system; and c. Generates audit records for the events defined in AU-2 d. with the content defined in AU-3.' WHERE [Requirement_Id] = 14333
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system compiles audit records from {{Assignment: organization-defined information system components}} into a system-wide (logical or physical) audit trail that is time-correlated in accordance with tolerance defined in AU-8.' WHERE [Requirement_Id] = 14334
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for {{Assignment: organization-defined individuals or roles}} to change the auditing to be performed on {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined selectable event criteria}} within {{Assignment: organization-defined time thresholds}}.' WHERE [Requirement_Id] = 14336
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors {{Assignment: organization-defined open source information and/or information sites}} {{Assignment: organization-defined frequency}} for evidence of unauthorized disclosure of organizational information.' WHERE [Requirement_Id] = 14337
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined methods}} for coordinating {{Assignment: organization-defined audit information}} among external organizations when audit information is transmitted across organizational boundaries.' WHERE [Requirement_Id] = 14344
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides cross-organizational audit information to {{Assignment: organization-defined organizations}} based on {{Assignment: organization-defined cross-organizational sharing agreements}}.' WHERE [Requirement_Id] = 14346
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security assessment plan that describes the scope of the assessment including: 1. Security controls and control enhancements under assessment; 2. Assessment procedures to be used to determine security control effectiveness; and 3. Assessment environment, assessment team, and assessment roles and responsibilities; b. Assesses the security controls in the information system and its environment of operation at least annually, or as stipulated in the organization''s continuous monitoring program to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements; c. Produces a security assessment report that documents the results of the assessment; and d. Provides the results of the security control assessment to {{Assignment: organization-defined individuals or roles}}.' WHERE [Requirement_Id] = 14348
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an all unclassified NSS to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 14350
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 14351
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 14352
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 14353
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined red team exercises}} to simulate attempts by adversaries to compromise organizational information systems in accordance with {{Assignment: organization-defined rules of engagement}}.' WHERE [Requirement_Id] = 14358
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A configuration management policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the configuration management policy and associated configuration management controls; and b. Reviews and updates the current: 1. Configuration management policy at least annually if not otherwise defined in formal organizational policy; and 2. Configuration management procedures at least annually if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14359
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Issues {{Assignment: organization-defined information systems, system components, or devices}} with {{Assignment: organization-defined configurations}} to individuals traveling to locations that the organization deems to be of significant risk; and (b) Applies {{Assignment: organization-defined security safeguards}} to the devices when the individuals return.' WHERE [Requirement_Id] = 14364
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines the types of changes to the information system that are configuration-controlled; b. Reviews proposed configuration-controlled changes to the information system and approves or disapproves such changes with explicit consideration for security impact analyses; c. Documents configuration change decisions associated with the information system; d. Implements approved configuration-controlled changes to the information system; e. Retains records of configuration-controlled changes to the information system for 1 year or two change cycles of baseline configurations as defined in CM-2(3), whichever is longer; f. Audits and reviews activities associated with configuration-controlled changes to the information system; and g. Coordinates and provides oversight for configuration change control activities through {{Assignment: organization-defined configuration change control element (e.g., committee, board)}} that convenes {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined configuration change conditions]}}.' WHERE [Requirement_Id] = 14365
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to: (a) Document proposed changes to the information system; (b) Notify {{Assignment: organized-defined approval authorities}} of proposed changes to the information system and request change approval; (c) Highlight proposed changes to the information system that have not been approved or disapproved by {{Assignment: organization-defined time period}}; (d) Prohibit changes to the information system until designated approvals are received; (e) Document all changes to the information system; and (f) Notify {{Assignment: organization-defined personnel}} when approved changes to the information system are completed.' WHERE [Requirement_Id] = 14366
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined security responses}} automatically if baseline configurations are changed in an unauthorized manner.' WHERE [Requirement_Id] = 14370
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for implementing changes to {{Assignment: organization-defined information system components and system-level information}}.' WHERE [Requirement_Id] = 14375
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and documents configuration settings for information technology products employed within the information system using organizationally approved guides such as DoD SRGs, STIGs, or NSA SCGs; if such a reference document is not available, the following are acceptable in descending order as available: (1) Commercially accepted practices (e.g., SANS) (2) Independent testing results (e.g., ICSA) or (3) Vendor literature that reflect the most restrictive mode consistent with operational requirements; b. Implements the configuration settings; c. Identifies, documents, and approves any deviations from established configuration settings for all configurable information system components based on {{Assignment: organization-defined operational requirements}}; and d. Monitors and controls changes to the configuration settings in accordance with organizational policies and procedures.' WHERE [Requirement_Id] = 14378
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to centrally manage, apply, and verify configuration settings for {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 14379
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to respond to unauthorized changes to {{Assignment: organization-defined configuration settings}}.' WHERE [Requirement_Id] = 14380
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents program execution in accordance with {{Selection (one or more): [Assignment: organization-defined policies regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage}}.' WHERE [Requirement_Id] = 14382
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures compliance with {{Assignment: organization-defined registration requirements for functions, ports, protocols, and services}}.' WHERE [Requirement_Id] = 14383
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs not authorized to execute on the information system}}; (b) Employs an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the information system; and (c) Reviews and updates the list of unauthorized software programs at least annually.' WHERE [Requirement_Id] = 14384
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs authorized to execute on the information system}}; (b) Employs a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the information system; and (c) Reviews and updates the list of authorized software programs at least annually.' WHERE [Requirement_Id] = 14385
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Employs automated mechanisms continuously to detect the presence of unauthorized hardware, software, and firmware components within the information system; and (b) Takes the following actions when unauthorized components are detected: {{Selection (one or more): disables network access by such components; isolates the components; notifies [Assignment: organization-defined personnel or roles]}}.' WHERE [Requirement_Id] = 14389
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined policies}} governing the installation of software by users; b. Enforces software installation policies through {{Assignment: organization-defined methods}}; and c. Monitors policy compliance at continuously.' WHERE [Requirement_Id] = 14396
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the unauthorized installation of software is detected.' WHERE [Requirement_Id] = 14397
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A contingency planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls; and b. Reviews and updates the current: 1. Contingency planning policy at least annually if not otherwise defined in formal organizational policy; and 2. Contingency planning procedures at least annually if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14399
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a contingency plan for the information system that: 1. Identifies essential missions and business functions and associated contingency requirements; 2. Provides recovery objectives, restoration priorities, and metrics; 3. Addresses contingency roles, responsibilities, assigned individuals with contact information; 4. Addresses maintaining essential missions and business functions despite an information system disruption, compromise, or failure; 5. Addresses eventual, full information system restoration without deterioration of the security safeguards originally planned and implemented; and 6. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the contingency plan to key personnel or roles and organizational elements identified in the contingency plan; c. Coordinates contingency planning activities with incident handling activities; d. Reviews the contingency plan for the information system at least annually unless otherwise defined in organizational policy; e. Updates the contingency plan to address changes to the organization, information system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing; f. Communicates contingency plan changes to key personnel and .organizational elements identified in the contingency plan; and g. Protects the contingency plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 14400
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires primary and alternate telecommunications service providers to have contingency plans; (b) Reviews provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtains evidence of contingency testing/training by providers {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 14427
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests alternate telecommunication services {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 14428
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization stores backup copies of {{Assignment: organization-defined critical information system software and other security-related information}} in a separate facility or in a fire-rated container that is not collocated with the operational system.' WHERE [Requirement_Id] = 14432
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization transfers information system backup information to the alternate storage site {{Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives}}.' WHERE [Requirement_Id] = 14433
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the deletion or destruction of {{Assignment: organization-defined backup information}}.' WHERE [Requirement_Id] = 14435
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to restore information system components within {{Assignment: organization-defined restoration time-periods}} from configuration-controlled and integrity-protected information representing a known, operational state for the components.' WHERE [Requirement_Id] = 14436
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for network access to privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 14445
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for network access to non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 14446
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a single sign-on capability for {{Assignment: organization-defined list of information system accounts and services}}.' WHERE [Requirement_Id] = 14449
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements multifactor authentication for remote access to privileged and non-privileged accounts such that one of the factors is provided by a device separate from the system gaining access and the device meets {{Assignment: organization-defined strength of mechanism requirements}}.' WHERE [Requirement_Id] = 14450
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined out-of-band authentication}} under {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 14452
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system authenticates {{Assignment: organization-defined specific devices and/or types of devices}} before establishing {{Selection (one or more): local; remote; network}} connection using bidirectional authentication that is cryptographically based.' WHERE [Requirement_Id] = 14453
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Standardizes dynamic address allocation lease information and the lease duration assigned to devices in accordance with {{Assignment: organization-defined lease information and lease duration}}; and (b) Audits lease information when assigned to a device.' WHERE [Requirement_Id] = 14454
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that device identification and authentication based on attestation is handled by {{Assignment: organization-defined configuration management process}}.' WHERE [Requirement_Id] = 14455
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system identifiers by: a. Receiving authorization from {{Assignment: organization-defined personnel or roles}} to assign an individual, group, role, or device identifier; b. Selecting an identifier that identifies an individual, group, role, or device; c. Assigning the identifier to the intended individual, group, role, or device; d. Preventing reuse of identifiers for at least a year for individuals, groups, roles; and e. Disabling the identifier within 35 days for individuals, groups, and roles.' WHERE [Requirement_Id] = 14456
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages individual identifiers by uniquely identifying each individual as {{Assignment: organization-defined characteristic identifying individual status}}.' WHERE [Requirement_Id] = 14460
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of identifiers.' WHERE [Requirement_Id] = 14462
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, or device receiving the authenticator; b. Establishing initial authenticator content for authenticators defined by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost/compromised or damaged authenticators, and for revoking authenticators; e. Changing default content of authenticators prior to information system installation; f. Establishing minimum and maximum lifetime restrictions and reuse conditions for authenticators; g. Changing/refreshing authenticators {{Assignment: organization-defined time period by authenticator type}} including changing passwords within 180 days; h. Protecting authenticator content from unauthorized disclosure and modification; i. Requiring individuals to take, and having devices implement, specific security safeguards to protect authenticators; and j. Changing authenticators for group/role accounts when membership to those accounts changes.' WHERE [Requirement_Id] = 14464
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that the registration process to receive {{Assignment: organization-defined types of and/or specific authenticators}} be conducted {{Selection: in person; by a trusted third party}} before {{Assignment: organization-defined registration authority}} with authorization by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14467
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of credentials.' WHERE [Requirement_Id] = 14473
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for hardware token-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined token quality requirements}}.' WHERE [Requirement_Id] = 14475
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for biometric-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined biometric quality requirements}}.' WHERE [Requirement_Id] = 14476
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs only FICAM-approved information system components in {{Assignment: organization-defined information systems}} to accept third-party credentials.' WHERE [Requirement_Id] = 14482
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies and authenticates {{Assignment: organization-defined information system services}} using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 14485
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that identification and authentication decisions are transmitted between {{Assignment: organization-defined services}} consistent with organizational policies.' WHERE [Requirement_Id] = 14487
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An incident response policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the incident response policy and associated incident response controls; and b. Reviews and updates the current: 1. Incident response policy at least annually if not otherwise defined in formal organizational policy; and 2. Incident response procedures at least annually if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14488
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests the incident response capability for the information system at least annually using {{Assignment: organization-defined tests}} to determine the incident response effectiveness and documents the results.' WHERE [Requirement_Id] = 14492
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes dynamic reconfiguration of {{Assignment: organization-defined information system components}} as part of the incident response capability.' WHERE [Requirement_Id] = 14495
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies {{Assignment: organization-defined classes of incidents}} and {{Assignment: organization-defined actions to take in response to classes of incidents}} to ensure continuation of organizational missions and business functions.' WHERE [Requirement_Id] = 14496
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements a configurable capability to automatically disable the information system if {{Assignment: organization-defined security violations}} are detected.' WHERE [Requirement_Id] = 14498
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates incident handling capability for insider threats across {{Assignment: organization-defined components or elements of the organization}}.' WHERE [Requirement_Id] = 14500
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with the appropriate CIRT/CERT (such as US-CERT, DoD CERT, IC CERT) to correlate and share {{Assignment: organization-defined incident information}} to achieve a cross-organization perspective on incident awareness and more effective incident responses.' WHERE [Requirement_Id] = 14501
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined dynamic response capabilities}} to effectively respond to security incidents.' WHERE [Requirement_Id] = 14502
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires personnel to report suspected security incidents to the organizational incident response capability within {{Assignment: organization-defined time period}}; and b. Reports security incident information to the appropriate Agency CIRT/CERT (see IR-4(8)).' WHERE [Requirement_Id] = 14504
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reports information system vulnerabilities associated with reported security incidents to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14505
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization responds to information spills by: a. Identifying the specific information involved in the information system contamination; b. Alerting {{Assignment: organization-defined personnel or roles}} of the information spill using a method of communication not associated with the spill; c. Isolating the contaminated information system or system component; d. Eradicating the information from the contaminated information system or component; e. Identifying other information systems or system components that may have been subsequently contaminated; and f. Performing other {{Assignment: organization-defined actions}}.' WHERE [Requirement_Id] = 14509
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization assigns {{Assignment: organization-defined personnel or roles}} with responsibility for responding to information spills.' WHERE [Requirement_Id] = 14510
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined procedures}} to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions.' WHERE [Requirement_Id] = 14512
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} for personnel exposed to information not within assigned access authorizations.' WHERE [Requirement_Id] = 14513
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prevents the unauthorized removal of maintenance equipment containing organizational information by: (a) Verifying that there is no organizational information contained on the equipment; (b) Sanitizing or destroying the equipment; (c) Retaining the equipment within the facility; or (d) Obtaining an exemption from {{Assignment: organization-defined personnel or roles}} explicitly authorizing removal of the equipment from the facility.' WHERE [Requirement_Id] = 14518
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects nonlocal maintenance sessions by: (a) Employing {{Assignment: organization-defined authenticators that are replay resistant}}; and (b) Separating the maintenance sessions from other network sessions with the information system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths based upon encryption.' WHERE [Requirement_Id] = 14521
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires the approval of each nonlocal maintenance session by {{Assignment: organization-defined personnel or roles}}; and (b) Notifies {{Assignment: organization-defined personnel or roles}} of the date and time of planned nonlocal maintenance.' WHERE [Requirement_Id] = 14522
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs preventive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 14529
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs predictive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 14530
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts access to all types of digital and/or non-digital media containing information not cleared for public release to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14533
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Protects and controls {{Assignment: organization-defined types of information system media}} during transport outside of controlled areas using {{Assignment: organization-defined security safeguards}}; b. Maintains accountability for information system media during transport outside of controlled areas; c. Documents activities associated with the transport of information system media; and d. Restricts the activities associated with the transport of information system media to authorized personnel.' WHERE [Requirement_Id] = 14535
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization applies nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the information system under the following circumstances: {{Assignment: organization-defined circumstances requiring sanitization of portable storage devices}}.' WHERE [Requirement_Id] = 14540
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the sanitization of {{Assignment: organization-defined information system media}}.' WHERE [Requirement_Id] = 14541
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to purge/wipe information from {{Assignment: organization-defined information systems, system components, or devices}} either remotely or under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 14542
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined information system media downgrading process}} that includes employing downgrading mechanisms with {{Assignment: organization-defined strength and integrity}}; b. Ensures that the information system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information; c. Identifies {{Assignment: organization-defined information system media requiring downgrading}}; and d. Downgrades the identified information system media using the established process.' WHERE [Requirement_Id] = 14543
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tests}} of downgrading equipment and procedures to verify correct performance at least annually if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14545
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization downgrades information system media containing {{Assignment: organization-defined Controlled Unclassified Information (CUI)}} prior to public release in accordance with applicable federal and organizational standards and policies.' WHERE [Requirement_Id] = 14546
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires two forms of identification from {{Assignment: organization-defined list of acceptable forms of identification}} for visitor access to the facility where the information system resides.' WHERE [Requirement_Id] = 14551
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts unescorted access to the facility where the information system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 14552
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs security checks {{Assignment: organization-defined frequency}} at the physical boundary of the facility or information system for unauthorized exfiltration of information or removal of information system components.' WHERE [Requirement_Id] = 14553
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization uses lockable physical casings to protect {{Assignment: organization-defined information system components}} from unauthorized physical access.' WHERE [Requirement_Id] = 14555
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization-defined hardware components}} within the information system.' WHERE [Requirement_Id] = 14556
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a penetration testing process that includes {{Assignment: organization-defined frequency}}, unannounced attempts to bypass or circumvent security controls associated with physical access points to the facility.' WHERE [Requirement_Id] = 14557
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Ensures that only authorized individuals receive output from the device.' WHERE [Requirement_Id] = 14558
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Links individual identity to receipt of the output from the device.' WHERE [Requirement_Id] = 14559
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization marks {{Assignment: organization-defined information system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 14560
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors physical access to the facility where the information system resides to detect and respond to physical security incidents; b. Reviews physical access logs at least every 90 days if not otherwise defined in formal organizational policy and upon occurrence of {{Assignment: organization-defined events or potential indications of events}}; and c. Coordinates results of reviews and investigations with the organizational incident response capability.' WHERE [Requirement_Id] = 14561
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to recognize {{Assignment: organization-defined classes/types of intrusions}} and initiate {{Assignment: organization-defined response actions}}.' WHERE [Requirement_Id] = 14562
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs video surveillance of {{Assignment: organization-defined operational areas}} and retains video recordings for at least 90 days if not otherwise defined in formal organizational policy.' WHERE [Requirement_Id] = 14563
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors physical access to the information system in addition to the physical access monitoring of the facility as {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 14564
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs redundant power cabling paths that are physically separated by {{Assignment: organization-defined distance}}.' WHERE [Requirement_Id] = 14566
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automatic voltage controls for {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 14567
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire detection devices/systems for the information system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire.' WHERE [Requirement_Id] = 14568
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire suppression devices/systems for the information system that provide automatic notification of any activation to {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}}.' WHERE [Requirement_Id] = 14569
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains temperature and humidity levels within the facility where the information system resides at {{Assignment: organization-defined acceptable levels}}; and b. Monitors temperature and humidity levels continuously.' WHERE [Requirement_Id] = 14571
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security plan for the information system that: 1. Is consistent with the organization''s enterprise architecture; 2. Explicitly defines the authorization boundary for the system; 3. Describes the operational context of the information system in terms of missions and business processes; 4. Provides the security categorization of the information system including supporting rationale; 5. Describes the operational environment for the information system and relationships with or connections to other information systems; 6. Provides an overview of the security requirements for the system; 7. Identifies any relevant overlays, if applicable; 8. Describes the security controls in place or planned for meeting those requirements including a rationale for the tailoring and supplementation decisions; and 9. Is reviewed and approved by the authorizing official or designated representative prior to plan implementation; b. Distributes copies of the security plan and communicates subsequent changes to the plan to {{Assignment: organization-defined personnel or roles}}; c. Reviews the security plan for the information system at least annually or when required due to system changes or modifications; d. Updates the plan to address changes to the information system/environment of operation or problems identified during plan implementation or security control assessments; and e. Protects the security plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 14577
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization designs its security architecture using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security safeguards operate in a coordinated and mutually reinforcing manner.' WHERE [Requirement_Id] = 14581
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that {{Assignment: organization-defined security safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 14582
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that individuals accessing an information system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 14587
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization, upon termination of individual employment: a. Disables information system access within if voluntary: As soon as possible, not to exceed 5 working days; If involuntary: Within same day as termination; b. Terminates/revokes any authenticators/credentials associated with the individual; c. Conducts exit interviews that include a discussion of {{Assignment: organization-defined information security topics}}; d. Retrieves all security-related organizational information system-related property; e. Retains access to organizational information and information systems formerly controlled by terminated individual; and f. Notifies {{Assignment: organization-defined personnel or roles}} as soon as possible, not to exceed 1 working day.' WHERE [Requirement_Id] = 14588
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and confirms ongoing operational need for current logical and physical access authorizations to information systems/facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiates reassignment actions to ensure all system access no longer required (need to know) are removed or disabled within 10 working days if not otherwise defined in formal organizational policy; c. Modifies access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 14590
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts an assessment of risk, including the likelihood and magnitude of harm, from the unauthorized access, use, disclosure, disruption, modification, or destruction of the information system and the information it processes, stores, or transmits; b. Documents risk assessment results in {{Selection: security plan; risk assessment report; [Assignment: organization-defined document]}}; c. Reviews risk assessment results at least annually if not otherwise defined in formal organizational policy; d. Disseminates risk assessment results to {{Assignment: organization-defined personnel or roles}}; and e. Updates the risk assessment at least annually if not otherwise defined in formal organizational policy or whenever there are significant changes to the information system or environment of operation (including the identification of new threats and vulnerabilities), or other conditions that may impact the security state of the system.' WHERE [Requirement_Id] = 14596
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Scans for vulnerabilities in the information system and hosted applications at least every 120 days and when new vulnerabilities potentially affecting the system/applications are identified and reported; b. Employs vulnerability scanning tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for: 1. Enumerating platforms, software flaws, and improper configurations; 2. Formatting checklists and test procedures; and 3. Measuring vulnerability impact; c. Analyzes vulnerability scan reports and results from security control assessments; d. Remediates legitimate vulnerabilities {{Assignment: organization-defined response times}} in accordance with an organizational assessment of risk; and e. Shares information obtained from the vulnerability scanning process and security control assessments with {{Assignment: organization-defined personnel or roles}} to help eliminate similar vulnerabilities in other information systems (i.e., systemic weaknesses or deficiencies).' WHERE [Requirement_Id] = 14597
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization determines what information about the information system is discoverable by adversaries and subsequently takes {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 14601
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide design and implementation information for the security controls to be employed that includes: {{Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design/implementation information]}} at {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 14609
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{Assignment: organization-defined state-of-the-practice system/security engineering methods, software development methods, testing/evaluation/validation techniques, and quality control processes}}.' WHERE [Requirement_Id] = 14610
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Deliver the system, component, or service with {{Assignment: organization-defined security configurations}} implemented; and (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.' WHERE [Requirement_Id] = 14611
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to produce a plan for the continuous monitoring of security control effectiveness that contains {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 14614
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes, documents, and maintains trust relationships with external service providers based on {{Assignment: organization-defined security requirements, properties, factors, or conditions defining acceptable trust relationships}}.' WHERE [Requirement_Id] = 14619
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to ensure that the interests of {{Assignment: organization-defined external service providers}} are consistent with and reflect organizational interests.' WHERE [Requirement_Id] = 14620
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts the location of {{Selection (one or more): information processing; information/data; information system services}} to {{Assignment: organization-defined locations}} based on {{Assignment: organization-defined requirements or conditions}}.' WHERE [Requirement_Id] = 14621
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security assessment plan and the evidence produced during security testing/evaluation; and (b) Ensures that the independent agent either is provided with sufficient information to complete the verification process or has been granted the authority to obtain such information.' WHERE [Requirement_Id] = 14630
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to perform a manual code review of {{Assignment: organization-defined specific code}} using {{Assignment: organization-defined processes, procedures, and/or techniques}}.' WHERE [Requirement_Id] = 14631
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to perform penetration testing at {{Assignment: organization-defined breadth/depth}} and with {{Assignment: organization-defined constraints}}.' WHERE [Requirement_Id] = 14632
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to verify that the scope of security testing/evaluation provides complete coverage of required security controls at {{Assignment: organization-defined depth of testing/evaluation}}.' WHERE [Requirement_Id] = 14634
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tailored acquisition strategies, contract tools, and procurement methods}} for the purchase of the information system, system component, or information system service from suppliers.' WHERE [Requirement_Id] = 14637
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to limit harm from potential adversaries identifying and targeting the organizational supply chain.' WHERE [Requirement_Id] = 14639
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} in accordance with classification guides to protect supply chain-related information for the information system, system component, or information system service.' WHERE [Requirement_Id] = 14642
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to validate that the information system or system component received is genuine and has not been altered.' WHERE [Requirement_Id] = 14643
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection (one or more): organizational analysis, independent third-party analysis, organizational penetration testing, independent third-party penetration testing}} of {{Assignment: organization-defined supply chain elements, processes, and actors}} associated with the information system, system component, or information system service.' WHERE [Requirement_Id] = 14644
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to ensure an adequate supply of {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 14646
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and retains unique identification of {{Assignment: organization-defined supply chain elements, processes, and actors}} for the information system, system component, or information system service.' WHERE [Requirement_Id] = 14647
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery}}.' WHERE [Requirement_Id] = 14649
