UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that developers perform threat modeling and a vulnerability analysis for the information system at {{Assignment: organization-defined breadth/depth}} that: (a) Uses {{Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels}}; (b) Employs {{Assignment: organization-defined tools and methods}}; and (c) Produces evidence that meets {{Assignment: organization-defined acceptance criteria}}.' WHERE [Requirement_Id] = 14652
