UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Perform an automated vulnerability analysis using {{Assignment: organization-defined tools}}; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 14655
