UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to ensure that only {{Assignment: organization-defined individuals or information systems}} receive the {{Assignment: organization-defined information, information system components, or devices}}.' WHERE [Requirement_Id] = 15966
