UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces the use of human reviews for {{Assignment: organization-defined information flows}} under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 16017
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for privileged administrators to enable/disable {{Assignment: organization-defined security policy filters}} under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 16018
