UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when transferring information between different security domains, decomposes information into {{Assignment: organization-defined policy-relevant subcomponents}} for submission to policy enforcement mechanisms.' WHERE [Requirement_Id] = 16021
