UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates source and destination points by {{Selection (one or more): organization, system, application, individual}} for information transfer.' WHERE [Requirement_Id] = 16024
