UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization explicitly authorizes access to {{Assignment: organization-defined security functions (deployed in hardware, software, and firmware) and security-relevant information}}.' WHERE [Requirement_Id] = 16032
