UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews {{Assignment: organization-defined frequency}} the privileges assigned to {{Assignment: organization-defined roles or classes of users}} to validate the need for such privileges; and (b) Reassigns or removes privileges, if necessary, to correctly reflect organizational mission/business needs.' WHERE [Requirement_Id] = 16038
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents {{Assignment: organization-defined software}} from executing at higher privilege levels than users executing the software.' WHERE [Requirement_Id] = 16039
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Enforces a limit of {{Assignment: organization-defined number}} consecutive invalid logon attempts by a user during a {{Assignment: organization-defined time period}}; and b. Automatically {{Selection: locks the account/node for an [Assignment: organization-defined time period]; locks the account/node until released by an administrator; delays next logon prompt according to [Assignment: organization-defined delay algorithm]}} when the maximum number of unsuccessful attempts is exceeded.' WHERE [Requirement_Id] = 16042
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system purges/wipes information from {{Assignment: organization-defined mobile devices}} based on {{Assignment: organization-defined purging/wiping requirements/techniques}} after {{Assignment: organization-defined number}} consecutive, unsuccessful device logon attempts.' WHERE [Requirement_Id] = 16043
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Displays to users {{Assignment: organization-defined system use notification message or banner}} before granting access to the system that provides privacy and security notices consistent with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance and states that: 1. Users are accessing a U.S. Government information system; 2. Information system usage may be monitored, recorded, and subject to audit; 3. Unauthorized use of the information system is prohibited and subject to criminal and civil penalties; and 4. Use of the information system indicates consent to monitoring and recording; b. Retains the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the information system; and c. For publicly accessible systems: 1. Displays system use information {{Assignment: organization-defined conditions}}, before granting further access; 2. Displays references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and 3. Includes a description of the authorized uses of the system.' WHERE [Requirement_Id] = 16044
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system limits the number of concurrent sessions for each {{Assignment: organization-defined account and/or account type}} to {{Assignment: organization-defined number}}.' WHERE [Requirement_Id] = 16046
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prevents further access to the system by initiating a session lock after {{Assignment: organization-defined time period}} of inactivity or upon receiving a request from a user; and b. Retains the session lock until the user reestablishes access using established identification and authentication procedures.' WHERE [Requirement_Id] = 16047
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system automatically terminates a user session after {{Assignment: organization-defined conditions or trigger events requiring session disconnect}}.' WHERE [Requirement_Id] = 16049
