UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Identifies {{Assignment: organization-defined user actions}} that can be performed on the information system without identification or authentication consistent with organizational missions/business functions; and b. Documents and provides supporting rationale in the security plan for the information system, user actions not requiring identification or authentication.' WHERE [Requirement_Id] = 16051
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Provides the means to associate {{Assignment: organization-defined types of security attributes}} having {{Assignment: organization-defined security attribute values}} with information in storage, in process, and/or in transmission; b. Ensures that the security attribute associations are made and retained with the information; c. Establishes the permitted {{Assignment: organization-defined security attributes}} for {{Assignment: organization-defined information systems}}; and d. Determines the permitted {{Assignment: organization-defined values or ranges}} for each of the established security attributes.' WHERE [Requirement_Id] = 16052
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system dynamically associates security attributes with {{Assignment: organization defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}} as information is created and combined.' WHERE [Requirement_Id] = 16053
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system maintains the association and integrity of {{Assignment: organization defined security attributes}} to {{Assignment: organization-defined subjects and objects}}.' WHERE [Requirement_Id] = 16055
