UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system displays security attributes in human-readable form on each object that the system transmits to output devices to identify {{Assignment: organization-identified special dissemination, handling, or distribution instructions}} using {{Assignment: organization-identified human-readable, standard naming conventions}}.' WHERE [Requirement_Id] = 16057
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization allows personnel to associate, and maintain the association of {{Assignment: organization-defined security attributes}} with {{Assignment: organization-defined subjects and objects}} in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 16058
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined techniques or technologies}} with {{Assignment: organization-defined level of assurance}} in associating security attributes to information.' WHERE [Requirement_Id] = 16060
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that security attributes associated with information are reassigned only via re-grading mechanisms validated using {{Assignment: organization-defined techniques or procedures}}.' WHERE [Requirement_Id] = 16061
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system routes all remote accesses through {{Assignment: organization-defined number}} managed network access control points.' WHERE [Requirement_Id] = 16066
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Authorizes the execution of privileged commands and access to security-relevant information via remote access only for {{Assignment: organization-defined needs}}; and (b) Documents the rationale for such access in the security plan for the information system.' WHERE [Requirement_Id] = 16067
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to expeditiously disconnect or disable remote access to the information system within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16069
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects wireless access to the system using authentication of {{Selection (one or more): users; devices}} and encryption.' WHERE [Requirement_Id] = 16071
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Prohibits the use of unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information unless specifically permitted by the authorizing official; and (b) Enforces the following restrictions on individuals permitted by the authorizing official to use unclassified mobile devices in facilities containing information systems processing, storing, or transmitting classified information: (1) Connection of unclassified mobile devices to classified information systems is prohibited; (2) Connection of unclassified mobile devices to unclassified information systems requires approval from the authorizing official; (3) Use of internal or external modems or wireless interfaces within the unclassified mobile devices is prohibited; and (4) Unclassified mobile devices and the information stored on those devices are subject to random reviews and inspections by {{Assignment: organization-defined security officials}}, and if classified information is found, the incident handling policy is followed. (c) Restricts the connection of classified mobile devices to classified information systems in accordance with {{Assignment: organization-defined security policies}}.' WHERE [Requirement_Id] = 16076
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: full-device encryption; container encryption}} to protect the confidentiality and integrity of information on {{Assignment: organization-defined mobile devices}}.' WHERE [Requirement_Id] = 16077
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of organization-controlled portable storage devices by authorized individuals on external information systems.' WHERE [Requirement_Id] = 16080
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of non-organizationally owned information systems, system components, or devices to process, store, or transmit organizational information.' WHERE [Requirement_Id] = 16081
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the use of {{Assignment: organization-defined network accessible storage devices}} in external information systems.' WHERE [Requirement_Id] = 16082
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Facilitates information sharing by enabling authorized users to determine whether access authorizations assigned to the sharing partner match the access restrictions on the information for {{Assignment: organization-defined information sharing circumstances where user discretion is required}}; and b. Employs {{Assignment: organization-defined automated mechanisms or manual processes}} to assist users in making information sharing/collaboration decisions.' WHERE [Requirement_Id] = 16083
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements information search and retrieval services that enforce {{Assignment: organization-defined information sharing restrictions}}.' WHERE [Requirement_Id] = 16085
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Designates individuals authorized to post information onto a publicly accessible information system; b. Trains authorized individuals to ensure that publicly accessible information does not contain nonpublic information; c. Reviews the proposed content of information prior to posting onto the publicly accessible information system to ensure that nonpublic information is not included; and d. Reviews the content on the publicly accessible information system for nonpublic information {{Assignment: organization-defined frequency}} and removes such information, if discovered.' WHERE [Requirement_Id] = 16086
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined data mining prevention and detection techniques}} for {{Assignment: organization-defined data storage objects}} to adequately detect and protect against data mining.' WHERE [Requirement_Id] = 16087
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes procedures to ensure {{Assignment: organization-defined access control decisions}} are applied to each access request prior to access enforcement.' WHERE [Requirement_Id] = 16088
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system transmits {{Assignment: organization-defined access authorization information}} using {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined information systems}} that enforce access control decisions.' WHERE [Requirement_Id] = 16089
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces access control decisions based on {{Assignment: organization defined security attributes}} that do not include the identity of the user or process acting on behalf of the user.' WHERE [Requirement_Id] = 16090
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements a reference monitor for {{Assignment: organization defined access control policies}} that is tamperproof, always invoked, and small enough to be subject to analysis and testing, the completeness of which can be assured.' WHERE [Requirement_Id] = 16091
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security awareness and training policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security awareness and training policy and associated security awareness and training controls; and b. Reviews and updates the current: 1. Security awareness and training policy {{Assignment: organization-defined frequency}}; and 2. Security awareness and training procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16092
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides basic security awareness training to information system users (including managers, senior executives, and contractors): a. As part of initial training for new users; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 16093
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides role-based security training to personnel with assigned security roles and responsibilities: a. Before authorizing access to the information system or performing assigned duties; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 16094
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Documents and monitors individual information system security training activities including basic security awareness training and specific information system security training; and b. Retains individual training records for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16095
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An audit and accountability policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the audit and accountability policy and associated audit and accountability controls; and b. Reviews and updates the current: 1. Audit and accountability policy {{Assignment: organization-defined frequency}}; and 2. Audit and accountability procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16096
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines that the information system is capable of auditing the following events: {{Assignment: organization-defined auditable events}}; b. Coordinates the security audit function with other organizational entities requiring audit related information to enhance mutual support and to help guide the selection of auditable events; c. Provides a rationale for why the auditable events are deemed to be adequate to support after-the-fact investigations of security incidents; and d. Determines that the following events are to be audited within the information system: {{Assignment: organization-defined audited events (the subset of the auditable events defined in AU-2 a.) along with the frequency of (or situation requiring) auditing for each identified event}}.' WHERE [Requirement_Id] = 16097
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the audited events {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16098
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system generates audit records containing the following additional information: {{Assignment: organization-defined additional, more detailed information}}.' WHERE [Requirement_Id] = 16100
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides centralized management and configuration of the content to be captured in audit records generated by {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 16101
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization allocates audit record storage capacity in accordance with {{Assignment: organization-defined audit record storage requirements}}.' WHERE [Requirement_Id] = 16102
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system off-loads audit records {{Assignment: organization-defined frequency}} onto a different system or media than the system being audited.' WHERE [Requirement_Id] = 16103
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Alerts {{Assignment: organization-defined personnel or roles}} in the event of an audit processing failure; and b. Takes the following additional actions: {{Assignment: organization-defined actions to be taken (e.g., shut down information system, overwrite oldest audit records, stop generating audit records)}}.' WHERE [Requirement_Id] = 16104
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides a warning to {{Assignment: organization-defined personnel, roles, and/or locations}} within {{Assignment: organization-defined time period}} when allocated audit record storage volume reaches {{Assignment: organization-defined percentage}} of repository maximum audit record storage capacity.' WHERE [Requirement_Id] = 16105
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides an alert in {{Assignment: organization-defined real-time period}} to {{Assignment: organization-defined personnel, roles, and/or locations}} when the following audit failure events occur: {{Assignment: organization-defined audit failure events requiring real-time alerts}}.' WHERE [Requirement_Id] = 16106
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system enforces configurable network communications traffic volume thresholds reflecting limits on auditing capacity and {{Selection: rejects; delays}} network traffic above those thresholds.' WHERE [Requirement_Id] = 16107
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system invokes a {{Selection: full system shutdown; partial system shutdown; degraded operational mode with limited mission/business functionality available}} in the event of {{Assignment: organization-defined audit failures}}, unless an alternate audit capability exists.' WHERE [Requirement_Id] = 16108
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and analyzes information system audit records {{Assignment: organization-defined frequency}} for indications of {{Assignment: organization-defined inappropriate or unusual activity}}; and b. Reports findings to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16109
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization integrates analysis of audit records with analysis of {{Selection (one or more): vulnerability scanning information; performance data; information system monitoring information; [Assignment: organization-defined data/information collected from other sources]}} to further enhance the ability to identify inappropriate or unusual activity.' WHERE [Requirement_Id] = 16113
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization specifies the permitted actions for each {{Selection (one or more): information system process; role; user}} associated with the review, analysis, and reporting of audit information.' WHERE [Requirement_Id] = 16115
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to process audit records for events of interest based on {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 16120
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to sort and search audit records for events of interest based on the content of {{Assignment: organization-defined audit fields within audit records}}.' WHERE [Requirement_Id] = 16121
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Uses internal system clocks to generate time stamps for audit records; and b. Records time stamps for audit records that can be mapped to Coordinated Universal Time (UTC) or Greenwich Mean Time (GMT) and meets {{Assignment: organization-defined granularity of time measurement}}.' WHERE [Requirement_Id] = 16122
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Compares the internal information system clocks {{Assignment: organization-defined frequency}} with {{Assignment: organization-defined authoritative time source}}; and (b) Synchronizes the internal system clocks to the authoritative time source when the time difference is greater than {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16123
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system backs up audit records {{Assignment: organization-defined frequency}} onto a physically different system or system component than the system or component being audited.' WHERE [Requirement_Id] = 16127
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes access to management of audit functionality to only {{Assignment: organization-defined subset of privileged users}}.' WHERE [Requirement_Id] = 16129
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for {{Selection (one or more): movement; deletion}} of {{Assignment: organization-defined audit information}}.' WHERE [Requirement_Id] = 16130
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes read-only access to audit information to {{Assignment: organization defined subset of privileged users}}.' WHERE [Requirement_Id] = 16131
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against an individual (or process acting on behalf of an individual) falsely denying having performed {{Assignment: organization-defined actions to be covered by non-repudiation}}.' WHERE [Requirement_Id] = 16132
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Binds the identity of the information producer with the information to {{Assignment: organization-defined strength of binding}}; and (b) Provides the means for authorized individuals to determine the identity of the producer of the information.' WHERE [Requirement_Id] = 16133
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Validates the binding of the information producer identity to the information at {{Assignment: organization-defined frequency}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 16134
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Validates the binding of the information reviewer identity to the information at the transfer or release points prior to release/transfer between {{Assignment: organization-defined security domains}}; and (b) Performs {{Assignment: organization-defined actions}} in the event of a validation error.' WHERE [Requirement_Id] = 16136
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization retains audit records for {{Assignment: organization-defined time period consistent with records retention policy}} to provide support for after-the-fact investigations of security incidents and to meet regulatory and organizational information retention requirements.' WHERE [Requirement_Id] = 16137
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined measures}} to ensure that long-term audit records generated by the information system can be retrieved.' WHERE [Requirement_Id] = 16138
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Provides audit record generation capability for the auditable events defined in AU-2 a. at {{Assignment: organization-defined information system components}}; b. Allows {{Assignment: organization-defined personnel or roles}} to select which auditable events are to be audited by specific components of the information system; and c. Generates audit records for the events defined in AU-2 d. with the content defined in AU-3.' WHERE [Requirement_Id] = 16139
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system compiles audit records from {{Assignment: organization-defined information system components}} into a system-wide (logical or physical) audit trail that is time correlated to within {{Assignment: organization-defined level of tolerance for relationship between time stamps of individual records in the audit trail}}.' WHERE [Requirement_Id] = 16140
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability for {{Assignment: organization-defined individuals or roles}} to change the auditing to be performed on {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined selectable event criteria}} within {{Assignment: organization-defined time thresholds}}.' WHERE [Requirement_Id] = 16142
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors {{Assignment: organization-defined open source information and/or information sites}} {{Assignment: organization-defined frequency}} for evidence of unauthorized disclosure of organizational information.' WHERE [Requirement_Id] = 16143
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews the open source information sites being monitored {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16145
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides an alternate audit capability in the event of a failure in primary audit capability that provides {{Assignment: organization-defined alternate audit functionality}}.' WHERE [Requirement_Id] = 16150
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined methods}} for coordinating {{Assignment: organization-defined audit information}} among external organizations when audit information is transmitted across organizational boundaries.' WHERE [Requirement_Id] = 16151
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides cross-organizational audit information to {{Assignment: organization defined organizations}} based on {{Assignment: organization-defined cross-organizational sharing agreements}}.' WHERE [Requirement_Id] = 16153
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security assessment and authorization policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security assessment and authorization policy and associated security assessment and authorization controls; and b. Reviews and updates the current: 1. Security assessment and authorization policy {{Assignment: organization-defined frequency}}; and 2. Security assessment and authorization procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16154
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security assessment plan that describes the scope of the assessment including: 1. Security controls and control enhancements under assessment; 2. Assessment procedures to be used to determine security control effectiveness; and 3. Assessment environment, assessment team, and assessment roles and responsibilities; b. Assesses the security controls in the information system and its environment of operation {{Assignment: organization-defined frequency}} to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements; c. Produces a security assessment report that documents the results of the assessment; and d. Provides the results of the security control assessment to {{Assignment: organization-defined individuals or roles}}.' WHERE [Requirement_Id] = 16155
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to conduct security control assessments.' WHERE [Requirement_Id] = 16156
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes as part of security control assessments, {{Assignment: organization defined frequency}}, {{Selection: announced; unannounced}}, {{Selection (one or more): in-depth monitoring; vulnerability scanning; malicious user testing; insider threat assessment; performance/load testing; [Assignment: organization-defined other forms of security assessment]}}.' WHERE [Requirement_Id] = 16157
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization accepts the results of an assessment of {{Assignment: organization-defined information system}} performed by {{Assignment: organization-defined external organization}} when the assessment meets {{Assignment: organization-defined requirements}}.' WHERE [Requirement_Id] = 16158
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes connections from the information system to other information systems through the use of Interconnection Security Agreements; b. Documents, for each interconnection, the interface characteristics, security requirements, and the nature of the information communicated; and c. Reviews and updates Interconnection Security Agreements {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16159
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, national security system}} to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 16160
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of a classified, national security system to an external network without the use of {{Assignment: organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 16161
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined unclassified, non-national security system}} to an external network without the use of {{Assignment; organization-defined boundary protection device}}.' WHERE [Requirement_Id] = 16162
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prohibits the direct connection of an {{Assignment: organization-defined information system}} to a public network.' WHERE [Requirement_Id] = 16163
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection: allow-all, deny-by-exception; deny-all, permit-by-exception}} policy for allowing {{Assignment: organization-defined information systems}} to connect to external information systems.' WHERE [Requirement_Id] = 16164
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a plan of action and milestones for the information system to document the organization''s planned remedial actions to correct weaknesses or deficiencies noted during the assessment of the security controls and to reduce or eliminate known vulnerabilities in the system; and b. Updates existing plan of action and milestones {{Assignment: organization-defined frequency}} based on the findings from security controls assessments, security impact analyses, and continuous monitoring activities.' WHERE [Requirement_Id] = 16165
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a senior-level executive or manager as the authorizing official for the information system; b. Ensures that the authorizing official authorizes the information system for processing before commencing operations; and c. Updates the security authorization {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16167
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization develops a continuous monitoring strategy and implements a continuous monitoring program that includes: a. Establishment of {{Assignment: organization-defined metrics}} to be monitored; b. Establishment of {{Assignment: organization-defined frequencies}} for monitoring and {{Assignment: organization-defined frequencies}} for assessments supporting such monitoring; c. Ongoing security control assessments in accordance with the organizational continuous monitoring strategy; d. Ongoing security status monitoring of organization-defined metrics in accordance with the organizational continuous monitoring strategy; e. Correlation and analysis of security-related information generated by assessments and monitoring; f. Response actions to address results of the analysis of security-related information; and g. Reporting the security status of organization and the information system to {{Assignment: organization-defined personnel or roles}} {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16168
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs assessors or assessment teams with {{Assignment: organization-defined level of independence}} to monitor the security controls in the information system on an ongoing basis.' WHERE [Requirement_Id] = 16169
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization conducts penetration testing {{Assignment: organization-defined frequency}} on {{Assignment: organization-defined information systems or system components}}.' WHERE [Requirement_Id] = 16171
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined red team exercises}} to simulate attempts by adversaries to compromise organizational information systems in accordance with {{Assignment: organization-defined rules of engagement}}.' WHERE [Requirement_Id] = 16173
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Authorizes internal connections of {{Assignment: organization-defined information system components or classes of components}} to the information system; and b. Documents, for each internal connection, the interface characteristics, security requirements, and the nature of the information communicated.' WHERE [Requirement_Id] = 16174
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A configuration management policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the configuration management policy and associated configuration management controls; and b. Reviews and updates the current: 1. Configuration management policy {{Assignment: organization-defined frequency}}; and 2. Configuration management procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16176
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews and updates the baseline configuration of the information system: (a) {{Assignment: organization-defined frequency}}; (b) When required due to {{Assignment organization-defined circumstances}}; and (c) As an integral part of information system component installations and upgrades.' WHERE [Requirement_Id] = 16178
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization retains {{Assignment: organization-defined previous versions of baseline configurations of the information system}} to support rollback.' WHERE [Requirement_Id] = 16180
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Issues {{Assignment: organization-defined information systems, system components, or devices}} with {{Assignment: organization-defined configurations}} to individuals traveling to locations that the organization deems to be of significant risk; and (b) Applies {{Assignment: organization-defined security safeguards}} to the devices when the individuals return.' WHERE [Requirement_Id] = 16182
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Determines the types of changes to the information system that are configuration-controlled; b. Reviews proposed configuration-controlled changes to the information system and approves or disapproves such changes with explicit consideration for security impact analyses; c. Documents configuration change decisions associated with the information system; d. Implements approved configuration-controlled changes to the information system; e. Retains records of configuration-controlled changes to the information system for {{Assignment: organization-defined time period}}; f. Audits and reviews activities associated with configuration-controlled changes to the information system; and g. Coordinates and provides oversight for configuration change control activities through {{Assignment: organization-defined configuration change control element (e.g., committee, board}} that convenes {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined configuration change conditions]}}.' WHERE [Requirement_Id] = 16183
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to: (a) Document proposed changes to the information system; (b) Notify {{Assignment: organized-defined approval authorities}} of proposed changes to the information system and request change approval; (c) Highlight proposed changes to the information system that have not been approved or disapproved by {{Assignment: organization-defined time period}}; (d) Prohibit changes to the information system until designated approvals are received; (e) Document all changes to the information system; and (f) Notify {{Assignment: organization-defined personnel}} when approved changes to the information system are completed.' WHERE [Requirement_Id] = 16184
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires an information security representative to be a member of the {{Assignment: organization-defined configuration change control element}}.' WHERE [Requirement_Id] = 16187
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined security responses}} automatically if baseline configurations are changed in an unauthorized manner.' WHERE [Requirement_Id] = 16188
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that cryptographic mechanisms used to provide {{Assignment: organization-defined security safeguards}} are under configuration management.' WHERE [Requirement_Id] = 16189
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reviews information system changes {{Assignment: organization-defined frequency}} and {{Assignment: organization-defined circumstances}} to determine whether unauthorized changes have occurred.' WHERE [Requirement_Id] = 16195
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents the installation of {{Assignment: organization-defined software and firmware components}} without verification that the component has been digitally signed using a certificate that is recognized and approved by the organization.' WHERE [Requirement_Id] = 16196
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for implementing changes to {{Assignment: organization-defined information system components and system-level information}}.' WHERE [Requirement_Id] = 16197
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Limits privileges to change information system components and system-related information within a production or operational environment; and (b) Reviews and reevaluates privileges {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16198
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and documents configuration settings for information technology products employed within the information system using {{Assignment: organization-defined security configuration checklists}} that reflect the most restrictive mode consistent with operational requirements; b. Implements the configuration settings; c. Identifies, documents, and approves any deviations from established configuration settings for {{Assignment: organization-defined information system components}} based on {{Assignment: organization-defined operational requirements}}; and d. Monitors and controls changes to the configuration settings in accordance with organizational policies and procedures.' WHERE [Requirement_Id] = 16200
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to centrally manage, apply, and verify configuration settings for {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 16201
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to respond to unauthorized changes to {{Assignment: organization-defined configuration settings}}.' WHERE [Requirement_Id] = 16202
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Configures the information system to provide only essential capabilities; and b. Prohibits or restricts the use of the following functions, ports, protocols, and/or services: {{Assignment: organization-defined prohibited or restricted functions, ports, protocols, and/or services}}.' WHERE [Requirement_Id] = 16203
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Reviews the information system {{Assignment: organization-defined frequency}} to identify unnecessary and/or non-secure functions, ports, protocols, and services; and (b) Disables {{Assignment: organization-defined functions, ports, protocols, and services within the information system deemed to be unnecessary and/or non-secure}}.' WHERE [Requirement_Id] = 16204
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents program execution in accordance with {{Selection (one or more): [Assignment: organization-defined policies regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage}}.' WHERE [Requirement_Id] = 16205
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures compliance with {{Assignment: organization-defined registration requirements for functions, ports, protocols, and services}}.' WHERE [Requirement_Id] = 16206
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs not authorized to execute on the information system}}; (b) Employs an allow-all, deny-by-exception policy to prohibit the execution of unauthorized software programs on the information system; and (c) Reviews and updates the list of unauthorized software programs {{Assignment: organization defined frequency}}.' WHERE [Requirement_Id] = 16207
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Identifies {{Assignment: organization-defined software programs authorized to execute on the information system}}; (b) Employs a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the information system; and (c) Reviews and updates the list of authorized software programs {{Assignment: organization defined frequency}}.' WHERE [Requirement_Id] = 16208
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents an inventory of information system components that: 1. Accurately reflects the current information system; 2. Includes all components within the authorization boundary of the information system; 3. Is at the level of granularity deemed necessary for tracking and reporting; and 4. Includes {{Assignment: organization-defined information deemed necessary to achieve effective information system component accountability}}; and b. Reviews and updates the information system component inventory {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16209
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Employs automated mechanisms {{Assignment: organization-defined frequency}} to detect the presence of unauthorized hardware, software, and firmware components within the information system; and (b) Takes the following actions when unauthorized components are detected: {{Selection (one or more): disables network access by such components; isolates the components; notifies [Assignment: organization-defined personnel or roles]}}.' WHERE [Requirement_Id] = 16212
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes in the information system component inventory information, a means for identifying by {{Selection (one or more): name; position; role}}, individuals responsible/accountable for administering those components.' WHERE [Requirement_Id] = 16213
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Assigns {{Assignment: organization-defined acquired information system components}} to an information system; and (b) Receives an acknowledgement from the information system owner of this assignment.' WHERE [Requirement_Id] = 16218
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes the following restrictions on the use of open source software: {{Assignment: organization-defined restrictions}}.' WHERE [Requirement_Id] = 16222
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined policies}} governing the installation of software by users; b. Enforces software installation policies through {{Assignment: organization-defined methods}}; and c. Monitors policy compliance at {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16223
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system alerts {{Assignment: organization-defined personnel or roles}} when the unauthorized installation of software is detected.' WHERE [Requirement_Id] = 16224
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A contingency planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls; and b. Reviews and updates the current: 1. Contingency planning policy {{Assignment: organization-defined frequency}}; and 2. Contingency planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16226
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a contingency plan for the information system that: 1. Identifies essential missions and business functions and associated contingency requirements; 2. Provides recovery objectives, restoration priorities, and metrics; 3. Addresses contingency roles, responsibilities, assigned individuals with contact information; 4. Addresses maintaining essential missions and business functions despite an information system disruption, compromise, or failure; 5. Addresses eventual, full information system restoration without deterioration of the security safeguards originally planned and implemented; and 6. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the contingency plan to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; c. Coordinates contingency planning activities with incident handling activities; d. Reviews the contingency plan for the information system {{Assignment: organization-defined frequency}}; e. Updates the contingency plan to address changes to the organization, information system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing; f. Communicates contingency plan changes to {{Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements}}; and g. Protects the contingency plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 16227
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans for the resumption of essential missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation.' WHERE [Requirement_Id] = 16230
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans for the resumption of all missions and business functions within {{Assignment: organization-defined time period}} of contingency plan activation.' WHERE [Requirement_Id] = 16231
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides contingency training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming a contingency role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 16236
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Tests the contingency plan for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the effectiveness of the plan and the organizational readiness to execute the plan; b. Reviews the contingency plan test results; and c. Initiates corrective actions, if needed.' WHERE [Requirement_Id] = 16239
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes an alternate processing site including necessary agreements to permit the transfer and resumption of {{Assignment: organization-defined information system operations}} for essential missions/business functions within {{Assignment: organization-defined time period consistent with recovery time and recovery point objectives}} when the primary processing capabilities are unavailable; b. Ensures that equipment and supplies required to transfer and resume operations are available at the alternate processing site or contracts are in place to support delivery to the site within the organization-defined time period for transfer/resumption; and c. Ensures that the alternate processing site provides information security safeguards equivalent to that of the primary site.' WHERE [Requirement_Id] = 16248
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes alternate telecommunications services including necessary agreements to permit the resumption of {{Assignment: organization-defined information system operations}} for essential missions and business functions within {{Assignment: organization defined time period}} when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.' WHERE [Requirement_Id] = 16254
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires primary and alternate telecommunications service providers to have contingency plans; (b) Reviews provider contingency plans to ensure that the plans meet organizational contingency requirements; and (c) Obtains evidence of contingency testing/training by providers {{Assignment: organization defined frequency}}.' WHERE [Requirement_Id] = 16258
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests alternate telecommunication services {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16259
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts backups of user-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; b. Conducts backups of system-level information contained in the information system {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; c. Conducts backups of information system documentation including security-related documentation {{Assignment: organization-defined frequency consistent with recovery time and recovery point objectives}}; and d. Protects the confidentiality, integrity, and availability of backup information at storage locations.' WHERE [Requirement_Id] = 16260
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests backup information {{Assignment: organization-defined frequency}} to verify media reliability and information integrity.' WHERE [Requirement_Id] = 16261
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization stores backup copies of {{Assignment: organization-defined critical information system software and other security-related information}} in a separate facility or in a fire-rated container that is not collocated with the operational system.' WHERE [Requirement_Id] = 16263
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization transfers information system backup information to the alternate storage site {{Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives}}.' WHERE [Requirement_Id] = 16264
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the deletion or destruction of {{Assignment: organization-defined backup information}}.' WHERE [Requirement_Id] = 16266
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to restore information system components within {{Assignment: organization-defined restoration time-periods}} from configuration-controlled and integrity-protected information representing a known, operational state for the components.' WHERE [Requirement_Id] = 16269
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to employ {{Assignment: organization defined alternative communications protocols}} in support of maintaining continuity of operations.' WHERE [Requirement_Id] = 16271
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, when {{Assignment: organization-defined conditions}} are detected, enters a safe mode of operation with {{Assignment: organization-defined restrictions of safe mode of operation}}.' WHERE [Requirement_Id] = 16272
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined alternative or supplemental security mechanisms}} for satisfying {{Assignment: organization-defined security functions}} when the primary means of implementing the security function is unavailable or compromised.' WHERE [Requirement_Id] = 16273
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An identification and authentication policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the identification and authentication policy and associated identification and authentication controls; and b. Reviews and updates the current: 1. Identification and authentication policy {{Assignment: organization-defined frequency}}; and 2. Identification and authentication procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16274
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system uniquely identifies and authenticates {{Assignment: organization defined specific and/or types of devices}} before establishing a {{Selection (one or more): local; remote; network}} connection.' WHERE [Requirement_Id] = 16276
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system authenticates {{Assignment: organization-defined specific devices and/or types of devices}} before establishing {{Selection (one or more): local; remote; network}} connection using bidirectional authentication that is cryptographically based.' WHERE [Requirement_Id] = 16277
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Standardizes dynamic address allocation lease information and the lease duration assigned to devices in accordance with {{Assignment: organization-defined lease information and lease duration}}; and (b) Audits lease information when assigned to a device.' WHERE [Requirement_Id] = 16278
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that device identification and authentication based on attestation is handled by {{Assignment: organization-defined configuration management process}}.' WHERE [Requirement_Id] = 16279
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system identifiers by: a. Receiving authorization from {{Assignment: organization-defined personnel or roles}} to assign an individual, group, role, or device identifier; b. Selecting an identifier that identifies an individual, group, role, or device; c. Assigning the identifier to the intended individual, group, role, or device; d. Preventing reuse of identifiers for {{Assignment: organization-defined time period}}; and e. Disabling the identifier after {{Assignment: organization-defined time period of inactivity}}.' WHERE [Requirement_Id] = 16280
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages individual identifiers by uniquely identifying each individual as {{Assignment: organization-defined characteristic identifying individual status}}.' WHERE [Requirement_Id] = 16284
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of identifiers.' WHERE [Requirement_Id] = 16286
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization manages information system authenticators by: a. Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, or device receiving the authenticator; b. Establishing initial authenticator content for authenticators defined by the organization; c. Ensuring that authenticators have sufficient strength of mechanism for their intended use; d. Establishing and implementing administrative procedures for initial authenticator distribution, for lost/compromised or damaged authenticators, and for revoking authenticators; e. Changing default content of authenticators prior to information system installation; f. Establishing minimum and maximum lifetime restrictions and reuse conditions for authenticators; g. Changing/refreshing authenticators {{Assignment: organization-defined time period by authenticator type}}; h. Protecting authenticator content from unauthorized disclosure and modification; i. Requiring individuals to take, and having devices implement, specific security safeguards to protect authenticators; and j. Changing authenticators for group/role accounts when membership to those accounts changes.' WHERE [Requirement_Id] = 16288
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for password-based authentication: (a) Enforces minimum password complexity of {{Assignment: organization-defined requirements for case sensitivity, number of characters, mix of upper-case letters, lower-case letters, numbers, and special characters, including minimum requirements for each type}}; (b) Enforces at least the following number of changed characters when new passwords are created: {{Assignment: organization-defined number}}; (c) Stores and transmits only encrypted representations of passwords; (d) Enforces password minimum and maximum lifetime restrictions of {{Assignment: organization defined numbers for lifetime minimum, lifetime maximum}}; (e) Prohibits password reuse for {{Assignment: organization-defined number}} generations; and (f) Allows the use of a temporary password for system logons with an immediate change to a permanent password.' WHERE [Requirement_Id] = 16289
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that the registration process to receive {{Assignment: organization defined types of and/or specific authenticators}} be conducted {{Selection: in person; by a trusted third party}} before {{Assignment: organization-defined registration authority}} with authorization by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16291
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated tools to determine if password authenticators are sufficiently strong to satisfy {{Assignment: organization-defined requirements}}.' WHERE [Requirement_Id] = 16292
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined security safeguards}} to manage the risk of compromise due to individuals having accounts on multiple information systems.' WHERE [Requirement_Id] = 16296
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} for cross-organization management of credentials.' WHERE [Requirement_Id] = 16297
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for hardware token-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined token quality requirements}}.' WHERE [Requirement_Id] = 16299
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system, for biometric-based authentication, employs mechanisms that satisfy {{Assignment: organization-defined biometric quality requirements}}.' WHERE [Requirement_Id] = 16300
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prohibits the use of cached authenticators after {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16301
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies and authenticates {{Assignment: organization-defined information system services}} using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 16307
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that identification and authentication decisions are transmitted between {{Assignment: organization-defined services}} consistent with organizational policies.' WHERE [Requirement_Id] = 16309
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that individuals accessing the information system employ {{Assignment: organization-defined supplemental authentication techniques or mechanisms}} under specific {{Assignment: organization-defined circumstances or situations}}.' WHERE [Requirement_Id] = 16310
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires users and devices to re-authenticate when {{Assignment: organization-defined circumstances or situations requiring re-authentication}}.' WHERE [Requirement_Id] = 16311
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. An incident response policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the incident response policy and associated incident response controls; and b. Reviews and updates the current: 1. Incident response policy {{Assignment: organization-defined frequency}}; and 2. Incident response procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16312
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides incident response training to information system users consistent with assigned roles and responsibilities: a. Within {{Assignment: organization-defined time period}} of assuming an incident response role or responsibility; b. When required by information system changes; and c. {{Assignment: organization-defined frequency}} thereafter.' WHERE [Requirement_Id] = 16313
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests the incident response capability for the information system {{Assignment: organization-defined frequency}} using {{Assignment: organization-defined tests}} to determine the incident response effectiveness and documents the results.' WHERE [Requirement_Id] = 16316
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization includes dynamic reconfiguration of {{Assignment: organization-defined information system components}} as part of the incident response capability.' WHERE [Requirement_Id] = 16321
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies {{Assignment: organization-defined classes of incidents}} and {{Assignment: organization-defined actions to take in response to classes of incidents}} to ensure continuation of organizational missions and business functions.' WHERE [Requirement_Id] = 16322
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements a configurable capability to automatically disable the information system if {{Assignment: organization-defined security violations}} are detected.' WHERE [Requirement_Id] = 16324
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates incident handling capability for insider threats across {{Assignment: organization-defined components or elements of the organization}}.' WHERE [Requirement_Id] = 16326
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization coordinates with {{Assignment: organization-defined external organizations}} to correlate and share {{Assignment: organization-defined incident information}} to achieve a cross organization perspective on incident awareness and more effective incident responses.' WHERE [Requirement_Id] = 16327
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined dynamic response capabilities}} to effectively respond to security incidents.' WHERE [Requirement_Id] = 16328
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires personnel to report suspected security incidents to the organizational incident response capability within {{Assignment: organization-defined time period}}; and b. Reports security incident information to {{Assignment: organization-defined authorities}}.' WHERE [Requirement_Id] = 16332
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reports information system vulnerabilities associated with reported security incidents to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16334
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an incident response plan that: 1. Provides the organization with a roadmap for implementing its incident response capability; 2. Describes the structure and organization of the incident response capability; 3. Provides a high-level approach for how the incident response capability fits into the overall organization; 4. Meets the unique requirements of the organization, which relate to mission, size, structure, and functions; 5. Defines reportable incidents; 6. Provides metrics for measuring the incident response capability within the organization; 7. Defines the resources and management support needed to effectively maintain and mature an incident response capability; and 8. Is reviewed and approved by {{Assignment: organization-defined personnel or roles}}; b. Distributes copies of the incident response plan to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; c. Reviews the incident response plan {{Assignment: organization-defined frequency}}; d. Updates the incident response plan to address system/organizational changes or problems encountered during plan implementation, execution, or testing; e. Communicates incident response plan changes to {{Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements}}; and f. Protects the incident response plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 16339
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization responds to information spills by: a. Identifying the specific information involved in the information system contamination; b. Alerting {{Assignment: organization-defined personnel or roles}} of the information spill using a method of communication not associated with the spill; c. Isolating the contaminated information system or system component; d. Eradicating the information from the contaminated information system or component; e. Identifying other information systems or system components that may have been subsequently contaminated; and f. Performing other {{Assignment: organization-defined actions}}.' WHERE [Requirement_Id] = 16340
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization assigns {{Assignment: organization-defined personnel or roles}} with responsibility for responding to information spills.' WHERE [Requirement_Id] = 16341
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides information spillage response training {{Assignment: organization defined frequency}}.' WHERE [Requirement_Id] = 16342
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined procedures}} to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions.' WHERE [Requirement_Id] = 16343
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} for personnel exposed to information not within assigned access authorizations.' WHERE [Requirement_Id] = 16344
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system maintenance policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system maintenance policy and associated system maintenance controls; and b. Reviews and updates the current: 1. System maintenance policy {{Assignment: organization-defined frequency}}; and 2. System maintenance procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16346
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Schedules, performs, documents, and reviews records of maintenance and repairs on information system components in accordance with manufacturer or vendor specifications and/or organizational requirements; b. Approves and monitors all maintenance activities, whether performed on site or remotely and whether the equipment is serviced on site or removed to another location; c. Requires that {{Assignment: organization-defined personnel or roles}} explicitly approve the removal of the information system or system components from organizational facilities for off-site maintenance or repairs; d. Sanitizes equipment to remove all information from associated media prior to removal from organizational facilities for off-site maintenance or repairs; e. Checks all potentially impacted security controls to verify that the controls are still functioning properly following maintenance or repair actions; and f. Includes {{Assignment: organization-defined maintenance-related information}} in organizational maintenance records.' WHERE [Requirement_Id] = 16347
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization prevents the unauthorized removal of maintenance equipment containing organizational information by: (a) Verifying that there is no organizational information contained on the equipment; (b) Sanitizing or destroying the equipment; (c) Retaining the equipment within the facility; or (d) Obtaining an exemption from {{Assignment: organization-defined personnel or roles}} explicitly authorizing removal of the equipment from the facility.' WHERE [Requirement_Id] = 16352
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Audits nonlocal maintenance and diagnostic sessions {{Assignment: organization-defined audit events}}; and (b) Reviews the records of the maintenance and diagnostic sessions.' WHERE [Requirement_Id] = 16355
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects nonlocal maintenance sessions by: (a) Employing {{Assignment: organization-defined authenticators that are replay resistant}}; and (b) Separating the maintenance sessions from other network sessions with the information system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths based upon encryption.' WHERE [Requirement_Id] = 16358
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires the approval of each nonlocal maintenance session by {{Assignment: organization defined personnel or roles}}; and (b) Notifies {{Assignment: organization-defined personnel or roles}} of the date and time of planned nonlocal maintenance.' WHERE [Requirement_Id] = 16359
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization obtains maintenance support and/or spare parts for {{Assignment: organization-defined information system components}} within {{Assignment: organization-defined time period}} of failure.' WHERE [Requirement_Id] = 16368
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs preventive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 16369
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs predictive maintenance on {{Assignment: organization-defined information system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 16370
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A media protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the media protection policy and associated media protection controls; and b. Reviews and updates the current: 1. Media protection policy {{Assignment: organization-defined frequency}}; and 2. Media protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16372
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts access to {{Assignment: organization-defined types of digital and/or non-digital media}} to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16373
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Marks information system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempts {{Assignment: organization-defined types of information system media}} from marking as long as the media remain within {{Assignment: organization-defined controlled areas}}.' WHERE [Requirement_Id] = 16374
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Physically controls and securely stores {{Assignment: organization-defined types of digital and/or non-digital media}} within {{Assignment: organization-defined controlled areas}}; and b. Protects information system media until the media are destroyed or sanitized using approved equipment, techniques, and procedures.' WHERE [Requirement_Id] = 16375
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Protects and controls {{Assignment: organization-defined types of information system media}} during transport outside of controlled areas using {{Assignment: organization-defined security safeguards}}; b. Maintains accountability for information system media during transport outside of controlled areas; c. Documents activities associated with the transport of information system media; and d. Restricts the activities associated with the transport of information system media to authorized personnel.' WHERE [Requirement_Id] = 16377
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Sanitizes {{Assignment: organization-defined information system media}} prior to disposal, release out of organizational control, or release for reuse using {{Assignment: organization defined sanitization techniques and procedures}} in accordance with applicable federal and organizational standards and policies; and b. Employs sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.' WHERE [Requirement_Id] = 16380
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization tests sanitization equipment and procedures {{Assignment: organization-defined frequency}} to verify that the intended sanitization is being achieved.' WHERE [Requirement_Id] = 16382
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization applies nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the information system under the following circumstances: {{Assignment: organization-defined circumstances requiring sanitization of portable storage devices}}.' WHERE [Requirement_Id] = 16383
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces dual authorization for the sanitization of {{Assignment: organization defined information system media}}.' WHERE [Requirement_Id] = 16384
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides the capability to purge/wipe information from {{Assignment: organization-defined information systems, system components, or devices}} either remotely or under the following conditions: {{Assignment: organization-defined conditions}}.' WHERE [Requirement_Id] = 16385
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization {{Selection: restricts; prohibits}} the use of {{Assignment: organization defined types of information system media}} on {{Assignment: organization-defined information systems or system components}} using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 16386
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes {{Assignment: organization-defined information system media downgrading process}} that includes employing downgrading mechanisms with {{Assignment: organization defined strength and integrity}}; b. Ensures that the information system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information; c. Identifies {{Assignment: organization-defined information system media requiring downgrading}}; and d. Downgrades the identified information system media using the established process.' WHERE [Requirement_Id] = 16389
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tests}} of downgrading equipment and procedures to verify correct performance {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16391
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization downgrades information system media containing {{Assignment: organization defined Controlled Unclassified Information (CUI)}} prior to public release in accordance with applicable federal and organizational standards and policies.' WHERE [Requirement_Id] = 16392
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A physical and environmental protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the physical and environmental protection policy and associated physical and environmental protection controls; and b. Reviews and updates the current: 1. Physical and environmental protection policy {{Assignment: organization-defined frequency}}; and 2. Physical and environmental protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16394
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, approves, and maintains a list of individuals with authorized access to the facility where the information system resides; b. Issues authorization credentials for facility access; c. Reviews the access list detailing authorized facility access by individuals {{Assignment: organization-defined frequency}}; and d. Removes individuals from the facility access list when access is no longer required.' WHERE [Requirement_Id] = 16395
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires two forms of identification from {{Assignment: organization-defined list of acceptable forms of identification}} for visitor access to the facility where the information system resides.' WHERE [Requirement_Id] = 16397
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization restricts unescorted access to the facility where the information system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 16398
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Enforces physical access authorizations at {{Assignment: organization-defined entry/exit points to the facility where the information system resides}} by; 1. Verifying individual access authorizations before granting access to the facility; and 2. Controlling ingress/egress to the facility using {{Selection (one or more): [Assignment: organization-defined physical access control systems/devices]; guards}}; b. Maintains physical access audit logs for {{Assignment: organization-defined entry/exit points}}; c. Provides {{Assignment: organization-defined security safeguards}} to control access to areas within the facility officially designated as publicly accessible; d. Escorts visitors and monitors visitor activity {{Assignment: organization-defined circumstances requiring visitor escorts and monitoring}}; e. Secures keys, combinations, and other physical access devices; f. Inventories {{Assignment: organization-defined physical access devices}} every {{Assignment: organization-defined frequency}}; and g. Changes combinations and keys {{Assignment: organization-defined frequency}} and/or when keys are lost, combinations are compromised, or individuals are transferred or terminated.' WHERE [Requirement_Id] = 16399
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization enforces physical access authorizations to the information system in addition to the physical access controls for the facility at {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 16400
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization performs security checks {{Assignment: organization-defined frequency}} at the physical boundary of the facility or information system for unauthorized exfiltration of information or removal of information system components.' WHERE [Requirement_Id] = 16401
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization uses lockable physical casings to protect {{Assignment: organization-defined information system components}} from unauthorized physical access.' WHERE [Requirement_Id] = 16403
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization defined hardware components}} within the information system.' WHERE [Requirement_Id] = 16404
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a penetration testing process that includes {{Assignment: organization defined frequency}}, unannounced attempts to bypass or circumvent security controls associated with physical access points to the facility.' WHERE [Requirement_Id] = 16405
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization controls physical access to {{Assignment: organization-defined information system distribution and transmission lines}} within organizational facilities using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 16406
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Ensures that only authorized individuals receive output from the device.' WHERE [Requirement_Id] = 16408
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: (a) Controls physical access to output from {{Assignment: organization-defined output devices}}; and (b) Links individual identity to receipt of the output from the device.' WHERE [Requirement_Id] = 16409
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization marks {{Assignment: organization-defined information system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 16410
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Monitors physical access to the facility where the information system resides to detect and respond to physical security incidents; b. Reviews physical access logs {{Assignment: organization-defined frequency}} and upon occurrence of {{Assignment: organization-defined events or potential indications of events}}; and c. Coordinates results of reviews and investigations with the organizational incident response capability.' WHERE [Requirement_Id] = 16411
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to recognize {{Assignment: organization-defined classes/types of intrusions}} and initiate {{Assignment: organization-defined response actions}}.' WHERE [Requirement_Id] = 16413
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs video surveillance of {{Assignment: organization-defined operational areas}} and retains video recordings for {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16414
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization monitors physical access to the information system in addition to the physical access monitoring of the facility as {{Assignment: organization-defined physical spaces containing one or more components of the information system}}.' WHERE [Requirement_Id] = 16415
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains visitor access records to the facility where the information system resides for {{Assignment: organization-defined time period}}; and b. Reviews visitor access records {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16416
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs redundant power cabling paths that are physically separated by {{Assignment: organization-defined distance}}.' WHERE [Requirement_Id] = 16419
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automatic voltage controls for {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 16420
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Provides the capability of shutting off power to the information system or individual system components in emergency situations; b. Places emergency shutoff switches or devices in {{Assignment: organization-defined location by information system or system component}} to facilitate safe and easy access for personnel; and c. Protects emergency power shutoff capability from unauthorized activation.' WHERE [Requirement_Id] = 16421
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a short-term uninterruptible power supply to facilitate {{Selection (one or more): an orderly shutdown of the information system; transition of the information system to long-term alternate power}} in the event of a primary power source loss.' WHERE [Requirement_Id] = 16422
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides a long-term alternate power supply for the information system that is: (a) Self-contained; (b) Not reliant on external power generation; and (c) Capable of maintaining {{Selection: minimally required operational capability; full operational capability}} in the event of an extended loss of the primary power source.' WHERE [Requirement_Id] = 16424
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire detection devices/systems for the information system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire.' WHERE [Requirement_Id] = 16428
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs fire suppression devices/systems for the information system that provide automatic notification of any activation to Assignment: organization-defined personnel or roles] and {{Assignment: organization-defined emergency responders}}.' WHERE [Requirement_Id] = 16429
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that the facility undergoes {{Assignment: organization-defined frequency}} inspections by authorized and qualified inspectors and resolves identified deficiencies within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16431
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Maintains temperature and humidity levels within the facility where the information system resides at {{Assignment: organization-defined acceptable levels}}; and b. Monitors temperature and humidity levels {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16432
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to detect the presence of water in the vicinity of the information system and alerts {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16436
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization authorizes, monitors, and controls {{Assignment: organization-defined types of information system components}} entering and exiting the facility and maintains records of those items.' WHERE [Requirement_Id] = 16437
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs {{Assignment: organization-defined security controls}} at alternate work sites; b. Assesses as feasible, the effectiveness of security controls at alternate work sites; and c. Provides a means for employees to communicate with information security personnel in case of security incidents or problems.' WHERE [Requirement_Id] = 16438
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization positions information system components within the facility to minimize potential damage from {{Assignment: organization-defined physical and environmental hazards}} and to minimize the opportunity for unauthorized access.' WHERE [Requirement_Id] = 16439
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs {{Assignment: organization-defined asset location technologies}} to track and monitor the location and movement of {{Assignment: organization-defined assets}} within {{Assignment: organization-defined controlled areas}}; and b. Ensures that asset location technologies are employed in accordance with applicable federal laws, Executive Orders, directives, regulations, policies, standards, and guidance.' WHERE [Requirement_Id] = 16443
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A security planning policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the security planning policy and associated security planning controls; and b. Reviews and updates the current: 1. Security planning policy {{Assignment: organization-defined frequency}}; and 2. Security planning procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16444
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security plan for the information system that: 1. Is consistent with the organization''s enterprise architecture; 2. Explicitly defines the authorization boundary for the system; 3. Describes the operational context of the information system in terms of missions and business processes; 4. Provides the security categorization of the information system including supporting rationale; 5. Describes the operational environment for the information system and relationships with or connections to other information systems; 6. Provides an overview of the security requirements for the system; 7. Identifies any relevant overlays, if applicable; 8. Describes the security controls in place or planned for meeting those requirements including a rationale for the tailoring and supplementation decisions; and 9. Is reviewed and approved by the authorizing official or designated representative prior to plan implementation; b. Distributes copies of the security plan and communicates subsequent changes to the plan to {{Assignment: organization-defined personnel or roles}}; c. Reviews the security plan for the information system {{Assignment: organization-defined frequency}}; d. Updates the plan to address changes to the information system/environment of operation or problems identified during plan implementation or security control assessments; and e. Protects the security plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 16445
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization plans and coordinates security-related activities affecting the information system with {{Assignment: organization-defined individuals or groups}} before conducting such activities in order to reduce the impact on other organizational entities.' WHERE [Requirement_Id] = 16446
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes and makes readily available to individuals requiring access to the information system, the rules that describe their responsibilities and expected behavior with regard to information and information system usage; b. Receives a signed acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the information system; c. Reviews and updates the rules of behavior {{Assignment: organization-defined frequency}}; and d. Requires individuals who have signed a previous version of the rules of behavior to read and resign when the rules of behavior are revised/updated.' WHERE [Requirement_Id] = 16447
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops a security Concept of Operations (CONOPS) for the information system containing at a minimum, how the organization intends to operate the system from the perspective of information security; and b. Reviews and updates the CONOPS {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16449
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops an information security architecture for the information system that: 1. Describes the overall philosophy, requirements, and approach to be taken with regard to protecting the confidentiality, integrity, and availability of organizational information; 2. Describes how the information security architecture is integrated into and supports the enterprise architecture; and 3. Describes any information security assumptions about, and dependencies on, external services; b. Reviews and updates the information security architecture {{Assignment: organization-defined frequency}} to reflect updates in the enterprise architecture; and c. Ensures that planned information security architecture changes are reflected in the security plan, the security Concept of Operations (CONOPS), and organizational procurements/acquisitions.' WHERE [Requirement_Id] = 16450
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization designs its security architecture using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security safeguards operate in a coordinated and mutually reinforcing manner.' WHERE [Requirement_Id] = 16451
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that {{Assignment: organization-defined security safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 16452
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization centrally manages {{Assignment: organization-defined security controls and related processes}}.' WHERE [Requirement_Id] = 16453
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A personnel security policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the personnel security policy and associated personnel security controls; and b. Reviews and updates the current: 1. Personnel security policy {{Assignment: organization-defined frequency}}; and 2. Personnel security procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16454
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Assigns a risk designation to all organizational positions; b. Establishes screening criteria for individuals filling those positions; and c. Reviews and updates position risk designations {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16455
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Screens individuals prior to authorizing access to the information system; and b. Rescreens individuals according to {{Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of such rescreening}}.' WHERE [Requirement_Id] = 16456
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that individuals accessing an information system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 16459
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization, upon termination of individual employment: a. Disables information system access within {{Assignment: organization-defined time period}}; b. Terminates/revokes any authenticators/credentials associated with the individual; c. Conducts exit interviews that include a discussion of {{Assignment: organization-defined information security topics}}; d. Retrieves all security-related organizational information system-related property; e. Retains access to organizational information and information systems formerly controlled by terminated individual; and f. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16460
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs automated mechanisms to notify {{Assignment: organization-defined personnel or roles}} upon termination of an individual.' WHERE [Requirement_Id] = 16462
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Reviews and confirms ongoing operational need for current logical and physical access authorizations to information systems/facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiates {{Assignment: organization-defined transfer or reassignment actions}} within {{Assignment: organization-defined time period following the formal transfer action}}; c. Modifies access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}}.' WHERE [Requirement_Id] = 16463
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and documents access agreements for organizational information systems; b. Reviews and updates the access agreements {{Assignment: organization-defined frequency}}; and c. Ensures that individuals requiring access to organizational information and information systems: 1. Sign appropriate access agreements prior to being granted access; and 2. Re-sign access agreements to maintain access to organizational information systems when access agreements have been updated or {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16464
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Establishes personnel security requirements including security roles and responsibilities for third-party providers; b. Requires third-party providers to comply with personnel security policies and procedures established by the organization; c. Documents personnel security requirements; d. Requires third-party providers to notify {{Assignment: organization-defined personnel or roles}} of any personnel transfers or terminations of third-party personnel who possess organizational credentials and/or badges, or who have information system privileges within {{Assignment: organization-defined time period}}; and e. Monitors provider compliance.' WHERE [Requirement_Id] = 16467
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Employs a formal sanctions process for individuals failing to comply with established information security policies and procedures; and b. Notifies {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time period}} when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.' WHERE [Requirement_Id] = 16468
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A risk assessment policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the risk assessment policy and associated risk assessment controls; and b. Reviews and updates the current: 1. Risk assessment policy {{Assignment: organization-defined frequency}}; and 2. Risk assessment procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16469
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Conducts an assessment of risk, including the likelihood and magnitude of harm, from the unauthorized access, use, disclosure, disruption, modification, or destruction of the information system and the information it processes, stores, or transmits; b. Documents risk assessment results in {{Selection: security plan; risk assessment report; [Assignment: organization-defined document]}}; c. Reviews risk assessment results {{Assignment: organization-defined frequency}}; d. Disseminates risk assessment results to {{Assignment: organization-defined personnel or roles}}; and e. Updates the risk assessment {{Assignment: organization-defined frequency}} or whenever there are significant changes to the information system or environment of operation (including the identification of new threats and vulnerabilities), or other conditions that may impact the security state of the system.' WHERE [Requirement_Id] = 16471
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Scans for vulnerabilities in the information system and hosted applications {{Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process}} and when new vulnerabilities potentially affecting the system/applications are identified and reported; b. Employs vulnerability scanning tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for: 1. Enumerating platforms, software flaws, and improper configurations; 2. Formatting checklists and test procedures; and 3. Measuring vulnerability impact; c. Analyzes vulnerability scan reports and results from security control assessments; d. Remediates legitimate vulnerabilities {{Assignment: organization-defined response times}} in accordance with an organizational assessment of risk; and e. Shares information obtained from the vulnerability scanning process and security control assessments with {{Assignment: organization-defined personnel or roles}} to help eliminate similar vulnerabilities in other information systems (i.e., systemic weaknesses or deficiencies).' WHERE [Requirement_Id] = 16472
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization updates the information system vulnerabilities scanned {{Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported}}.' WHERE [Requirement_Id] = 16474
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization determines what information about the information system is discoverable by adversaries and subsequently takes {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 16476
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements privileged access authorization to {{Assignment: organization identified information system components}} for selected {{Assignment: organization-defined vulnerability scanning activities}}.' WHERE [Requirement_Id] = 16477
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a technical surveillance countermeasures survey at {{Assignment: organization-defined locations}} {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined events or indicators occur]}}.' WHERE [Requirement_Id] = 16481
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and services acquisition policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and services acquisition policy and associated system and services acquisition controls; and b. Reviews and updates the current: 1. System and services acquisition policy {{Assignment: organization-defined frequency}}; and 2. System and services acquisition procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16482
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Manages the information system using {{Assignment: organization-defined system development life cycle}} that incorporates information security considerations; b. Defines and documents information security roles and responsibilities throughout the system development life cycle; c. Identifies individuals having information security roles and responsibilities; and d. Integrates the organizational information security risk management process into system development life cycle activities.' WHERE [Requirement_Id] = 16484
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide design and implementation information for the security controls to be employed that includes: {{Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design/implementation information]}} at {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 16487
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{Assignment: organization-defined state-of-the-practice system/security engineering methods, software development methods, testing/evaluation/validation techniques, and quality control processes}}.' WHERE [Requirement_Id] = 16488
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Deliver the system, component, or service with {{Assignment: organization-defined security configurations}} implemented; and (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.' WHERE [Requirement_Id] = 16489
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to produce a plan for the continuous monitoring of security control effectiveness that contains {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 16492
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Obtains administrator documentation for the information system, system component, or information system service that describes: 1. Secure configuration, installation, and operation of the system, component, or service; 2. Effective use and maintenance of security functions/mechanisms; and 3. Known vulnerabilities regarding configuration and use of administrative (i.e., privileged) functions; b. Obtains user documentation for the information system, system component, or information system service that describes: 1. User-accessible security functions/mechanisms and how to effectively use those security functions/mechanisms; 2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner; and 3. User responsibilities in maintaining the security of the system, component, or service; c. Documents attempts to obtain information system, system component, or information system service documentation when such documentation is either unavailable or nonexistent and {{Assignment: organization-defined actions}} in response; d. Protects documentation as required, in accordance with the risk management strategy; and e. Distributes documentation to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 16495
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires that providers of external information system services comply with organizational information security requirements and employ {{Assignment: organization-defined security controls}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, standards, and guidance; b. Defines and documents government oversight and user roles and responsibilities with regard to external information system services; and c. Employs {{Assignment: organization-defined processes, methods, and techniques}} to monitor security control compliance by external service providers on an ongoing basis.' WHERE [Requirement_Id] = 16497
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Perform configuration management during system, component, or service {{Selection (one or more): design; development; implementation; operation}}; b. Document, manage, and control the integrity of changes to {{Assignment: organization-defined configuration items under configuration management}}; c. Implement only organization-approved changes to the system, component, or service; d. Document approved changes to the system, component, or service and the potential security impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service and report findings to {{Assignment: organization-defined personnel}}.' WHERE [Requirement_Id] = 16498
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: a. Create and implement a security assessment plan; b. Perform {{Selection (one or more): unit; integration; system; regression}} testing/evaluation at {{Assignment: organization-defined depth and coverage}}; c. Produce evidence of the execution of the security assessment plan and the results of the security testing/evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during security testing/evaluation.' WHERE [Requirement_Id] = 16505
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Requires an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security assessment plan and the evidence produced during security testing/evaluation; and (b) Ensures that the independent agent either is provided with sufficient information to complete the verification process or has been granted the authority to obtain such information.' WHERE [Requirement_Id] = 16508
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to perform a manual code review of {{Assignment: organization-defined specific code}} using {{Assignment: organization-defined processes, procedures, and/or techniques}}.' WHERE [Requirement_Id] = 16509
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to perform penetration testing at {{Assignment: organization-defined breadth/depth}} and with {{Assignment: organization-defined constraints}}.' WHERE [Requirement_Id] = 16510
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to verify that the scope of security testing/evaluation provides complete coverage of required security controls at {{Assignment: organization-defined depth of testing/evaluation}}.' WHERE [Requirement_Id] = 16512
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects against supply chain threats to the information system, system component, or information system service by employing {{Assignment: organization-defined security safeguards}} as part of a comprehensive, defense-in-breadth information security strategy.' WHERE [Requirement_Id] = 16514
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined tailored acquisition strategies, contract tools, and procurement methods}} for the purchase of the information system, system component, or information system service from suppliers.' WHERE [Requirement_Id] = 16515
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to limit harm from potential adversaries identifying and targeting the organizational supply chain.' WHERE [Requirement_Id] = 16517
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} in accordance with classification guides to protect supply chain-related information for the information system, system component, or information system service.' WHERE [Requirement_Id] = 16520
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to validate that the information system or system component received is genuine and has not been altered.' WHERE [Requirement_Id] = 16521
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Selection (one or more): organizational analysis, independent third-party analysis, organizational penetration testing, independent third-party penetration testing}} of {{Assignment: organization-defined supply chain elements, processes, and actors}} associated with the information system, system component, or information system service.' WHERE [Requirement_Id] = 16522
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined security safeguards}} to ensure an adequate supply of {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 16524
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and retains unique identification of {{Assignment: organization defined supply chain elements, processes, and actors}} for the information system, system component, or information system service.' WHERE [Requirement_Id] = 16525
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Describes the trustworthiness required in the {{Assignment: organization-defined information system, information system component, or information system service}} supporting its critical missions/business functions; and b. Implements {{Assignment: organization-defined assurance overlay}} to achieve such trustworthiness.' WHERE [Requirement_Id] = 16527
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization identifies critical information system components and functions by performing a criticality analysis for {{Assignment: organization-defined information systems, information system components, or information system services}} at {{Assignment: organization defined decision points in the system development life cycle}}.' WHERE [Requirement_Id] = 16528
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Requires the developer of the information system, system component, or information system service to follow a documented development process that: 1. Explicitly addresses security requirements; 2. Identifies the standards and tools used in the development process; 3. Documents the specific tool options and tool configurations used in the development process; and 4. Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; and b. Reviews the development process, standards, tools, and tool options/configurations {{Assignment: organization-defined frequency}} to determine if the process, standards, tools, and tool options/configurations selected and employed can satisfy {{Assignment: organization defined security requirements}}.' WHERE [Requirement_Id] = 16529
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery}}.' WHERE [Requirement_Id] = 16530
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to perform a criticality analysis at {{Assignment: organization-defined breadth/depth}} and at {{Assignment: organization-defined decision points in the system development life cycle}}.' WHERE [Requirement_Id] = 16532
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that developers perform threat modeling and a vulnerability analysis for the information system at {{Assignment: organization-defined breadth/depth}} that: (a) Uses {{Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels}}; (b) Employs {{Assignment: organization-defined tools and methods}}; and (c) Produces evidence that meets {{Assignment: organization-defined acceptance criteria}}.' WHERE [Requirement_Id] = 16533
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to reduce attack surfaces to {{Assignment: organization-defined thresholds}}.' WHERE [Requirement_Id] = 16534
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Perform an automated vulnerability analysis using {{Assignment: organization-defined tools}}; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to {{Assignment: organization defined personnel or roles}}.' WHERE [Requirement_Id] = 16536
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to provide {{Assignment: organization-defined training}} on the correct use and operation of the implemented security functions, controls, and/or mechanisms.' WHERE [Requirement_Id] = 16541
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, a formal policy model describing the {{Assignment: organization-defined elements of organizational security policy}} to be enforced; and (b) Prove that the formal policy model is internally consistent and sufficient to enforce the defined elements of the organizational security policy when implemented.' WHERE [Requirement_Id] = 16543
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service to: (a) Produce, as an integral part of the development process, an informal descriptive top-level specification that specifies the interfaces to security-relevant hardware, software, and firmware in terms of exceptions, error messages, and effects; (b) Show via {{Selection: informal demonstration, convincing argument with formal methods as feasible}} that the descriptive top-level specification is consistent with the formal policy model; (c) Show via informal demonstration, that the descriptive top-level specification completely covers the interfaces to security-relevant hardware, software, and firmware; (d) Show that the descriptive top-level specification is an accurate description of the interfaces to security-relevant hardware, software, and firmware; and (e) Describe the security-relevant hardware, software, and firmware mechanisms not addressed in the descriptive top-level specification but strictly internal to the security-relevant hardware, software, and firmware.' WHERE [Requirement_Id] = 16546
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization inspects {{Assignment: organization-defined information systems, system components, or devices}} {{Selection (one or more): at random; at [Assignment: organization defined frequency], upon [Assignment: organization-defined indications of need for inspection]}} to detect tampering.' WHERE [Requirement_Id] = 16552
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops and implements anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the information system; and b. Reports counterfeit information system components to {{Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]}}.' WHERE [Requirement_Id] = 16553
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization trains {{Assignment: organization-defined personnel or roles}} to detect counterfeit information system components (including hardware, software, and firmware).' WHERE [Requirement_Id] = 16554
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization maintains configuration control over {{Assignment: organization-defined information system components}} awaiting service/repair and serviced/repaired components awaiting return to service.' WHERE [Requirement_Id] = 16555
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization disposes of information system components using {{Assignment: organization defined techniques and methods}}.' WHERE [Requirement_Id] = 16556
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization scans for counterfeit information system components {{Assignment: organization defined frequency}}.' WHERE [Requirement_Id] = 16557
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization re-implements or custom develops {{Assignment: organization-defined critical information system components}}.' WHERE [Requirement_Id] = 16558
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires that the developer of {{Assignment: organization-defined information system, system component, or information system service}}: a. Have appropriate access authorizations as determined by assigned {{Assignment: organization defined official government duties}}; and b. Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 16559
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization requires the developer of the information system, system component, or information system service take {{Assignment: organization-defined actions}} to ensure that the required access authorizations and screening criteria are satisfied.' WHERE [Requirement_Id] = 16560
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization provides {{Selection (one or more): in-house support; [Assignment: organization defined support from external providers]}} for unsupported information system components.' WHERE [Requirement_Id] = 16562
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Develops, documents, and disseminates to {{Assignment: organization-defined personnel or roles}}: 1. A system and communications protection policy that addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and 2. Procedures to facilitate the implementation of the system and communications protection policy and associated system and communications protection controls; and b. Reviews and updates the current: 1. System and communications protection policy {{Assignment: organization-defined frequency}}; and 2. System and communications protection procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16563
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents unauthorized information transfer via shared resources in accordance with {{Assignment: organization-defined procedures}} when system processing explicitly switches between different information classification levels or security categories.' WHERE [Requirement_Id] = 16573
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects against or limits the effects of the following types of denial of service attacks: {{Assignment: organization-defined types of denial of service attacks or reference to source for such information}} by employing {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 16574
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system restricts the ability of individuals to launch {{Assignment: organization defined denial of service attacks}} against other information systems.' WHERE [Requirement_Id] = 16575
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Employs {{Assignment: organization-defined monitoring tools}} to detect indicators of denial of service attacks against the information system; and (b) Monitors {{Assignment: organization-defined information system resources}} to determine if sufficient resources exist to prevent effective denial of service attacks.' WHERE [Requirement_Id] = 16577
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the availability of resources by allocating {{Assignment: organization-defined resources}} by {{Selection (one or more); priority; quota; [Assignment: organization-defined security safeguards]}}.' WHERE [Requirement_Id] = 16578
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Monitors and controls communications at the external boundary of the system and at key internal boundaries within the system; b. Implements subnetworks for publicly accessible system components that are {{Selection: physically; logically}} separated from internal organizational networks; and c. Connects to external networks or information systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security architecture.' WHERE [Requirement_Id] = 16579
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Implements a managed interface for each external telecommunication service; (b) Establishes a traffic flow policy for each managed interface; (c) Protects the confidentiality and integrity of the information being transmitted across each interface; (d) Documents each exception to the traffic flow policy with a supporting mission/business need and duration of that need; and (e) Reviews exceptions to the traffic flow policy {{Assignment: organization-defined frequency}} and removes exceptions that are no longer supported by an explicit mission/business need.' WHERE [Requirement_Id] = 16581
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system routes {{Assignment: organization-defined internal communications traffic}} to {{Assignment: organization-defined external networks}} through authenticated proxy servers at managed interfaces.' WHERE [Requirement_Id] = 16584
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system only allows incoming communications from {{Assignment: organization defined authorized sources}} routed to {{Assignment: organization-defined authorized destinations}}.' WHERE [Requirement_Id] = 16587
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization implements {{Assignment: organization-defined host-based boundary protection mechanisms}} at {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 16588
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization isolates {{Assignment: organization-defined information security tools, mechanisms, and support components}} from other internal information system components by implementing physically separate subnetworks with managed interfaces to other components of the system.' WHERE [Requirement_Id] = 16589
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization protects against unauthorized physical connections at {{Assignment: organization-defined managed interfaces}}.' WHERE [Requirement_Id] = 16590
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system blocks both inbound and outbound communications traffic between {{Assignment: organization-defined communication clients}} that are independently configured by end users and external service providers.' WHERE [Requirement_Id] = 16595
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides the capability to dynamically isolate/segregate {{Assignment: organization-defined information system components}} from other components of the system.' WHERE [Requirement_Id] = 16596
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs boundary protection mechanisms to separate {{Assignment: organization-defined information system components}} supporting {{Assignment: organization defined missions and/or business functions}}.' WHERE [Requirement_Id] = 16597
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of transmitted information.' WHERE [Requirement_Id] = 16600
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to {{Selection (one or more): prevent unauthorized disclosure of information; detect changes to information}} during transmission unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 16601
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system maintains the {{Selection (one or more): confidentiality; integrity}} of information during preparation for transmission and during reception.' WHERE [Requirement_Id] = 16602
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to protect message externals unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 16603
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to conceal or randomize communication patterns unless otherwise protected by {{Assignment: organization-defined alternative physical safeguards}}.' WHERE [Requirement_Id] = 16604
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system terminates the network connection associated with a communications session at the end of the session or after {{Assignment: organization-defined time period}} of inactivity.' WHERE [Requirement_Id] = 16605
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system establishes a trusted communications path between the user and the following security functions of the system: {{Assignment: organization-defined security functions to include at a minimum, information system authentication and re-authentication}}.' WHERE [Requirement_Id] = 16606
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization establishes and manages cryptographic keys for required cryptography employed within the information system in accordance with {{Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction}}.' WHERE [Requirement_Id] = 16608
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization produces, controls, and distributes symmetric cryptographic keys using {{Selection: NIST FIPS-compliant; NSA-approved}} key management technology and processes.' WHERE [Requirement_Id] = 16610
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization produces, controls, and distributes asymmetric cryptographic keys using {{Selection: NSA-approved key management technology and processes; approved PKI Class 3 certificates or prepositioned keying material; approved PKI Class 3 or Class 4 certificates and hardware security tokens that protect the user''s private key}}.' WHERE [Requirement_Id] = 16611
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements {{Assignment: organization-defined cryptographic uses and type of cryptography required for each use}} in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, and standards.' WHERE [Requirement_Id] = 16612
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system: a. Prohibits remote activation of collaborative computing devices with the following exceptions: {{Assignment: organization-defined exceptions where remote activation is to be allowed}}; and b. Provides an explicit indication of use to users physically present at the devices.' WHERE [Requirement_Id] = 16613
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization disables or removes collaborative computing devices from {{Assignment: organization-defined information systems or information system components}} in {{Assignment: organization-defined secure work areas}}.' WHERE [Requirement_Id] = 16615
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system provides an explicit indication of current participants in {{Assignment: organization-defined online meetings and teleconferences}}.' WHERE [Requirement_Id] = 16616
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system associates {{Assignment: organization-defined security attributes}} with information exchanged between information systems and between system components.' WHERE [Requirement_Id] = 16617
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization issues public key certificates under an {{Assignment: organization defined certificate policy}} or obtains public key certificates from an approved service provider.' WHERE [Requirement_Id] = 16619
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system identifies {{Assignment: organization-defined unacceptable mobile code}} and takes {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 16621
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization ensures that the acquisition, development, and use of mobile code to be deployed in the information system meets {{Assignment: organization-defined mobile code requirements}}.' WHERE [Requirement_Id] = 16622
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents the download and execution of {{Assignment: organization defined unacceptable mobile code}}.' WHERE [Requirement_Id] = 16623
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system prevents the automatic execution of mobile code in {{Assignment: organization-defined software applications}} and enforces {{Assignment: organization-defined actions}} prior to executing the code.' WHERE [Requirement_Id] = 16624
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system generates a unique session identifier for each session with {{Assignment: organization-defined randomness requirements}} and recognizes only session identifiers that are system-generated.' WHERE [Requirement_Id] = 16632
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system only allows the use of {{Assignment: organization-defined certificate authorities}} for verification of the establishment of protected sessions.' WHERE [Requirement_Id] = 16633
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system fails to a {{Assignment: organization-defined known-state}} for {{Assignment: organization-defined types of failures}} preserving {{Assignment: organization-defined system state information}} in failure.' WHERE [Requirement_Id] = 16634
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined information system components}} with minimal functionality and information storage.' WHERE [Requirement_Id] = 16635
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system includes: {{Assignment: organization-defined platform independent applications}}.' WHERE [Requirement_Id] = 16637
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system protects the {{Selection (one or more): confidentiality; integrity}} of {{Assignment: organization-defined information at rest}}.' WHERE [Requirement_Id] = 16638
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system implements cryptographic mechanisms to prevent unauthorized disclosure and modification of {{Assignment: organization-defined information}} on {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 16639
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization removes from online storage and stores off-line in a secure location {{Assignment: organization-defined information}}.' WHERE [Requirement_Id] = 16640
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs a diverse set of information technologies for {{Assignment: organization-defined information system components}} in the implementation of the information system.' WHERE [Requirement_Id] = 16641
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs virtualization techniques to support the deployment of a diversity of operating systems and applications that are changed {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 16642
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined concealment and misdirection techniques}} for {{Assignment: organization-defined information systems}} at {{Assignment: organization-defined time periods}} to confuse and mislead adversaries.' WHERE [Requirement_Id] = 16643
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined techniques}} to introduce randomness into organizational operations and assets.' WHERE [Requirement_Id] = 16644
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization changes the location of {{Assignment: organization-defined processing and/or storage}} {{Selection: [Assignment: organization-defined time frequency]; at random time intervals}}.' WHERE [Requirement_Id] = 16645
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs realistic, but misleading information in {{Assignment: organization defined information system components}} with regard to its security state or posture.' WHERE [Requirement_Id] = 16646
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined techniques}} to hide or conceal {{Assignment: organization-defined information system components}}.' WHERE [Requirement_Id] = 16647
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: a. Performs a covert channel analysis to identify those aspects of communications within the information system that are potential avenues for covert {{Selection (one or more): storage; timing}} channels; and b. Estimates the maximum bandwidth of those channels.' WHERE [Requirement_Id] = 16648
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization reduces the maximum bandwidth for identified covert {{Selection (one or more); storage; timing}} channels to {{Assignment: organization-defined values}}.' WHERE [Requirement_Id] = 16650
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization measures the bandwidth of {{Assignment: organization-defined subset of identified covert channels}} in the operational environment of the information system.' WHERE [Requirement_Id] = 16651
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization partitions the information system into {{Assignment: organization-defined information system components}} residing in separate physical domains or environments based on {{Assignment: organization-defined circumstances for physical separation of components}}.' WHERE [Requirement_Id] = 16652
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The information system at {{Assignment: organization-defined information system components}}: a. Loads and executes the operating environment from hardware-enforced, read-only media; and b. Loads and executes {{Assignment: organization-defined applications}} from hardware enforced, read-only media.' WHERE [Requirement_Id] = 16653
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization employs {{Assignment: organization-defined information system components}} with no writeable storage that is persistent across component restart or power on/off.' WHERE [Requirement_Id] = 16654
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization: (a) Employs hardware-based, write-protect for {{Assignment: organization-defined information system firmware components}}; and (b) Implements specific procedures for {{Assignment: organization-defined authorized individuals}} to manually disable hardware write-protect for firmware modifications and re-enable the write protect prior to returning to operational mode.' WHERE [Requirement_Id] = 16656
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'The organization distributes {{Assignment: organization-defined processing and storage}} across multiple physical locations.' WHERE [Requirement_Id] = 16658
