UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Require the approval of each nonlocal maintenance session by {{Assignment: organization-defined personnel or roles}}; and (b) Notify {{Assignment: organization-defined personnel or roles}} of the date and time of planned nonlocal maintenance.' WHERE [Requirement_Id] = 29132
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Obtain maintenance support and/or spare parts for {{Assignment: organization-defined system components}} within {{Assignment: organization-defined time-period}} of failure.' WHERE [Requirement_Id] = 29141
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Perform preventive maintenance on {{Assignment: organization-defined system components}} at {{Assignment: organization-defined time intervals}}.' WHERE [Requirement_Id] = 29142
