UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Sanitize {{Assignment: organization-defined system media}} prior to disposal, release out of organizational control, or release for reuse using {{Assignment: organization-defined sanitization techniques and procedures}}; and b. Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.' WHERE [Requirement_Id] = 29153
