UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require two forms of identification from {{Assignment: organization-defined list of acceptable forms of identification}} for visitor access to the facility where the system resides.' WHERE [Requirement_Id] = 29176
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Restrict unescorted access to the facility where the system resides to personnel with {{Selection (one or more): security clearances for all information contained within the system; formal access authorizations for all information contained within the system; need for access to all information contained within the system; [Assignment: organization-defined credentials]}}.' WHERE [Requirement_Id] = 29177
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Enforce physical access authorizations at {{Assignment: organization-defined entry and exit points to the facility where the system resides}} by; 1. Verifying individual access authorizations before granting access to the facility; and 2. Controlling ingress and egress to the facility using {{Selection (one or more): [Assignment: organization-defined physical access control systems or devices]; guards}}; b. Maintain physical access audit logs for {{Assignment: organization-defined entry/exit points}}; c. Provide {{Assignment: organization-defined security safeguards}} to control access to areas within the facility designated as publicly accessible; d. Escort visitors and monitor visitor activity {{Assignment: organization-defined circumstances requiring visitor escorts and monitoring}}; e. Secure keys, combinations, and other physical access devices; f. Inventory {{Assignment: organization-defined physical access devices}} every {{Assignment: organization-defined frequency}}; and g. Change combinations and keys {{Assignment: organization-defined frequency}} and/or when keys are lost, combinations are compromised, or individuals are transferred or terminated.' WHERE [Requirement_Id] = 29178
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Enforce physical access authorizations to the system in addition to the physical access controls for the facility at {{Assignment: organization-defined physical spaces containing one or more components of the system}}.' WHERE [Requirement_Id] = 29179
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Perform security checks {{Assignment: organization-defined frequency}} at the physical boundary of the facility or system for exfiltration of information or removal of system components.' WHERE [Requirement_Id] = 29180
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ guards to control {{Assignment: organization-defined physical access points}} to the facility where the system resides 24 hours per day, 7 days per week.' WHERE [Requirement_Id] = 29181
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Use lockable physical casings to protect {{Assignment: organization-defined system components}} from unauthorized physical access.' WHERE [Requirement_Id] = 29182
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined security safeguards}} to {{Selection (one or more): detect; prevent}} physical tampering or alteration of {{Assignment: organization-defined hardware components}} within the system.' WHERE [Requirement_Id] = 29183
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Control physical access to {{Assignment: organization-defined system distribution and transmission lines}} within organizational facilities using {{Assignment: organization-defined security safeguards}}.' WHERE [Requirement_Id] = 29185
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Control physical access to output from {{Assignment: organization-defined output devices}} to prevent unauthorized individuals from obtaining the output.' WHERE [Requirement_Id] = 29186
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Mark {{Assignment: organization-defined system output devices}} indicating the appropriate security marking of the information permitted to be output from the device.' WHERE [Requirement_Id] = 29189
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Monitor physical access to the facility where the system resides to detect and respond to physical security incidents; b. Review physical access logs {{Assignment: organization-defined frequency}} and upon occurrence of {{Assignment: organization-defined events or potential indications of events}}; and c. Coordinate results of reviews and investigations with the organizational incident response capability.' WHERE [Requirement_Id] = 29190
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ automated mechanisms to recognize {{Assignment: organization-defined classes or types of intrusions}} and initiate {{Assignment: organization-defined response actions}}.' WHERE [Requirement_Id] = 29192
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ video surveillance of {{Assignment: organization-defined operational areas}} and retain video recordings for {{Assignment: organization-defined time-period}}.' WHERE [Requirement_Id] = 29193
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Monitor physical access to the system in addition to the physical access monitoring of the facility at {{Assignment: organization-defined physical spaces containing one or more components of the system}}.' WHERE [Requirement_Id] = 29194
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ redundant power cabling paths that are physically separated by {{Assignment: organization-defined distance}}.' WHERE [Requirement_Id] = 29196
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ automatic voltage controls for {{Assignment: organization-defined critical system components}}.' WHERE [Requirement_Id] = 29197
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Provide the capability of shutting off power to the system or individual system components in emergency situations; b. Place emergency shutoff switches or devices in {{Assignment: organization-defined location by system or system component}} to facilitate safe and easy access for personnel; and c. Protect emergency power shutoff capability from unauthorized activation.' WHERE [Requirement_Id] = 29198
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Provide a short-term uninterruptible power supply to facilitate {{Selection (one or more): an orderly shutdown of the system; transition of the system to long-term alternate power}} in the event of a primary power source loss.' WHERE [Requirement_Id] = 29199
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Provide a long-term alternate power supply for the system that is: (a) Self-contained; (b) Not reliant on external power generation; and (c) Capable of maintaining {{Selection: minimally required operational capability; full operational capability}} in the event of an extended loss of the primary power source.' WHERE [Requirement_Id] = 29201
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ fire detection devices/systems for the system that activate automatically and notify {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}} in the event of a fire.' WHERE [Requirement_Id] = 29205
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Employ fire suppression devices/systems for the system that provide automatic notification of any activation to {{Assignment: organization-defined personnel or roles}} and {{Assignment: organization-defined emergency responders}}; and (b) Employ an automatic fire suppression capability for the system when the facility is not staffed on a continuous basis.' WHERE [Requirement_Id] = 29206
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Verify that the facility undergoes {{Assignment: organization-defined frequency}} fire protection inspections by authorized and qualified inspectors and resolves identified deficiencies within {{Assignment: organization-defined time-period}}.' WHERE [Requirement_Id] = 29207
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Maintain temperature and humidity levels within the facility where the system resides at {{Assignment: organization-defined acceptable levels}}; and b. Monitor temperature and humidity levels {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29208
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ temperature and humidity monitoring that provides an alarm or notification of changes potentially harmful to personnel or equipment to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 29210
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ automated mechanisms to detect the presence of water near the system and alert {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 29212
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Authorize, monitor, and control {{Assignment: organization-defined types of system components}} entering and exiting the facility and maintain records of those items.' WHERE [Requirement_Id] = 29213
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Determine and document the {{Assignment: organization-defined alternate work sites}} allowed for use by employees; b. Employ {{Assignment: organization-defined security and privacy controls}} at alternate work sites; c. Assess the effectiveness of security and privacy controls at alternate work sites; and d. Provide a means for employees to communicate with information security and privacy personnel in case of security or privacy incidents or problems.' WHERE [Requirement_Id] = 29214
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Position system components within the facility to minimize potential damage from {{Assignment: organization-defined physical and environmental hazards}} and to minimize the opportunity for unauthorized access.' WHERE [Requirement_Id] = 29215
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined asset location technologies}} to track and monitor the location and movement of {{Assignment: organization-defined assets}} within {{Assignment: organization-defined controlled areas}}.' WHERE [Requirement_Id] = 29219
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined security safeguards}} against electromagnetic pulse damage for {{Assignment: organization-defined systems and system components}}.' WHERE [Requirement_Id] = 29220
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Mark {{Assignment: organization-defined system hardware components}} indicating the impact or classification level of the information permitted to be processed, stored, or transmitted by the hardware component.' WHERE [Requirement_Id] = 29221
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop, document, and disseminate to {{Assignment: organization-defined personnel or roles}}: 1. Security and privacy planning policies that: (a) Address purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Are consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and 2. Procedures to facilitate the implementation of the security and privacy planning policies and the associated security and privacy planning controls; b. Designate an {{Assignment: organization-defined senior management official}} to manage the security and privacy planning policies and procedures; c. Review and update the current security and privacy planning: 1. Policies {{Assignment: organization-defined frequency}}; and 2. Procedures {{Assignment: organization-defined frequency}}; d. Ensure that the security and privacy planning procedures implement the security and privacy planning policies and controls; and e. Develop, document, and implement remediation actions for violations of the planning policy.' WHERE [Requirement_Id] = 29222
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop security and privacy plans for the system that: 1. Are consistent with the organization''s enterprise architecture; 2. Explicitly define the authorization boundary for the system; 3. Describe the operational context of the system in terms of missions and business processes; 4. Provide the security categorization of the system including supporting rationale; 5. Describe the operational environment for the system and relationships with or connections to other systems; 6. Provide an overview of the security and privacy requirements for the system; 7. Identify any relevant overlays, if applicable; 8. Describe the security and privacy controls in place or planned for meeting those requirements including a rationale for the tailoring decisions; and 9. Are reviewed and approved by the authorizing official or designated representative prior to plan implementation; b. Distribute copies of the security and privacy plans and communicate subsequent changes to the plans to {{Assignment: organization-defined personnel or roles}}; c. Review the security and privacy plans {{Assignment: organization-defined frequency}}; d. Update the security and privacy plans to address changes to the system and environment of operation or problems identified during plan implementation or security and privacy control assessments; and e. Protect the security and privacy plans from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 29223
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Plan and coordinate security- and privacy-related activities affecting the system with {{Assignment: organization-defined individuals or groups}} before conducting such activities to reduce the impact on other organizational entities.' WHERE [Requirement_Id] = 29224
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Establish and provide to individuals requiring access to the system, the rules that describe their responsibilities and expected behavior for information and system usage, security, and privacy; b. Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system; c. Review and update the rules of behavior {{Assignment: organization-defined frequency}}; and d. Require individuals who have signed a previous version of the rules of behavior to read and re-sign {{Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated.}}' WHERE [Requirement_Id] = 29225
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop a Concept of Operations (CONOPS) for the system describing how the organization intends to operate the system from the perspective of information security and privacy; and b. Review and update the CONOPS {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29227
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop security and privacy architectures for the system that: 1. Describe the philosophy, requirements, and approach to be taken for protecting the confidentiality, integrity, and availability of organizational information; 2. Describe the philosophy, requirements, and approach to be taken for processing personally identifiable information; 3. Describe how the security and privacy architectures are integrated into and support the enterprise architecture; and 4. Describe any security- and privacy-related assumptions about, and dependencies on, external services; b. Review and update the security and privacy architectures {{Assignment: organization-defined frequency}} to reflect updates in the enterprise architecture; and c. Reflect planned security and privacy architecture changes in the security and privacy plans, the Concept of Operations (CONOPS), and organizational procurements and acquisitions.' WHERE [Requirement_Id] = 29228
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Design the security and privacy architectures for the system using a defense-in-depth approach that: (a) Allocates {{Assignment: organization-defined security and privacy safeguards}} to {{Assignment: organization-defined locations and architectural layers}}; and (b) Ensures that the allocated security and privacy safeguards operate in a coordinated and mutually reinforcing manner.' WHERE [Requirement_Id] = 29229
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require that {{Assignment: organization-defined security and privacy safeguards}} allocated to {{Assignment: organization-defined locations and architectural layers}} are obtained from different suppliers.' WHERE [Requirement_Id] = 29230
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Centrally manage {{Assignment: organization-defined security and privacy controls and related processes}}.' WHERE [Requirement_Id] = 29231
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop and disseminate an organization-wide information security program plan that: 1. Provides an overview of the requirements for the security program and a description of the security program management controls and common controls in place or planned for meeting those requirements; 2. Includes the identification and assignment of roles, responsibilities, management commitment, coordination among organizational entities, and compliance; 3. Reflects the coordination among organizational entities responsible for information security; and 4. Is approved by a senior official with responsibility and accountability for the risk being incurred to organizational operations (including mission, functions, image, and reputation), organizational assets, individuals, other organizations, and the Nation; b. Review the organization-wide information security program plan {{Assignment: organization-defined frequency}}; c. Update the information security program plan to address organizational changes and problems identified during plan implementation or control assessments; and d. Protect the information security program plan from unauthorized disclosure and modification.' WHERE [Requirement_Id] = 29234
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develops a comprehensive strategy to manage: 1. Security risk to organizational operations and assets, individuals, other organizations, and the Nation associated with the operation and use of organizational systems; 2. Privacy risk to individuals resulting from the collection, sharing, storing, transmitting, use, and disposal of personally identifiable information; and 3. Supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services; b. Implement the risk management strategy consistently across the organization; and c. Review and update the risk management strategy {{Assignment: organization-defined frequency}} or as required, to address organizational changes.' WHERE [Requirement_Id] = 29242
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, other organizations, and the Nation; and b. Determine information protection and personally identifiable information processing needs arising from the defined mission and business processes; and c. Review and revise the mission and business processes {{Assignment: organization-defined frequency}}, until achievable protection and personally identifiable information processing needs are obtained.' WHERE [Requirement_Id] = 29244
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Establish policy and procedures to ensure that the requirements for the protection of Controlled Unclassified Information processed, stored or transmitted on external systems, are implemented in accordance with applicable laws, Executive Orders, directives, policies, regulations, and standards. b. Update the policy and procedures {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29251
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Establish a written charter for a Data Management Board; b. Establish the Data Management Board consisting of {{Assignment: organization-defined roles}} with the following responsibilities: 1. Develop and implement guidelines supporting data modeling, quality, integrity, and de-identification needs of personally identifiable information across the information life cycle; 2. Review and approve applications to release data outside of the organization, archiving the applications and the released data, and performing post-release monitoring to ensure that the assumptions made as part of the data release continue to be valid; c. Include requirements for personnel interaction with the Data Management Board in security and privacy awareness and/or role-based training.' WHERE [Requirement_Id] = 29261
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Establish, maintain, and update {{Assignment: organization-defined frequency}} an inventory of all programs and systems that create, collect, use, process, store, maintain, disseminate, disclose, or dispose of personally identifiable information; b. Provide updates of the personally identifiable information inventory to the Chief Information Officer, Senior Agency Official for Privacy, and Senior Agency Information Security Officer {{Assignment: organization-defined frequency}}; c. Use the personally identifiable information inventory to support the establishment of information security and privacy requirements for all new or modified systems containing personally identifiable information; d. Review the personally identifiable information inventory {{Assignment: organization-defined frequency}}; e. Ensure to the extent practicable, that personally identifiable information is accurate, relevant, timely, and complete; and f. Reduce personally identifiable information to the minimum necessary for the proper performance of authorized organizational functions.' WHERE [Requirement_Id] = 29267
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Develop, disseminate, and update privacy reports to: a. The Office of Management and Budget, Congress, and other oversight bodies to demonstrate accountability with statutory and regulatory privacy program mandates; and b. {{Assignment: organization-defined officials}} and other personnel with responsibility for monitoring privacy program progress and compliance.' WHERE [Requirement_Id] = 29269
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop a plan for managing supply chain risks associated with the development, acquisition, maintenance, and disposal of systems, system components, and system services; b. Implement the supply chain risk management plan consistently across the organization; and c. Review and update the supply chain risk management plan {{Assignment: organization-defined frequency}} or as required, to address organizational changes.' WHERE [Requirement_Id] = 29270
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop, document, and disseminate to {{Assignment: organization-defined personnel or roles}}: 1. A personnel security policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and 2. Procedures to facilitate the implementation of the personnel security policy and the associated personnel security controls; b. Designate an {{Assignment: organization-defined senior management official}} to manage the personnel security policy and procedures; c. Review and update the current personnel security: 1. Policy {{Assignment: organization-defined frequency}}; and 2. Procedures {{Assignment: organization-defined frequency}}; d. Ensure that the personnel security procedures implement the personnel security policy and controls; and e. Develop, document, and implement remediation actions for violations of the personnel security policy.' WHERE [Requirement_Id] = 29272
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Assign a risk designation to all organizational positions; b. Establish screening criteria for individuals filling those positions; and c. Review and update position risk designations {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29273
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Screen individuals prior to authorizing access to the system; and b. Rescreen individuals in accordance with {{Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening}}.' WHERE [Requirement_Id] = 29274
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Verify that individuals accessing a system processing, storing, or transmitting information requiring special protection: (a) Have valid access authorizations that are demonstrated by assigned official government duties; and (b) Satisfy {{Assignment: organization-defined additional personnel screening criteria}}.' WHERE [Requirement_Id] = 29277
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Verify that individuals accessing a system processing, storing, or transmitting {{Assignment: organization-defined information types}} meet {{Assignment: organization-defined citizenship requirements}}.' WHERE [Requirement_Id] = 29278
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Upon termination of individual employment: a. Disable system access within {{Assignment: organization-defined time-period}}; b. Terminate or revoke any authenticators and credentials associated with the individual; c. Conduct exit interviews that include a discussion of {{Assignment: organization-defined information security topics}}; d. Retrieve all security-related organizational system-related property; e. Retain access to organizational information and systems formerly controlled by terminated individual; and f. Notify {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time-period}}.' WHERE [Requirement_Id] = 29279
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ automated mechanisms to notify {{Assignment: organization-defined personnel or roles}} upon termination of an individual.' WHERE [Requirement_Id] = 29281
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization; b. Initiate {{Assignment: organization-defined transfer or reassignment actions}} within {{Assignment: organization-defined time-period following the formal transfer action}}; c. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and d. Notify {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time-period}}.' WHERE [Requirement_Id] = 29282
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop and document access agreements for organizational systems; b. Review and update the access agreements {{Assignment: organization-defined frequency}}; and c. Verify that individuals requiring access to organizational information and systems: 1. Sign appropriate access agreements prior to being granted access; and 2. Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29283
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Establish personnel security requirements including security roles and responsibilities for external providers; b. Require external providers to comply with personnel security policies and procedures established by the organization; c. Document personnel security requirements; d. Require external providers to notify {{Assignment: organization-defined personnel or roles}} of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within {{Assignment: organization-defined time-period}}; and e. Monitor provider compliance.' WHERE [Requirement_Id] = 29286
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Employ a formal sanctions process for individuals failing to comply with established information security policies and procedures; and b. Notify {{Assignment: organization-defined personnel or roles}} within {{Assignment: organization-defined time-period}} when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.' WHERE [Requirement_Id] = 29287
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop, document, and disseminate to {{Assignment: organization-defined personnel or roles}}: 1. A risk assessment policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and 2. Procedures to facilitate the implementation of the risk assessment policy and the associated risk assessment controls; b. Designate an {{Assignment: organization-defined senior management official}} to manage the risk assessment policy and procedures; c. Review and update the current risk assessment: 1. Policy {{Assignment: organization-defined frequency}}; and 2. Procedures {{Assignment: organization-defined frequency}}; d. Ensure that the risk assessment procedures implement the risk assessment policy and controls; and e. Develop, document, and implement remediation actions for violations of the risk assessment policy.' WHERE [Requirement_Id] = 29288
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Conduct a risk assessment, including the likelihood and magnitude of harm, from: 1. The unauthorized access, use, disclosure, disruption, modification, or destruction of the system, the information it processes, stores, or transmits, and any related information; and 2. Privacy-related problems for individuals arising from the intentional processing of personally identifiable information; b. Integrate risk assessment results and risk management decisions from the organization and missions/business process perspectives with system-level risk assessments; c. Document risk assessment results in {{Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]}}; d. Review risk assessment results {{Assignment: organization-defined frequency}}; e. Disseminate risk assessment results to {{Assignment: organization-defined personnel or roles}}; and f. Update the risk assessment {{Assignment: organization-defined frequency}} or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system.' WHERE [Requirement_Id] = 29291
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Assess supply chain risks associated with {{Assignment: organization-defined systems, system components, and system services}}; and (b) Update the supply chain risk assessment {{Assignment: organization-defined frequency}}, when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain.' WHERE [Requirement_Id] = 29292
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Scan for vulnerabilities in the system and hosted applications {{Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process}} and when new vulnerabilities potentially affecting the system are identified and reported; b. Employ vulnerability scanning tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for: 1. Enumerating platforms, software flaws, and improper configurations; 2. Formatting checklists and test procedures; and 3. Measuring vulnerability impact; c. Analyze vulnerability scan reports and results from control assessments; d. Remediate legitimate vulnerabilities {{Assignment: organization-defined response times}} in accordance with an organizational assessment of risk; e. Share information obtained from the vulnerability scanning process and control assessments with {{Assignment: organization-defined personnel or roles}} to help eliminate similar vulnerabilities in other systems; and f. Employ vulnerability scanning tools that include the capability to readily update the vulnerabilities to be scanned.' WHERE [Requirement_Id] = 29293
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Update the system vulnerabilities to be scanned {{Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported}}.' WHERE [Requirement_Id] = 29294
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Determine unintended discoverable information about the system and take {{Assignment: organization-defined corrective actions}}.' WHERE [Requirement_Id] = 29296
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Implements privileged access authorization to {{Assignment: organization-identified system components}} for {{Assignment: organization-defined vulnerability scanning activities}}.' WHERE [Requirement_Id] = 29297
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ a technical surveillance countermeasures survey at {{Assignment: organization-defined locations}} {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined events or indicators occur]}}.' WHERE [Requirement_Id] = 29301
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Identify critical system components and functions by performing a criticality analysis for {{Assignment: organization-defined systems, system components, or system services}} at {{Assignment: organization-defined decision points in the system development life cycle}}.' WHERE [Requirement_Id] = 29304
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Develop, document, and disseminate to {{Assignment: organization-defined personnel or roles}}: 1. A system and services acquisition policy that: (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and (b) Is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and 2. Procedures to facilitate the implementation of the system and services acquisition policy and the associated system and services acquisition controls; b. Designate an {{Assignment: organization-defined senior management official}} to manage the system and services acquisition policy and procedures; c. Review and update the current system and services acquisition: 1. Policy {{Assignment: organization-defined frequency}}; and 2. Procedures {{Assignment: organization-defined frequency}}; d. Ensure that the system and services acquisition procedures implement the system and services acquisition policy and controls; and e. Develop, document, and implement remediation actions for violations of the system and services acquisition policy.' WHERE [Requirement_Id] = 29305
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Manage the system using {{Assignment: organization-defined system development life cycle}} that incorporates information security and privacy considerations; b. Define and document information security and privacy roles and responsibilities throughout the system development life cycle; c. Identify individuals having information security and privacy roles and responsibilities; and d. Integrate the organizational information security and privacy risk management process into system development life cycle activities.' WHERE [Requirement_Id] = 29307
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to provide design and implementation information for the selected controls that includes: {{Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information]}} at {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 29313
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to demonstrate the use of a system development life cycle process that includes {{Assignment: organization-defined systems engineering methods; [Selection (one or more): systems security engineering methods; privacy engineering methods]; software development methods; testing, evaluation, assessment, verification, and validation methods; and quality control processes}}.' WHERE [Requirement_Id] = 29314
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to: (d) Deliver the system, component, or service with {{Assignment: organization-defined security configurations}} implemented; and (e) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.' WHERE [Requirement_Id] = 29315
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to produce a plan for continuous monitoring of security and privacy control effectiveness that contains the following: {{Assignment: organization-defined level of detail}}.' WHERE [Requirement_Id] = 29318
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Obtain administrator documentation for the system, system component, or system service that describes: 1. Secure configuration, installation, and operation of the system, component, or service; 2. Effective use and maintenance of security and privacy functions and mechanisms; and 3. Known vulnerabilities regarding configuration and use of administrative or privileged functions; b. Obtain user documentation for the system, system component, or system service that describes: 1. User-accessible security and privacy functions and mechanisms and how to effectively use those functions and mechanisms; 2. Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner and protect individual privacy; and 3. User responsibilities in maintaining the security of the system, component, or service and privacy of individuals; c. Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent and takes {{Assignment: organization-defined actions}} in response; d. Protect documentation as required, in accordance with the organizational risk management strategy; and e. Distribute documentation to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 29321
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Apply {{Assignment: organization-defined systems security engineering principles}} in the specification, design, development, implementation, and modification of the system and system components.' WHERE [Requirement_Id] = 29322
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Require that providers of external system services comply with organizational security and privacy requirements and employ {{Assignment: organization-defined security and privacy controls}}; b. Define and document organizational oversight and user roles and responsibilities with regard to external system services; and c. Employ {{Assignment: organization-defined processes, methods, and techniques}} to monitor security and privacy control compliance by external service providers on an ongoing basis.' WHERE [Requirement_Id] = 29323
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Conduct an organizational assessment of risk prior to the acquisition or outsourcing of information security services; and (b) Verify that the acquisition or outsourcing of dedicated information security services is approved by {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 29324
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require providers of {{Assignment: organization-defined external system services}} to identify the functions, ports, protocols, and other services required for the use of such services.' WHERE [Requirement_Id] = 29325
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Establish, document, and maintain trust relationships with external service providers based on {{Assignment: organization-defined security and privacy requirements, properties, factors, or conditions defining acceptable trust relationships}}.' WHERE [Requirement_Id] = 29326
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Take {{Assignment: organization-defined actions}} to verify that the interests of {{Assignment: organization-defined external service providers}} are consistent with and reflect organizational interests.' WHERE [Requirement_Id] = 29327
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Restrict the location of {{Selection (one or more): information processing; information or data; system services}} to {{Assignment: organization-defined locations}} based on {{Assignment: organization-defined requirements or conditions}}.' WHERE [Requirement_Id] = 29328
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to: a. Perform configuration management during system, component, or service {{Selection (one or more): design; development; implementation; operation; disposal}}; b. Document, manage, and control the integrity of changes to {{Assignment: organization-defined configuration items under configuration management}}; c. Implement only organization-approved changes to the system, component, or service; d. Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; and e. Track security flaws and flaw resolution within the system, component, or service and report findings to {{Assignment: organization-defined personnel}}.' WHERE [Requirement_Id] = 29331
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service, at all post-design phases of the system development life cycle, to: a. Create and implement a security and privacy assessment plan; b. Perform {{Selection (one or more): unit; integration; system; regression}} testing/evaluation {{Assignment: organization-defined frequency}} at {{Assignment: organization-defined depth and coverage}}; c. Produce evidence of the execution of the assessment plan and the results of the testing and evaluation; d. Implement a verifiable flaw remediation process; and e. Correct flaws identified during testing and evaluation.' WHERE [Requirement_Id] = 29338
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to perform threat modeling and vulnerability analyses at {{Assignment: organization-defined breadth and depth}} during development and during the subsequent testing and evaluation of the system, component, or service that: (a) Uses {{Assignment: organization-defined information concerning impact, environment of operations, known or assumed threats, and acceptable risk levels}}; (b) Employs {{Assignment: organization-defined tools and methods}}; and (c) Produces evidence that meets {{Assignment: organization-defined acceptance criteria}}.' WHERE [Requirement_Id] = 29340
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Require an independent agent satisfying {{Assignment: organization-defined independence criteria}} to verify the correct implementation of the developer security and privacy assessment plans and the evidence produced during testing and evaluation; and (b) Verify that the independent agent is provided with sufficient information to complete the verification process or granted the authority to obtain such information.' WHERE [Requirement_Id] = 29341
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to perform a manual code review of {{Assignment: organization-defined specific code}} using {{Assignment: organization-defined processes, procedures, and/or techniques}}.' WHERE [Requirement_Id] = 29342
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to perform penetration testing at {{Assignment: organization-defined breadth and depth}} and with {{Assignment: organization-defined constraints}}.' WHERE [Requirement_Id] = 29343
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to verify that the scope of testing and evaluation provides complete coverage of required security and privacy controls at {{Assignment: organization-defined depth of testing and evaluation}}.' WHERE [Requirement_Id] = 29345
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'a. Employ {{Assignment: organization-defined supply chain safeguards}} to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events; and b. Document the selected and implemented supply chain safeguards in {{Selection: security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document]}}.' WHERE [Requirement_Id] = 29347
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined acquisition strategies, contract tools, and procurement methods}} to protect against, identify, and mitigate supply chain risks.' WHERE [Requirement_Id] = 29348
