UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined Operations Security (OPSEC) safeguards}} to protect supply chain-related information for the system, system component, or system service.' WHERE [Requirement_Id] = 29353
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Employ {{Assignment: organization-defined security safeguards}} to validate that the system or system component received is genuine and has not been altered.' WHERE [Requirement_Id] = 29354
