UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the {{Selection (one or more): notification of supply chain compromises; results of assessments or audits; [Assignment: organization-defined information]}}.' WHERE [Requirement_Id] = 29356
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Establish and maintain unique identification of {{Assignment: organization-defined supply chain elements, processes, and personnel}} associated with the {{Assignment: organization-defined system, critical system components}}.' WHERE [Requirement_Id] = 29357
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Establish a process or processes to address weaknesses or deficiencies in supply chain elements in coordination with {{Assignment: organization-defined supply chain personnel}}.' WHERE [Requirement_Id] = 29358
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Document, monitor, and maintain valid provenance of {{Assignment: organization-defined systems, system components, and associated data}}.' WHERE [Requirement_Id] = 29359
