UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics {{Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery}}.' WHERE [Requirement_Id] = 29361
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to perform a criticality analysis at {{Assignment: organization-defined breadth/depth}} and at {{Assignment: organization-defined decision points in the system development life cycle}}.' WHERE [Requirement_Id] = 29363
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to reduce attack surfaces to {{Assignment: organization-defined thresholds}}.' WHERE [Requirement_Id] = 29364
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to: (a) Perform an automated vulnerability analysis using {{Assignment: organization-defined tools}}; (b) Determine the exploitation potential for discovered vulnerabilities; (c) Determine potential risk mitigations for delivered vulnerabilities; and (d) Deliver the outputs of the tools and results of the analysis to {{Assignment: organization-defined personnel or roles}}.' WHERE [Requirement_Id] = 29366
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require the developer of the system, system component, or system service to provide {{Assignment: organization-defined training}} on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms.' WHERE [Requirement_Id] = 29370
