UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Re-implement or custom develops {{Assignment: organization-defined critical system components}}.' WHERE [Requirement_Id] = 29387
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Require that the developer of [Assignment: organization-defined system, system component, or system service]: a. Have appropriate access authorizations as determined by assigned [Assignment: organization- defined official government duties]; b. Satisfy {{Assignment: organization-defined additional personnel screening criteria}}; and c. Provide information that the access authorizations and screening criteria specified in a. and b. are satisfied.' WHERE [Requirement_Id] = 29388
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Provide {{Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]}} for unsupported system components.' WHERE [Requirement_Id] = 29390
