UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'(a) Prevent the exfiltration of information; and (b) Conduct exfiltration tests {{Assignment: organization-defined frequency}}.' WHERE [Requirement_Id] = 29413
