UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Protect against unauthorized physical connections at {{Assignment: organization-defined managed interfaces}}.' WHERE [Requirement_Id] = 29417
UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Block inbound and outbound communications traffic between {{Assignment: organization-defined communication clients}} that are independently configured by end users and external service providers.' WHERE [Requirement_Id] = 29422
