UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Establish and manage cryptographic keys for required cryptography employed within the system in accordance with {{Assignment: organization-defined requirements for key generation, distribution, storage, access, and destruction}}.' WHERE [Requirement_Id] = 29436
