UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'Protect the {{Selection (one or more): confidentiality; integrity}} of {{Assignment: organization-defined information}} at rest.' WHERE [Requirement_Id] = 29467
