UPDATE [dbo].[NEW_REQUIREMENT] SET [Requirement_Text]=N'<ol type="a">
  <li>Identify and document:
    <ol type="1">
      <li>Assumptions affecting risk assessments, risk responses, and risk monitoring;</li>
